local P = LoreForeverPacks.Begin("LoreForever_Lang_ukUA")
P.entries["quest:6082"] = {n="Приборкання звіра",s="Це завдання — останнє випробування в основних обрядах посвяти молодого мисливця Орди в Дуротарі. Під проводом мисливця-ветерана Тотара в Гострому Пагорбі майбутній слідопит має зустрітися з небезпечним броньованим скорпідом і приборкати його. Перемога над цим панцирним хижаком доводить владу над дикими звірами й відкриває довічну здатність приборкувати, кликати й відпускати справжнього супутника.",h="Це завдання — останнє випробування в основних обрядах посвяти молодого мисливця Орди в Дуротарі.",kw={"мисливець","тотар","скорпід","приборкання","гострий пагорб","улюбленець"},ang={["class:Hunter"]="Цей обряд посвяти — визначальна віха раннього шляху мисливця: він назавжди відкриває основні вміння приборкувати, кликати й вести звіриних супутників.",["faction:Horde"]="Молоді орки й тролі в Дуротарі мають вистояти проти найлютіших хижаків пустельної землі, щоб заслужити місце справжніх розвідників і годувальників Орди.",["race:Orc"]="Упокорення скорпідів Дуротару вшановує орківську філософію: долати сувору землю незламною волею й воїнською дисципліною.",["race:Troll"]="Мисливці Темного Списа покладаються на гостре чуття й глибокий зв'язок із духами дикої природи, щоб угамувати отруйних хижаків, які вразили б інших."},sec={{t="Останнє випробування",b="Перш ніж мисливцеві дозволять блукати Калімдором із вірним звіриним супутником, він має довести, що здатен приборкати найсуворішу звірину Дуротару. Наставник мисливців Гострого Пагорба Тотар посилає учнів впокорити трьох різних створінь зачарованим жезлом приборкання. Уже випробувавши свою стійкість проти лютих вепрів і прудких прибійних крабів, мисливці мають стати проти броньованого скорпіда — отруйного хижака в товстому панцирі, що втілює витривалість і смертоносну швидкість."},{t="Зв'язок із дикою природою",b="Упокорити броньованого скорпіда — це не просто вбивство, а доказ зосередженості й панування під невпинним натиском. Тотар закликає мисливців наслідувати швидкі, впевнені удари звіра. Повернення до Гострого Пагорба після успішного приборкання отруйного членистоногого доводить, що мисливець має спокійну волю, потрібну, щоб утримувати владу. Коли жезл приборкання повернуто, Тотар передає вроджені прийоми дикої природи, і мисливець може сам шукати й прив'язувати постійного супутника на власний вибір."}},fp="16,359,15.484.0,21.523.0,47.128.0,63.215.0,35.136.0,69.220.0,52.122.0,28.207.0"}
P.entries["quest:6083"] = {n="Приборкання звіра",s="Друге випробування в обряді майстерності молодого мисливця в Дуротарі, яке доручає наставник Тотар у Гострому Пагорбі. Майбутніх мисливців-орків і тролів посилають на узбережжя біля Островів Відлуння приборкати прибійного краба — так їхній зв'язок виходить за межі суходільних звірів до прибережної живності.",h="Друге випробування в обряді майстерності молодого мисливця в Дуротарі, яке доручає наставник Тотар у Гострому...",kw={"мисливець","тотар","прибійний краб","приборкання","острови відлуння","узбережжя"},ang={["class:Hunter"]="Це випробування закладає основну дисципліну, потрібну, щоб керувати захисними звірами, і показує, як природний панцир і впертість створіння доповнюють стрільця.",["race:Orc"]="Для орків, що облаштовують постійний дім у Дуротарі, впокорення витривалої живності узбережжя підкріплює їхню владу над суворим краєм.",["race:Troll"]="Тролі Темного Списа добре знають води біля Островів Відлуння й Села Сен'джин, тож це випробування — зустріч зі знайомою живністю їхнього прибережного притулку."},sec={{t="Зв'язок із узбережжям",b="Упокоривши лютого плямистого вепра, мисливець-початківець дістає від Тотара нове завдання — звернути погляд до моря. Сувора природа Дуротару — це й зубчасті береги, і мілкі рифи, де кишать панцирні ракоподібні. Зустріч із прибійним крабом вимагає терпіння й стійкості, адже ці броньовані краби опираються кожному вторгненню в їхні прибережні володіння."},{t="Продовження волі",b="Тотар навчає, що кожен звір, якого прив'язує мисливець, має стати продовженням його власної сили. Упокорюючи жезлом приборкання водяне створіння, як-от прибійного краба, мисливець учиться поширювати свою владну присутність на різні вдачі й середовища, доводячи готовність до постійних супутників."}},fp="16,281,22.353.0,21.318.0,30.166.0,45.230.0,39.219.0,21.126.0,41.179.0,47.241.0"}
P.entries["quest:6084"] = {n="Приборкання звіра",s="Це завдання — друге випробування в посвяті дворфійського мисливця, яке дає Ґріф Вайлдгарт у Хараносі. Навчившись давати раду грубій витривалості скелястого вепра, юний мисливець має опанувати прудкість і смертоносну грацію тутешнього снігового леопарда.",h="Це завдання — друге випробування в посвяті дворфійського мисливця, яке дає Ґріф Вайлдгарт у Хараносі.",kw={"приборкання","леопард","мисливець","вайлдгарт","жезл","харанос"},ang={["class:Hunter"]="Цей обряд переходу вчить дворфійських мисливців-новачків різниці між витривалими улюбленцями на кшталт вепрів і прудкими, агресивними бійцями на кшталт котів.",["race:Dwarf"]="Горяни Каз Модану здавна ділять замерзлі вершини Дун Мороґу зі сніговими леопардами, поважаючи і їхню скрадливість, і смертоносну мисливську вправність."},sec={{t="Урок витонченості",b="Якщо скелясті вепри вчать горянина витримувати неприкриту лють і тримати удар, то Ґріф Вайлдгарт наголошує: справжній мисливець має розуміти різні стилі бою. Він показує учням на південний схід, де нишпорять снігові леопарди Дун Мороґу. Ґріф порівнює цих граційних хижаків із вишукано зробленою рушницею: зовні вражають, та під білосніжними шубами ховають нищівну силу."},{t="Опанування Жезла Приборкання",b="Зачарованим жезлом приборкання мисливець має зустріти дикого леопарда і повернути його мисливські інстинкти на партнерство. Снігові леопарди випробовують спритність, швидкість і гострі рефлекси, а не чисту витривалість. Опанувати такого звіра означає довести, що новачок здатен порозумітися з хижаками, які блискавично б'ють із засніжених скель, — і зробити ще один крок до справжньої влади над дикими звірами."}},fp="16,259,19.416.0,24.396.0,34.251.0,34.110.0,50.228.0,47.254.0,23.91.0,29.204.1"}
P.entries["quest:6085"] = {n="Приборкання звіра",s="Це завдання — останнє випробування в базовому вишколі дворфійського мисливця під проводом Ґріфа Вайлдгарта з Хараноса. Приборкавши зачарованим жезлом агресивного Ведмедя Крижаного Кігтя і зрозумівши його, мисливець доводить владу над чистою грубою силою. Виконання цієї вправи відкриває основні вміння, потрібні, щоб приборкати, покликати й відпустити постійного дикого супутника.",h="Це завдання — останнє випробування в базовому вишколі дворфійського мисливця під проводом Ґріфа Вайлдгарта з...",kw={"приборкання","ведмідь","крижаний кіготь","мисливець","вайлдгарт","жезл","харанос"},ang={["class:Hunter"]="Це завдання — обряд переходу, що перетворює самотнього лучника на справжнього мисливця-приборкувача й відкриває головні вміння приборкувати та прикликати звірів.",["race:Dwarf"]="Ведмеді здавна були знаковими супутниками дворфійських горян, що патрулюють Дун Мороґ, і славляться тим, що не поступаються господарям упертою стійкістю."},sec={{t="Сила дикої природи",b="По всьому Дун Мороґу горяни й розвідники здавна покладаються на витривалих звірів, щоб пережити крижані скелі. Після вправ на прудких і хитрих хижаках майстер-мисливець Ґріф Вайлдгарт ставить перед новачками останню ціль — Ведмідь Крижаний Кіготь. Ці величезні звірі, що нишпорять у снігових заметах на схід від Хараноса, втілюють грубу фізичну міць і невтомну витривалість — якості, які кожен дворфійський мисливець має навчитися підкоряти."},{t="Заслужити супутника",b="Випробування з Жезлом Приборкання — суто навчальні вправи, що показують мисливцям, як дикі інстинкти відгукуються на волю і спокійний намір. Щойно жезл утихомирює ведмедя, тимчасовий зв'язок виконує своє призначення. Повернення знаряддя Ґріфу завершує офіційні випробування, і майстер розкриває довічні таємниці володіння звірами: як умиротворити будь-яке придатне дике створіння і кликати його впродовж цілого життя пригод."}},fp="16,364,24.446.0,19.439.0,45.200.0,55.227.0,32.168.0,52.198.0,50.177.0,57.223.0"}
P.entries["quest:6086"] = {n="Навчання звіра",s="«Навчання звіра» — завершальний обряд переходу для молодих дворфійських мисливців у Дун Мороґу. Опанувавши мистецтво втихомирення й приборкання диких хижаків серед засніжених скель, слідопити-новачки вирушають у серце Айронфорджа, щоб навчитися годувати, вишколювати й доглядати довічного тваринного супутника.",h="«Навчання звіра» — завершальний обряд переходу для молодих дворфійських мисливців у Дун Мороґу.",kw={"навчання звіра","мисливець","тандерґраніт","зала зброї","айронфордж","супутник","улюбленець"},ang={["class:Hunter"]="Ця віха відкриває саму серцевину мисливського ремесла: уміння належно годувати постійного тваринного супутника, керувати ним і воскрешати його.",["faction:Alliance"]="Володарі звірів Айронфорджа — вагома частина розвідувальних сил Альянсу, що покладаються на вірних супутників із дикої природи, патрулюючи крижані гірські перевали.",["race:Dwarf"]="Дворфи бачать у полюванні давню традицію гірських нетрів Каз Модану й мають ведмедів, вепрів і гірських котів за шанованих партнерів у розвідці та обороні."},sec={{t="З дикої природи до Кузні",b="Довівши свою вправність на диких звірах Дун Мороґу — втихомиривши жезлом приборкання великих скелястих вепрів, снігових леопардів і міцних ведмедів Крижаних Кігтів, — учні-мисливці завершують випробування під пильним оком Ґріфа Вайлдгарта біля Хараноса. Та впіймати дике серце тварини — лише половина зв'язку. Ґріф посилає своїх загартованих вихованців гірським перевалом до Айронфорджа — знайти військовий квартал, відомий як Зала Зброї."},{t="Наука Белії Тандерґраніт",b="У кам'яних склепіннях Зали Зброї Айронфорджа стоїть Белія Тандерґраніт — одна з найшанованіших майстринь дресирування тварин у дворфійському королівстві. Белія передає найважливіше знання, яке перетворює дикого переляканого звіра на запекло відданого партнера. Її наука сягає далеко за прості команди: вона показує молодим мисливцям, як годувати улюбленців, навчати їх нових бойових умінь і навіть повертати їхні душі зі смерті, якщо ті поляжуть, боронячи господаря."},{t="Зв'язок дворфійського мисливця",b="Дворфійська традиція наголошує, що володіння звірами будується на повазі, а не на підкоренні. Белія нагадує кожному молодому мисливцю: тваринний супутник відображає турботу, яку отримує. Якщо звіра добре годувати, поважати й належно вишколювати, він відплатить непохитною відданістю проти трогів, морозних тролів і будь-якої загрози, що зазіхне на Каз Модан."}},fp="18,311,26.447.0,32.466.0,25.360.0,34.249.0,28.258.0,37.166.0,67.211.0,41.254.0,21.184.0"}
P.entries["quest:6087"] = {n="Приборкання звіра",s="Це випробування — другий ступінь посвяти мисливця-таурена в мистецтво приборкання звірів. Під проводом наставника мисливців Ява Шарпмейна в Селі Бладгуф новачок має підкорити швидкого й безстрашного степового переслідувача.",h="Це випробування — другий ступінь посвяти мисливця-таурена в мистецтво приборкання звірів.",kw={"приборкання","степовий переслідувач","вовк","яв шарпмейн","село бладгуф","малгор","мисливець"},ang={["class:Hunter"]="Цей обряд посвяти поєднує основи виживання з наступальною злагодженістю і вчить вас битися пліч-о-пліч зі стрімким супутником.",["race:Tauren"]="На відміну від культур, де улюбленців мають лише за робочу худобу, шу'хало бачать у приборканні звіра кування священної спорідненості під пильною ласкою Земної Матері."},sec={{t="Уроки переслідувача",b="Коли молодий мисливець опанував оборонну витривалість дорослого довгоступа, Яв Шарпмейн кидає йому виклик: дивитися далі простого виживання. Степовий переслідувач утілює зовсім іншу філософію полювання — невпинну швидкість, злагодженість зграї та безстрашний натиск. Щоб приборкати такого, треба підійти до хитрого хижака, не збившись із кроку, віддзеркаливши рішучу вдачу самого вовка."},{t="Пліч-о-пліч",b="Для тауренів полювання разом зі звіром ніколи не було ні рабством, ні грубим підкоренням. Яв Шарпмейн наголошує: мисливець і хижак мають битися як одне ціле, пов'язані взаємною повагою та спільним ритмом. Зріднившись зі степовим переслідувачем під відкритим небом Малгору, мисливець учиться доповнювати натиск партнера й рухатися з ним у лад у розпал бою."}},fp="16,233,21.405.0,16.376.0,60.124.0,46.237.0,44.136.0,53.198.0,21.187.0,44.173.0"}
P.entries["quest:6088"] = {n="Приборкання звіра",s="Це випробування — останній урок молодого мисливця-таурена в навчанні у Ява Шарпмейна в Селі Бладгуф. Зріднившись за допомогою жезла приборкання з диким стрімкокрилом, мисливець доводить владу над створіннями повітря й здобуває священну довіру Земної Матері. Виконання цього завдання дарує тривке знання, потрібне, щоб приборкати довічного супутника й керувати ним.",h="Це випробування — останній урок молодого мисливця-таурена в навчанні у Ява Шарпмейна в Селі Бладгуф.",kw={"приборкання","стрімкокрил","яв шарпмейн","село бладгуф","малгор","мисливець","жезл приборкання"},ang={["class:Hunter"]="Це завдання завершує ланцюжок основного навчання, що відкриває постійне приборкання звірів, і позначає перехід від учня до цілком самостійного розвідника дикого краю.",["race:Tauren"]="Для шу'хало зріднення з диким звіром — акт духовного єднання, благословенний Земною Матір'ю, і воно має глибоке культурне значення на всіх рівнинах Малгору."},sec={{t="Влада над небом",b="Коли наземних хижаків пагорбистих рівнин Малгору вже підкорено, Яв Шарпмейн звертає вашу увагу до відкритого неба. Стрімкокрил — лютий гостродзьобий хижий птах, відомий розмашистими піке й грізною поставою. Узяти під владу такого дикого крилатого мисливця — випробування для ваших рефлексів і спокою: доведеться витерпіти його кігті, зачарованим жезлом настроюючи свій дух на його інстинкти."},{t="Дар Земної Матері",b="Для тауренів полювання й дружба з тваринами — передусім духовний шлях, а не просте підкорення. Опанувавши створіння і землі, і неба, ви засвідчуєте рівновагу й повагу, потрібні, щоб ходити рівнинами, не порушуючи природи. Яв Шарпмейн визнає цю зрілість: забирає свій тимчасовий жезл приборкання й передає вам тривкі вміння — кликати, відпускати й назавжди приборкувати супутника на власний вибір."}},fp="16,362,18.438.0,22.453.0,50.249.0,45.209.0,48.161.0,43.207.0,40.132.0,58.199.0"}
P.entries["quest:6089"] = {n="Навчання звіра",s="«Навчання звіра» — завершальний обряд посвяти для молодих мисливців-тауренів у Малгорі. Довівши духовне терпіння й рішучість, потрібні, щоб угамувати диких звірів рівнин, мисливці вирушають до Тандер Блафа опановувати довічну науку: ріднитися з постійним тваринним супутником, годувати його й керувати ним.",h="«Навчання звіра» — завершальний обряд посвяти для молодих мисливців-тауренів у Малгорі.",kw={"навчання звіра","голт тандергорн","узвишшя мисливців","тандер блаф","яв шарпмейн","мисливець","супутник"},ang={["class:Hunter"]="Цей обряд позначає перехід від самотньої боротьби до бою поруч із вірним супутником і завершує ваше основне навчання як охоронця дикого краю.",["race:Tauren"]="Для шу'хало взяти тваринного супутника в бій — священний обов'язок опіки та поваги до творінь Земної Матері."},sec={{t="Шлях до Великого Бескиду",b="Випробувавши свій дух проти небезпечних хижаків Малгору — довгоступів, степових переслідувачів і стрімкокрилів, — мисливці-таурени визнаються гідними справжнього мисливського звання. Яв Шарпмейн, наставник із Села Бладгуф, доручає новачкові подорож на Узвишшя Мисливців у Тандер Блафі. Там стоїть Голт Тандергорн — легендарна постать серед шу'хало, чия слава в єднанні з дикою природою поступається лише його шані до Земної Матері."},{t="Священний зв'язок",b="Для тауренів звір — не проста зброя і не невільник, а партнер, дарований через гармонію з природним світом. Голт Тандергорн передає знання, конче потрібні, щоб підтримувати це партнерство. Мисливець має навчитися не лише спрямовувати бойові інстинкти створіння, а й живити його тіло регулярним годуванням, гоїти його рани й кликати його дух назад, якщо воно впаде, захищаючи свого товариша на рівнинах."}},fp="18,336,27.484.0,13.429.0,33.201.0,63.180.0,53.226.0,71.272.0,66.194.0,58.257.0"}
P.entries["quest:6101"] = {n="Приборкання звіра",s="Це випробування — другий етап навчання мисливця нічних ельфів приборкувати звірів під проводом Дазалара в Доланаарі. Мисливцям доручають упокорити зачарованим жезлом приборкання нічного шаблезуба-переслідувача, щоб краще відчути мінливе розмаїття диких звірів. Так міцніє порозуміння між дикою природою Тельдрассила й слідопитами-вартовими, що ходять під її гіллям.",h="Це випробування — другий етап навчання мисливця нічних ельфів приборкувати звірів під проводом Дазалара в...",kw={"приборкання звіра","мисливець","дазалар","нічний шаблезуб","переслідувач","доланаар"},ang={["class:Hunter"]="Цей обряд — серцевина науки мисливця: ви вчитеся поважати різні звірині вдачі, перш ніж вам довірять супутника на все життя.",["race:NightElf"]="Нічні шаблезуби глибоко вплетені в історію й культуру калдорей, тож приборкання переслідувача — традиційна віха для місцевих лісових розвідників."},sec={{t="Мінлива природа звірів",b="Перші уроки зосереджені на розумінні основних інстинктів, та Дазалар наголошує: єдина сталість природи — її безнастанна мінливість. Кожен лісовий вид має власну вдачу, і мисливець мусить навчитися відповідно підлаштовувати свою волю. У тіні крони Тельдрассила це означає мати справу зі створіннями хитрими, потайними й куди більш хижими, ніж прості павуки-прядильники."},{t="Упокорення нічного шаблезуба",b="Нічні шаблезуби шановані калдореями як священні хижаки, люті охоронці й потайні супутники Вартових. Для мисливця-новачка спрямувати силу жезла приборкання на нічного шаблезуба-переслідувача означає мати міцні нерви й спокійну владність. Обернувши хижу агресію переслідувача на прихильний зв'язок, мисливець доводить, що здатен владарювати не лише над сумирними чи меншими створіннями лісу."}},fp="16,377,29.399.0,23.418.0,34.227.0,39.105.0,60.230.0,21.140.0,48.213.0,38.180.0"}
P.entries["quest:6102"] = {n="Приборкання звіра",s="Це завдання — останнє випробування базового вишколу юного мисливця нічних ельфів. Під проводом Дазалара з Доланаара мисливці мають приборкати хижу сову небес, перш ніж здобути право обрати собі справжнього супутника на все життя.",h="Це завдання — останнє випробування базового вишколу юного мисливця нічних ельфів.",kw={"приборкання звіра","мисливець","дазалар","верескун-стригід","сова","жезл приборкання","доланаар"},ang={["class:Hunter"]="Цей обряд переходу — поріг, за яким мисливець перестає битися сам і укладає довічне партнерство з диким супутником.",["race:NightElf"]="Приборкання корінної живності Тельдрассила відображає шлях калдорей — іти в злагоді з природою, а не гнути її силою."},sec={{t="Влада над кронами",b="Перш ніж завершити початкову науку звірознавства, мисливці нічних ельфів мають досягти злагоди зі створіннями з кожного куточка екосистеми Тельдрассила. Мисливець уже довів свою волю проти звірів підліска, тож тепер Дазалар доручає йому впокорити дух небес; його ціль — Верескун-стригід. Ці пильні хижі птахи гніздяться високо в гіллі на захід від Доланаара, і щоб утихомирити їх зачарованим Жезлом Приборкання, потрібні терпіння й міцні нерви."},{t="Зв'язок мисливця",b="Успіх із Верескуном-стригідом завершує давні уроки єднання мисливців калдорей із природою. Повернувши Дазаларові спорожнілий жезл, учень лишає позаду тренувальні вправи й здобуває повне мистецтво кликати, відпускати й назавжди приборкувати обраних звірів по всьому Азероту."}},fp="16,234,21.463.0,15.320.0,35.165.0,15.244.0,49.250.0,41.205.0,42.245.0,47.160.0"}
P.entries["quest:6103"] = {n="Навчання звіра",s="«Навчання звіра» — завершальний обряд переходу для мисливців-початківців нічних ельфів у Тельдрассилі. Довівши свою майстерність приборканням диких звірів на гіллі, мисливці вирушають до Дарнасуса — вчитися глибших мистецтв догляду й дисципліни улюбленця в Джокасте.",h="«Навчання звіра» — завершальний обряд переходу для мисливців-початківців нічних ельфів у Тельдрассилі.",kw={"навчання звіра","мисливець","джокасте","дазалар","ценаріонський анклав","дарнасус"},ang={["class:Hunter"]="Цей обряд знаменує ваш випуск із новачків-слідопитів у справжні володарі звірів: ви здобуваєте змогу навчати, годувати й оживляти свого супутника.",["race:NightElf"]="Традиція калдорей товаришувати зі звірами будується на повазі й співіснуванні, відображаючи вчення, передані через Дарнасус і Ценаріонський Анклав."},sec={{t="Обряд переходу мисливця",b="Перш ніж мисливець нічних ельфів зможе блукати Калімдором із вірним супутником поруч, йому треба опанувати більше, ніж жезл приборкання. Упокорення дикого створіння доводить базову силу й волю, та ненавчений звір лишається непередбачуваним тягарем. Щойно посвячений показує свої здібності в хащах довкола Доланаара, Дазалар скеровує його вглиб, до Дарнасуса, щоб завершити навчання."},{t="Настанови в Ценаріонському Анклаві",b="У тихих гаях Ценаріонського Анклаву шанована мисливиця Джокасте передає основні мистецтва товариства зі звіром. Вона вчить молодого мисливця, як належно годувати улюбленця, воскрешати його, коли станеться лихо, і плекати його бойові інстинкти тренуванням. Для нічних ельфів ці стосунки вкорінені в глибокій шанобі до природи, а не в простому пануванні."}},fp="18,265,26.403.0,32.383.0,34.188.0,24.149.0,21.135.0,38.161.0,50.175.0,39.151.0"}
P.entries["quest:62"] = {n="Копальня Фарґодіп",s="Маршал Дуґан із Ґолдшира доручає розвідникам перевірити повідомлення, що Копальню Фарґодіп захопили кобольди. Копальня лежить на південь від містечка, між фермами Стоунфілдів і Маклурів, і її падіння свідчить про дедалі більшу навалу шкідників по всьому Лісі Елвінн.",h="Маршал Дуґан із Ґолдшира доручає розвідникам перевірити повідомлення, що Копальню Фарґодіп захопили кобольди.",kw={"копальня фарґодіп","кобольди","маршал дуґан","ґолдшир","розвідка","стоунфілди","маклури"},ang={["faction:Alliance"]="Захоплена копальня — ще один виразний знак того, що влада Стормвінда в Елвінні слабне, а місцева варта ледве захищає найнеобхідніше господарство.",["profession:Mining"]="Багаті мідні жили Копальні Фарґодіп життєво важливі для ковалів-початківців, та щоб їх розробляти, доведеться прорубуватися крізь кобольдів, які бережуть свою територію."},sec={{t="Клопіт на південь від Ґолдшира",b="Поки Долина Нортширу давала раду власним шкідникам, до Ґолдшира дійшли тривожні вісті: кобольди захопили ще одне важливе місце. Копальня Фарґодіп, що притулилася між ворогуючими садибами Стоунфілдів і Маклурів на південь від містечка, колись давала королівству камінь і руду. Тепер вогкі тунелі сповнені пронизливого цвірінькання й мерехтіння лойових свічок, і Маршал Дуґан посилає шукачів пригод розвідати глибини й підтвердити найгірше."},{t="Виснажена варта",b="Підтверджена навала лише додає головного болю вартовим Стормвінда. Регулярні війська розтягнуті між обороною від бандитів Дефіас і нападами гнолів, тож варті бракує людей, щоб одразу зачистити копальню. Похмура реакція Дуґана на підтвердження показує, як поступово вислизає з рук контроль над серцем королівства, і він одразу починає тривожитися за інші рудні місця — зокрема за Яшмову копальню на північному сході."}},fp="18,257,26.450.0,16.435.0,36.127.0,42.132.0,40.117.0,59.193.0,47.150.1,53.200.0"}
P.entries["quest:6285"] = {n="Повернення до Льюїса",s="«Повернення до Льюїса» — останній відтинок вступного кур'єрського перельоту, яким украй потрібний обладунок зі Стормвінда доставляють просто на Сентінел Гілл. Дунґар Лонґдрінк довіряє кур'єрам Ящик Осріка, і ті летять на грифонах небом Елвінну й Вестфолу, щоб поповнити запаси обложеного Народного Ополчення.",h="«Повернення до Льюїса» — останній відтинок вступного кур'єрського перельоту, яким украй потрібний обладунок...",kw={"повернення до льюїса","інтендант льюїс","сентінел гілл","грифон","ящик осріка","дунґар лонґдрінк","народне ополчення"},ang={["class:Warrior"]="Кожен ящик нагрудників і поножів, доставлений на Сентінел Гілл, означає ще одного бійця ополчення, здатного витримати удари розбійників Дефіас.",["faction:Alliance"]="Налагоджені маршрути грифонів між Стормвіндом і віддаленими поселеннями на кшталт Сентінел Гілла конче потрібні, щоб скріпити дедалі розколотіше королівство.",["race:Dwarf"]="Уся система повітряних перевезень королівства тримається на дворфійській майстерності — від Дунґара Лонґдрінка на столичному сідалі до Тора у Вестфолі."},sec={{t="Рятівна нитка в небі",b="Вестфол вислизає з рук королівства: його облягають бандити Дефіас, ненажерливі гноли й механічні жниварки. Сухопутні шляхи постачання під ударами, дороги небезпечні для самотніх возів, тож мережа розпорядників польотів стає життєво важливою ниткою. Осрік, зброяр зі Старого Міста Стормвінда, підготував важкий ящик з обладунком, щоб підкріпити побитих добровольців Народного Ополчення на Сентінел Гіллі."},{t="Звичаї грифонів",b="Грифони — надзвичайно вірні й добре вишколені звірі, та щоб вести їх над землями, потрібне знайомство з маршрутом. Як пояснює Дунґар Лонґдрінк кур'єрам-новачкам, грифони інстинктивно знають дорогу додому, до столичного сідала в Стормвінді, але понесуть вершника до віддаленої застави лише тоді, коли мандрівник особисто зустрівся з тамтешнім розпорядником польотів. Якщо ви вже відмітилися в Тора на Сентінел Гіллі, небо над прикордонням відкрите для швидких перельотів."},{t="Припаси для ополчення",b="Після приземлення на Сентінел Гіллі доставлений ящик приймає Інтендант Льюїс — офіцер, що споряджає добровольче військо Ґраяна Стаутмантла. Льюїс одразу береться роздавати обладунок захисникам прикордоння. Для Сентінел Гілла надійний повітряний зв'язок зі столицею — це різниця між утриманням лінії оборони й цілковитим розгромом від рук Братства Дефіас."}},fp="15,310,17.432.0,20.495.0,24.404.0,29.275.0,27.232.0,24.194.0,58.253.0,12.151.0,57.224.0"}
P.entries["quest:637"] = {n="Лист Саллі Баллу",s="Знайдений на потонулому кістяку під розбитими арками Мосту Тандол, цей розмоклий лист містить передсмертні слова дворфійського солдата на ім'я Саллі Баллу. Адресований його дружині Сарі в Айронфорджі, він несе останні думки захисника, що зник у крижаних водах річки під час боїв за міст.",h="Знайдений на потонулому кістяку під розбитими арками Мосту Тандол, цей розмоклий лист містить передсмертні...",kw={"саллі баллу","лист","міст тандол","сара баллу","айронфордж","удова","багнокрай"},ang={["faction:Alliance"]="Лист — зворушливе нагадування про особисту жертву рядових солдатів передової, які бережуть крихкі сухопутні зв'язки між південними й північними землями Альянсу.",["race:Dwarf"]="Для дворфів Айронфорджа повернути останні слова Саллі — означає вшанувати побратима, який поклав життя, обороняючи велику дворфійську кам'яну споруду від північних загроз."},sec={{t="Голос із річкового дна",b="Під масивними кам'яними опорами Мосту Тандол — важливої переправи, що з'єднує Багнокрай з Аратійським нагір'ям, — лежить потонулий кістяк полеглого дворфа. У кістлявій руці він досі стискає пошкоджений водою конверт, який ледве витримує дотик. Написані з болісною ретельністю серед пожеж бою, сторінки починаються ніжним «Моя люба Саро…», зберігаючи голос солдата довго після того, як його забрала вода."},{t="Ціна Мосту",b="Міст Тандол бачив запеклі бої між силами Альянсу та їхніми ворогами — від диверсантів Темного Заліза до розбійницьких ватаг, що зазіхають на прикордоння. Саллі Баллу був одним із багатьох дворфійських солдатів, посланих на північ боронити цю важливу переправу. Коли він загинув під хвилями, його доля лишалася невідомою родині в горах, доки нирець нарешті не дістав його прощальний заповіт."},{t="Удова в Айронфорджі",b="Повернення врятованого листа до Айронфорджа тихо спустошує вдову Саллі, Сару Баллу. Живучи серед гамірних зал дворфійської столиці, вона застигла між горем і крихкою надією, не знаючи, зник її чоловік безвісти чи втрачений назавжди. Побачивши його рукописні слова й дізнавшись про його могилу під водою, вона нарешті змушена зустрітися з гіркою правдою про його смерть."}},fp="21,327,25.455.0,21.403.0,20.428.1,37.197.0,21.214.0,19.167.0,42.203.1,43.229.0,49.228.0"}
P.entries["quest:6395"] = {n="Останнє бажання Марли",s="Останнє бажання Марли — раннє завдання Відступників від Послушниці Елрет у Похоронному Подзвоні. Воно просить вас вистежити поневолені Погибеллю рештки Семюела Фіппса, щоб поховати його поруч із убитою ним дружиною Марлою. Завдання відображає прагнення молодого суспільства Відступників шанувати людські зв'язки й відрізнятися від безтямної Погибелі.",h="Останнє бажання Марли — раннє завдання Відступників від Послушниці Елрет у Похоронному Подзвоні.",kw={"останнє бажання марли","марла","семюел фіппс","елрет","поховання","похоронний подзвін"},ang={["class:Priest"]="Наполягання Послушниці Елрет на належному похоронному обряді прямо стосується духовного обов'язку жерців Відступників, які мають справу зі смертністю, горем і оскверненням мертвих Лордерону.",["race:Undead"]="Для новопіднятих Відступників виконати бажання Марли — емоційний якір у колишньому людському житті, доказ того, що співчуття і честь не загинули разом із Лордероном."},sec={{t="Трагічне возз'єднання",b="Перш ніж Третя війна спустошила Лордерон, Марла і Семюел Фіппси жили як чоловік і дружина. Коли їхніми землями прокотилася чума, Семюел піддався заразі й був піднятий безтямним рабом Погибелі. Марлу нежиття оминуло, та від самого Семюела вона втекти не змогла: у безтямному шалі він жорстоко вбив її. Попри загибель від рук чоловіка, в останні миті Марла не тримала зла. Її передсмертне бажання, яке запам'ятала Послушниця Елрет, — спочивати вічно поруч із чоловіком на цвинтарі Похоронного Подзвону."},{t="Повага до мертвих",b="Послушниця Елрет відряджає шукачів пригод із Відступників на північний схід від Похоронного Подзвону — знайти Семюела Фіппса, який досі блукає зруйнованим табором. Покласти край мукам Семюела означає подвійну користь: очистити долину від прислужника Погибелі, що насідає, і принести його тілесні рештки до місця спочинку Марли. Як наголошує Елрет, шана до покійних і повага до їхньої останньої волі — важлива моральна межа, що відділяє щойно звільнених Відступників від безтямної злоби Погибелі."}},fp="17,339,16.550.0,19.517.0,20.225.0,20.235.0,56.265.0,27.162.0,31.96.0,32.97.0"}
P.entries["quest:683"] = {n="Благання Сари Баллу",s="«Благання Сари Баллу» — сумне доручення від імені дворфійської вдови з Айронфорджа, що тужить за чоловіком. Не маючи сил постати перед своїм монархом у горі, Сара довіряє вам особисте звернення до Короля Маґні Бронзбірда щодо її полеглого чоловіка Саллі Баллу.",h="«Благання Сари Баллу» — сумне доручення від імені дворфійської вдови з Айронфорджа, що тужить за чоловіком.",kw={"сара баллу","благання","король маґні","бронзбірд","айронфордж","удова","саллі"},ang={["faction:Alliance"]="Передавати слово між скорботними громадянами й провідниками Альянсу — означає бачити особисту ціну, яку простий люд платить у війнах за збереження королівства.",["race:Dwarf"]="Доставити благання скорботної вдови просто вашому королю — означає торкнутися глибокої культурної ваги, якої дворфи надають каменю, роду й шануванню жертви предків."},sec={{t="Прохання вдови",b="Отримавши трагічний прощальний лист, піднятий із водних глибин там, де Міст Тандол забрав її чоловіка, Сара Баллу завмирає в жалобі. Не бажаючи, щоб жертва її чоловіка Саллі канула в забуття, вона пише благання, адресоване просто до трону Айронфорджа. Надто розбита горем, щоб самій постати перед придворним етикетом, вона довіряє запечатаний пергамент перевіреному захиснику Альянсу, аби той клопотав перед Королем Маґні Бронзбірдом від її імені."},{t="Аудієнція в короля",b="Нести приватне прохання до Високого Престолу Айронфорджа — не буденна справа, та Маґні Бронзбірд особисто цікавиться відважними захисниками Каз Модану. Отримавши послання, король відкладає державні справи, щоб прочитати скромне благання солдатської вдови, і цим показує свій зв'язок із простими дворфами, які збудували й боронять його гірське королівство."}},fp="18,262,17.468.0,22.359.1,19.156.0,63.195.0,21.158.0,38.100.0,45.158.1,37.137.0"}
P.entries["quest:689"] = {n="Королівська шана",s="Король Маґні Бронзбірд замовив пам'ятник Саллі Баллу — дворфійському солдату, що загинув, обороняючи Міст Тандол. Щоб ушанувати полеглого воїна з належною гідністю, Великий Каменяр Марблстен посилає мандрівників до Гілсбреду по бездоганний Альтеракський Граніт.",h="Король Маґні Бронзбірд замовив пам'ятник Саллі Баллу — дворфійському солдату, що загинув, обороняючи Міст...",kw={"королівська шана","марблстен","граніт","альтерак","гілсбред","пам'ятник","саллі баллу"},ang={["faction:Alliance"]="Здобуття матеріалів у Гілсбреді зміцнює присутність Альянсу на роз'єднаній півночі й водночас ушановує простого солдата, що віддав життя за спільну справу.",["profession:Mining"]="Гірники розуміють прискіпливість Марблстена: тверді, непіддатливі жили Альтеракського Граніту потребують досвідчених рук, щоб вийняти їх чисто, без тріщин.",["race:Dwarf"]="Ушанування Саллі Баллу торкається серця дворфійської культури, де каменярство, бойова жертва й непохитна вірність Королю Бронзбірду тісно переплетені."},sec={{t="Королівське замовлення",b="Коли Король Маґні Бронзбірд вирішив, що полеглий солдат Саллі Баллу заслуговує на вічну пам'ять, справа лягла просто на плечі найкращого майстра Айронфорджа — Великого Каменяра Марблстена. Баллу поклав життя під час лиха на Мосту Тандол — важливій артерії, що з'єднує дворфійські землі з північними королівствами і зазнала жорстоких нападів диверсантів Темного Заліза. Для Марблстена виконати королівський наказ означає створити скульптуру, яка витримає і час, і війну, щоб дворфійська жертва не лишилася непоміченою чи забутою у Великій Кузні."},{t="Камінь із півночі",b="Майстер-каменяр дворфів не вдовольниться звичайним кар'єрним каменем для королівського замовлення. Марблстен наполягає: подобу Саллі Баллу можна відтворити лише в Альтеракському Граніті — щільному, міцному камені, цінованому за довговічність і чисту фактуру. Складність у тому, щоб його здобути: найкращі поклади лежать довкола Пагорба Дарроу, серед спірних передгір'їв Гілсбреду. Вирушати вглиб неспокійної півночі небезпечно, та дворфійське каменярство вимагає матеріалів, гідних героїзму, який вони увічнюють."}},fp="16,272,18.565.0,18.498.0,20.240.0,30.213.0,30.242.0,21.161.0,34.232.0,54.131.0"}
P.entries["quest:7"] = {n="Зачистка табору кобольдів",s="«Зачистка табору кобольдів» — одне з перших військових завдань, яке Маршал Макбрайд дає щойно прибулим у Долину Нортширу новобранцям. Місія посилає добровольців у північні ліси — зачистити табір кобольдів і не дати агресивним підземним збирачам заполонити землі абатства. Для посвяченого це перше справжнє випробування в обороні кордонів Королівства Стормвінд.",h="«Зачистка табору кобольдів» — одне з перших військових завдань, яке Маршал Макбрайд дає щойно прибулим у...",kw={"зачистка","кобольди","табір","маршал макбрайд","нортшир","новобранці"},ang={["faction:Alliance"]="Заворушення в Нортширі показують, як напружені рідні землі Стормвінда: навіть дрібна навала збирачів вимагає термінового добровольчого ополчення.",["race:Human"]="Для людей Нортширу відігнати кобольдів — базовий громадський обов'язок: захистити абатство й поля від навали."},sec={{t="Долина під тиском",b="Долина Нортширу колись була тихим прихистком для молитви, землеробства й вишколу новачків, та останні роки розтягнули військо Стормвінда до краю. Король зник, королівські гарнізони розпорошені, і дикі істоти та пройдисвіти зухвало натискають на край цивілізованих земель. Маршал Макбрайд організовує місцеву оборону просто біля Абатства Нортшира, покладаючись на свіжих добровольців, щоб придушити загрози, перш ніж вони зірвуть життя абатства чи загрожуватимуть довколишнім виноградникам."},{t="Шкідники в лісі",b="Кобольди за природою боягузливі печерні мешканці, схиблені на свічках: зазвичай їм досить колупатися в підземних жилах подалі від сонця. Однак цілий клан просунувся до північного узлісся Нортширу. Якщо їх не спинити, сама їхня кількість обертає збиральництво на відверті набіги. Наказ Макбрайда полювати на кобольдів має подвійну мету: прорідити їхній авангард і перевірити, чи має новобранець рішучість, потрібну для захисту королівства."}},fp="19,401,23.483.0,23.457.0,42.162.0,56.240.0,55.252.0,34.160.1,50.223.0,48.225.0"}
P.entries["quest:71"] = {n="Донесення Томасу",s="«Донесення Томасу» — завдання на сході Лісу Елвінн, пов'язане з розслідуванням Вартового Томаса щодо зниклих вартових Стормвінда біля східних річок. Шукач пригод допомагає Вартовому Томасу біля східного мосту: з'ясовує долю його зниклих товаришів і доповідає про становище вздовж річки.",h="«Донесення Томасу» — завдання на сході Лісу Елвінн, пов'язане з розслідуванням Вартового Томаса щодо зниклих...",kw={"донесення","вартовий томас","медальйони","мурлоки","рольф","малакай","ліс елвінн"},ang={["faction:Alliance"]="Загибель Рольфа й Малакая показує вразливість кордонів Лісу Елвінн, де через нестачу людей гинуть навіть звичайні річкові патрулі.",["race:Human"]="Повернуті медальйони полеглих вартових дають частку честі й завершення солдатам Стормвінда, що загинули, захищаючи внутрішні дороги королівства."},sec={{t="Гірке підтвердження",b="Вартовий Томас із жменькою людей тримає переправу, що з'єднує Ґолдшир і Лісозаготівельний Табір Східної Долини. Коли двоє його товаришів, Малакай і Рольф, зникли в прирічкових землях, лишалася надія, що їх просто відрізали або затримали. Повернуті на міст службові медальйони гасять цю надію й підтверджують: обох вартових убили біля річок."},{t="Загроза вздовж води",b="Місяцями керівництво Стормвінда здебільшого відмахувалося від мурлоків як від дрібної річкової прикрості, зосереджуючись на бандитах і далеких кордонах королівства. Розправа над двома озброєними вартовими Стормвінда біля внутрішніх струмків свідчить про організовану жорстокість. Із доказами в руках Томас розуміє, що східне прикордоння Елвінну зазнає справжнього наступу, і вимагає відповіді, перш ніж лісозаготівельні шляхи й поселення захлинуть."}},fp="16,314,19.388.0,26.440.0,30.156.0,26.176.1,36.175.1,41.224.1,44.177.1,47.209.0"}
P.entries["quest:743"] = {n="Небезпека Вітрофурій",s="«Небезпека Вітрофурій» — обряд бойової готовності, який пропонує Руул Іглталон у Селі Бладгуф. Молодим тауренам і шукачам пригод Орди доручають битися з дикими гарпіями-Вітрофуріями, що гніздяться на південно-східних скелях Малгору. Полювання на цих лютих хижаків — важлива перевірка вправності й уміння вижити перед тим, як вирушити за межі племінної батьківщини.",h="«Небезпека Вітрофурій» — обряд бойової готовності, який пропонує Руул Іглталон у Селі Бладгуф.",kw={"вітрофурії","гарпії","руул іглталон","село бладгуф","малгор","воїн","випробування"},ang={["class:Warrior"]="Виклик Руула Іглталона особливо значущий для майбутніх воїнів, яким треба навчитися відбивати стрімкі удари з піке й долати лютих крилатих нападників твердою наземною дисципліною.",["faction:Horde"]="Союзники тауренів, які беруться за випробування Руула, засвідчують відданість захисту серця Орди й здобувають тривку повагу Села Бладгуф.",["race:Tauren"]="Для молодих тауренів розорення гнізд Вітрофурій — водночас захист рівнин і священний перехід до визнаної зрілості під пильним оком старійшин села."},sec={{t="Оцінка вчителя",b="У Селі Бладгуф ветеран-воїн Руул Іглталон приглядається до всіх мандрівників, що проходять серцем Малгору. Від тих, хто входить у зрілий вік або хоче довести готовність до ширших пригод, Руул вимагає відчутного доказу бойового чуття. Щоб вижити за межами затишних долин Малгору, потрібна витримка проти напористих і хитрих ворогів, тож Руул міряє гарт молоді найлютішими місцевими хижаками."},{t="Загроза Вітрофурій",b="Гарпії-Вітрофурії гніздяться вздовж гористого південно-східного краю Малгору — осторонь від уторованих стежок, але постійно загрожуючи звірині й самотнім подорожнім. Хижі й невситимо голодні до свіжої плоті, ці крилаті страхіття покладаються на стрімкі піке та гострі, мов бритва, пазурі. Перемога над ними й здобуті кігті засвідчують не лише силу здолати укорінену загрозу, а й швидкість, потрібну, щоб дати відсіч нападникам із повітря."}},fp="23,364,22.435.0,19.451.0,23.275.0,48.204.0,70.299.0,53.188.0,63.257.0,35.220.0"}
P.entries["quest:745"] = {n="Спільна земля",s="Доручене Бейном Бладгуфом у Селі Бладгуф, це завдання посилає молодих шукачів пригод Орди приборкати нищівне браконьєрство тутешніх гнолів-Блідоманів. Знищуючи їхніх чинбарів, білувальників і браконьєрів, ви захищаєте звірину Малгору й осягаєте тауренську філософію життя в рівновазі із Земною Матір'ю.",h="Доручене Бейном Бладгуфом у Селі Бладгуф, це завдання посилає молодих шукачів пригод Орди приборкати нищівне...",kw={"блідогриви","гноли","браконьєрство","бейн бладгуф","село бладгуф","малгор","рівновага"},ang={["class:Druid"]="Друїди розуміють, що нестримне браконьєрство збурює дух рівнин і потребує негайного втручання, щоб зцілити гармонію землі.",["class:Hunter"]="Білувальники й браконьєри Блідоманів — цілковита протилежність справжнього мисливця: вони вирізають диких створінь жорстоко й марнотратно, без жодної поваги.",["faction:Horde"]="Допомога Бейну Бладгуфу зміцнює зв'язок між новими шукачами пригод Орди та проводом молодої тауренської нації.",["race:Tauren"]="Для молодих тауренів відгукнутися на поклик Бейна — важливий крок до осягнення священного обов'язку боронити Малгор і шанувати рівновагу Земної Матері."},sec={{t="Земля без рівноваги",b="Таурени глибоко шанують природний світ: беруть від нього лише потрібне для виживання і в усьому вшановують Земну Матір. Гноли-Блідомани, що осіли на південь від Села Бладгуф і в печері на заході, такої поваги не знають. Замість полювати в міру, вони завзято вирізають звірину по всіх рівнинах, залишаючи по собі обдерті туші й зруйновані оселища. Для народу, що прагне збудувати мирну батьківщину в Малгорі, таку безоглядну різанину терпіти не можна."},{t="Коли слова безсилі",b="Бейн Бладгуф спершу сподівався залагодити справу мирно й намагався завести розмову з гнолами-зайдами. Блідомани відкинули всі пропозиції, відповівши на дипломатію ворожістю та новим спустошенням. Переконавшись, що перемовини марні, Бейн удається до сили. Молодих сміливців посилають просто в мисливські табори гнолів — приборкати браконьєрів, чинбарів і білувальників, доки трави не зазнали невиправної шкоди."},{t="Коло життя і смерті",b="Це доручення — водночас обряд посвяти й моральний урок для майбутніх звитяжців. Коли шукач пригод повертається після вилову, Бейн нагадує: відбирати життя не можна зі злоби — лише з потреби зберегти гармонію. Життя і смерть — єдине коло, де одне не може квітнути без другого; цю основоположну істину має нести далі кожен захисник Малгору."}},fp="16,309,21.523.0,15.429.0,28.396.0,21.114.0,49.178.0,31.122.0,39.155.0,42.222.0,28.160.0"}
P.entries["quest:746"] = {n="Дворфські розкопки",s="«Дворфські розкопки» — завдання в Малгорі, яке дає Бейн Бладгуф у Селі Бладгуф. Побоюючись, що дворфські розкопки розлютять тутешніх звірів і споганять священну землю, Бейн доручає молодим захисникам Орди зірвати їхню роботу: відібрати й потрощити їхні кайла.",h="«Дворфські розкопки» — завдання в Малгорі, яке дає Бейн Бладгуф у Селі Бладгуф.",kw={"дворфи","розкопки","кайла","бейн бладгуф","село бладгуф","малгор","ліга дослідників"},ang={["class:Shaman"]="Шаман розуміє: недбалі розкопки, що тривожать підложжя, порушують рівновагу стихій і сіють неспокій серед духів і створінь землі.",["faction:Horde"]="Вторгнення дворфів, союзних Альянсу, в серце земель Орди підважує крихкий мир, усталений після Третьої війни, і зухвало нехтує племінними кордонами.",["profession:Mining"]="Гірники шанують багатства, приховані в камені, та дворфські методи в Малгорі оминають повагу й гармонію, обираючи безоглядне руйнування.",["race:Tauren"]="Тіло Земної Матері священне, і бачити, як чужинці вгризаються в пагорбисті степи Малгору, — образа, що вимагає негайної і твердої відповіді."},sec={{t="Зайди на пагорбах",b="На північний захід від Села Бладгуф дворфські старателі заходилися розмічати розкоп серед пагорбів Малгору. Ліга Дослідників та її землекопні бригади шукають реліквії титанів і таємниці земних надр по всьому Калімдору, та їхні роботи рідко зважають на землі й звичаї тубільців. Для тауренів земля — жива мати, яку належить шанувати, а не обдирати й видовбувати заради каміння й металу."},{t="Захист священної землі",b="Бейн Бладгуф розуміє: дворфські машини й безперервні вибухи загрожують крихкій гармонії рівнин. Окрім самого руйнування, гуркіт тривожить тутешню звірину й доводить рівнинних кодо до шалу. Розбиваючи знаряддя старателів просто біля їхніх кузень, таурени сподіваються послати недвозначне застереження й зупинити вторгнення, доки не сталося непоправного."}},fp="15,289,24.392.0,26.388.0,35.232.0,36.137.0,63.245.0,52.187.0,31.201.0,75.232.0"}
P.entries["quest:747"] = {n="Полювання починається",s="«Полювання починається» — основоположний обряд посвяти для молодих шукачів пригод у Таборі Нарачі на Плато Червоної Хмари. За дорученням Ґрулла Гоквінда посвячені вирушають полювати на тутешніх довгоступів, щоб забезпечити селище м'ясом і пір'ям. Виконання цього завдання — перший крок до поваги Вождя Гоквінда й, зрештою, до права ввійти в Тандер Блаф.",h="«Полювання починається» — основоположний обряд посвяти для молодих шукачів пригод у Таборі Нарачі на Плато...",kw={"полювання","довгоступ","ґрулл гоквінд","табір нарачі","плато червоної хмари","вождь гоквінд","м'ясо"},ang={["class:Hunter"]="Вистежування прудких довгоступів Плато Червоної Хмари — найперша практична вправа у влучності, читанні слідів і шані до звірів, які вас годують.",["race:Tauren"]="Для молодих шу'хало перші вполювані довгоступи плато — важливий обряд посвяти, що підтверджує ваш зв'язок із землею та обов'язок годувати Табір Нарачі."},sec={{t="Прожиток племені",b="На висотах Плато Червоної Хмари виживання й традиція сплетені воєдино. Таурени полюють із потреби — щоб нагодувати й одягти свій народ, — але бачать у вистежуванні та гонитві й важливе випробування дисципліни, і змагання. Коли запаси Табору Нарачі убожіють, громада звертається до своєї молоді, щоб та добула свіжого м'яса довгоступів для кухні й міцного пір'я для племінного вбрання."},{t="Здобути визнання",b="Жоден майбутній герой не сходить із Плато Червоної Хмари на простори Малгору, не довівши своєї вартості. Ґрулл Гоквінд — перший суддя вдачі новачків: він наполягає, що спершу треба показати свою спроможність, а вже потім ставати перед його батьком, Вождем Гоквіндом. Чисте полювання засвідчує не лише самостійність, а й відданість підтримці племені."}},fp="15,361,20.383.0,19.382.0,21.181.0,53.182.0,59.252.0,59.239.0,27.181.0,33.203.0"}
P.entries["quest:748"] = {n="Отруйна вода",s="«Отруйна вода» відкриває зусилля тауренів очистити священні криниці Малгору від забруднення. За дорученням Малла Тандергорна в Селі Бладгуф молоді захисники Орди збирають на рівнинах природні складники для цілющого ритуального тотема.",h="«Отруйна вода» відкриває зусилля тауренів очистити священні криниці Малгору від забруднення.",kw={"отруйна вода","криниця","малл тандергорн","село бладгуф","малгор","тотем","гобліни"},ang={["class:Druid"]="Гобліни, що труять прісні джерела, — прямий напад на природну рівновагу, який вимагає негайної відповіді, щоб уберегти крихку флору й фауну Малгору.",["class:Shaman"]="Відновлення забруднених вод тотемами, наснаженими силою звірів, показує основи тауренського шаманізму: працювати разом із тутешньою звіриною, щоб залагодити збурення стихій.",["race:Tauren"]="Споганення прісної води б'є в самісіньке осердя дарів Земної Матері, тож обряд очищення — основний обов'язок кожного таурена, який дорослішає в Малгорі."},sec={{t="Споганена земля",b="Трав'янисті рівнини Малгору — священна земля тауренів, але підступні сили почали зазіхати на її життєдайну жилу. Малл Тандергорн, старійшина з Села Бладгуф, виявляє, що зайди-гобліни зі своїми посіпаками затруїли дорогоцінні криниці, які напувають племена й тутешню звірину. Це забруднення б'є просто в духовне серце кочового народу, що лише нещодавно тут осів."},{t="Збирання сутності природи",b="Проти промислової отрути Малл покладається на традиційний тауренський шаманізм, а не на грубі зілля. Щоб очистити Водяну Криницю Вінтергуфів, треба виготовити могутній ритуальний тотем, насичений життєвою силою корінних хижаків Малгору. Він посилає мисливців на південно-західні рівнини — по лапи степових вовків і кігті дорослих довгоступів, закликаючи міць самої землі, щоб та зцілила власні рани."}},fp="12,238,17.428.0,26.435.0,40.234.0,65.236.0,46.172.0,34.141.0,58.96.0,53.172.0"}
P.entries["quest:749"] = {n="Сплюндрований караван",s="Морін Клаудсталкер посилає мандрівників оглянути рештки каравану Венчурної Компанії, розгромленого біля північного берега Озера Кам'яного Бика. Хоч таурени й спалили валку, помщаючись за втрачених товаришів, гоблінські збирачі повернулися по вцілілий вантаж. Огляд уцілілих ящиків із припасами відкриває справжній промисловий розмах дій Венчурної Компанії в Малгорі.",h="Морін Клаудсталкер посилає мандрівників оглянути рештки каравану Венчурної Компанії, розгромленого біля...",kw={"караван","венчурна компанія","морін клаудсталкер","озеро кам'яного бика","малгор","гобліни","гірнича справа"},ang={["faction:Horde"]="Нестримне корпоративне просування в Малгор загрожує стабільності Тандер Блафа, тож розвідники Орди мають зірвати постачання Венчурної Компанії.",["profession:Mining"]="Міцні ящики й супровідні записи свідчать про напористу розвідку й видобуток руд, які Венчурна Компанія розгорнула по всьому Малгору.",["race:Tauren"]="Споганення рівнин машинами Венчурної Компанії та вирубка лісу б'ють просто по вашій прабатьківщині, тож повернути й знищити їхні припаси конче важливо для захисту Малгору."},sec={{t="Відплата біля озера",b="Обгорілі рештки на північному березі Озера Кам'яного Бика — слід стрімкого удару тауренів. Оплакуючи двох товаришів, убитих у попередній сутичці, Морін Клаудсталкер зі своїми воїнами влаштував засідку на озброєну валку з припасами Венчурної Компанії. Прагнучи знищити справу зайд, таурени підпалили вози й покинули димуче згарище, певні, що вогонь поглине все, що гобліни хотіли вивезти."},{t="Незавершена справа",b="Невдовзі таурени помітили збирачів Венчурної Компанії, які нишпорили серед почорнілих уламків, — отже, вогонь не знищив найважливішого вантажу. Не бажаючи наосліп ризикувати новими життями, Морін посилає розвідників оглянути згарище. Серед закіптюжених уламків лежать цілі ящики з тавром гірничого відділу Венчурної Компанії — спаковані й призначені для центральних переробних потужностей."}},fp="19,390,23.438.0,19.408.0,30.169.0,37.102.0,46.197.0,33.171.0,26.190.0,56.201.0"}
P.entries["quest:751"] = {n="Сплюндрований караван",s="Огляд розбитої валки в Малгорі відкриває, що гоблінські промисловці незаконно закріпилися на землях тауренів. Діставши документи із запечатаного ящика, розвідники підтверджують: Венчурна Компанія планомірно вигрібає мінеральні багатства краю. Це відкриття спонукає Скороходів Бладгуф стати на дієвий захист прабатьківських рівнин.",h="Огляд розбитої валки в Малгорі відкриває, що гоблінські промисловці незаконно закріпилися на землях тауренів.",kw={"караван","венчурна компанія","документи","морін клаудсталкер","скороходи","село бладгуф","малгор"},ang={["class:Druid"]="Друїди мають рівновагу землі за святиню, тож нищівний, задимлений відкритий видобуток Венчурної Компанії — споганення, яке належить очистити.",["faction:Horde"]="Орда покладається на вірність і стабільність Малгору; дозволити чужим купецьким картелям спустошувати його пагорби означало б загрожувати безпеці самого Тандер Блафа.",["profession:Mining"]="Високоякісні руди в ящику доводять: східні пагорби Малгору ховають багаті підземні жили, до яких уже рвуться чужинці.",["race:Tauren"]="Для тауренів бачити, як груба промислова машинерія роздирає прабатьківські рівнини Малгору, — образа Земній Матері й оголошення війни їхньому новознайденому миру."},sec={{t="Докази визиску",b="Рештки сплюндрованого каравану на схід від Села Бладгуф розповідають тривожну історію. У запечатаному ящику з припасами лежить щільний сховок видобутої руди й мінералів, а поруч — підшивка документів Венчурної Компанії. Ці папери — незаперечний доказ того, що захланна Венчурна Компанія розпочала недозволений видобуток у глибині тихих долин Малгору."},{t="Варта Скороходів",b="Морін Клаудсталкер і його побратими-Скороходи обачно пильнують кордони Малгору, пам'ятаючи про чужі угруповання, що прагнуть нажитися на їхній мирній батьківщині. Передані документи підтверджують найгірші побоювання Моріна: дим над східними передгір'ями знаменує дедалі ширше торгове вторгнення. Тауренам не лишається вибору, окрім як дати відсіч плюндрувальникам, доки їхні пагорби не випотрошено дощенту."}},fp="19,373,24.371.0,21.434.0,39.146.0,26.176.0,38.180.0,32.169.0,40.178.1,34.178.0"}
P.entries["quest:752"] = {n="Скромне завдання",s="«Скромне завдання» — ранній обряд обов'язку, який дає Вождь Гоквінд у Таборі Нарачі. Поки вождь залагоджує нагальні племінні справи на Плато Червоної Хмари, він просить молодого шукача пригод піти на південний схід і навідати його стару матір біля тутешньої криниці. Прохання підкреслює спільну відповідальність, шану до старших і повсякденну гармонію, без якої немислиме життя тауренів.",h="«Скромне завдання» — ранній обряд обов'язку, який дає Вождь Гоквінд у Таборі Нарачі.",kw={"скромне завдання","вождь гоквінд","прамати гоквінд","табір нарачі","криниця","плато червоної хмари","малгор"},ang={["faction:Horde"]="Тихий, пасторальний характер доручень Нарачі показує, як лагідна громадська філософія тауренів відрізняється від суворішої, гартованої виживанням вдачі решти молодої Орди.",["race:Tauren"]="Для молодих тауренських сміливців відгукнутися на поклик вождя означає втілити основи науки Земної Матері: шану до старших і беззастережну відданість спільному добробуту племені."},sec={{t="Громадська злагода й обов'язок",b="У затінку Табору Нарачі кожен член племені має нести свою частку й долучатися до злагоди життя. Для молодих тауренів, що входять у зрілість, племінний обов'язок міряється не лише бойовою вправністю проти шипогривів і хижаків — він починається з простої суспільної відповідальності. Вождь Гоквінд показує це власним прикладом: прикутий до свого поста клопотами управління й оборони, він довіряє новачкам доглянути вразливих старійшин громади."},{t="Криниця на південний схід від Нарачі",b="Плато Червоної Хмари в Малгорі живиться природними криницями, розкиданими за межами табору. Рано-вранці Прамати Гоквінд сама вийшла із селища по свіжу воду до південно-східного джерела. У краю, де підстерігає територіальна звірина й зазіхають шипогриви-Щетиноспини, кількагодинна відсутність старої жінки будить тиху тривогу, тож Гоквінд посилає когось переконатися, що з нею все гаразд."}},fp="13,384,25.487.0,29.432.0,47.166.0,38.125.0,55.242.0,46.215.0,64.231.0,48.151.0"}
P.entries["quest:753"] = {n="Скромне завдання",s="«Скромне завдання» — вступний обряд служіння на Плато Червоної Хмари, де старійшина випробовує смирення й старанність новачка. Несучи свіжу криничну воду через рівнини до провідника Табору Нарачі, молоді таурени осягають: служіння народові починається з найпростіших обов'язків.",h="«Скромне завдання» — вступний обряд служіння на Плато Червоної Хмари, де старійшина випробовує смирення й...",kw={"скромне завдання","прамати гоквінд","вождь гоквінд","вода","табір нарачі","плато червоної хмари","тандер блаф"},ang={["faction:Horde"]="Уроки родини Гоквіндів показують, як таурени зберігають єдність і виживають у Малгорі, утворюючи мирний, але непохитний наріжний камінь Орди Тралла.",["race:Tauren"]="Принести води своїм старшим — утілення основоположної тауренської чесноти громадської турботи; це знак, що ви готові ступити на шлях Земної Матері."},sec={{t="Сила молодості",b="Прамати Гоквінд пройшла за довге життя багато стежок, і хоч дух її лишається твердим, ноги вже не носять її рівнинами з колишньою прудкістю. Облаштувавшись біля криниці на південному краю Плато Червоної Хмари, вона терпляче й рішуче дбає про свої обов'язки. Коли її стежку перетинають майбутні захисники племені, вона спрямовує їхню молоду снагу на практичні потреби громади, даючи змогу довести свою вартість служінням, а не насильством."},{t="Служіння племені",b="Завдання просить посвяченого віднести наповнений глек води назад на північний захід, до Табору Нарачі, й передати його просто в руки провідникові поселення — Вождеві Гоквінду, синові Праматері. У тауренському суспільстві виживання на посушливих рівнинах Малгору вимагає спільної праці й надійних запасів прісної води. Виявити шану до старійшин громади, беручи на себе їхній тягар, вважається наріжним каменем становлення справжнього захисника племені."},{t="Шлях до Тандер Блафа",b="Коли молодий мандрівник приходить із водою від його матері, Вождь Гоквінд бачить у цьому більше, ніж виконану дрібну роботу. За звичаєм тауренів, готовність боронити свій народ на ширших землях починається зі смирення й неспонуканого бажання допомогти. Виявивши цю тиху дисципліну, посвячений привертає увагу вождя й здобуває рекомендацію до прадавніх Обрядів Земної Матері — справжніх духовних випробувань, що відчиняють брами Тандер Блафа."}},fp="13,288,21.500.0,20.469.0,27.468.0,28.220.0,32.178.0,22.203.0,47.236.0,42.202.0,37.209.0"}
P.entries["quest:754"] = {n="Очищення Вінтергуф",s="«Очищення Вінтергуф» — обряд, який Малл Тандергорн у Селі Бладгуф довіряє шукачам пригод Орди. Після того як гоблінські роботи споганили тутешні джерела, освячений тотем треба пронести на землі Венчурної Компанії, щоб очистити Водяну Криницю Вінтергуфів. Відновлення цього джерела — перший важливий крок до зцілення отруєних вод центрального Малгору.",h="«Очищення Вінтергуф» — обряд, який Малл Тандергорн у Селі Бладгуф довіряє шукачам пригод Орди.",kw={"очищення","вінтергуф","криниця","тотем","малл тандергорн","венчурна компанія","малгор"},ang={["class:Druid"]="Негайне повернення спраглої звірини до очищеного джерела доводить, як важливо зцілювати природу всюди, де цивілізація загрожує її сплюндрувати.",["class:Shaman"]="Спрямовувати духів через тотеми, щоб повернути назад неприродне промислове споганення, — сама суть зв'язку шамана з водною стихією.",["faction:Horde"]="Убезпечення запасів прісної води Малгору зміцнює серце земель новоосілих тауренів — південну опору молодої Орди.",["race:Tauren"]="Криниці Малгору — священні джерела життя, даровані Земною Матір'ю; боронити їх від гоблінської захланності — і громадський, і святий обов'язок кожного таурена."},sec={{t="Сплюндрована земля",b="Трав'янисті рівнини Малгору тримаються на тонкій мережі прабатьківських криниць, що напувають і дичину, і розпорошені племена тауренів. Нещодавно безжальні промислові найманці Венчурної Компанії осіли на пагорбах на південний схід від Села Бладгуф. Їхні роботи забруднили тутешні водоносні шари, і Водяна Криниця Вінтергуфів стала смердючою та отруйною. Дикі звірі цураються затруєної води, а поблизькі табори опиняться перед лихом, якщо скверна поповзе землею далі."},{t="Обряд очищення вод",b="Щоб протистояти промисловому бруду, Малл Тандергорн вирізьблює й зачаровує ритуальний тотем очищення, наснажений благословенням Земної Матері. Та щоб доставити ці ліки, доведеться пройти повз озброєних посіпак Венчурної Компанії, які заявили права на джерело. Поставивши тотем просто біля джерела, шукач пригод розвіює огидні стоки, і з надр землі знову здіймається чиста, життєдайна вода."}},fp="20,358,16.505.0,30.432.0,43.191.0,32.227.0,24.205.0,40.212.1,31.195.0,34.192.0"}
P.entries["quest:756"] = {n="Тотем Громового Рогу",s="«Тотем Громового Рогу» — завдання від Малла Тандергорна в Селі Бладгуф: виготовити священний тотем очищення. Щоб побороти гоблінське забруднення, що розповзається криницями Малгору, молоді звитяжці Орди мають зібрати кігті степових хижаків і вплести первісну міць землі в ритуальне дерево.",h="«Тотем Громового Рогу» — завдання від Малла Тандергорна в Селі Бладгуф: виготовити священний тотем очищення.",kw={"тотем","громорог","тандергорн","пазурі","степовий переслідувач","пума","малл тандергорн","малгор"},ang={["class:Hunter"]="Щоб зібрати пазурі, треба розуміти корінних хижаків рівнин і шанувати здобич, оберігаючи рівновагу живого світу.",["class:Shaman"]="Відновлення тотемами спирається на заклик до живих духів землі, щоб очистити воду, споганену неприродним, недбалим промислом.",["race:Tauren"]="Захист водоносних шарів Малгору від чужоземного визиску — священний племінний обов'язок, що відбиває заповіт Земної Матері жити в рівновазі, а не грабувати."},sec={{t="Полювання на степових хижаків",b="Поки промисловий визиск Венчурної Компанії труїть дорогоцінні джерела Малгору, Малл Тандергорн поспіхом готує ліки. Для Очисного Тотема Громорога потрібна природна сутність найзосередженіших мисливців рівнин — степових переслідувачів і рівнинних пум. Беручи пазурі цих хижаків, що блукають на схід і захід від Села Бладгуф, обряд спрямовує сиру, неспотворену хижу снагу звірини просто в тотем."},{t="Природа полювання",b="Тауренська традиція глибоко розрізняє полювання заради прожитку чи духовної рівноваги й гуртове плюндрування, яке чинять гобліни. Малл наголошує: чистота, з якою полюють корінні хижаки, конче потрібна, щоб очистити споганену землю. Там, де гоблінські машини отруюють джерела мастилом і промисловими відходами, природна сила звірів, що змагаються із землею, стає духовним каталізатором для відновлення Водяної Криниці Тандергорнів."}},fp="17,307,28.469.0,22.465.0,46.237.0,39.200.0,58.146.0,50.174.1,66.195.0,72.236.0"}
P.entries["quest:757"] = {n="Обряд Сили",s="Обряд Сили — перше випробування в традиційних Обрядах Земної Матері, які проходять молоді таурени в Таборі Нарачі. Щоб довести хоробрість і готовність боронити плем'я, посвячені мають винищити шипогривів-Щетиноспинів, що зазіхають на Яр Тернистого Клинка, і піднести їхні пояси Вождеві Гоквінду.",h="Обряд Сили — перше випробування в традиційних Обрядах Земної Матері, які проходять молоді таурени в Таборі...",kw={"обряд сили","обряди земної матері","шипогриви","щетиноспини","віщун ґрейтанг","вождь гоквінд","яр тернистого клинка"},ang={["faction:Horde"]="Оборона плато вбезпечує одне з головних місць, де Орда гартує поповнення, щоб молоді воїни й шамани могли спокійно змужніти на допомогу новому союзові.",["race:Tauren"]="Кожен молодий таурен починає свою подорож із цих прадавніх обрядів, доводячи готовність захистити свій народ від загрози шипогривів перед тим, як покинути Плато Червоної Хмари."},sec={{t="Перше випробування",b="Для молодого таурена, що прагне визнання племінних старійшин і, зрештою, прийняття в Тандер Блафі, пройти Обряди Земної Матері — неодмінний обов'язок. Обряд Сили, який дає Віщун Ґрейтанг, слугує відправним випробуванням. Він вимагає тілесної відваги й рішучих дій на захист Плато Червоної Хмари і перевіряє, чи здатен посвячений не здригнувшись стати перед смертельними ворогами племені."},{t="Загроза Щетиноспинів",b="Горнилом цього випробування обрано Яр Тернистого Клинка — зарослу колючками розколину на схід від Табору Нарачі, яку зайняли шипогриви-Щетиноспини. Ці напасливі зайди раз у раз вдираються на прабатьківські землі, нападають із засідок на мисливські загони й під покровом темряви грабують табірні запаси. Убивати їх і забирати їхні пояси — і доказ доблесті, і конечний захід, щоб поселення лишалося в безпеці."}},fp="16,303,15.399.0,22.404.0,44.234.0,34.237.0,37.150.0,40.223.0,44.196.0,49.201.0"}
P.entries["quest:758"] = {n="Очищення Громорога",s="«Очищення Громорога» — важливий духовний обряд у Малгорі, що доручає мандрівникам очистити споганену Водяну Криницю Тандергорнів. Озброєні ритуальним тотемом, який приготував Малл Тандергорн, шукачі пригод відновлюють затруєне джерело, життєво важливе для тутешнього племені. Успішне очищення здобуває щиру вдячність предків Тандергорнів.",h="«Очищення Громорога» — важливий духовний обряд у Малгорі, що доручає мандрівникам очистити споганену Водяну...",kw={"очищення","громорог","тандергорн","криниця","тотем","малл тандергорн","предки","малгор"},ang={["class:Druid"]="Очищення отруєних вод зупиняє поширення скверни живим світом Малгору й зберігає природну гармонію рівнин.",["class:Shaman"]="Спрямовувати силу предків через тотеми, щоб зцілити споганені природні джерела, — сама основа шаманського покликання.",["faction:Horde"]="Допомога тауренам із їхніми священними джерелами зміцнює зв'язок між молодою Ордою та її гордими союзниками шу'хало.",["race:Tauren"]="Відновлення священних джерел вшановує Земну Матір і захищає ваших родичів, поки вони здобувають собі постійний мирний дім у Малгорі."},sec={{t="Затруєна життєва жила",b="Криниці на розлогих рівнинах Малгору — життєві жили кочових племен тауренів, що нещодавно осіли серед трав. Коли підземні джерела затруюють огидні отрути, і звірина, і поблизькі поселення опиняються перед нищівними наслідками. Водяна Криниця Тандергорнів на північ від Села Бладгуф, що стала жертвою забруднення, потребує свідомого духовного втручання, щоб зцілити стражденну землю."},{t="Очищення предків",b="Щоб здолати скверну, Малл Тандергорн виготовляє освячений Очисний Тотем, наснажений духовною силою. Принісши цю реліквію просто до отруєних вод, шукачі пригод спрямовують у джерело силу предків, розсіюють отруту й повертають первозданну природну рівновагу. Малл дістає пряме підтвердження успіху, коли духи предків Тандергорнів навідуються до нього уві сні, щоб висловити свою незгасну вдячність."}},fp="21,345,18.422.0,19.447.0,44.167.0,36.161.0,48.196.0,45.184.0,51.191.0,40.180.0"}
P.entries["quest:759"] = {n="Тотем Вайлдмейнів",s="«Тотем Вайлдмейнів» — третій, останній етап зусиль Малла Тандергорна виготовити тотеми очищення для отруєних криниць Малгору. Щоб відновити Криницю Вайлдмейнів, обряд вимагає підношень від найлютіших природних хижаків краю — ватажків степових вовків.",h="«Тотем Вайлдмейнів» — третій, останній етап зусиль Малла Тандергорна виготовити тотеми очищення для отруєних...",kw={"тотем","вайлдмейн","степові вовки","ватажок","зуби","малл тандергорн","тандер блаф","малгор"},ang={["class:Hunter"]="Вистежування хитрих вовків-ватажків довкола високих стрімчаків випробовує повагу мисливця до дикого краю та його найгостріших хижаків.",["class:Shaman"]="Шаман цінує тонкі обряди, що узгоджують тотеми хижаків зі стихією води, щоб вигнати отруйну заразу.",["race:Tauren"]="Очищення прабатьківських криниць підкреслює обов'язок тауренів виправляти порушену рівновагу довкілля й шанувати жертви, яких вимагає Земна Матір."},sec={{t="Остання криниця",b="Після того як зібрано все потрібне для освячення тотемів криниць Вінтергуфів і Тандергорнів, у центральному Малгорі лишається одне уражене джерело — Криниця Вайлдмейнів. Отруєна вода на рівнинах загрожує і мандрівній звірині, і поселенням, тож для відновлення природної рівноваги землі потрібні могутні первісні складники."},{t="Сила хижака",b="Щоб здолати стійку скверну, що затаїлася в північних водах, Маллу Тандергорну потрібна жертва лютості. Ватажки степових вовків нишпорять травами, надто довкола високих стрімчаків під Тандер Блафом. Їхні зуби вливають невпинний запал і витривалість верховних мисливців Малгору просто у виготовлення тотема очищення."},{t="Жертва й рівновага",b="У духовній традиції тауренів звертання до створінь землі має і чуттєву, і стихійну вагу. Малл бачить у збиранні зубів ватажків не завоювання, а скорботну необхідність, коли жертва хижаків Малгору допомагає зцілити уражені води Земної Матері."}},fp="14,272,14.339.0,23.367.0,21.277.0,38.141.0,55.192.0,47.130.0,21.146.0,48.147.0,44.199.0"}
P.entries["quest:76"] = {n="Яшмова копальня",s="Коли з'ясувалося, що кобольди захопили Копальню Фарґодіп, Маршал Дуґан доручає розвідникам оглянути Яшмову копальню далі на схід. На місці підтверджується найгірше: навала поширилася на життєво важливі рудні жили Елвінну й розтягнула решту захисників Стормвінда понад усяку межу.",h="Коли з'ясувалося, що кобольди захопили Копальню Фарґодіп, Маршал Дуґан доручає розвідникам оглянути Яшмову...",kw={"яшмова копальня","кобольди","маршал дуґан","вежа азори","розвідка","фарґодіп"},ang={["faction:Alliance"]="Одночасна втрата Фарґодіпу та Яшмової копальні оголює, якими крихкими стали рідні землі Стормвінда без централізованої королівської підтримки.",["profession:Mining"]="Для рудокопа бачити багаті підземні жили в лапах шкідників — гірке видовище. Тунелі Яшмової копальні зберігають цінні поклади, та щоб їх добути, доведеться пробиватися крізь рої кобольдів, які бережуть свою територію.",["race:Human"]="Розвідники з людей на власні очі бачать, як повільно розвалюється сільське господарство Елвінну, коли ресурси прикордоння падають просто біля столиці."},sec={{t="Друге вторгнення",b="Здобувши докази, що кобольди заполонили тунелі Фарґодіпу на південь від Ґолдшира, Маршал Дуґан побоювався, що навала не була поодиноким випадком. Яшмова копальня, що притулилася в скелястих передгір'ях на північний схід від Вежі Азори, — ще одне важливе джерело каменю й металу для королівства. Не маючи змоги зняти регулярних вартових Стормвінда з міських патрулів, Дуґан покладається на незалежних шукачів пригод: ті мають рушити на схід і з'ясувати, чи не впало й це місце перед підземними шкідниками зі свічками."},{t="Перенапружена оборона",b="Розвідка глибоких камер Яшмової копальні показує, що кобольди цілком витіснили людей-рудокопів, окопалися й укріпили темні переходи. Для Маршала Дуґана цей похмурий звіт — ще один удар у кризі, що наростає. Король Варіан Рінн зник, королівські війська не доходять до віддалених земель, і місцевому гарнізону бракує людей, щоб зачистити копальні, — серце королівства лишається економічно знекровленим і затиснутим з усіх боків."}},fp="19,314,18.518.0,21.456.0,37.191.0,63.268.0,43.266.0,48.280.0,60.230.0,35.246.0"}
P.entries["quest:760"] = {n="Очищення Вайлдмейнів",s="«Очищення Вайлдмейнів» вінчає ритуальні зусилля тауренів очистити життєво важливі водопої Малгору. За дорученням Малла Тандергорна в Селі Бладгуф герої несуть довершений Тотем Вайлдмейнів на північ, щоб очистити останню отруєну криницю. Вигнання гоблінської отрути повертає рівновагу рівнинам і забезпечує пастуший прожиток племен тауренів.",h="«Очищення Вайлдмейнів» вінчає ритуальні зусилля тауренів очистити життєво важливі водопої Малгору.",kw={"очищення","вайлдмейн","криниця","тотем","малл тандергорн","венчурна компанія","тандер блаф","малгор"},ang={["class:Druid"]="Повернення назад руйнування довкілля гоблінами прямо відбиває заповіт Кола Кенарія зцілювати уражені оселища й захищати зелені пасовища.",["class:Shaman"]="Застосування ритуальних тотемів, щоб скасувати механічне забруднення, — зразок шаманського обов'язку підтримувати злагоду між природними стихіями й живими громадами.",["race:Tauren"]="Відновлення трьох прабатьківських криниць Малгору — основоположний обряд посвяти, що доводить відданість молодого сміливця збереженню дарів Земної Матері."},sec={{t="Очищення дару Земної Матері",b="Вода — священна життєва кров сонячних рівнин Малгору: вона живить стада, ґрунт і кочові племена, що нещодавно зібралися довкола Тандер Блафа. Коли Венчурна Компанія та зайди-гобліни взялися забруднювати ці водоносні шари отруйними промисловими стоками, старійшини тауренів побачили в цьому загрозу самому існуванню. Після очищення криниць Вінтергуфів і Тандергорнів Водяна Криниця Вайлдмейнів лишається третім, останнім споганеним місцем, що потребує духовного втручання."},{t="Тотем Вайлдмейнів",b="Виготовлений із особливих складників, зібраних по всьому краю, Тотем Очищення Вайлдмейн спрямовує відновлювальну силу духів предків і стихії землі. Поставлений біля огидних вод на північ від Тандер Блафа, він розсіює бридкі хімікати, витягає отруту й оживлює природний плин. Довершивши обряд, таурени вберігають свій народ від хвороб і посилають недвозначне послання: плюндрування їхньої священної землі не терпітимуть."}},fp="18,371,33.509.0,18.481.0,41.206.0,41.104.0,36.139.0,54.153.0,34.166.0,60.179.0"}
P.entries["quest:761"] = {n="Полювання на стрімкокрилів",s="«Полювання на стрімкокрилів» — обряд вистежування й влучності, який пропонує Гаркен Віндтотем у Селі Бладгуф. Щоб довести кмітливість і терпіння, мисливцям і мандрівникам пропонують вистежити невловимих птахів на пагорбистих рівнинах Малгору. Повернутися з бездоганними трофейними перами означає виявити і відданість полюванню, і повагу до природних випробувань Земної Матері.",h="«Полювання на стрімкокрилів» — обряд вистежування й влучності, який пропонує Гаркен Віндтотем у Селі Бладгуф.",kw={"стрімкокрил","полювання","пера","гаркен віндтотем","село бладгуф","малгор","мисливець"},ang={["class:Druid"]="Вистежування стрімкокрилів на вітряних плато зближує друїдів із хижими птахами, які підтримують рівновагу в небі Малгору.",["class:Hunter"]="Це полювання — ранній майстер-клас із випередження крилатої здобичі, читання її звичок і точних ударів по пильних хижаках.",["race:Tauren"]="Для тауренської молоді й мандрівників полювання на прудких стрімкокрилів Малгору — шанований обряд посвяти, що гострить чуття слідопита й підтримує прадавні мисливські звичаї."},sec={{t="Випробування гострого ока",b="Трав'янисті степи Малгору кишать звіриною, та мало хто випробовує чуття переслідувача так, як тутешній Стрімкокрил. Ці великі хижі птахи непомітно зливаються з небокраєм і рівнинами, кружляючи вгорі чи низько шугаючи над високою травою. На відміну від вайлуватих довгоступів чи кодо на пасовищі, стрімкокрили вимагають гострої уваги й прудких ніг, щоб їх наздогнати, тож їхнє переслідування — традиційна вправа для молодших мисливців, які прагнуть здобути становище серед племен."},{t="Відзнаки полювання",b="Для Гаркена Віндтотема збирання трофейних пер — не так вилов звірини, як виховання дисципліни. У культурі тауренів носити знаки важко здобутого полювання означає кмітливість і наполегливість. Піднести ці бездоганні пера старійшинам у Селі Бладгуф — значить показати, що шукач пригод здатен годувати й боронити громаду, що його копита прудкі, а чуття досить гострі, щоб опанувати ширший світ."}},fp="13,385,19.466.0,18.451.0,59.252.0,39.172.0,41.246.0,48.215.0,24.192.0,55.222.0"}
P.entries["quest:763"] = {n="Обряди Земної Матері",s="«Обряди Земної Матері» знаменують перехід молодого таурена з відлюдного Плато Червоної Хмари на широкі рівнини Малгору. Коли ви довели свій гарт у Таборі Нарачі, Вождь Гоквінд посилає вас на північ, до Села Бладгуф, із різьбленим тотемом — продовжити прадавні випробування під проводом Бейна Бладгуфа.",h="«Обряди Земної Матері» знаменують перехід молодого таурена з відлюдного Плато Червоної Хмари на широкі...",kw={"обряди земної матері","тотем","вождь гоквінд","бейн бладгуф","село бладгуф","плато червоної хмари","табір нарачі"},ang={["faction:Horde"]="Традиційні обряди зміцнюють племінну єдність по всьому Малгору й гарантують, що нові захисники Орди мають і бойову вправність, і глибоке духовне підґрунтя.",["race:Tauren"]="Кожен молодий таурен має пройти шлях Земної Матері, щоб довести свою вартість старійшинам і знайти місце серед об'єднаних племен."},sec={{t="Прощання з плато",b="Поколіннями молоді таурени випробовували свою силу в безпечній колисці Табору Нарачі на Плато Червоної Хмари. Пройдені перші випробування доводять дисципліну й рішучість вижити, але священні Обряди Земної Матері вимагають значно більшого, ніж уміння впоратися з місцевою звіриною. Вождь Гоквінд бачить, коли посвячений переріс затишні мисливські угіддя плато й має ступити в ширшу громаду."},{t="Знак для Бейна",b="Щоб з'єднати шлях від Нарачі до центральних поселень, Вождь Гоквінд дає різьблений власноруч тотем як знак рекомендації. Несучи цю відзнаку звивистою стежкою до Села Бладгуф, ви стаєте перед Бейном Бладгуфом — молодим вождем села й сином Верховного Вождя Кайрна Бладгуфа. Тотем засвідчує вашу готовність до обрядів духу й мудрості, що чекають попереду."}},fp="24,305,16.421.0,17.420.0,34.199.0,23.201.0,30.219.0,27.170.0,35.185.0,44.246.0"}
P.entries["quest:764"] = {n="Корпорація «Венчур»",s="Огляд сплюндрованого каравану Венчурної Компанії в Малгорі відкриває, що гобліни Венчурної Компанії напористо вгризаються у східні пагорби. Коли їхні офіційні прохання про дозвіл на видобуток рішуче відхилили, компанія все одно взялася довбати землю Земної Матері, і Морін Клаудсталкер замовив смертельну відповідь.",h="Огляд сплюндрованого каравану Венчурної Компанії в Малгорі відкриває, що гобліни Венчурної Компанії напористо...",kw={"венчурна компанія","гобліни","видобуток","морін клаудсталкер","малгор","наглядачі","вторгнення"},ang={["faction:Horde"]="Захист Малгору від торгового визиску скріплює вашу відданість народові Кайрна Бладгуфа, що намагається закріпитися на новій батьківщині.",["profession:Mining"]="Венчурна Компанія діє лише грубим видобутком: зрізає кути й розхитує землю без жодної поваги до природної рівноваги чи безпечного гірничого ремесла.",["race:Tauren"]="Для тауренів Земна Матір священна. Відкритий видобуток Венчурної Компанії — не просто вторгнення, а брутальне споганення прабатьківського дому, що вимагає негайного й рішучого вигнання."},sec={{t="Промислове вторгнення",b="Таурени Малгору шанують землю як продовження Земної Матері й бережуть її незаймані рівнини та врівноважену звірину. Коли Венчурна Компанія звернулася до племен по право підривати й розкопувати пагорби заради сирої руди, її клопотання відхилили беззастережно. Не зважаючи ні на племінні ухвали, ні на чужу територіальну владу, невідступний картель потай завіз важку техніку, робітників і наглядачів просто на східні кряжі Малгору, щоб добувати руду поза законом."},{t="Недвозначне послання",b="Тауренські розвідники на кшталт Моріна Клаудсталкера розуміють: коли кайла вже б'ють у камінь, корпоративну захланність дипломатичними зверненнями не вгамуєш. Маючи документи зі сплюндрованого каравану Венчурної Компанії, які підтверджують її гірничі роботи, Морін посилає звитяжців Орди вирізати і наглядачів, що ляскають батогами, і робітників, що крутять бури. Кривава відплата має змусити Венчурну Компанію порахувати, що ціна вторгнення надто висока."}},fp="15,339,20.472.0,23.485.0,38.269.0,40.215.0,42.253.0,54.219.0,50.237.0,46.224.0"}
P.entries["quest:765"] = {n="Наглядач Фіззпрокет",s="Наглядач Фіззпрокет — високопоставлений доглядач Венчурної Компанії, що засів у гірничих тунелях Малгору. За дорученням Моріна Клаудсталкера покласти край розрахованому грабунку гоблінського підприємства шукачі пригод Орди входять до копальні, щоб знищити його й забрати його докладну дошку з записами.",h="Наглядач Фіззпрокет — високопоставлений доглядач Венчурної Компанії, що засів у гірничих тунелях Малгору.",kw={"фіззпрокет","наглядач","венчурна компанія","копальня","морін клаудсталкер","малгор","гобліни"},ang={["faction:Horde"]="Допомога тауренам проти корпоративних грабіжників зміцнює захист Орди над щойно здобутими серцевинними землями Калімдору.",["race:Tauren"]="Відкритий задум Венчурної Компанії виселити ваше плем'я й розграбувати священну землю робить убивство Фіззпрокета актом життєво важливої оборони території."},sec={{t="Змова проти рівнин",b="Документи зі знищеного каравану Венчурної Компанії відкрили: Венчурна Компанія не просто копала руду — вона свідомо виношувала плани цілком вигнати тауренів із Малгору. Викорінивши тубільців, захланна корпорація прагнула нестримної свободи обдирати пагорби й глибокі підземні жили до останньої крихти природних багатств."},{t="Удар по старшому",b="Морін Клаудсталкер, розлючений корпоративними звірствами, замисленими проти його народу, посилає звитяжців до копальні Венчурної Компанії одразу на схід від сплюндрованих торгових возів. Глибоко в правих тунелях, в оточенні робітників і менших начальників, роботами керує Наглядач Фіззпрокет. Здолати Фіззпрокета й забрати його дошку з записами означає розірвати місцеву злагодженість і здобути важливі відомості про подальші задуми компанії."}},fp="22,298,25.371.0,21.456.1,30.251.0,50.232.0,40.207.0,54.160.0,38.219.0,67.204.0"}
P.entries["quest:767"] = {n="Обряд видіння",s="Обряд видіння — ключове випробування дорослішання в Обрядах Земної Матері, що перевіряє духовну зрілість молодого шукача пригод. Розпочате Бейном Бладгуфом, завдання спрямовує претендентів по пораду до сільського провидця Зарлмана Ту-Мунса. Ця подорож неодмінна для кожного, хто прагне благословення й поваги старійшин на узвишшях Тандер Блафа.",h="Обряд видіння — ключове випробування дорослішання в Обрядах Земної Матері, що перевіряє духовну зрілість...",kw={"обряд видіння","обряди земної матері","зарлман ту-мунс","бейн бладгуф","село бладгуф","провидець","духи"},ang={["class:Druid"]="Єднання з видіннями Земної Матері прямо зміцнює друїдське покликання уважно слухати мудрість і шепіт живого світу.",["class:Shaman"]="Пошук Зарлмана Ту-Мунса й шлях видінь глибоко суголосні шаманському обов'язку узгоджувати мирські справи з волею предків.",["faction:Horde"]="Проходження цих традиційних священних обрядів доводить вашу вірність і культурну шану тауренським старійшинам, які допомагають вести Орду.",["race:Tauren"]="Обряд видіння — неодмінна культурна віха для кожного молодого таурена, що знаменує ваше перетворення на довіреного захисника й духоходця племен."},sec={{t="Священна сходинка",b="Поколіннями кочові таурени зверталися до Земної Матері, щоб вона вела їхній народ рівнинами Калімдору. Тепер, зібравшись у безпечних межах Малгору, вони зберігають духовні традиції як наріжний камінь свого суспільства. Обряд видіння — одне з прадавніх випробувань, відомих як Обряди Земної Матері. Якщо попередні випробування перевіряють тілесну силу посвяченого і зв'язок із полюванням, то Обряд видіння вимагає подорожі всередину себе й спрямовує молодих тауренів і шанованих союзників безпосередньо до єднання з духами."},{t="Настанова провидця",b="Перш ніж шукати будь-якого духовного видіння, посвяченого має підготувати хтось обізнаний у прадавній мудрості. У Селі Бладгуф цей обов'язок лягає на шанованого шамана Зарлмана Ту-Мунса. Бейн Бладгуф довірив йому готувати мандрівників, і Зарлман має гострий зір, щоб розпізнати тих, хто ступає шляхом предків, і провести попередні обряди та священні приготування, потрібні, щоб пронизати заслону тілесного світу."}},fp="14,381,23.535.0,19.443.0,27.255.0,22.205.0,25.190.0,61.255.0,44.208.0,33.154.0"}
P.entries["quest:770"] = {n="Плащ зі шрамом від демона",s="Плащ зі шрамом від демона — Демоноспоганений Плащ, подерта шкура легендарного білого вовка на ім'я Примарне Виття, що блукає трав'янистими рівнинами Малгору. Позначена незагойною раною від давніх сутичок із Палаючим Легіоном, шкура свідчить, що звіра звільнено від мук. Принести її старійшинам Села Бладгуф означає завершити історію трагічної місцевої легенди.",h="Плащ зі шрамом від демона — Демоноспоганений Плащ, подерта шкура легендарного білого вовка на ім'я Примарне...",kw={"примарне виття","вовк","плащ","демон","палаючий легіон","скорн вайтклауд","село бладгуф","малгор"},ang={["class:Druid"]="Друїди бачать у споганеній демоном шкурі похмуре нагадування: земля та її дикі мешканці досі носять незагоєні рани від демонічного вторгнення в Калімдор.",["class:Hunter"]="Вистежити самотнього пошрамованого ватажка, як-от Примарне Виття, — неодмінний обряд посвяти, що здобуває високу похвалу й дарунок майстра-мисливця від старійшини Скорна Вайтклауда.",["race:Tauren"]="Для шу'хало полювання на Примарне Виття — не жорстокість і не завоювання, а скорботний обряд, що дарує змученому створінню спокій від незгасної скверни Палаючого Легіону."},sec={{t="Реліквія ран Скверни",b="Примарне Виття — невловимий білий вовк, відомий по всьому Малгору і лютістю, і тужливим виттям. Коли звіра вбивають, по ньому лишається шкура, помітно пошрамована огидною демонічною скверною. Ці незгасні сліди сягають відчайдушних боїв вовка з демонами-загарбниками Палаючого Легіону — зіткнення, що лишило Примарне Виття зраненим і тілом, і духом ще довго після кінця Третьої війни."},{t="Спокій для змученого духу",b="Таурени Малгору глибоко шанують диких звірів своєї батьківщини як дітей Земної Матері. Піднесений Скорну Вайтклауду в Селі Бладгуф пошрамований плащ підтверджує загибель змученого хижака. Скорн визнає, якої величезної майстерності треба, щоб вистежити й здолати Примарне Виття, і висловлює скорботну надію: у смерті замордований дух вовка нарешті знайшов спокій."}},fp="23,378,21.424.0,27.421.0,32.174.0,49.141.0,28.104.0,48.224.0,26.172.0,53.220.0"}
P.entries["quest:771"] = {n="Обряд видіння",s="Обряд видіння — основоположне духовне випробування, яке проходять молоді таурени, виходячи з Плато Червоної Хмари у великий Малгор. Щоб пронизати заслону й дістати настанову духів предків, посвячені мають зібрати природні складники й зварити Воду Провидців під пильним оком Зарлмана Ту-Мунса в Селі Бладгуф.",h="Обряд видіння — основоположне духовне випробування, яке проходять молоді таурени, виходячи з Плато Червоної...",kw={"обряд видіння","вода провидців","зарлман ту-мунс","криничні камені","бурштиновий жолудь","село бладгуф","малгор"},ang={["class:Druid"]="Друїди глибоко шанують бурштинові жолуді й криничні камені, бачачи в них прямі прояви рослинності й життєдайних вод, що підтримують рівновагу Малгору.",["class:Shaman"]="Шаман упізнає в приготуванні Води Провидців традиційний обряд укорінення, що настроює дух читати незриме перед прямою розмовою з духами.",["race:Tauren"]="Для тауренів Обряд видіння — неодмінна культурна віха, що пов'язує майбутнього воїна, мисливця чи містика з духовним спадком Земної Матері й предків."},sec={{t="Складники землі",b="Перш ніж дістати видіння, посвячений має показати глибоке знання природних дарів Малгору. Зарлман Ту-Мунс велить шукачеві зібрати криничні камені біля священних громадських криниць і бурштинові жолуді, що впали під корінням прадавніх дерев Малгору. Для тауренів це не прості речі: вони містять приховану магію й життєву кров Земної Матері, готову влитися в обряд."},{t="Варіння Води Провидців",b="Із зібраних каменів і бурштинових жолудів Зарлман готує могутню Воду Провидців. Випитий біля племінного вогню села, цей обрядовий напій прояснює розум і прикликає безтілесного провідника. Іти за цією проявою через рівнини — справжнє серце обряду, що випробовує здатність посвяченого ходити між тілесним світом і духовним шепотом землі."}},fp="14,335,24.476.0,30.397.0,42.238.0,25.234.0,42.210.0,51.214.1,47.219.0,38.207.1"}
P.entries["quest:772"] = {n="Обряд видіння",s="Обряд видіння — духовна кульмінація прадавнього випробування, яке проходять молоді таурени в Селі Бладгуф. Випивши священну Воду Провидців біля племінного багаття, посвячені прикликають примарного провідника, який веде їх назустріч долі.",h="Обряд видіння — духовна кульмінація прадавнього випробування, яке проходять молоді таурени в Селі Бладгуф.",kw={"обряд видіння","вода провидців","примарний вовк","віщун вайзраннер","зарлман ту-мунс","село бладгуф","малгор"},ang={["class:Druid"]="Обряд зміцнює шану до природного світу й духовне смирення перед проводом звіриних подоб.",["class:Shaman"]="Іти за духовним вовком предків — ранній урок ходіння між світами, що закорінює зв'язок шамана з духами, які ведуть Орду.",["race:Tauren"]="Для молодих тауренів Обряд видіння — глибоко священний перехід у зрілість, що засвідчує єднання з предками й покору духовному проводу."},sec={{t="Вода Провидців",b="Коли потрібне обрядове зілля зібрано, а перші випробування віри пройдено, сільський шаман Зарлман Ту-Мунс дарує посвяченому Воду Провидців. Цей могутній напій треба випити перед ревучим племінним вогнем у серці Села Бладгуф. Спожиті із зосередженим і шанобливим розумом, священні води розширюють сприйняття питця поза тілесний зір, перекидаючи міст через заслону між матеріальним і духовним світами."},{t="Слідом за примарним вовком",b="Щойно напій випито, полум'я являє безтілесну з'яву — примарного вовка предків. Дух не говорить і не б'ється, а мовчки біжить на північний захід пагорбистими рівнинами Малгору. Справжній посвячений має зважати на його тиху стежку, йдучи за ним геть від села в глиб скелястих пагорбів, де в усамітненому спогляданні чекає відлюдник Віщун Вайзраннер."},{t="Хода до мудрості",b="Дістатися Віщуна Вайзраннера біля входу до його гірської печери означає успішно завершити видіння. Ця подорож трав'янистими пагорбами випробовує терпіння посвяченого, довіру до проводу предків і єднання із Земною Матір'ю. Пройдений обряд дає молодому шукачеві пригод право на останнє випробування зрілості — Обряд Мудрості."}},fp="14,249,22.467.0,24.371.0,16.362.0,49.192.0,36.150.0,25.171.0,23.189.0,49.197.0,41.173.0"}
P.entries["quest:773"] = {n="Обряд Мудрості",s="Обряд Мудрості — завершальне випробування в традиційних Обрядах Земної Матері, які проходять молоді шукачі пригод у Малгорі. Очистивши свій зір Обрядом видіння, прохачі вирушають до священного поховання Червоних Скель, щоб поєднатися з Духом предків і дістати благословення мертвих.",h="Обряд Мудрості — завершальне випробування в традиційних Обрядах Земної Матері, які проходять молоді шукачі...",kw={"обряд мудрості","червоні скелі","дух предків","поховання","обряди земної матері","тандер блаф","кайрн бладгуф"},ang={["class:Druid"]="Обряд показує рівновагу між живим світом і вічним колом, яке наглядає Земна Матір, і закорінює молодих друїдів у їхньому обов'язку перед землею.",["class:Shaman"]="Пряме єднання з Духом предків зміцнює основний шаманський обов'язок шанувати мертвих і берегти вірність духам, що пильнують Малгор.",["race:Tauren"]="Для шу'хало прийняти мантію від предків на Червоних Скелях — вершина переходу в повну зрілість і визнання серед племінних старійшин."},sec={{t="Випробування Червоних Скель",b="Прояснивши сприйняття Обрядом видіння, молоді захисники вирушають на схід від Тандер Блафа, до Червоних Скель. Це прадавнє поховання береже тлінні рештки й незгасні духи тих, хто бився й поліг, щоб вибороти мирне життя в Малгорі. Щоб пройти випробування, треба наблизитися до місця спочинку з належною шаною і єднанням, здолавши будь-які територіальні загрози, що блукають пагорбами, і просити поради в шанованих мертвих."},{t="Передання мантії",b="На вершині Червоних Скель єднання з Духом предків — випробування не бойової сили, а духовної готовності й тяглості. Духи, що спочивають там, — покоління, яке билося пліч-о-пліч із Кайрном Бладгуфом, щоб заснувати Тандер Блаф і вберегти племена. Діставши їхнє благословення, прохач офіційно успадковує урочистий обов'язок захищати місто й здобуває місце визнаного дорослого й захисника, гідного з гордістю ввійти в Тандер Блаф."}},fp="14,321,22.468.0,18.492.0,42.310.0,36.186.0,39.137.0,41.175.0,49.138.0,49.160.0"}
P.entries["quest:775"] = {n="Подорож до Громового Бескиду",s="«Подорож до Громового Бескиду» — завершальне паломництво, що знаменує кінець випробувань молодого героя в Малгорі. Пройшовши священні Обряди Земної Матері під проводом духів, шукач пригод дістає аудієнцію у Верховного Вождя тауренів Кайрна Бладгуфа в Тандер Блафі.",h="«Подорож до Громового Бескиду» — завершальне паломництво, що знаменує кінець випробувань молодого героя в...",kw={"тандер блаф","кайрн бладгуф","верховний вождь","високе узвишшя","обряди земної матері","дух предків","паломництво"},ang={["faction:Horde"]="Готовність тауренів приймати будь-кого з союзних народів, хто пройде їхні священні традиції, промовляє про взаємну повагу, що тримає молоду Орду вкупі.",["race:Tauren"]="Для молодого таурена стати перед Кайрном Бладгуфом після обрядів Земної Матері — остаточний поріг зрілості й племінної честі."},sec={{t="Завершений обряд посвяти",b="Перш ніж будь-який мандрівник чи молодий воїн зможе по праву сказати, що довів себе в Малгорі, він має пройти прадавні Обряди Земної Матері. Ці випробування перевіряють силу, зір і мудрість на пагорбистих рівнинах і прабатьківських місцях краю. Щойно Дух предків визнає останній обряд, посвяченого вважають гідним увійти до міста Тандер Блаф не простим гостем, а шанованим захисником народу тауренів."},{t="Сходження на Високе Узвишшя",b="Завдання веде мандрівника зі священної землі, де блукають духи, просто на височінь Тандер Блафа. Місто, що вмостилося на верхівках плато, — маяк миру, витесаний із червоного каменю й з'єднаний розмашистими мотузяними мостами та величезними дерев'яними підйомниками. Там, на Високому Узвишші, Верховний Вождь Кайрн Бладгуф чекає, щоб особисто привітати тих, хто пройшов шляхом предків."}},fp="26,296,27.451.0,26.407.0,30.141.0,34.138.0,50.216.0,37.208.0,38.141.0,48.197.0"}
P.entries["quest:780"] = {n="Бойові вепри",s="«Бойові вепри» — мисливське завдання-посвята, яке дає Ґрулл Гоквінд у Таборі Нарачі. Молодим тауренам доручають винищити лютих, вишколених для війни вепрів Яру Тернистого Клинка, щоб захистити племінні землі й нагодувати молодь поселення.",h="«Бойові вепри» — мисливське завдання-посвята, яке дає Ґрулл Гоквінд у Таборі Нарачі.",kw={"бойові вепри","ґрулл гоквінд","табір нарачі","яр тернистого клинка","шипогриви","щетиноспини","юшка"},ang={["class:Hunter"]="Зіткнення зі звірами, яких Щетиноспини вишколили для злоби, вчить молодих мисливців гострої різниці між природною звіриною й тваринами, перекрученими на зброю війни.",["profession:Cooking"]="Прохання про боки й рила показує основу тауренської кухні: грубе, жорстке м'ясо завжди можна уварити в ситну, поживну юшку.",["race:Tauren"]="Це завдання втілює тауренську рівновагу: боронити землі Земної Матері й не марнувати нічого здобутого в бою, обертаючи бойових звірів ворога на харч для телят табору."},sec={{t="Загроза на кордоні",b="На схід від Плато Червоної Хмари лежить Яр Тернистого Клинка — зарослий колючками рубець, який тримають шипогриви-Щетиноспини. Поки напруга між шу'хало й шипогривами переростає у відкриту війну, Щетиноспини вишколили лютих бойових вепрів, щоб промацувати тауренські рубежі й тероризувати їхні споконвічні мисливські угіддя. Якщо їх не спинити, ці напасливі звірі загрожують не лише стежкам дичини, а й безпеці самого Табору Нарачі."},{t="Нагодувати плем'я",b="Для тауренів полювання — і оборонна потреба, і прожиток громади. Ґрулл Гоквінд велить посвяченим принести рила й боки вбитих бойових вепрів. Навіть звірів, вишколених руками шипогривів, не марнують: їхнє м'ясо й хрящі йдуть на ситну юшку для молоді племені, і зброя шипогривів обертається на поживу для наступного покоління захисників-тауренів."}},fp="15,237,22.418.0,17.402.0,43.234.0,31.147.0,32.137.0,50.191.0,57.232.0,36.132.0"}
P.entries["quest:781"] = {n="Напад на Табір Нараче",s="«Напад на Табір Нараче» — важливе відкриття, зроблене в лігві шипогривів у Яру Тернистого Клинка. Забруднена мапа відкриває, що напасливе плем'я Щетиноспинів діяльно замишляє злагоджену облогу Табору Нарачі. Доставка цих планів Вождеві Гоквінду вчасно попереджає Табір Нарачі, щоб той прикликав допомогу із Села Бладгуф.",h="«Напад на Табір Нараче» — важливе відкриття, зроблене в лігві шипогривів у Яру Тернистого Клинка.",kw={"напад","табір нарачі","мапа","шипогриви","щетиноспини","вождь гоквінд","облога","яр тернистого клинка"},ang={["faction:Horde"]="Збереження опори тауренів у Малгорі гарантує Орді її життєво важливий південний якір у центральному Калімдорі.",["race:Tauren"]="Для молодих тауренських сміливців, що проходять перші обряди на плато, перехоплення цієї мапи доводить вашу вірність племені й захищає родичів від раптової різанини."},sec={{t="Змова в терновищі",b="Розвідуючи глибини печер Яру Тернистого Клинка, молоді тауренські шукачі пригод знаходять на кам'яній долівці грубу, забруднену мапу. Придивившись, вони бачать на пергаменті свідомі тактичні позначки шипогривів-Щетиноспинів. Замість принагідних сутичок шипогриви готують повномасштабну тривалу облогу Табору Нарачі."},{t="Застерегти вождя",b="Принесені до Табору Нарачі плани нападу дають Вождеві Гоквінду вкрай важливі відомості. Усвідомлюючи грізну загрозу для майже беззахисного табору та його молодих посвячених, Гоквінд готується послати до Села Бладгуф по підкріплення. Перехоплена мапа обертає те, що могло стати згубною засідкою, на підготовлену оборону."}},fp="22,330,22.393.0,21.361.0,45.143.0,42.85.0,56.152.0,50.168.0,69.149.0,35.185.0"}
P.entries["quest:783"] = {n="Загроза зсередини",s="«Загроза зсередини» — початок служби для захисників, що відгукнулися на поклик Стормвінда в Долині Нортширу. Направлені в Абатство Нортшира до Маршала Макбрайда, свіжі добровольці дізнаються: військо королівства розпорошене за кордоном, і місцеві гарнізони не впораються з домашніми клопотами без допомоги цивільних.",h="«Загроза зсередини» — початок служби для захисників, що відгукнулися на поклик Стормвінда в Долині Нортширу.",kw={"загроза зсередини","маршал макбрайд","нортшир","новобранці","абатство","стормвінд"},ang={["faction:Alliance"]="Завдання підкреслює напругу, з якою стикається Великий Альянс: військові зобов'язання на далеких територіях лишають навіть найбезпечніші серцевинні землі вразливими до розпаду зсередини.",["race:Human"]="Нортшир — початкова долина для захисників із людей, тож відгукнутися на поклик Маршала Макбрайда означає скласти свою першу офіційну обітницю захищати батьківщину й Королівство Стормвінд."},sec={{t="Королівство, розтягнуте до краю",b="Долина Нортширу колись була тихим притулком, присвяченим молитві, землеробству й чернечій науці. Сьогодні вона — перша лінія оборони від внутрішніх заворушень у Лісі Елвінн. Регулярні сили Стормвінда розкидані далекими фронтами, і серце столичних земель небезпечно оголене. Офіційних солдатів на місці обмаль, тож вартові Стормвінда мусять набирати кожного охочого добровольця, що з'являється біля брами абатства."},{t="Поклик маршала",b="В Абатстві Нортшира Маршал Макбрайд керує обороною долини під дедалі більшим тиском з усіх боків. Поки чужоземні небезпеки загрожують Альянсу здалеку, бандити, шкідники й підземні паразити користаються з безвладдя просто на порозі королівства. Відгукнутися на цей поклик означає одразу стати до військової служби: спершу очистити найближчі околиці абатства, а потім узятися за глибшу гниль, що пускає коріння по всьому Елвінну."}},fp="15,323,24.457.0,18.466.0,34.210.0,23.230.0,75.292.0,54.256.0,37.227.0,62.272.0"}
P.entries["quest:784"] = {n="Знищити зрадників",s="Знищити зрадників — військовий удар Орди, який наказує Ґар'Ток із Гострого Пагорба, щоб відбити Фортецю Тіраґард у людських загарбників. Сили Кул Тірасу під проводом лейтенанта Бенедикта знову зайняли твердиню, відверто порушивши крихкий мир між Дуротаром і Терамором. Знищення їхнього гарнізону вкрай важливе, щоб убезпечити східне узбережжя орківської батьківщини.",h="Знищити зрадників — військовий удар Орди, який наказує Ґар'Ток із Гострого Пагорба, щоб відбити Фортецю...",kw={"ґар'ток","фортеця тіраґард","бенедикт","кул тірас","гострий пагорб","праудмур"},ang={["faction:Horde"]="Окупація Фортеці Тіраґард Кул Тірасом — це тривалий акт війни просто на порозі Дуротару. Знищення сил Бенедикта доводить, що Орда здатна захистити щойно заселений дім від чужоземних флотів.",["race:Orc"]="Орки шанують перемир'я, укладене з Джайною на горі Гіджал, та Кул Тірас повертає гіркі спогади про Другу війну. Відбиття морських піхотинців Бенедикта — справа виживання й гордості предків.",["race:Troll"]="Фортеця Тіраґард лежить тривожно близько до поселення Темного Списа — Села Сен'джин. Вибивши звідти ворожих моряків, ви напряму захищаєте вразливий новий дім тролів."},sec={{t="Розірване перемир'я",b="Коли Тралл повів Орду через Велике Море до Калімдору, він уклав непевний союз із леді Джайною Праудмур, щоб здолати Палаючий Легіон на горі Гіджал. Той мир розбився, коли відчужений батько Джайни, великий адмірал Делін Праудмур, прибув із грізним флотом Кул Тірасу. Звинувачуючи всіх орків у звірствах Старої Орди, адмірал вторгся в Дуротар і захопив прибережні опорні пункти, зокрема Фортецю Тіраґард. Хоч Делін зрештою загинув у Тераморі, рештки його флоту відмовляються шанувати будь-яку угоду чи зректися своєї ненависті."},{t="Відродження Бенедикта",b="Після загибелі великого адмірала Фортеця Тіраґард ненадовго впала, та резерви Кул Тірасу під проводом лейтенанта Бенедикта відтоді знову захопили твердиню. З цього укріпленого редуту між Гострим Пагорбом і Селом Сен'джин моряки й морські піхотинці нападають на подорожніх і загрожують східним морським підступам. Ґар'Ток бачить у їхніх окопаних позиціях безпосередню небезпеку для Дуротару й закликає воїнів Орди вдарити просто по командуванню Бенедикта."}},fp="22,366,17.559.0,21.469.0,43.323.0,27.292.0,43.277.0,32.304.0,32.240.0"}
P.entries["quest:786"] = {n="Зупинити агресію Колкарів",s="Зупинити агресію Колкарів — життєво важлива оборонна місія Орди, яку доручає розвідник Лар Праултаск біля Села Сен'джин. Гравцям належить проникнути на Кручу Колкарів і знищити три комплекти узгоджених планів вторгнення, перш ніж клан кентаврів ударить по молодих поселеннях Дуротару.",h="Зупинити агресію Колкарів — життєво важлива оборонна місія Орди, яку доручає розвідник Лар Праултаск біля...",kw={"колкари","кентаври","лар праултаск","круча колкарів","село сен'джин","вторгнення"},ang={["faction:Horde"]="Зрив наступу Колкарів рятує молоду Орду від виснажливої війни на кілька фронтів просто на порозі її нового дому.",["race:Orc"]="Долина Випробувань — місце, де молоді орки проходять обряди дорослішання, тож агресія кентаврів там — це образа самої суті орківської воїнської культури.",["race:Troll"]="Уже втративши свій давній острівний дім, тролі Темного Списа не можуть дозволити, щоб Село Сен'джин затопили кентаври-грабіжники."},sec={{t="Нависла навала",b="Розвідуючи західний Дуротар, троль-слідопит Лар Праултаск під покровом ночі прокрався на Кручу Колкарів. Те, що він побачив, стривожило його: кентаври Колкари не просто чинили безладні набіги на узбережжя, а готували зухвале вторгнення трьома ударами, націлене просто на землі орків і Темного Списа. Воєначальники кентаврів розділили свої бойові задуми між трьома ватажками, маючи намір ударити по Долині Випробувань, Селу Сен'джин і самих воротах Оргріммару."},{t="Удар по каньйонах",b="Щоб відвернути спустошливу війну серед сухих червоних каньйонів Дуротару, новобранців посилають углиб Кручі Колкарів відтяти голову змії. Проникнення в запилений табір і спалення трьох сувоїв з планами нападу ламає ланцюг командування кентаврів. Хоч Лар Праултаск упевнений, що Орда неминуче розчавила б будь-яке повномасштабне вторгнення, знищення цих документів позбавляє захисників Дуротару дорогої ціни крові, поки їхня молода держава ще тільки стає на ноги."}},fp="27,294,18.498.0,20.475.0,49.137.0,55.154.0,29.121.0,49.157.0,41.207.0,43.179.0"}
P.entries["quest:787"] = {n="Нова Орда",s="Нова Орда — вступне завдання в Долині Випробувань, яке дає воїн-ветеран Ейтріґґ. Воно скеровує новобранців до Ґорнека в Лігві, щоб розпочати навчання. Через цей короткий виклик Ейтріґґ ділиться власною історією та провідним баченням Тралла — Орди, що здобула спокуту.",h="Нова Орда — вступне завдання в Долині Випробувань, яке дає воїн-ветеран Ейтріґґ.",kw={"ейтріґґ","нова орда","тралл","ґорнек","долина випробувань","лігво"},ang={["faction:Horde"]="Це завдання втілює засадничий дух правління Тралла: цілковитий розрив із демонічним рабством на користь честі, виживання й сутності предків.",["race:Orc"]="Для молодих орків, що ступають у Долину Випробувань, Ейтріґґ — жива пам'ять про трагічне минуле їхнього народу та його спокуту під проводом Тралла.",["race:Troll"]="Тролі Темного Списа навчаються пліч-о-пліч з орками в Долині Випробувань, прийнявши бачення Тралла про спільне виживання й честь."},sec={{t="Повернення ветерана",b="Ейтріґґ стоїть у Долині Випробувань за наказом Вождя Тралла, щоб оцінювати й наставляти найновіших претендентів Орди. Покинувши Стару Орду після Другої війни, розчарований її розбещенням Палаючим Легіоном, Ейтріґґ жив у тихому вигнанні, доки його не полонили люди. Врятований Траллом, він вирішив повернутися, дізнавшись про мрію молодого Вождя: шляхетна Орда, вкорінена в шаманізмі предків і цілком відірвана від демонічних господарів."},{t="Прибуття до Лігва",b="Перш ніж будь-який новобранець зможе вийти за межі суворих каньйонів Долини Випробувань, він має довести свою стійкість. Ейтріґґ посилає новачків у затінену печеру, відому як Лігво, поговорити з Ґорнеком. Хоч Ґорнек рідко добирає слова, говорячи про жалюгідний стан новоприбулих, його нагляд дбає про те, щоб у ширші землі Дуротару пускали лише тих, хто опанував дисципліну й виживання."}},fp="13,299,18.465.0,20.397.0,15.378.0,44.288.0,24.139.0,39.181.0,23.179.0,49.232.0"}
P.entries["quest:791"] = {n="Внеси свою частку",s="Внеси свою частку — вступне завдання, яке пропонує Фурл Скорнброу з вершини сторожової вежі над Гострим Пагорбом. Надто старий, щоб битися на передовій, укритий шрамами ветеран просить молодих шукачів пригод Орди здобути полотно в тутешніх ворожих людей і кентаврів, щоб пошити спорядження на поміч у їхній дорозі.",h="Внеси свою частку — вступне завдання, яке пропонує Фурл Скорнброу з вершини сторожової вежі над Гострим...",kw={"фурл скорнброу","гострий пагорб","полотно","ветеран","сторожова вежа","торби"},ang={["faction:Horde"]="Кожен молодий воїн у Дуротарі покладається на загартованих ветеранів, як-от Фурл Скорнброу, які нагадують новачкам: шанувати Орду — означає виконувати будь-який обов'язок, якого вимагає батьківщина, чи то вартувати заставу, чи шити полотно.",["profession:Tailoring"]="Фурл показує практичне, суворе кравецтво рубежу: він перетворює покинуте грубе полотно людських загарбників і кентаврів-нападників на міцне спорядження для виживання в дикій природі.",["race:Orc"]="Фурл утілює старше покоління орків, які вирвалися з демонічного розбещення, перетнули море з Траллом і тепер присвячують останні роки вихованню майбутнього своєї молодої держави."},sec={{t="Покликання ветерана",b="Фурл Скорнброу — ветеран Третьої війни, що крокував пліч-о-пліч із Вождем Траллом під час освоєння Дуротару й відчайдушної оборони гори Гіджал. Нині, сповільнений віком і старими ранами, він більше не здіймає сокиру в бою. Натомість він несе невпинну варту на сторожовій вежі Гострого Пагорба, здіймаючи тривогу при вторгненнях і підтримуючи нове покоління захисників."},{t="Здобуте полотно",b="Що міцніше Орда тримає цей край, то рідше лунає сигнальний ріг, тож Фурл заповнює години виготовленням корисного спорядження. Міцне полотно важко дістати в посушливих каньйонах Дуротару, та його вдосталь мають і кул-тіраські зайди на східному узбережжі, і кочові кентаври Колкари, що блукають рівнинами. Клапті, здобуті в цих ворожих сил, дають Фурлові тканину, щоб зшивати практичні торби для розвідників на службі."}},fp="17,302,19.390.0,16.458.0,22.359.0,44.251.0,46.190.0,44.239.0,56.310.0,27.327.0"}
P.entries["quest:792"] = {n="Мерзенні прислужники",s="Мерзенні прислужники — раннє завдання, яке Зуріта Фарґейз дає щойно прибулим героям у Долині Випробувань. Наглядаючи за випробуваннями долини, Зуріта виявила підступний ковен Палаючого Клинка, що ховається в сусідній печері. Щоб спинити їхнє раптове поширення, новобранців посилають винищувати демонічних прислужників, які виповзають на червону землю Дуротару.",h="Мерзенні прислужники — раннє завдання, яке Зуріта Фарґейз дає щойно прибулим героям у Долині Випробувань.",kw={"зуріта фарґейз","палаючий клинок","прислужники","біси","долина випробувань","демони"},ang={["class:Warlock"]="Чорнокнижники-орки й тролі мають зіткнутися з правдою про відступників-тіньовиків, які зловживають демонічними угодами заради руйнування, замість спрямовувати сили скверни на виживання Орди.",["faction:Horde"]="Палаючий Клинок — одна з найгостріших внутрішніх загроз Дуротару: він прагне згноїти молоду Орду зсередини, перш ніж вона міцно утвердить свою незалежність.",["race:Orc"]="Для орків, що прагнуть шанувати Траллову відмову від демонічного рабства, зустріч зі скверною на їхніх священних тренувальних землях — гірке нагадування, що спадок Ради Тіней досі гноїться."},sec={{t="Тінь над долиною",b="Долина Випробувань має бути місцем, де молоді орки й тролі Темного Списа доводять свою силу, дисципліну й вірність Орді Тралла. Її призначення — випробовувати новобранців проти тутешніх хижаків, як-от скорпідів і вепрів, а не проти демонічного розбещення. Та в печері на північному сході агенти, що звуть себе Палаючим Клинком, заснували таємний ковен просто під пильним оком наглядачів долини."},{t="Винищення бісів",b="Зуріта Фарґейз, наставниця, послана допомагати новачкам біля Лігва, помітила ледь відчутну скверну, перш ніж та встигла затопити каньйон. Дрібні демонічні створіння, відомі як мерзенні прислужники, почали виповзати з пащі печери, жбурляючи вогонь і погрожуючи кожному, хто підійде надто близько. Перш ніж Орда зможе викорінити господарів, що ховаються в тінях, молодим новобранцям доручають винищити цих нижчих слуг, щоб долина лишалася безпечною."}},fp="14,360,22.441.0,16.434.0,35.126.0,24.175.0,41.139.0,49.232.0,45.174.1,57.140.0"}
P.entries["quest:794"] = {n="Медальйон Палаючого Клинка",s="Доручене чорнокнижницею Зурітою Фарґейз, це завдання посилає молодих новачків Орди вглиб печери Ковену Палаючого Клинка в Долині Випробувань. Там гравцям належить зустрітися з прихованим культистом і здобути артефакт темної магії, відомий як Медальйон Палаючого Клинка. Місія відкриває, що демонічне розбещення пускає коріння просто під носом в Орди.",h="Доручене чорнокнижницею Зурітою Фарґейз, це завдання посилає молодих новачків Орди вглиб печери Ковену...",kw={"медальйон","палаючий клинок","ярроґ бейншедов","зуріта фарґейз","ковен","чорнокнижник"},ang={["class:Shaman"]="Здобуття опоганеної реліквії допомагає Зуріті Фарґейз викрити демонічне розбещення, що оскверняє землю Дуротару.",["class:Warlock"]="Зустріч із Ярроґом — суворе нагадування про небезпеку свавільного поклоніння демонам поза дозволеними, ретельно прихованими угодами, укладеними під владою Тралла.",["faction:Horde"]="Ця місія — останнє випробування молодих новобранців, що знаменує їхню готовність вийти в ширші нетрі Дуротару на захист молодої держави.",["race:Orc"]="Полювання на Ярроґа Бейншедова висвітлює внутрішню боротьбу нової Орди — очистити тренувальні землі від демонічної скверни старих звичаїв."},sec={{t="Прихована загроза в долині",b="Поки молоді орки й тролі проходять основні випробування бою й виживання в Долині Випробувань, у тінях чаїться підступна загроза. Через свої ворожіння чорнокнижниця Зуріта Фарґейз відчуває, що мерзенні прислужники, які кишать на північних кручах, — лише передовий загін темнішої присутності. Глибоко в сусідній печері культ Палаючого Клинка заснував таємний ковен, де практикує темні мистецтва й переховує небезпечні реліквії демонічної сили."},{t="Зустріч із Ярроґом Бейншедовом",b="Сам медальйон тримає в пазурах Ярроґ Бейншедов, орк-чорнокнижник, що діє як агент Палаючого Клинка. Сховавшись на високому виступі глибоко в підземному лігві, Ярроґ командує звірами скверни й темною магією далеко від пильних очей наглядачів долини. Убивство його й захоплення медальйона ламає місцеве керівництво культу, перш ніж їхні ритуали розповзуться далі в серце Дуротару."},{t="Тінь, що не зникає",b="Здобутий талісман підтверджує найгірші побоювання Зуріти Фарґейз. Хоч ковен у Долині Випробувань розгромлено, медальйон — доказ того, що Палаючий Клинок діє організовано й цілеспрямовано. Його досяг простягається далеко за межі земель посвяти, а це означає, що молоду Орду чекають значно ширші демонічні змови по всьому Дуротару."}},fp="23,363,29.453.0,29.434.1,20.361.1,40.168.0,44.165.0,26.180.0,54.208.0,53.189.0,44.190.0"}
P.entries["quest:804"] = {n="Саркот",s="Помстившись за пораненого троля Гана'зуа вбивством жахливого скорпіда Саркота, шукач пригод має віднести звістку про його біду назад до Лігва. Треба попередити Ґорнека, щоб допомога дісталася до ураженого розвідника, перш ніж отруйні рани заберуть його життя.",h="Помстившись за пораненого троля Гана'зуа вбивством жахливого скорпіда Саркота, шукач пригод має віднести...",kw={"саркот","гана'зуа","ґорнек","скорпід","лігво","долина випробувань"},ang={["faction:Horde"]="Нова Орда збудована на спільному виживанні в суворому, безжальному краї; не кидати товариша — засаднича настанова, якої вчать від перших кроків новачка.",["race:Orc"]="Орківська культура цінує особисту силу, та стати на захист честі знесиленого союзника — ось що доводить серце справжнього воїна.",["race:Troll"]="Молодий союз між племенем Темного Списа й орками Тралла міцнішає через такі вчинки братерства, як порятунок Гана'зуа від повільної смерті від отрути."},sec={{t="Біда розвідника",b="Застряглий на високих кручах Долини Випробувань, розвідник Темного Списа Гана'зуа був уражений отрутою й не міг сам спуститися підступними стежками. Хоч помсту Саркотові — страхітливому скорпідові, що звалив його, — вже здійснено, сама гордість не перенесе отруєного воїна через посушливе каміння. Прикутий до своєї скелі, він покладається на новачка, що проходив повз, аби той відніс звістку вниз до тренувального табору."},{t="Честь у Лігві",b="Повернення до Ґорнека в Лігво завершує випробування. Ґорнек одразу усвідомлює, яку загрозу становив Саркот, і швидко організовує допомогу для Гана'зуа. В очах командирів Орди відкласти власне навчання, щоб відстояти честь і врятувати полеглого незнайомця, — це втілення справжньої честі, що доводить гідність новачка задовго до того, як він вирушить у справжній Дуротар."}},fp="7,254,16.425.0,16.363.0,39.228.0,14.201.0,16.197.0,33.141.1,43.198.0,25.125.0"}
P.entries["quest:805"] = {n="Доповідь у село Сен'джин",s="Доповідь у село Сен'джин — мить, коли молоді новачки Орди залишають усамітнену Долину Випробувань, щоб попередити тролів Темного Списа про діяльність демонічного культу. Посланці, яким довірилася Зуріта Фарґейз, несуть звістку про Палаючий Клинок Майстрові Ґадріну — і дізнаються, що тіньова магія вже загрожує сусідньому узбережжю.",h="Доповідь у село Сен'джин — мить, коли молоді новачки Орди залишають усамітнену Долину Випробувань, щоб...",kw={"село сен'джин","майстер ґадрін","зуріта фарґейз","палаючий клинок","темний спис","доповідь"},ang={["faction:Horde"]="Це завдання показує життєво важливу співпрацю між расами-засновницями Орди Тралла: обмін відомостями заради захисту молодих поселень одне одного.",["race:Orc"]="Для молодих орків вихід із Долини Випробувань на поміч Темному Спису — рання перевірка честі й солідарності з союзниками, що стояли поруч із Траллом за Великим Морем.",["race:Troll"]="Повернення до Села Сен'джин ставить шукачів пригод Темного Списа віч-на-віч із вигнанням їхнього народу й триваючою боротьбою за повернення Островів Відлуння."},sec={{t="Прощання з Лігвом",b="Довівши свою бойову стійкість і здобувши темні медальйони Ковену Палаючого Клинка в Долині Випробувань, новачків оголошують готовими до ширшого світу. Зуріта Фарґейз розуміє, що демонічна присутність на священних землях посвяти — не поодинока прикрість, а ознака пошесті, що повзе по всьому Дуротару. Вона посилає молодих шукачів пригод на схід повз гирло ущелини й далі на південь до узбережжя — попередити плем'я Темного Списа."},{t="Тіні над узбережжям",b="Прибувши до прибережного поселення — Села Сен'джин, подорожні передають своє застереження Майстрові Ґадріну, старому знахареві, що веде Темний Спис у вигнанні. Ґадрін підтверджує, що сам Палаючий Клинок не ступав на піски села, та відкриває, що темна магія вже пустила коріння поруч — на Островах Відлуння. Доповідь оголює, яким крихким лишається плацдарм молодої Орди: навіть поки союзники поспішають на захист одне одного, давні племінні зради та скверна б'ють у їхні фланги водночас."}},fp="25,322,15.449.0,22.510.1,70.285.0,21.259.0,47.227.0,33.168.0,57.234.0,46.216.0"}
P.entries["quest:806"] = {n="Темні бурі",s="Темні бурі — важливе завдання від Орґніла Соулскара з Гострого Пагорба: знищити чорнокнижника-відступника, що оскверняє землю. Гоблін на ім'я Фіззл Дарксторм окопався на Громовому Хребті на службі підступного культу Палаючого Клинка. Його усунення життєво важливе, щоб уберегти Дуротар від демонічного відродження, перш ніж культисти розповзуться далі.",h="Темні бурі — важливе завдання від Орґніла Соулскара з Гострого Пагорба: знищити чорнокнижника-відступника, що...",kw={"фіззл дарксторм","громовий хребет","орґніл соулскар","палаючий клинок","гоблін","чорнокнижник"},ang={["class:Shaman"]="Темні обряди Фіззла та його поплічників порушують природних духів Громового Хребта, роз'ятрюють його звірів і вимагають відновлення рівноваги стихій.",["class:Warlock"]="Фіззл Дарксторм показує безоглядну небезпеку неконтрольованої відданості скверні — він ганьба й загроза, яких дисципліновані практики Орди терпіти не можуть.",["faction:Horde"]="Убезпечивши серце Дуротару від демонічного підриву, молода Орда може спрямувати оборону назовні, замість розвалюватися зсередини.",["race:Orc"]="Палаючий Клинок — це темне минуле, яке орки щодня борються подолати. Знищення культистів-лазутчиків на кшталт Фіззла необхідне, щоб зберегти вільну державу Тралла."},sec={{t="Загроза на хребті",b="Поки молоді захисники Орди патрулюють кордони Дуротару, внутрішнє розбещення гноїться просто в них під носом. Орґніл Соулскар, що веде розслідування з Гострого Пагорба, виявив: Громовий Хребет на північному заході підпав під владу темної магії. Ущелина кишить культистами Палаючого Клинка, що несуть руїну й хаос тутешній звірині та землі."},{t="Фіззл Дарксторм",b="Діяльністю культистів на хребті керує Фіззл Дарксторм — гоблін-чорнокнижник і пристосуванець, що зв'язався з Палаючим Клинком. Замість служити торгівлі чи інтересам картелю, Фіззл спрямовує силу скверни просто на підривні цілі культу. Його смерть і здобутий скручений пазур доводять Орґнілові, що безпосереднє керівництво культу в ущелині зламано."},{t="Викорінення культу",b="Палаючий Клинок утілює все, що нова Орда Тралла прагне лишити позаду: демонічне рабство, безоглядне розбещення й кровожерне безумство. Удар по Фіззлу усуває діяльного змовника з глибини Дуротару, та водночас показує, що тінь над орківською батьківщиною сягає значно глибше за поодинокі табори."}},fp="11,352,21.362.0,16.385.0,20.328.1,24.237.0,31.216.0,36.211.0,57.194.0,35.221.1,46.223.0"}
P.entries["quest:808"] = {n="Череп Міншіни",s="Майстра Ґадріна з Села Сен'джин переслідують відчайдушні крики його покійного брата Міншіни. Убитий і підданий темній магії знахарем-відступником Залазаном на Островах Відлуння, Міншіна й досі ув'язнений душею у власному відтятому черепі. Щоб звільнити полеглого троля, треба проникнути на ритуальні землі Залазана, повернути реліквію й визволити його дух від вічних мук.",h="Майстра Ґадріна з Села Сен'джин переслідують відчайдушні крики його покійного брата Міншіни.",kw={"міншіна","череп","залазан","майстер ґадрін","острови відлуння","вуду","душа"},ang={["class:Priest"]="Жерці розуміють глибоку святість душі, що відійшла, і бачать жах ритуальної некромантії, яка не дає полеглому братові знайти вічний спокій.",["class:Shaman"]="Шамани шанують духів предків; розірвати коло Залазана й звільнити закатовану душу — означає відновити рівновагу між світом духів і світом живих.",["faction:Horde"]="Допомога Майстрові Ґадріну вшановує зв'язок між новою Ордою та племенем Темного Списа й доводить, що горе союзника — спільне для всіх.",["race:Troll"]="Для троля Темного Списа повернути череп Міншіни — священний обов'язок перед родиною та племенем і удар по тому, як Залазан спотворює традиції вуду предків."},sec={{t="Благання з тіней",b="Майстер Ґадрін — одна з духовних опор племені Темного Списа в Селі Сен'джин, та його розум мучать темні видіння. Його брат Міншіна став жертвою зради Залазана, коли божевільний чаклун захопив владу над Островами Відлуння. Міншіна загинув у тій боротьбі, та в тролівській традиції та містиці вуду тілесна смерть не завжди дарує спокій. Змучений голос Міншіни промовляє в снах Ґадріна, благаючи порятунку від долі, гіршої за смерть."},{t="Коло сили Залазана",b="Залазан не просто вбиває колишніх побратимів — він ловить їхні душі, щоб живити своє темне чаклунство. Сутність Міншіни ритуально прив'язали до його власного черепа, який тепер лежить посеред блюзнірського кола сили на найбільшому з Островів Відлуння. Під охороною зурочених тролів, у мерехтінні ритуальних свічок, череп слугує осередком для покрученого моджо зрадника. Доки він лежить у колі, Міншіна лишається вічним бранцем волі Залазана."},{t="Свобода у смерті",b="Щоб урятувати Міншіну, відважний герой має перетнути води на схід від Села Сен'джин до південних околиць Островів Відлуння, прорватися в ритуальне коло й вирвати череп з-під впливу знахаря. Повернення останків Майстрові Ґадріну розриває темні пута: вдячний дух Міншіни на мить постає, шанобливо вклоняється й нарешті відходить у царство предків."}},fp="16,388,23.481.0,26.459.0,16.402.1,17.226.0,46.270.0,37.212.0,63.214.1,39.252.0,44.254.0"}
P.entries["quest:812"] = {n="Потреба в ліках",s="Застряглий серед суворих скель північно-західного Дуротару, троль Темного Списа Рінаґ лежить отруєний жалом отруйнохвостого скорпіда. Часу до того, як отрута доб'є його, лишилося обмаль, тож він покладається на гінця, що помчить до Оргріммару й принесе ліки від Кор'ґана.",h="Застряглий серед суворих скель північно-західного Дуротару, троль Темного Списа Рінаґ лежить отруєний жалом...",kw={"рінаґ","кор'ґан","скорпід","отрута","ліки","тіньова розколина","оргріммар"},ang={["faction:Horde"]="Скелястий край Дуротару суворий і безжальний — невпинне випробування вогнем для щойно прибулих захисників молодої держави Тралла.",["race:Troll"]="Страх Рінаґа повернутися до Села Сен'джин підкреслює сувору гордість племені Темного Списа, де необережність в основах виживання в дикій природі накликає нещадні кпини рідних."},sec={{t="Жало скорпіда",b="У посушливих каньйонах Дуротару кишать отруйнохвості скорпіди — агресивні хижаки, чиє жало несе швидкий, знесилювальний нейротоксин. Рінаґ припустився помилки, втративши пильність у бою з цими тварюками біля прикордоння. Знаючи, що отрута в його жилах уб'є його менш ніж за годину, він не здатен сам дійти до міських воріт і мусить віддати своє життя в руки того, хто проходитиме повз його віддалений табір."},{t="Таємниці в тінях",b="Замість довіритися звичайному аптекареві чи шаманові, Рінаґ посилає подорожніх глибоко під Оргріммар, у затінені підземні печери Тіньової Розколини. Там живе Кор'ґан — загадковий знавець суворих отрут пусток Дуротару. Кор'ґан має знання, потрібні, щоб зварити дієву протиотруту, хоч рідко дає допомогу задарма тим, хто ще не довів своєї стійкості."}},fp="15,260,17.452.0,22.425.0,14.270.0,39.310.0,67.251.0,48.282.1,26.127.0,47.148.0"}
P.entries["quest:813"] = {n="Пошук протиотрути",s="Пошук протиотрути — невідкладне завдання для Кор'ґана в Оргріммарі: зварити ліки для отруєного мисливця Рінаґа. Часу обмаль — отрута ось-ось стане смертельною, тож шукач пригод має зібрати отруйні мішечки отруйнохвостих скорпідів за міськими мурами. Завдання підкреслює безжальну природу живності Дуротару й потребу готуватися до походів у дику природу.",h="Пошук протиотрути — невідкладне завдання для Кор'ґана в Оргріммарі: зварити ліки для отруєного мисливця...",kw={"протиотрута","кор'ґан","рінаґ","скорпід","отрута","оргріммар"},ang={["class:Hunter"]="Кор'ґан — суворе нагадування всім мисливцям: знати отруту звіра й носити при собі потрібні ліки не менш важливо, ніж ваш лук і вміння вистежувати.",["faction:Horde"]="Орда в Дуротарі дбає про своїх: самотні слідопити й розвідники на околицях можуть покластися на твердиню Оргріммару по допомогу.",["race:Orc"]="Виживання в Дуротарі випробовує витривалість щойно оселених орків і показує, що навіть бувалий розвідник може впасти від тутешніх небезпек, якщо втратить обережність."},sec={{t="Перегони з отрутою",b="Полюючи в Дуротарі, троль Темного Списа на ім'я Рінаґ припустився небезпечної помилки — зчепився з тутешніми отруйнохвостими скорпідами, не маючи при собі протиотрути. Ужалений і швидко слабнучи від їхніх сильних токсинів, він мусив послати по негайну допомогу. Завдання лягає на Кор'ґана, досвідченого мисливця з Оргріммару: змішати цілющий напій, перш ніж отрута завершить свою справу."},{t="Виготовлення ліків",b="Щоб створити протиотруту, треба здобути саме джерело недуги — отруйні мішечки дорослих отруйнохвостів, що чаяться за воротами Оргріммару. Кор'ґан зауважує, що докори Рінаґові за недбалість доведеться відкласти, адже кожна мить на вагу золота. Щойно мішечки швидко здобуто й принесено до міста, Кор'ґан готує напій, щоб його чимдуж доправили до вмирущого мисливця."}},fp="20,368,24.397.0,17.405.0,14.266.0,16.259.0,43.165.0,47.242.0,53.250.0,46.238.0"}
P.entries["quest:816"] = {n="Втрачене, та не забуте",s="Втрачене, та не забуте — сумне завдання, яке дає Міша Тор'крен у своїй садибі на північний захід від Гострого Пагорба. Відчайдушно прагнучи бодай якоїсь певності, вона просить подорожніх обшукати небезпечні береги Річки Південної Люті, щоб знайти хоч якийсь слід її впертого сина Крона.",h="Втрачене, та не забуте — сумне завдання, яке дає Міша Тор'крен у своїй садибі на північний захід від Гострого...",kw={"міша тор'крен","крон","кроколіски","річка південної люті","амулет","горе"},ang={["class:Hunter"]="Для мисливців Крон — застережна історія про слідопита, який не оцінив лютості своєї здобичі й сам став її обідом.",["faction:Horde"]="Життя в ранньому Дуротарі суворе й непоступливе: звичайні родини борються з безжальним краєм і смертоносними хижаками, що блукають його кордонами.",["race:Orc"]="Доля Крона — трагічне нагадування: хоч гордість і воїнська слава — осердя орківської культури, безоглядна зарозумілість без поваги до небезпечних звірів веде до негеройської смерті."},sec={{t="Материнський страх",b="На північний захід від Гострого Пагорба, у посушливих червоних пустках Дуротару, стоїть скромна садиба Тор'кренів. Тут живе Міша Тор'крен, орчиха-мати, скута горем і тривогою. Кілька днів тому її син Крон оголосив, що йде на захід до Річки Південної Люті на кордоні зі Пустками полювати на лютих річкових кроколісків. Попри її застереження про смертоносних звірів, уперта гордість погнала Крона геть доводити свою силу. Відтоді його ніхто не бачив."},{t="Гірке підтвердження",b="Міша просить перехожих шукачів пригод прочесати береги Річки Південної Люті в пошуках будь-якого знаку про долю Крона — і навіть радить зазирнути в черева кроколісків. На жаль, її найтемніші передчуття справджуються. У вбитих кроколісків-страхопащ біля води знаходиться проковтнутий амулет Крона. Повернення цієї пам'ятки Міші гасить останню надію, що її хлопець вижив, але нарешті дає згорьованій матері певність, потрібну, щоб почати оплакувати сина."}},fp="22,244,16.475.0,19.465.1,22.201.0,13.202.1,26.114.0,38.184.1,28.224.1,38.212.0"}
P.entries["quest:817"] = {n="Практична здобич",s="Практична здобич — мисливське завдання від шкіряника Вел'ріна Фанга в Селі Сен'джин. Населення зростає, а запаси тануть, тож плем'я Темного Списа мусить добути міцні тигрові шкури на сусідніх Островах Відлуння, щоб виготовити необхідні намети, одяг і спорядження.",h="Практична здобич — мисливське завдання від шкіряника Вел'ріна Фанга в Селі Сен'джин.",kw={"вел'рін фанг","тигри","шкури","село сен'джин","острови відлуння","полювання"},ang={["class:Hunter"]="Розповідь Вел'ріна про цілий день мовчазного вистежування перед тим, як захлопнути пастку, напряму говорить про головні чесноти, яких навчають усіх молодих мисливців: терпіння й точність.",["faction:Horde"]="Підтримка молодого анклаву Темного Списа необхідними товарами допомагає закріпити південний фланг Орди вздовж Великого Моря.",["race:Troll"]="Для вигнанців Темного Списа полювання на Островах Відлуння — гірке нагадування про втрачений дім, де, щоб прогодувати плем'я, доводиться ступати землею, яку вкрав Залазан."},sec={{t="Питання виживання",b="Життя на посушливому узбережжі Дуротару суворе, і тролі Темного Списа, вигнані до Села Сен'джин, мають використовувати кожен ресурс сповна. Тигрові шкури — один із найуніверсальніших матеріалів: без них не зшити наметів, важких ковдр і підсиленої броні. Поселення переповнюється біженцями й розвідниками, що повертаються, запаси вичерпалися, і ремісники на кшталт Вел'ріна Фанга змушені замовляти нові полювання."},{t="Рівновага й полювання",b="Темний Спис підтримує виважені стосунки з хижаками своїх земель. Замість винищувати тутешніх тигрів Дуротару, тролі здебільшого дають хижакам жити спокійно й відстрілюють їх лише тоді, коли племінні комори потребують поповнення. Переправа через воду на Острови Відлуння, щоб вистежити цих хижаків, — водночас і практична потреба, і традиційне випробування терпіння, дисципліни та вміння виживати в дикій природі."}},fp="14,280,20.430.0,20.432.0,20.197.0,41.219.0,35.127.0,48.256.0,51.212.0,65.231.0"}
P.entries["quest:818"] = {n="Спиртовий розчинник",s="Майстер Ворнал із Села Сен'джин випробовує шукачів пригод-початківців, вимагаючи реагентів, щоб відшкодувати слабкий зір. Він посилає можливих учнів збирати очі макрур і слиз крабів на узбережжі Дуротару. Хоч він глузує з самої думки взяти учня, це завдання — свідоме випробування терпіння й рішучості.",h="Майстер Ворнал із Села Сен'джин випробовує шукачів пригод-початківців, вимагаючи реагентів, щоб відшкодувати...",kw={"майстер ворнал","алхімія","макрури","слиз","село сен'джин","реагенти"},ang={["faction:Horde"]="Узбережжя Дуротару лишається небезпечним для молодої Орди; винищення агресивних макрур і прибійних крабів убезпечує рибальські береги довкола Села Сен'джин.",["race:Orc"]="Ворнал відкрито сумнівається, чи здатні орки на тиху дисципліну, потрібну для алхімії, тож це завдання — нагода довести, що єдність Орди сягає й ученого терпіння.",["race:Troll"]="Для Темного Списа, що відбудовується в Селі Сен'джин, довести свою гідність старшим майстрам, як-от Майстер Ворнал, життєво важливо, щоб понести далі містичні й алхімічні традиції племені."},sec={{t="Згаслий зір майстра",b="Майстер Ворнал сидить у Селі Сен'джин, обтяжений віком і згасанням зору. Там, де первісна магія колись сама текла до його пальців, він тепер тяжко спирається на алхімію, щоб загострити чуття й творити своє мистецтво. Попри дедалі більшу тілесну неміч, упертий троль відмовляється брати учня, заявляючи, що ні Темний Спис, ні орки Дуротару не породили нікого, гідного його науки."},{t="Випробування невипробуваних",b="Замість прямого навчання Ворнал вимагає сирих матеріалів із суворого узбережжя: цілих очей макрур і флаконів слизу крабів-повзунів. Щоб здобути неушкоджені очі в броньованих клешнястих макрур, потрібні точні удари, а збирання достатньої кількості слизу перевіряє готовність шукача пригод терпіти нудну, чорну роботу. Для Ворнала полювання на цих прибережних створінь — не стільки про реагенти, скільки про відсіювання тих, кому бракує зосередженості."},{t="Міра волі",b="Для Майстра Ворнала час і терпіння — остаточна міра сили. Він чекає, що нетерплячі юнаки піддадуться роздратуванню або й зовсім покинуть цю марудну справу. Повернення до Села Сен'джин із бездоганними інгредієнтами доводить не лише вміння виживати серед небезпечних рифів протоки Островів Відлуння, а й дисципліну, потрібну, щоб опанувати тонке мистецтво алхімії."}},fp="16,336,23.409.0,20.445.0,17.369.0,21.225.0,52.240.0,50.245.0,55.146.0,42.197.0,38.240.0"}
P.entries["quest:823"] = {n="Доповідь Орґнілу",s="Доповідь Орґнілу — раннє завдання Орди, яке доручає Майстер Ґадрін із Села Сен'джин. Воно посилає шукачів пригод-початківців на північ до Гострого Пагорба — попередити Орґніла Соулскара про підступну руку культу Палаючого Клинка. Ця доповідь допомагає узгодити розрізнену оборону Дуротару проти демонічного розбещення, що визріває просто на батьківщині орків.",h="Доповідь Орґнілу — раннє завдання Орди, яке доручає Майстер Ґадрін із Села Сен'джин.",kw={"орґніл соулскар","майстер ґадрін","гострий пагорб","палаючий клинок","доповідь","дуротар"},ang={["faction:Horde"]="Це завдання знаменує життєво важливий зв'язок і співпрацю між новими союзниками — тролями Темного Списа й орками Дуротару — перед спільними загрозами.",["race:Orc"]="Орґніл Соулскар — передова оборона вашої нової батьківщини: він дбає, щоб демонічна скверна не вкоренилася в межах Дуротару.",["race:Troll"]="Хоч Темний Спис поглинутий боротьбою із Залазаном, Майстер Ґадрін показує відданість тролів Орді, попереджаючи орківських ватажків про небезпеки в краї."},sec={{t="Узгоджена оборона",b="Поки Село Сен'джин бореться з власними бідами — передусім зі зрадою Залазана на Островах Відлуння, — Майстер Ґадрін розуміє, що звістки про культ Палаючого Клинка означають значно ширшу небезпеку. Шепіт демонічного розбещення було викрито в Долині Випробувань, і знахар Темного Списа знає: з такими загрозами не впоратися поодинці. Він посилає мандрівних героїв на північ запиленою дорогою до Гострого Пагорба, де тутешня орківська влада тримає ширшу варту над Дуротаром."},{t="Орґніл Соулскар",b="Розміщений у військовому таборі Гострого Пагорба, Орґніл Соулскар — орк, якому доручено викорінювати внутрішнє зло й берегти серце краю. Коли шукачі пригод передають застереження Ґадріна, Орґніл не гаючись зводить докупи звістки з Долини Випробувань і Села Сен'джин. Усвідомивши, що тінь Палаючого Клинка нависла небезпечно близько, він швидко збирає сили, щоб розгромити культистів, перш ніж їхні темні ритуали похитнуть молоду державу."}},fp="16,347,21.502.0,15.482.0,37.175.0,33.120.0,46.258.0,49.215.0,36.165.0,64.169.0"}
P.entries["quest:825"] = {n="З уламків…",s="Ґар'Ток із Гострого Пагорба посилає розвідників Орди обшукати затонулі рештки флоту великого адмірала Праудмура біля Дріботливого Узбережжя. Здобувши з підводних уламків досконалі Гномські Інструменти, Орда сподівається розібрати інженерію Альянсу й обернути цю технічну перевагу собі на користь.",h="Ґар'Ток із Гострого Пагорба посилає розвідників Орди обшукати затонулі рештки флоту великого адмірала...",kw={"ґар'ток","гномські інструменти","уламки","дріботливе узбережжя","праудмур","флот"},ang={["faction:Horde"]="Ґар'Ток бачить у кожному клапті металу Альянсу подвійну здобич: знання, щоб відбити майбутні вторгнення, і матеріал, щоб будувати молоду державу Дуротар.",["profession:Engineering"]="Для інженерів здобуття Гномських Інструментів висвітлює раннє технічне суперництво між механічною точністю Альянсу та ремеслами Орди, що лише зароджуються.",["race:Gnome"]="Хоч гноми невеликі на зріст, вони лишають слід усюди, куди пливе Альянс; їхнє витончене спорядження Орда шанує настільки, що відряджає по нього окремі місії."},sec={{t="Відлуння флоту",b="Коли великий адмірал Делін Праудмур привів морську міць Кул Тірасу до Калімдору, його судна забили берегову лінію біля Фортеці Тіраґард. Після його поразки розтрощені корпуси осіли вздовж Дріботливого Узбережжя. Поки вцілілі вояки Кул Тірасу укріплюють саму фортецю, рештки їхньої армади лежать розбиті на мілинах і повільно гниють під припливом."},{t="Гномські пристрої",b="Орківська війна традиційно спирається на грубу силу, залізо й кров, та Орда визнає небезпечну перевагу, яку дає винахідливість Альянсу. Гномські техніки супроводжували експедиційні флоти, оснащуючи судна Альянсу складними механізмами й точними приладами. Ґар'Ток прагне дістати ці затонулі інструменти, щоб Орда розгадала механіку, яка за ними стоїть."},{t="Дорога до Оргріммару",b="Здобуті інструменти не мають припадати пилом у Гострому Пагорбі. Ґар'Ток домовляється, щоб караван доправив їх просто до Оргріммару. Розбираючи гномські прилади, ремісники й тактики Орди прагнуть краще протистояти пристроям Альянсу в прийдешніх зіткненнях і водночас зміцнити власну молоду промисловість."}},fp="21,302,19.363.0,20.378.0,22.336.0,51.283.0,46.249.0,49.208.0,46.210.0,26.220.0,58.272.0"}
P.entries["quest:826"] = {n="Залазан",s="Майстер Ґадрін із Села Сен'джин доручає героям Орди вирушити на Острови Відлуння й покласти край зраді знахаря Залазана. Збожеволілий від темної магії, Залазан поневолив своїх одноплемінників і захопив законний дім тролів Темного Списа, змусивши їх до вигнання на узбережжі Дуротару.",h="Майстер Ґадрін із Села Сен'джин доручає героям Орди вирушити на Острови Відлуння й покласти край зраді...",kw={"залазан","знахар","острови відлуння","майстер ґадрін","темний спис","вол'джин","зрада"},ang={["class:Shaman"]="Залазан спотворює духовні мистецтва й первісні сили, якими володіють тролівські шамани та знахарі, обертаючи магію поневолення проти власних побратимів.",["faction:Horde"]="Це зіткнення — одне з перших великих випробувань єдності молодої Орди: воно доводить, що союзники з усього Дуротару стануть на захист вигнаного племені Темного Списа.",["race:Troll"]="Для троля Темного Списа вбити Залазана — глибоко особистий акт помсти й обов'язку: кара зраднику, що вкрав законний дім вашого народу й поневолив ваших братів."},sec={{t="Зрада на островах",b="Коли плем'я Темного Списа втекло зі свого затонулого острівного дому й рушило за Траллом через Велике Море, воно оселилося на Островах Відлуння біля південно-східного узбережжя Дуротару. Залазан, шанований і могутній знахар племені, піддався жадобі влади. Опанувавши прокляття, що поневолюють розум, він підкорив багатьох своїх родичів і підняв криваве повстання. Решту вільних тролів Темного Списа на чолі з Вол'джином вигнали з таборів предків за водою, і вони мусили збудувати тимчасовий притулок — Село Сен'джин."},{t="Муки племені",b="Залазанові було замало просто прогнати плем'я. Зі свого редуту на пагорбі центрального острова він раз у раз посилає загони через протоку, щоб викрадати нових тролів Темного Списа й затягувати їх у своє рабство. Уражені стають бездумними зуроченими рабами вуду, назавжди втраченими для племені. Майстер Ґадрін бачить у цьому не просто захоплення землі, а загрозу самому існуванню: доки відтяту голову Залазана не принесуть старійшинам, жоден троль Темного Списа не буде по-справжньому в безпеці."}},fp="8,295,21.525.0,17.490.0,16.236.0,42.307.0,52.300.0,26.227.0,37.208.0,46.307.0"}
P.entries["quest:828"] = {n="Марґоз",s="Марґоз — завдання Орди, яке доручає шукачам пригод розшукати відлюдного орка-шамана, що пильнує північні околиці Дуротару. Після сутички зі скверною в каньйоні Орґніл Соулскар посилає героїв порадитися з Марґозом, перш ніж штурмувати сусідню твердиню культистів. Мудрий відлюдник дає важливу пораду щодо тіні Палаючого Клинка, яка дедалі більшає.",h="Марґоз — завдання Орди, яке доручає шукачам пригод розшукати відлюдного орка-шамана, що пильнує північні...",kw={"марґоз","шаман","відлюдник","череп-скеля","орґніл соулскар","палаючий клинок"},ang={["class:Shaman"]="Марґоз утілює давню, терплячу мудрість шаманізму: він вартує на околицях дикої природи, щоб відчути духовне розбещення, перш ніж воно вибухне війною.",["faction:Horde"]="Застереження Марґоза висвітлює вразливість Оргріммару й доводить, що демонічні культи чаяться на відстані удару від серця Орди.",["race:Orc"]="Зустріч із Марґозом нагадує воїнам-оркам про спокусу сили скверни, що не минає, і закликає нове покоління йти чистим і чесним шляхом."},sec={{t="Варта відлюдника",b="Виявивши глибину скверни на Громовому Хребті, Орґніл Соулскар розуміє, що самої грубої сили замало, щоб очистити Дуротар. Він скеровує своїх героїв до Марґоза — досвідченого орка-шамана, що тримає самотній табір серед скель на північний схід від Гострого Пагорба. Розташувавшись між зубчастими висотами Яру Сухої Балки та східним морем, Марґоз пильнує темні знамення, які метушливі воїни Оргріммару часто не помічають."},{t="Загроза Череп-скелі",b="Марґоз володіє важливими відомостями про справжню опору Палаючого Клинка в північному Дуротарі: приховану систему печер, відому як Череп-скеля, вирубану просто в гірських кручах за південними воротами Оргріммару. Порадившись із Марґозом, подорожні дізнаються, що культисти діють значно ближче до столиці Тралла, ніж гадає сторожа Вождя. Шаман дбає, щоб той, кого пошлють очистити ковен, не ступив наосліп у демонічну засідку."}},fp="6,392,16.446.0,24.462.0,14.205.0,23.154.0,43.222.0,19.209.0,34.174.1,36.147.0"}
P.entries["quest:83"] = {n="Червоні лляні вироби",s="«Червоні лляні вироби» — завдання в Лісі Елвінн від швачки Сари Тімберлейн, чия майстерня — Лісозаготівельний Табір Східної Долини. Їй потрібна тканина, тож вона просить шукачів пригод, що проходять повз, полювати на місцевих бандитів Дефіас і знімати з них лляні бандани. Навзамін із повернутої тканини вона шиє корисні речі для мандрівників.",h="«Червоні лляні вироби» — завдання в Лісі Елвінн від швачки Сари Тімберлейн, чия майстерня — Лісозаготівельний...",kw={"червоні лляні вироби","сара тімберлейн","бандани","дефіас","кравецтво","східна долина"},ang={["faction:Alliance"]="Зачистка бандитів Дефіас, що заполонили гаї Елвінну, не лише дає Східній Долині корисну здобич, а й реально послаблює хватку Братства на серці королівства.",["profession:Tailoring"]="Ремесло Сари Тімберлейн показує сувору правду сільського кравецтва: сувоїв тканини бракує, і місцевим швачкам доводиться знімати полотно просто зі спин місцевих бандитів."},sec={{t="Бандити й мішковина",b="Якщо дрібні розбійники Дефіас, що зчиняють сутички в Долині Нортширу, обходяться дешевими масками з мішковини, то організовані злочинці, які никають рештою Лісу Елвінн, носять добірніші бандани з багряного льону. Для місцевих ремісників, яким бракує сировини, ці знаки банди — напрочуд практичне джерело придатної тканини."},{t="Здобич у таборі",b="Сара Тімберлейн працює там, де гуде Лісозаготівельний Табір Східної Долини, біля східного кордону Елвінну, і завжди шукає придатні тканини. Заохочуючи шукачів пригод проріджувати табори Дефіас, сховані по лісах, вона забезпечує своє кравецьке ремесло сировиною й водночас допомагає стримати зухвалий наступ Братства."}},fp="15,310,18.315.0,19.337.0,37.120.0,42.122.0,49.185.0,54.246.0,46.182.0,43.142.0"}
P.entries["quest:830"] = {n="Накази адмірала",s="Здобуті із замкненої скрині на вершині Фортеці Тіраґард, ці потерті папери несуть особисту печатку покійного великого адмірала Деліна Праудмура. Знайдені накази відкривають, що людський гарнізон Кул Тірасу на узбережжі Дуротару значно глибше окопався й краще організований, ніж прості вцілілі з кораблетрощі. Доставка їх Ґар'Току в Гострий Пагорб викриває приховані військові плани, що загрожують молодій державі орків.",h="Здобуті із замкненої скрині на вершині Фортеці Тіраґард, ці потерті папери несуть особисту печатку покійного...",kw={"накази","праудмур","фортеця тіраґард","ґар'ток","кул тірас","бенедикт"},ang={["faction:Horde"]="Викриті накази Праудмура доводять, що присутність Альянсу на берегах Дуротару була спланованою кампанією винищення, і зайвий раз пояснюють, чому Орда має пильно боронити свій новий дім.",["race:Orc"]="Для орків, що борються за майбутнє в Дуротарі, ці документи — суворе нагадування про невгамовну ненависть Деліна Праудмура й про недобитків, які досі прагнуть їх знищити."},sec={{t="Запечатаний спадок",b="Схований у важкій скрині на верхніх поверхах Фортеці Тіраґард, старий конверт уцілів під наглядом лейтенанта Бенедикта. Запечатаний гербом великого адмірала Деліна Праудмура, пергамент містить прямі морські накази, видані під час кривавого вторгнення Кул Тірасу в Дуротар. Навіть після того, як великий адмірал поліг у Тераморі, його офіцери тримали укріплення, вперто чіпляючись за свою місію — винищити поселення Орди."},{t="Тривога в Гострому Пагорбі",b="Доставка знайдених документів Ґар'Току, командирові Гострого Пагорба, підтверджує найгірші побоювання тутешніх захисників. Люди, що окопалися вздовж східного узбережжя, — не безцільні викинуті на берег моряки, а усталений плацдарм, що чекає підкріплення. Ґар'Ток одразу усвідомлює: зруйнувати командування Тіраґарду — невідкладна справа виживання Дуротару."}},fp="20,412,15.452.0,19.385.1,37.221.0,27.293.0,51.255.0,48.265.0,41.180.0,49.194.0"}
P.entries["quest:832"] = {n="Палаючі тіні",s="Здобутий у культиста Палаючого Клинка Ґазз'уза в глибинах Череп-скелі, цей загадковий сяйливий кулон шепоче в розум носія настійливі застереження. Голос відверто погрожує Ґазз'узу гнівом Ніру Файрблейда — орка-чорнокнижника, що живе в Оргріммарі.",h="Здобутий у культиста Палаючого Клинка Ґазз'уза в глибинах Череп-скелі, цей загадковий сяйливий кулон шепоче в...",kw={"око палаючої тіні","ґазз'уз","ніру файрблейд","палаючий клинок","череп-скеля","кулон"},ang={["class:Warlock"]="Для чорнокнижника, що навчається в Тіньовій Розколині, почути, як Палаючий Клинок згадує ім'я іншого практика, — суворе нагадування про те, яка тонка межа між дозволеним державою вивченням скверни та відкритою зрадою.",["faction:Horde"]="Викриті перешіптування культистів одразу за воротами столиці показують, що демонічне розбещення Старої Орди досі гноїться тривожно близько до серця Дуротару.",["race:Orc"]="Орки, що билися пліч-о-пліч із Траллом, щоб очиститися від скверни Легіону, бачать у присутності Палаючого Клинка в Дуротарі нестерпне осквернення своєї нової батьківщини."},sec={{t="Голос у камені",b="Після вбивства Ґазз'уза глибоко в Череп-скелі з його останків дістають зловісний кулон, відомий як Око Палаючої Тіні. Це не мертва магічна дрібничка: камінь тремтить від думкомови. Владний голос промовляє просто в розум кожного, хто його тримає, вимагаючи звітів від Ґазз'уза й попереджаючи, що його таємні справи на схід від Оргріммару викрито."},{t="Дивна погроза",b="Що заскочує зненацька будь-якого вірного розвідника Орди, то це відчайдушний ультиматум голосу: відповідай, інакше Ніру Файрблейда повідомлять, щоб він вистежив Ґазз'уза зі швидкою жорстокістю. Ніру Файрблейд відкрито живе в Тіньовій Розколині Оргріммару, нібито практикуючи темні мистецтва під суворим наглядом Тралла. Коли талісман приносять Ніру, той удає подив і цікавість, дивуючись, що його ім'ям лякали культистів, наче страховиськом."}},fp="15,272,20.410.0,16.454.1,34.200.0,36.174.0,57.252.0,42.134.0,50.210.1,25.136.0"}
P.entries["quest:833"] = {n="Священне поховання",s="«Священне поховання» — завдання від Хранителя Знань Рейнтотема, що доручає шукачам пригод Орди захистити Червоні Скелі у східному Малгорі. Священне поховання предків заполонили мародери — шипогриви-Щетиноспини, які плюндрують могили шанованих воїнів-тауренів. Вигнання цих зайд повертає честь і спокій тим, хто віддав життя, засновуючи й боронячи Тандер Блаф.",h="«Священне поховання» — завдання від Хранителя Знань Рейнтотема, що доручає шукачам пригод Орди захистити...",kw={"священне поховання","червоні скелі","хранитель знань рейнтотем","шипогриви","щетиноспини","предки","малгор"},ang={["class:Shaman"]="Споганення священної землі збурює духів шанованих предків, тож ваше втручання потрібне, щоб повернути землі рівновагу.",["faction:Horde"]="Допомога тауренським старійшинам в убезпеченні їхніх священних пам'яток скріплює обітницю Орди боронити Малгор разом із союзниками.",["race:Tauren"]="Захист Червоних Скель — справа глибокої честі перед предками: воїни, завдяки яким ваш народ здобув об'єднану батьківщину, мають спочивати непотривоженими."},sec={{t="Святиня шу'хало",b="Червоні Скелі — одна з найшанованіших святинь усього Малгору. Схована серед бескидів під східними горами, це місце останнього спочинку, призначене лише для найдоблесніших тауренів. Поховані тут герої — легендарні воїни, що проливали кров, захищаючи свої племена, підтримуючи вождів і здобуваючи постійну батьківщину на плато Тандер Блафа. Для шу'хало потривожити їхній спокій — образа не лише традиції, а й самої Земної Матері."},{t="Споганення Щетиноспинами",b="Кочові шипогриви племені Щетиноспинів уперто заперечують владу тауренів над центральним Калімдором, але їхнє нещодавнє вторгнення до Червоних Скель — серйозне загострення. Ватаги зайд-Щетиноспинів прокралися на святу землю, розриваючи ґрунт і тривожачи місця спочинку. Оскільки сторож Хранитель Знань Рейнтотем надто старий, щоб самотужки вигнати нападників, молоді звитяжці Орди мають узятися до зброї, очистити святиню від зайд і захистити шанованих мертвих."}},fp="15,401,31.497.0,27.505.0,18.233.0,28.262.0,46.243.0,51.257.0,32.248.0,27.196.0"}
P.entries["quest:834"] = {n="Вітри в пустелі",s="Резлаку, інженерові, найнятому з підприємств Ґазлоу, потрібна допомога: гарпії в Дуротарі вкрали важливі будівельні матеріали. Караван, що прямував до Оргріммару, потрапив у засідку в Каньйоні Гострого Вітру, і мішки з припасами розкидало по скелях.",h="Резлаку, інженерові, найнятому з підприємств Ґазлоу, потрібна допомога: гарпії в Дуротарі вкрали важливі...",kw={"резлак","гарпії","каньйон гострого вітру","припаси","ґазлоу","караван"},ang={["faction:Horde"]="Кожен вантаж, утрачений через звірів каньйону, загрожує швидкому розширенню й укріпленню твердині Орди в Дуротарі.",["profession:Engineering"]="Резлак утілює практичну винахідливість інженерів картелю Стімвідл, яких значно більше хвилюють креслення й вчасні поставки, ніж клопоти з місцевою живністю.",["race:Orc"]="Орки покладаються на гоблінський досвід і чужоземні припаси, щоб перетворити суворий, сухий ґрунт Дуротару на укріплену батьківщину."},sec={{t="Гоблін і терміни",b="Резлака послав сам Головний Інженер Ґазлоу з Раджета — допомагати Орді з її зухвалими будівельними проєктами по всьому Дуротарі. Зводити укріплення на суворій, пустельній землі й без того важко, не кажучи вже про провали постачання, та вантажі Резлака раз у раз зникають, не дійшовши до будівництв. Без важливого вантажу вся робота стає, і дратівливий гоблін-наглядач лишається без нічого, з чого можна будувати."},{t="Засідка в каньйоні",b="Останній життєво важливий вантаж, обіцяний Резлакові, перехопили гарпії Пилового Вітру, що живуть у Каньйоні Гострого Вітру. Ці крилаті падложерки гніздяться на високих уступах ущелини обабіч дороги між Гострим Пагорбом і Оргріммаром і пікірують на необережні вози. Замість з'їсти чи знищити вантаж, гарпії складають ящики й мішки довкола своїх гнізд, залишаючи його цілим для кожного, кому стане відваги пробитися на їхню територію."}},fp="19,251,22.451.0,20.454.0,14.186.0,41.264.0,33.151.0,38.234.0,34.233.0,46.215.0"}
P.entries["quest:835"] = {n="Убезпечити шляхи",s="Убезпечити шляхи — завдання, яке дає Резлак біля Каньйону Гострого Вітру, щоб захистити важливі гоблінські шляхи постачання через Дуротар. Гарпії, що гніздяться в Яру Сухої Балки, невпинно перехоплюють і грабують каравани, тож роздратований гоблін наймає бійців, щоб їх вибити.",h="Убезпечити шляхи — завдання, яке дає Резлак біля Каньйону Гострого Вітру, щоб захистити важливі гоблінські...",kw={"резлак","гарпії","яр сухої балки","каньйон гострого вітру","каравани","постачання"},ang={["faction:Horde"]="Усунення загрози гарпій у східній частині Каньйону Гострого Вітру зберігає потік товарів і підкріплень між прикордонними заставами Дуротару й прибережними торговими осередками.",["profession:Engineering"]="Захист вантажів Резлака дбає, щоб новітні гоблінські деталі й далі йшли з Раджета до рук місцевих інженерів."},sec={{t="Шлях, обсаджений гарпіями",b="Сухі долини Дуротару й так суворі, а тут ще й агресивні гарпії пікірують на необережних подорожніх. Гоблін Резлак, що працює на свого боса Ґазлоу, наглядає за постачанням у краї. На жаль, гарпії Пилового Вітру, що оселилися в Яру Сухої Балки, перетворили Каньйон Гострого Вітру на смертельну пастку: вони регулярно грабують каравани й захоплюють вантажі, перш ніж ті дійдуть до мети."},{t="Справа й кров",b="Резлак живе за гоблінським правилом: за належну ціну можна зробити що завгодно. Замість самому лізти в каньйон, він наймає шукачів пригод зламати хребет гніздовищу, винищивши дикунок Пилового Вітру та штормових відьом Пилового Вітру. Очищення від гарпій тримає торгові коридори відкритими, убезпечує поставки інженерних пристроїв і вказує корисним подорожнім на більші можливості в Раджеті."}},fp="18,283,26.418.0,22.418.0,26.197.0,39.239.0,33.139.0,34.208.0,60.281.0,48.169.0"}
P.entries["quest:84"] = {n="Назад до Біллі",s="«Назад до Біллі» — ще один крок у тривалій ворожнечі родин Стоунфілдів і Маклурів у центрі Лісу Елвінн. Зібравши складники для пирога з грудинкою, ви несете щойно спечену страву малому Біллі Маклуру, щоб витягти з нього, куди поділося намисто Берніс Стоунфілд.",h="«Назад до Біллі» — ще один крок у тривалій ворожнечі родин Стоунфілдів і Маклурів у центрі Лісу Елвінн.",kw={"біллі маклур","пиріг","грудинка","стоунфілди","маклури","намисто","ліс елвінн"},ang={["faction:Alliance"]="Навіть мирний Ліс Елвінн потерпає від буденних чвар; розбиратися зі сварливими людськими садибами — звична робота для мандрівників, що допомагають місцевим.",["profession:Cooking"]="Пиріг з грудинкою — класична домашня страва елвіннських фермерів, яку готують із м'яса диких вепрів, що блукають лісом."},sec={{t="Гіркий пиріг",b="Сварка Стоунфілдів і Маклурів тягнеться поколіннями й не лишає місця для сусідської ласки. Тітонька Берніс Стоунфілд знехотя спекла замовлений пиріг з грудинкою лише тому, що малий Біллі Маклур відмовився без нього розповідати, що знає про її родинну реліквію. Навіть передаючи теплу випічку, вона не приховує роздратування й просить кур'єра переказати хлопчиськові Маклурів: нехай удавиться кожним шматком."},{t="Хабар для хлопчиська",b="Через дорогу, на Виноградниках Маклюрів, Біллі Маклур чекає з порожнім животом і напрочуд зручною дірою в пам'яті. Цей обмін показує вперту дріб'язковість, що розділяє дві садиби: тут навіть діти вчаться міняти плітки й поцуплені дрібнички на сільські ласощі. Щойно пиріг доставлено, пам'ять Біллі дивовижно прояснюється — і починаються пошуки справжнього місця, де лежить намисто."}},fp="13,296,12.426.0,13.394.1,37.233.0,42.221.0,46.169.1,31.129.0,29.138.0,54.157.0"}
P.entries["quest:85"] = {n="Загублене намисто",s="«Загублене намисто» — вступне завдання на півдні Лісу Елвінн від «Тітоньки» Берніс Стоунфілд. Підозрюючи в крадіжці бешкетного хлопчиська з ворожого роду, Берніс посилає шукачів пригод через дорогу — притиснути Біллі Маклура й повернути її зниклу реліквію.",h="«Загублене намисто» — вступне завдання на півдні Лісу Елвінн від «Тітоньки» Берніс Стоунфілд.",kw={"загублене намисто","берніс стоунфілд","біллі маклур","крадіжка","стоунфілди","маклури"},ang={["faction:Alliance"]="Для новачків Альянсу, що починають свій шлях у Лісі Елвінн, залагоджувати дрібні чвари між сварливими Стоунфілдами й Маклурами — найхарактерніший смак місцевого життя на прикордонні.",["race:Human"]="Ворожнеча Стоунфілдів і Маклурів показує, що не всі чвари в Королівстві Стормвінд ідуть від злочинців Дефіас чи загонів гнолів: давні сільські сусідські сварки сягають не менш глибоко."},sec={{t="Сусідське звинувачення",b="Родини Стоунфілдів і Маклурів володіють сусідніми землями на півдні Лісу Елвінн, та доброї волі між ними майже немає. Виявивши, що її улюблене намисто зникло, «Тітонька» Берніс Стоунфілд не гаючись тицяє пальцем у наймолодшого з ворожого дому. Переконана, що малий Біллі Маклур прокрався на її ферму й поцупив прикрасу, озлоблена вдова просить будь-якого охочого мандрівника піти на виноградники, знайти хлопця й вимагати повернення."},{t="Хлопчисько з апетитом",b="Розмова з Біллі Маклуром на сусідньому винограднику швидко все ускладнює. Біллі обурено заперечує, що брав намисто, і запевняє, що він не злодій. Однак із хитрою посмішкою натякає: він, може, і знає, що насправді сталося з дрібничкою, — якщо спершу хтось утамує його бурчливий живіт свіжим пирогом зі свининою."}},fp="13,264,23.485.0,22.334.1,33.211.0,46.185.1,31.146.0,55.225.0,44.171.1,33.144.0"}
P.entries["quest:86"] = {n="Пиріг для Біллі",s="«Пиріг для Біллі» — доручення, що потрапило під перехресний вогонь давньої ворожнечі родин Стоунфілдів і Маклурів у Лісі Елвінн. Малий Біллі Маклур відмовляється розповідати про зникле намисто тітоньки Берніс Стоунфілд, поки не отримає навзамін пиріг з грудинкою. Шукачам пригод доведеться вполювати місцевих вепрів і зібрати м'ясо, щоб Берніс спекла вимаганий хабар.",h="«Пиріг для Біллі» — доручення, що потрапило під перехресний вогонь давньої ворожнечі родин Стоунфілдів і...",kw={"пиріг для біллі","біллі маклур","берніс стоунфілд","вепри","грудинка","кулінарія"},ang={["profession:Cooking"]="Тітонька Берніс зауважує: м'ясо дикого вепра буває жорстким і прісним, але правильні прянощі й повільне тушкування роблять із нього чудову начинку для пирога.",["race:Human"]="Ця сварка показує вперте, замкнуте суперництво, що квітне серед сільських господарів Елвінну просто на південь від брами Стормвінда."},sec={{t="Хабар для хлопчиська",b="Коли Біллі Маклура розпитують про крадіжку родинного намиста тітоньки Берніс Стоунфілд, він не виявляє й тіні каяття, на яке міг би сподіватися старший. Замість повернути реліквію чи зізнатися, хлопець користається з нагоди догодити своєму апетиту. Він вимагає свіжоспеченого пирога з грудинкою, перш ніж скаже бодай слово про те, у кого намисто, — чудово знаючи, що тітонька Берніс — найкраща куховарка в долині."},{t="Випічка попри давню кров",b="Маклури й Стоунфілди поколіннями обмінюються образами, бійками та звинуваченнями через гарбузові грядки. Хоч її глибоко обурює потреба годувати шибеника, який украв родинну прикрасу, тітонька Берніс погоджується розпалити піч. В обмін на ніжне м'ясо вепрів, уполюваних на сусідніх пасовищах, вона проковтує гордість, щоб задобрити неслухняного хлопця й повернути свій скарб."}},fp="13,365,13.436.0,24.422.0,41.237.0,50.262.0,42.126.0,57.222.0,38.174.0,41.161.0"}
P.entries["quest:861"] = {n="Шлях мисливця",s="«Шлях мисливця» — обряд посвяти, який старійшина Скорн Вайтклауд пропонує майбутнім слідопитам у Малгорі. Щоб довести свою нову вправність і повагу до дикої природи, мандрівники мають здолати хитрих рівнинних скрадачів і піднести їхні пазурі Мелору Стоунгуфу на Узвишші Мисливців у Тандер Блафі.",h="«Шлях мисливця» — обряд посвяти, який старійшина Скорн Вайтклауд пропонує майбутнім слідопитам у Малгорі.",kw={"шлях мисливця","скрадачі","пазурі","скорн вайтклауд","мелор стоунгуф","узвишшя мисливців","тандер блаф"},ang={["class:Hunter"]="Випробування прямо перевіряє основи дикого краю: вистежити хижака-засідника, перш ніж він ударить першим, і читати ледь помітні знаки трав.",["faction:Horde"]="Цей обряд — міст для союзних мандрівників Орди, щоб зрозуміти тауренську шану до природи й здобути їхню довіру на висотах Тандер Блафа.",["race:Tauren"]="Для молодих тауренів піднести пазурі скрадачів на Узвишші Мисливців — основоположний обряд посвяти, що єднає їх із поколіннями предків, які полювали на цих самих розлогих рівнинах."},sec={{t="Традиція рівнин",b="Для тауренів полювання — не розвага й не простий прожиток: його мають за одну з найвищих почестей свого народу. Воно вимагає терпіння, усвідомлення рівноваги Земної Матері й шани до звірів, що блукають пагорбистими рівнинами. Старійшина Скорн Вайтклауд, що відпочиває в Малгорі після десятиліть вистежування по всьому Калімдору, упізнає цей неспокій у молодих шукачах пригод. Замість дозволити їм блукати без мети, він спрямовує їхнє честолюбство в традиційне випробування зрілості й дисципліни."},{t="Скрадачі трав'яних рівнин",b="Щоб довести, що їхнє чуття слідопита справжнє, претендентам доручають здолати рівнинних скрадачів Малгору. Ці великі коти — прудкі, потайні й хитрі хижаки-засідники, що легко зливаються з високою травою рівнин. Чотири пари пазурів доводять: молодий мандрівник уміє помітити хижака, перш ніж стати здобиччю, і обернути лють мисливця проти нього самого."},{t="Дістатися Узвишшя Мисливців",b="Здобувши трофеї, посвячений підіймається високими дерев'яними вежами й мостами, що ведуть у Тандер Блаф. Там, на Узвишші Мисливців, пазурі приймає Мелор Стоунгуф. Як майстер-слідопит, що цінує прадавню мудрість Скорна Вайтклауда, Стоунгуф приймає підношення як доказ: посвячений має належний дух, щоб його вели далі мисливськими стежками Калімдору."}},fp="16,291,25.509.0,30.399.0,20.391.0,45.165.0,43.105.0,53.238.0,50.170.0,61.211.1,54.224.0"}
P.entries["quest:8649"] = {n="Старійшина Стормброу",s="Старійшина Стормброу — один із прадавніх духів, яких шанують під час Місячного фестивалю; він стоїть біля води неподалік Ґолдшира. Мандрівники, що розшукують цього старійшину, віддають шану давнім традиціям і стародавнім расам Азерота. У відповідь на виявлену повагу старійшина дарує невеликий пам'ятний знак.",h="Старійшина Стормброу — один із прадавніх духів, яких шанують під час Місячного фестивалю; він стоїть біля...",kw={"старійшина стормброу","місячний фестиваль","ґолдшир","дух","предки","ліс елвінн"},ang={["faction:Alliance"]="Старійшина Стормброу, що відпочиває в самому серці Лісу Елвінн, — один із найдоступніших духів предків для молодих шукачів пригод Альянсу, які проходять через Ґолдшир.",["race:Human"]="Для людей Елвінну присутність Старійшини Стормброу — нагадування про давню історію поза мурами й недавніми війнами Стормвінда."},sec={{t="Дух у Ґолдширі",b="Старійшина Стормброу з'являється біля тихого ставка, що причаївся одразу за кузнею в Ґолдширі. Зазвичай містечко вирує від вартових в обладунках, ремісників і втомлених шукачів пригод, що прямують у ліс, та поява шанованого духа приносить тиху паузу. Стоячи під мирним склепінням Лісу Елвінн, Стормброу вітає кожного, хто готовий ушанувати довгу історію краю."},{t="Шана стародавнім расам",b="Місячний фестиваль — час, коли духи великих предків повертаються ходити серед живих. Старійшина Стормброу хвалить смертних мандрівників за те, що вони знаходять час згадати тих, хто був до них. В обмін на визнання мудрості й спадщини старших народів він дарує своє благословення та пам'ятну монету на честь свята."}},fp="19,300,21.389.0,24.344.0,33.124.0,23.140.0,48.197.0,43.176.0,32.131.0,45.177.0"}
P.entries["quest:8652"] = {n="Старійшина Грейвборн",s="Старійшина Ґрейвборн — зустріч Місячного фестивалю біля містечка Брілл у Галявинах Тірісфалю. Під час святкування мандрівники шукають Старійшину Ґрейвборна серед спустошених гаїв, щоб ушанувати стародавніх пращурів Азероту. Віддана цьому духові шана приносить його благословення і святковий дарунок.",h="Старійшина Ґрейвборн — зустріч Місячного фестивалю біля містечка Брілл у Галявинах Тірісфалю.",kw={"старійшина ґрейвборн","місячний фестиваль","монета роду","брілл","пращури","старійшина"},ang={["class:Druid"]="Друїди шанують старійшин Місячного фестивалю як ланки, що єднають із давнім світом до Розколу, незважаючи на неспокійні фракційні межі, серед яких ті перебувають.",["faction:Alliance"]="Шукачам пригод з Альянсу, які хочуть знайти Старійшину Ґрейвборна, слід обережно пробиратися Галявинами Тірісфалю: Брілл — добре укріплений притулок Відступників.",["race:Undead"]="Для Відступників, що живуть у Бріллі, прихід духів давніх пращурів — яскраве нагадування про глибшу історію Азероту за межами недавніх трагедій Погибелі."},sec={{t="Примарна варта у Бріллі",b="Поки Відступники живуть серед зруйнованих маєтків і могил Галявин Тірісфалю, Місячний фестиваль приносить несподіване єднання з давніми часами. Старійшина Ґрейвборн постає примарним старцем просто за межами Брілла. Навіть у краї, розтрощеному Погибеллю й відвойованому нежиттю, він вітає прочан, які зупиняються вшанувати давні звичаї."},{t="Шана давнім народам",b="Місячний фестиваль — час, коли великі духи давно минулих епох повертаються, щоб поділитися мудрістю і вдячністю. Коли мандрівники підходять до Старійшини Ґрейвборна, він зауважує, як утішно, що мешканці Тірісфалю досі вшановують пращурів попри нинішній занепад краю, і дарує Монету Роду тим, хто його привітав."}},fp="19,307,24.352.0,24.344.0,33.126.0,47.165.0,52.270.0,43.233.0,38.176.0,39.218.0"}
P.entries["quest:8653"] = {n="Старійшина Голдвелл",s="«Старійшина Голдвелл» — завдання Місячного фестивалю, яке дає Старійшина Ґолдвелл у Хараносі, в Дун Мороґу. Вшанувати його — означає долучитися до давньої традиції шукати духів предків по засніжених дворфійських землях. В обмін на вашу шану він дарує знак благословення предків.",h="«Старійшина Голдвелл» — завдання Місячного фестивалю, яке дає Старійшина Ґолдвелл у Хараносі, в Дун Мороґу.",kw={"старійшина","ґолдвелл","місячний фестиваль","харанос","монета роду","предки"},ang={["faction:Alliance"]="Розташований у безпечних землях Альянсу, Ґолдвелл — один із найдоступніших старійшин для юних героїв Альянсу, що мандрують між Долиною Холодного Хребта та Айронфорджем.",["faction:Horde"]="Щоб дістатися Ґолдвелла, доведеться прокрастися вглиб Дун Мороґу, повз дворфійську варту й лютий холод, просто під високі брами Айронфорджа.",["race:Dwarf"]="Для дворфів, що повертаються з Айронфорджа, зустріч зі старійшиною давнього роду просто біля їхньої головної таверни в Хараносі поєднує одвічну шану з гордістю за рідне місто."},sec={{t="Гірське вітання",b="Стоячи на лютому морозі біля Ґуральні Тандербрю в Хараносі, Старійшина Ґолдвелл наглядає за жвавим торговим шляхом, що веде до брам Айронфорджа. Під час Місячного фестивалю ця поважна постать вітає втомлених мандрівників, шукачів пригод і місцевих, утілюючи довгу пам'ять давніх днів, коли перші смертні ходили під зорями Азероту."},{t="Шана предкам",b="Підійти до Ґолдвелла — означає на мить замислитися серед суворих зимових вітрів Дун Мороґу. Він висловлює полегшення й радість, що смертні досі пам'ятають давні народи та їхні діяння, і дякує всім, хто перериває подорож, щоб засвідчити повагу. Натомість він дарує священну Монету Роду як знак свого благословення."}},fp="18,282,19.365.0,22.316.0,32.177.0,50.213.0,40.183.0,43.212.0,45.227.0,43.151.0"}
P.entries["quest:8670"] = {n="Старійшина Рунтотем",s="Старійшина Рунтотем — зустріч із духом предків під час Місячного фестивалю в Дуротарі. Вона стоїть у Гострому Пагорбі під стовпом небесного світла й дарує благословення та святкові монети подорожнім, що приходять ушанувати минуле.",h="Старійшина Рунтотем — зустріч із духом предків під час Місячного фестивалю в Дуротарі.",kw={"старійшина рунтотем","місячний фестиваль","гострий пагорб","дух предків","монета","таурени"},ang={["faction:Alliance"]="Щоб ушанувати Старійшину Рунтотем, доведеться прослизнути глибоко в тил ворога, у серце Дуротару, не накликавши на себе гніву орківської варти Гострого Пагорба.",["faction:Horde"]="Старійшина Рунтотем стоїть просто в мурах Гострого Пагорба — одна з найбезпечніших і найзручніших предків, яких молоді мандрівники Орди можуть ушанувати на початку свого шляху.",["race:Tauren"]="Зустріч із духом, що носить шановане родове ім'я Рунтотемів, за межами рівнин Малгору — потужне нагадування про глибоку духовну спадщину вашого народу по всьому Калімдору."},sec={{t="Дух у Гострому Пагорбі",b="Під час Місячного фестивалю духи давніх старійшин постають по всьому Азероту, щоб спілкуватися з живими. Старійшина Рунтотем з'являється в Гострому Пагорбі одразу за південним входом. Омита чистим променем зоряного світла згори, вона пильнує орківське поселення й вітає шукачів пригод, які відволікаються від своїх мандрів, щоб ушанувати мудрість тих, хто був до них."},{t="Настанови на всі землі",b="Підійти до Старійшини Рунтотем — означає не лише вшанувати одного предка. В обмін на вашу шану вона винагороджує вас святковою монетою удачі й розповідає, де можна знайти інших духів, скеровуючи мандрівників до Старійшини Даркгорна та Старійшини Гай Маунтіна по всьому континенту."}},fp="19,263,22.398.0,25.290.0,33.143.0,44.191.0,49.197.0,43.196.0,36.147.0,46.144.0"}
P.entries["quest:8673"] = {n="Старійшина Бладгуф",s="«Старійшина Бладгуф» — зустріч з одним із шанованих духів предків, що з'являються під час Місячного фестивалю. Цей шанований дух, що стоїть одразу за Селом Бладгуф у Малгорі, приймає пошану від мандрівників і дарує навзаєм знак предків.",h="«Старійшина Бладгуф» — зустріч з одним із шанованих духів предків, що з'являються під час Місячного фестивалю.",kw={"старійшина бладгуф","місячний фестиваль","монета роду","предки","село бладгуф","малгор","дух"},ang={["class:Druid"]="Друїди високо шанують духів Місячного фестивалю і спілкуються зі старійшинами, щоб зміцнити свій природний зв'язок із землею та зорями.",["class:Shaman"]="Для шамана розмова з проявленими предками, як-от Старійшина Бладгуф, прямо зміцнює живе єднання між смертним світом і духами предків.",["faction:Alliance"]="Щоб дістатися Старійшини Бладгуфа, треба прокрастися в саме серце Малгору, тож це зухвала подорож ворожими рівнинами Орди.",["race:Tauren"]="Привітати Старійшину Бладгуфа на рідній землі — священний обов'язок, що вшановує спадок племені, яке допомогло привести тауренів до їхнього мирного прихистку в Малгорі."},sec={{t="Гостина предків",b="Під час святкування Місячного фестивалю духи великих героїв і старійшин минулих віків повертаються в Азерот. Оповитий небесним сяйвом, Старійшина Бладгуф з'являється одразу на північ від Села Бладгуф, біля мосту. Підійти до цих шанованих предків означає вшанувати давні жертви, а навзаєм Старійшина Бладгуф дарує слова підбадьорення і священну Монету Роду."},{t="Спадок Бладгуфів",b="Стоячи на прабатьківських землях Малгору, Старійшина Бладгуф служить мостом між живими племенами тауренів і пам'яттю про їхніх пращурів. Для тауренів шанування мертвих — опора духовного життя, що зміцнює гармонію між Земною Матір'ю, предками й тими, хто нині ходить рівнинами."}},fp="19,285,26.394.0,20.316.0,33.142.0,51.245.0,49.185.0,54.211.0,48.159.0,40.234.0"}
P.entries["quest:86784"] = {n="Палиці й кістки",s="Палиці й кістки — місцеве завдання від Вартового Смерті Бартоломью в Галявинах Тірісфалю. Він посилає мандрівників збирати сухе гілля по спустошеному лісу й нести його Елеанор Шеклтон — досвідченій виживальниці, що отаборилася в західних пагорбах.",h="Палиці й кістки — місцеве завдання від Вартового Смерті Бартоломью в Галявинах Тірісфалю.",kw={"палиці й кістки","бартоломью","елеанор шеклтон","гілля","багаття","табір"},ang={["faction:Horde"]="Такі віддалені табори, як у Елеанор, — приязні зупинки для молодих шукачів пригод Орди, що вирушають у мандри Галявинами Тірісфалю.",["race:Undead"]="Навіть у спустошених лісах Лордерону мандрівники з Відступників на кшталт Елеанор Шеклтон мусять пристосовувати давні навички виживання до свого нового нежиття."},sec={{t="Дружній жест",b="Вартові Смерті в Галявинах Тірісфалю зазвичай цілком поглинуті патрулюванням і обороною від Погибелі чи багряних хрестоносців, та Вартовий Смерті Бартоломью знаходить хвилину подбати про знайому. Знаючи, що Елеанор Шеклтон проводить своє нежиття просто неба, серед суворої стихії, він заохочує перехожих шукачів пригод назбирати сухого гілля для її багаття."},{t="Життя в дикій глушині",b="Елеанор Шеклтон пишається тим, що виживає у спустошених нетрях Тірісфалю сама. Хоч Відступники й нежить, вони все одно відчувають вогкий, пронизливий холод, що котиться з північних боліт. Філософія Елеанор щодо хмизу проста: коли вам здається, що дров уже досить, назбирайте ще вп'ятеро більше. Вдячна за додаткове паливо, вона дозволяє гінцеві лишити собі кошик Бартоломью і ділиться теплом свого вогнища."}},fp="16,247,18.361.0,17.436.0,38.135.0,35.140.0,53.241.0,51.138.0,45.164.0,50.154.0"}
P.entries["quest:87"] = {n="Золотозуб",s="«Золотозуб» — завдання в Лісі Елвінн, що завершує пошуки зниклої реліквії тітоньки Берніс Стоунфілд, які мало не розпалили нову ворожнечу. Коли малий Біллі Маклур зізнається, куди поділося намисто, ви маєте вистежити злодійкуватого кобольда, що причаївся біля Копальні Фарґодіп.",h="«Золотозуб» — завдання в Лісі Елвінн, що завершує пошуки зниклої реліквії тітоньки Берніс Стоунфілд, які мало...",kw={"золотозуб","кобольд","намисто","копальня фарґодіп","біллі маклур","берніс стоунфілд"},ang={["race:Human"]="Залагоджена сварка згладжує тертя між двома найстарішими фермерськими родинами Елвінну й водночас дає раду невідчепним кобольдам, що плюндрують королівство."},sec={{t="Хлопчачі витівки",b="Пошуки загубленого родинного намиста тітоньки Берніс Стоунфілд починаються як кисла прикордонна суперечка між ворогуючими Стоунфілдами й Маклурами. Берніс, звісно, підозрювала ворожу родину, та винуватцем виявляється Біллі Маклур. Бавлячись біля Копальні Фарґодіп, малий шибеник загубив дрібничку й поспіхом прикрив провину, запевняючи, що лише натрапив на неї, перш ніж якась істота її поцупила."},{t="Лігво над шахтою",b="За словами Біллі, незвично великий кобольд із блискучими іклами підхопив блискучу пам'ятку й дременув геть. Біллі запевняє, що той побіг до лігва над шахтою, та насправді звір на ім'я Золотозуб ховається на нижньому ярусі всередині Копальні Фарґодіп. Убивши істоту, ви повертаєте намисто Берніс, кладете край сусідській суперечці й отримуєте стару похідну пам'ятку, що лишилася від покійного чоловіка Берніс."}},fp="9,261,16.451.0,22.411.0,36.191.1,29.111.0,35.148.0,61.240.1,39.164.0,41.152.0"}
P.entries["quest:88"] = {n="Принцеса має померти!",s="«Принцеса має померти!» — місцева винагорода від Ма Стоунфілд із Ферми Стоунфілдів на півдні Лісу Елвінн. Вона хоче покласти край Принцесі — величезній призовій свині з сусідньої Гарбузової Ділянки Брекуеллів, яка раз у раз плюндрує її дорогоцінні грядки. Коли буйну свиню буде вбито, Стоунфілди зможуть спокійно зібрати врожай.",h="«Принцеса має померти!» — місцева винагорода від Ма Стоунфілд із Ферми Стоунфілдів на півдні Лісу Елвінн.",kw={"принцеса","свиня","ма стоунфілд","ферма стоунфілдів","гарбузова ділянка","нашийник","вепри"},ang={["faction:Alliance"]="Допомога місцевим фермерам на кшталт Ма Стоунфілд у боротьбі з норовливою худобою підтримує південну житницю Стормвінда, поки регулярної армії королівства тут немає.",["profession:Cooking"]="Розправа з велетенською свинею Принцесою — легендарна історія серед місцевих кухарів, адже велетенські вепри Елвінну дають удосталь ситного м'яса для смаження на відкритому вогні."},sec={{t="Загроза врожаю",b="Ферма Стоунфілдів живе з урожаю, та ненажерлива напасть поставила його під загрозу. Принцеса, уславлена призова свиня Брекуеллів, виросла до потворних розмірів, залазячи на грядки Стоунфілдів і пожираючи їхню городину. Ма Стоунфілд досить нахабної свині, що бенкетує плодами її тяжкої праці, і вона хоче, щоб тварюку вбили, перш ніж та знищить урожай цілого сезону."},{t="Свиняче Поріддя",b="Принцеса рідко блукає сама. На Гарбузовій Ділянці Брекуеллів, що лежить на схід за садибою Маклурів, її постійно оточує вірний почет вепрів-охоронців. Щоб убити цю велетенську свиню, доведеться прорубатися крізь її варту й зняти з її шиї прикметний мідний нашийник — доказ того, що ненажерлива тварюка більше не турбуватиме поля Стоунфілдів."}},fp="18,353,23.426.0,21.383.0,16.219.0,44.265.0,28.186.0,37.258.0,34.136.0,26.135.0"}
P.entries["quest:91208"] = {n="Прийняти і відпустити",s="Це завдання від Араміса Гаммергенда в Похоронному Подзвоні доручає новопіднятим паладинам простягнути руку побратимці-лицарці, яка не може змиритися з нежиттям. Утікши в жаху до пагорбів, щойно повернута воїтелька стикається з болісним усвідомленням: вона стала тим, із чим колись боролася.",h="Це завдання від Араміса Гаммергенда в Похоронному Подзвоні доручає новопіднятим паладинам простягнути руку...",kw={"прийняти і відпустити","араміс гаммергенд","паладин","божевілля","пагорби","похоронний подзвін"},ang={["class:Paladin"]="Це завдання б'є в саме серце дилеми паладина в нежитті: зіткнутися з жахом того, що ви стали тим, що присягалися винищувати.",["race:Undead"]="Психологічна ціна пробудження у Тірісфалі ламає чимало умів; мати справу з тими, кого поглинула паніка, — трагічна дійсність раннього життя Відступників."},sec={{t="Гірке воскресіння",b="Пробудження зі смерті в лавах Відступників приголомшує будь-кого, та для колишніх паладинів Срібної Длані удар особливо глибокий. Присвятивши смертне життя винищенню нежиті в служінні Святому Світлу, ці люди раптом виявляють, що їхні душі знову прив'язані до розкладеної плоті. Хтось пристосовується під наставництвом Араміса Гаммергенда, а когось переповнюють жах і сум'яття, і вони тікають у нетрі Тірісфалю, замість зустріти своє похмуре нове існування віч-на-віч."},{t="Милосердне звільнення",b="Араміс Гаммергенд сподівається, що побратим-лицар зуміє достукатися до паладинки, яка в паніці сховалася в пагорбах на захід від каплиці, — зі співчуттям і розумінням. На жаль, тягар переміни доводить її до цілковитого божевілля. Коли до неї підходять, вона сліпо кидається в бій зі страху й люті, не лишаючи вибору, крім як убити її. Для тих Відступників, чий розум розбивається вже на могилі, швидкий кінець — єдине милосердя, що лишилося."}},fp="15,283,21.505.0,18.425.1,30.189.0,39.223.1,36.188.0,35.129.0,40.111.0,46.180.1"}
P.entries["quest:91209"] = {n="Продовжуй навчання",s="Це завдання велить новопіднятим паладинам Відступників залишити Похоронний Подзвін і вирушити до Брілла по поглиблене навчання. Доручена Арамісом Гаммергендом подорож знайомить молодого святого воїна з ширшими небезпеками Галявин Тірісфалю. Вона також суворо попереджає про глибоку підозру, з якою нежить ставиться до носіїв святої сили.",h="Це завдання велить новопіднятим паладинам Відступників залишити Похоронний Подзвін і вирушити до Брілла по...",kw={"продовжуй навчання","араміс гаммергенд","шарі стілвелл","паладин","брілл","похоронний подзвін"},ang={["class:Paladin"]="Для паладина-нежиті цей перехід — тверезе нагадування: володіння святою силою робить вас чужинцем навіть серед побратимів-Відступників.",["race:Undead"]="Завдання висвітлює внутрішню напругу в суспільстві Відступників, де вірність землі Лордерону стикається з незагоєною травмою, пов'язаною зі Святим Світлом."},sec={{t="Вихід із Похоронного Подзвону",b="Щойно пробуджена душа опановує ази бою й спрямування святої сили в замкненому цвинтарі Похоронного Подзвону, Араміс Гаммергенд відсилає її на схід, у ширші простори Галявин Тірісфалю. Мета — Брілл, жвава застава краю, що править за адміністративний осередок центрального Тірісфалю. Там Шарі Стілвелл наглядає за поступом тих, хто наважився йти шляхом паладина в нежитті."},{t="Хистке покликання",b="На прощання Араміс дає пораду, яка підкреслює непросту дійсність паладина-нежиті. Лордерону досі потрібні захисники від зовнішніх загроз, та володіння Святим Світлом під знаменом Сильвани Віндраннер викликає гірку підозру. Незліченні Відступники зазнали мук або смерті від рук святих фанатиків, тож сама присутність Світла породжує недовіру серед їхніх побратимів по нежитті."}},fp="22,342,18.436.0,20.392.0,46.111.0,42.137.0,38.288.0,39.160.0,14.155.0,53.166.0"}
P.entries["quest:916"] = {n="Отрута Вебвуда",s="«Отрута Вебвуда» — завдання Альянсу в Тінедолі, що на Тельдрассилі. Учений Ґілшалан Віндвокер доручає юним нічним ельфам зібрати отруйні залози велетенських павуків Вебвуда, щоб дослідити, як ріст нового Світового Дерева вплинув на корінну живність.",h="«Отрута Вебвуда» — завдання Альянсу в Тінедолі, що на Тельдрассилі.",kw={"отрута вебвуда","павуки","ґілшалан віндвокер","печера тіньової нитки","тінедол","тельдрассил"},ang={["class:Druid"]="Друїди кровно зацікавлені у висновках Ґілшалана, адже розуміння того, зцілює чи спотворює Тельдрассил довколишню живність, — осердя пильності Кола Кенарія.",["race:NightElf"]="Для юних нічних ельфів, що дорослішають у Тінедолі, це завдання — ранній урок того, якою крихкою й непередбачуваною стала природа під гіллям Тельдрассила."},sec={{t="Цікавість природознавця",b="Ґілшалан Віндвокер прибув до Тінедола вивчати неприродні розміри й агресію місцевих павуків Вебвуда, що заполонили Печеру Тіньової Нитки. Він зауважує, що ці створіння — родичі куди менших видів з інших країв. Підозрюючи, що величезні магічні сили Тельдрассила спричиняють стрімкі й тривожні мутації місцевої фауни, він просить отруйні залози, щоб порівняти їхні біологічні властивості зі звичайними павуками."},{t="Нависла загроза в Тінедолі",b="Павуки Вебвуда, що живуть довкола Печери Тіньової Нитки й усередині неї, стають дедалі небезпечнішими для юних новачків нічних ельфів у долині. Збирання їхньої отрути слугує двом цілям: воно проріджує небезпечне місцеве нашестя й дає дослідникам із Дарнасуса прямі біологічні докази бурхливого впливу Тельдрассила на дику природу."}},fp="13,247,24.442.0,32.357.0,28.207.0,37.205.0,27.131.0,43.185.0,44.162.0,33.152.0"}
P.entries["quest:917"] = {n="Яйце Павука Вебвуда",s="Ґілшалан Віндвокер доручає юним захисникам у Тінедолі добути невилуплене павуче яйце з глибин Печери Тіньової Нитки. Зібравши зразки отрути, він потребує живих особин, щоб дослідити неприродну агресію живності Тельдрассила. Невилуплена кладка дозволяє вченим безпечно вивчати цих створінь, не впокорюючи дорослих павуків.",h="Ґілшалан Віндвокер доручає юним захисникам у Тінедолі добути невилуплене павуче яйце з глибин Печери Тіньової...",kw={"яйце павука вебвуда","павуки","ґілшалан віндвокер","печера тіньової нитки","тінедол","дарнасус"},ang={["class:Druid"]="Вивчення яєць і отрути дає дослідникам Кола Кенарія змогу визначити, чи можна очистити зіпсуття, що змінює цих звірів, чи пошесть сягає глибше.",["race:NightElf"]="Для юних нічних ельфів добування цього яйця показує підступне зіпсуття, що охоплює Тельдрассил і змушує вчених вивчати живність рідного краю як ворожу загрозу."},sec={{t="Безпечний зразок",b="Здобувши сиру отруту агресивних павуків Вебвуда, що нишпорять околицями Тінедола, Ґілшалан Віндвокер потребує живих піддослідних, аби краще зрозуміти їхнє неприродне зіпсуття. Знаючи, що витягати з підземних глибин велетенського павука, який шалено пручається, для будь-якого новачка смертельно, Ґілшалан обирає практичніший спосіб: невилуплене яйце, взяте просто з виводкових кладок у Печері Тіньової Нитки."},{t="Шлях до столиці",b="Печера Тіньової Нитки — підземний розплідник дедалі ворожіших лісових павуків. Проникнення до печери й добування цілого яйця дає вченим контрольований зразок, що може вилупитися в ізоляції. Ґілшалан має намір спакувати яйце разом зі зразками отрути й відправити просто до Дарнасуса для подальшого вивчення — так завершується його польове дослідження, а новобранців скеровують до вищих обов'язків на гіллі Алдрассила."}},fp="11,383,15.437.0,23.476.0,58.293.0,31.150.0,28.194.0,46.214.0,38.156.0,42.204.0"}
P.entries["quest:918"] = {n="Насіння деревляників",s="«Насіння деревляників» — раннє завдання від ботаніка Деналана біля Озера Ал'Амет у Тельдрассилі. Стривожений дедалі більшою ворожістю місцевих елементалів природи, Деналан хоче зібрати їхнє насіння й перевірити, чи виростить збагачений ґрунт спокійніше, злагідніше покоління. Завдання відкриває тихі зусилля травників нічних ельфів зрозуміти ледь помітні недуги Світового Дерева.",h="«Насіння деревляників» — раннє завдання від ботаніка Деналана біля Озера Ал'Амет у Тельдрассилі.",kw={"насіння деревляників","деревляники","деналан","озеро ал'амет","ґрунт","тельдрассил"},ang={["class:Druid"]="Друїди мають глибоку спорідненість із духами природи. Допомога дослідженню Деналана береже рівновагу стихій без опори лише на криваве проріджування.",["profession:Herbalism"]="Збирачі, чутливі до флори Тельдрассила, оцінять ботанічні досліди Деналана, що вивчають тонкий зв'язок між рослинним насінням і збагаченим ґрунтом.",["race:NightElf"]="Для калдорей деревляники — прямий показник здоров'я Тельдрассила. Бачити, як ці лагідні духи дичавіють, — моторошний знак, що їхня нова домівка хвора."},sec={{t="Неспокійна природа",b="Деревляники — елементалі природи, корінні мешканці гілля Тельдрассила, нерозривно пов'язані зі здоров'ям і силою довколишньої флори. Зазвичай вони — мирне відображення лісової рівноваги, тож їхня недавня й незрозуміла ворожість стривожила місцевих нічних ельфів. Замість просто винищувати їх, ботанік Деналан сподівається зрозуміти джерело їхнього збурення."},{t="Насіння нового росту",b="Підозрюючи, що вада криється глибоко в самій землі, Деналан має намір проростити свіжих деревляників у збагаченому, дбайливо обробленому ґрунті. Збираючи насіння з деревляників, що блукають біля Озера Ал'Амет, він сподівається виплекати лагідніше покоління елементалів і з'ясувати, чи можна протидіяти зіпсуттю землі від самого коріння."}},fp="16,418,15.378.0,21.341.0,21.153.0,43.202.0,15.165.0,39.112.0,44.172.0,53.190.0"}
P.entries["quest:919"] = {n="Паростки деревляників",s="«Паростки деревляників» — завдання від спостерігача за природою Деналана біля Озера Ал'Амет у центрі Тельдрассила. Стривожений раптовим і неприродним розмноженням лісових паростків на берегах озера, Деналан просить мандрівників викорінити їх, перш ніж вони виростуть у ворожих деревляників. Завдання показує перші ознаки того, що повзуче зіпсуття порушує рівновагу щойно вирослого Світового Дерева.",h="«Паростки деревляників» — завдання від спостерігача за природою Деналана біля Озера Ал'Амет у центрі...",kw={"паростки деревляників","деревляники","деналан","озеро ал'амет","зіпсуття","тельдрассил"},ang={["class:Druid"]="Друїди відповідають за тонку рівновагу природи; викорінювати уражені паростки — сумний, але необхідний обов'язок заради ширшої екосистеми.",["profession:Herbalism"]="Травники добре знають, як має рости здорова рослинність, і одразу розпізнають, що ці паростки хворі й неприродно скручені.",["race:NightElf"]="Для калдорей Тельдрассил мав стати новим прихистком, тож зіпсутий ріст біля священних вод, як-от Озера Ал'Амет, — глибоко тривожне знамення."},sec={{t="Прополювання Озера Ал'Амет",b="На тихих берегах Озера Ал'Амет дивні рослиноподібні створіння, відомі як деревляники, почали множитися з тривожною швидкістю. Замість рости в злагоді з лісом, молоді паростки деревляників виказують ознаки зіпсуття з тієї миті, як пускають коріння. Деналан, відданий учень природи, що живе біля озера, розуміє: ці паростки вже не зцілити. Якщо їх не спинити, вони швидко виростають у агресивних укритих корою створінь, що загрожують місцевій живності й необачним мандрівникам. Збирання й знищення паростків — перша лінія оборони, що тримає гай чистим."},{t="Ознаки глибшої скверни",b="Викорінення паростків допомагає впоратися з місцевою загрозою, та Деналан із жахом зауважує, як швидко вони з'являються. Їхнє нестримне розмноження — неприродне явище для Тельдрассила. Заражені паростки — не окреме нашестя, а симптом глибшої недуги, що загрожує корінню й ґрунту самого Світового Дерева, — загадка, яку Деналан і друїди Дарнасуса квапляться розгадати."}},fp="18,402,21.618.0,23.414.0,28.245.0,15.222.0,53.227.0,28.119.0,54.251.0,42.159.0"}
P.entries["quest:920"] = {n="Виклик Тенарона",s="«Виклик Тенарона» — важливий перелом для юних нічних ельфів у Тінедолі. Допомігши Ґілшалану Віндвокеру з місцевими лісовими небезпеками, ви одержуєте поклик піднятися на могутнє гілля Алдрассила — на розмову з Тенароном Стормґріпом. Цей виклик знаменує мить, коли новачок лишає позаду дрібні місцеві клопоти, щоб стати проти глибших духовних недуг Тельдрассила.",h="«Виклик Тенарона» — важливий перелом для юних нічних ельфів у Тінедолі.",kw={"виклик тенарона","тенарон стормґріп","ґілшалан віндвокер","алдрассил","тінедол","місячні колодязі"},ang={["class:Druid"]="З'явитися до Тенарона Стормґріпа — неодмінний крок, щоб дізнатися, як стежать за друїдською рівновагою Тельдрассила і як її підтримують.",["race:NightElf"]="Цей виклик знаменує ваше повноліття серед калдорей: від простого захисту лісу ви переходите до прямого служіння старійшинам, що доглядають Світове Дерево."},sec={{t="Поклик на гілля",b="Ваше вміння дати раду отруйним павукам і зіпсутій живності, що заворушилася в долині, не лишається непоміченим. Ґілшалан Віндвокер переказує, що сам Тенарон Стормґріп просить вас прибути. Навіть серед надзвичайно довговічних нічних ельфів змушувати старійшину-друїда чекати на вершині великого дерева Алдрассил вважається поганим тоном."},{t="Сходження на Алдрассил",b="Тенарон чекає у найвищій залі Алдрассила, споглядаючи зелене гілля Тінедола. Відгук на цей виклик веде просто до більших справ опіки: очищення місячних колодязів Тельдрассила й дослідження неприродного зіпсуття, що повзе в юну екосистему Світового Дерева."}},fp="17,375,20.370.0,19.317.0,25.231.0,34.182.0,27.224.0,30.200.0,25.155.0,18.189.0"}
P.entries["quest:921"] = {n="Корона Землі",s="«Корона Землі» — вступний обряд від Тенарона Стормґріпа високо в Алдрассилі. Юних нічних ельфів, що готуються вийти за межі Тінедола, посилають набрати священної води з сусіднього місячного колодязя й зустрітися з болісною історією гори Гіджал і втраченого безсмертя їхнього народу.",h="«Корона Землі» — вступний обряд від Тенарона Стормґріпа високо в Алдрассилі.",kw={"корона землі","тенарон стормґріп","місячний колодязь","гора гіджал","нордрассил","безсмертя","алдрассил"},ang={["class:Druid"]="Місячні колодязі — неодмінне знаряддя Кола Кенарія: вони дають очищені провідники сили природи, конче потрібні для підтримання лісової рівноваги.",["class:Priest"]="Присвячені Елуні місячні колодязі — святині для роздумів, де води освячує погляд Матері-Місяця.",["race:NightElf"]="Цей обряд знаменує ваш вихід із Тінедола й пов'язує вашу особисту долю з жертвою на вершині гори Гіджал і з відповідальністю за Тельдрассил."},sec={{t="Урок недавньої історії",b="Перш ніж будь-який шукач пригод-початківець покине затишне гілля Тінедола, старійшини дбають, щоб він усвідомив, яку страшну ціну нещодавно заплатили калдореї. У битві за гору Гіджал Світове Дерево Нордрассил було принесено в жертву, щоб здолати Архімонда й вигнати Палаючий Легіон. З тим нищівним вибухом нічні ельфи втратили своє вічне безсмертя й священний щит. Тенарон Стормґріп — водночас наставник та історик: він дає новачкам цей обряд, щоб прищепити смирення й мету, перш ніж вони зустрінуть мінливий світ."},{t="Води колодязя",b="Завдання вимагає набрати кришталевою фіалою води з місячного колодязя на північ від Алдрассила. Ці місячні колодязі — не звичайні джерела: їхні води сповнені решток прадавнього Колодязя Вічності. Друїди спрямовують їхню відновлювальну силу в дику природу, а Вартові шанують їх як тихі святині богині Елуни, та калдореї лишаються вкрай обережними. Таємна магія в суспільстві нічних ельфів і досі суворо заборонена, адже джерело, що живить їхню землю, нагадує й про безрозсудні чари, які колись мало не розкололи світ."}},fp="18,298,26.527.0,18.561.0,25.270.0,49.294.0,47.286.0,35.305.0,38.266.0,45.132.0"}
P.entries["quest:927"] = {n="Серце, оплетене мохом",s="Оповите Мохом Серце — дивне зіпсуте осердя, вийняте з жахливого деревляника Блекмосса Смердючого. Укрите масним темним мохом, серце моторошно продовжує битися саме по собі, спонукаючи ботаніка Деналана з Озера Ал'Амет до дослідження.",h="Оповите Мохом Серце — дивне зіпсуте осердя, вийняте з жахливого деревляника Блекмосса Смердючого.",kw={"серце оплетене мохом","блекмосс смердючий","деревляник","деналан","озеро ал'амет","мох","зіпсуття"},ang={["class:Druid"]="Друїди Кола Кенарія пильно цікавляться такими аномаліями, як це уражене серце, що б'ється: вони прагнуть визначити, чи можна вичистити зіпсуття, чи воно свідчить про глибшу гниль.",["profession:Herbalism"]="Кожен, хто вивчає рослини, бачить: масний наріст на цій серцевині цілком неприродний — він кидає виклик звичним законам ботаніки, підтримуючи життя у відтятому серці.",["race:NightElf"]="Для калдорей бачити, як молоде Світове Дерево Тельдрассил плодить заражених агресивних деревляників на кшталт Блекмосса, — тверезий знак, що їхню нову домівку мучить повзуча хвороба."},sec={{t="Серцевина, що б'ється",b="Вирізане з решток Блекмосса Смердючого, це серце деревляника майже не впізнати під шаром темного масного моху. Єдине, що видає його справжню природу, — повільний ритмічний пульс, який не вщухає навіть після того, як серце відтяли від створіння. Така неприродна живучість натякає, що зіпсуття, яке шириться дикою рослинністю Тельдрассила, сягає куди глибше за звичайну гниль."},{t="Огляд Деналана",b="Деналан, уважний дослідник місцевої флори, що облаштувався біля Озера Ал'Амет, одразу розпізнає, яку похмуру правду несе ця знахідка. Деревляники мали б бути лагідними створіннями, сплетеними з гіллям Світового Дерева, та це серце виказує шалений уражальний вплив. Заінтригований і стривожений, Деналан вирішує посадити зіпсутий орган і вивчити його, щоб зрозуміти мерзенний мох, який укорінюється в ґрунті острова."}},fp="21,262,14.391.0,21.417.0,43.125.0,31.174.0,15.214.0,36.152.0,36.180.0,50.162.0"}
P.entries["quest:928"] = {n="Корона Землі",s="«Корона Землі» — перехідна подорож, що виводить юних нічних ельфів із Тінедола в ширші володіння Тельдрассила. Несучи священну воду місячного колодязя, освячену на вершині Алдрассила, мандрівники прямують на південь лісовою дорогою до Корітраса Мунрейджа в Доланаарі. Це випуск із відлюдного вишколу — до нагального екологічного захисту великого Світового Дерева.",h="«Корона Землі» — перехідна подорож, що виводить юних нічних ельфів із Тінедола в ширші володіння Тельдрассила.",kw={"корона землі","корітрас мунрейдж","тенарон стормґріп","місячний колодязь","тінедол","доланаар"},ang={["class:Druid"]="Перенесення освячених вод пов'язує молодих друїдів із тривалими, крихкими зусиллями плекати й урівноважувати буйну екосистему Тельдрассила.",["class:Priest"]="Нести воду місячного колодязя, освячену благодаттю Елуни, — священний обов'язок її жрецтва дбати про духовне здоров'я громади.",["race:NightElf"]="Крок за межі Тінедола — неодмінний обряд переходу для кожного юного калдорея, що вирушає служити своєму народові."},sec={{t="Прощання з галявиною",b="Довівши свою відданість збиранням зачарованої води з місячного колодязя Тінедола, посвячених кличуть до Тенарона Стормґріпа на вершину Алдрассила. Визнавши їхню готовність, Тенарон запечатує набрану воду в більшу посудину й велить вирушати за межі затишного гаю. Дорога на південь до Доланаара — головна артерія з Тінедола, що в'ється лісами, які стають дедалі непередбачуванішими й ворожішими."},{t="Дорога до Доланаара",b="Доланаар — перше велике село, яке зустрічають мандрівники, виходячи зі стартової долини. Поселення, що розкинулося вздовж брукованих стежок центрального Тельдрассила, вирує довкола власного незайманого місячного колодязя. Тут чекає Корітрас Мунрейдж — старійшина, якому доручено наглядати за ширшими зусиллями зі збереження на гіллі. Посудина, передана в його руки, пов'язує шукача пригод-початківця безпосередньо з ширшою, тривожною долею Світового Дерева."}},fp="18,388,17.462.0,20.460.0,31.243.0,26.209.0,46.250.0,30.199.0,45.223.0,37.178.0"}
P.entries["quest:929"] = {n="Корона Землі",s="«Корона Землі» — священне завдання від Корітраса Мунрейджа в Доланаарі: набрати освяченої води з місячного колодязя біля Села Зоряного Вітерця. В обмін на поповнення вод Дарнасуса юні нічні ельфи дізнаються трагічну історію, що привела їхній народ до вирощування могутнього гілля Тельдрассила.",h="«Корона Землі» — священне завдання від Корітраса Мунрейджа в Доланаарі: набрати освяченої води з місячного...",kw={"корона землі","корітрас мунрейдж","місячний колодязь","село зоряного вітерця","нордрассил","малфуріон стормрейдж","іллідан"},ang={["class:Druid"]="Місячні колодязі — життєво важливі провідники природної й зоряної магії, живі водойми, що пов'язують обов'язки вашого ордену в Дарнасусі з корінням Тельдрассила.",["race:NightElf"]="Кожен нічний ельф мусить зустрітися з втратою безсмертя й зникненням Малфуріона Стормрейджа, тож цей священний обряд збирання — неодмінний урок недавнього горя вашого народу."},sec={{t="Живлення місячних колодязів",b="Великий центральний місячний колодязь Дарнасуса потребує постійного зв'язку з меншими джерелами, розсіяними по короні Світового Дерева. Друїди виготовляють витончені нефритові фіали саме для того, щоб набирати й переносити ці сяйливі води, не порушуючи їхньої чистоти. Посилаючи посвячених пішки до Села Зоряного Вітерця, старійшини дбають і про те, щоб міські фонтани повнилися благодаттю Елуни, і про те, щоб молодь зрозуміла, якої праці вимагає живлення Тельдрассила."},{t="Відлуння Третьої війни",b="За виконану роботу посвячений одержує в нагороду усну історію. Корітрас Мунрейдж розповідає про розпач, що охопив калдорей одразу після битви за гору Гіджал. Жертва прадавнього Світового Дерева Нордрассил позбавила нічних ельфів дорогоцінного безсмертя, а серед руїни на волю вирвався Іллідан Стормрейдж, тоді як Шан'до Малфуріона Стормрейджа поглинув Смарагдовий Сон. Ця атмосфера скорботи й самотності заклала підґрунтя для суперечливого висадження Тельдрассила."}},fp="18,313,24.463.0,23.498.0,46.189.0,44.106.0,26.168.0,46.200.0,47.222.0,18.146.0"}
P.entries["quest:931"] = {n="Мерехтливе листя",s="Серед коріння й крон Тельдрассила знайдено дивовижну рослину, що випромінює неземне мерехтіння. Усвідомлюючи її рідкісність, мандрівники несуть зразок ботанікові Деналану до Озера Ал'Амет, щоб з'ясувати її походження.",h="Серед коріння й крон Тельдрассила знайдено дивовижну рослину, що випромінює неземне мерехтіння.",kw={"мерехтливе листя","деналан","озеро ал'амет","болото скорботи","рослина","тельдрассил"},ang={["class:Druid"]="Друїди, що пильнують рівновагу Великого Дерева, беруть на замітку чужорідні рослини, занесені до тонкої молодої крони Тельдрассила.",["profession:Herbalism"]="Травники й шанувальники рослин оцінять ботанічну інтригу: болотяна рослина буяє за тисячі миль від рідної екосистеми.",["race:NightElf"]="Для нічних ельфів, що доглядають нову домівку, досліди Деналана дають важливе розуміння того, наскільки витривалий насправді ґрунт Тельдрассила."},sec={{t="Дивне сяйво",b="Блукаючи зеленим гіллям Тельдрассила, уважні мандрівники можуть натрапити на дивну рослину з розлогим листям. На відміну від звичайної лісової зелені, її листя ловить світло й мерехтить пульсівним, звивистим сяйвом. Така неприродна поява впадає в око кожному, хто дбає про тонку, щойно народжену екосистему острова."},{t="Відкриття Деналана",b="Принесений ботанікові Деналану до Озера Ал'Амет живець відкриває несподівану правду. Деналан упізнає в рослині чужоземний зразок, не властивий півночі Калімдору: востаннє він бачив такий вид десятиліття тому, під час подорожі до далекого Болота Скорботи у Східних Королівствах. Зачарований тим, як таке насіння могло перетнути океан і вирости на Світовому Дереві до таких вражаючих розмірів, Деналан одразу береться вирощувати й випробовувати зразок."}},fp="20,224,14.334.0,19.478.1,50.222.0,15.252.0,40.225.0,47.204.1,47.188.0"}
P.entries["quest:932"] = {n="Спотворена ненависть",s="«Спотворена ненависть» — таємне завдання від Таллонкая Свіфтрута в Тельдрассилі. Він просить довірених звитяжців спуститися в печеру Скелі Скверни й стратити Лорда Меленаса — сатира, що збирає місцевих ґреллів в організовану зіпсуту силу небезпечно близько до поселень нічних ельфів.",h="«Спотворена ненависть» — таємне завдання від Таллонкая Свіфтрута в Тельдрассилі.",kw={"спотворена ненависть","лорд меленас","сатир","скеля скверни","ґрелли","таллонкай свіфтрут","тельдрассил"},ang={["class:Druid"]="Мерзенна присутність Меленаса та його зіпсутих ґреллів біля Скелі Скверни труїть крихку рівновагу щойно вирослих хащ Тельдрассила.",["race:NightElf"]="Кожен сатир — давнє нагадування про падіння ваших предків перед демонічними амбіціями; стяти Лорда Меленаса — і обов'язок перед Світовим Деревом, і акт спокути за предків."},sec={{t="Гірка ганьба",b="Для нічних ельфів сатири — жива пам'ять про давню зраду. Народжені з Високородних, що віддалися Палаючому Легіону під час Війни Древніх, ці козлоногі демони — болюча, невитравна пляма на історії калдорей. Те, що сатир закріпився просто тут, у Тельдрассилі, молодому Світовому Дереві, яке мало стати прихистком, місцеві захисники, як-от Таллонкай Свіфтрут, сприймають як гостру ганьбу."},{t="Загроза біля Скелі Скверни",b="На північ від найближчих стежок лежить Скеля Скверни — зіпсута система печер, що кишить здичавілими ґреллами. Лорд Меленас згуртував цих від природи хаотичних створінь у ворожу, впорядковану силу під своєю темною волею. Побоюючись того, що сатир замислив випустити на гілля Світового Дерева, Таллонкай вимагає усунути Меленаса швидко, тихо й рішуче — і принести на доказ його відтяту голову."}},fp="14,280,17.452.0,22.395.0,20.193.0,30.143.0,51.299.0,50.218.0,54.273.0,27.189.0"}
P.entries["quest:933"] = {n="Корона Землі",s="«Корона Землі» — завдання Альянсу від Корітраса Мунрейджа в Доланаарі. Він велить вам набрати води з місячного колодязя біля Озерець Арлітрієну — у краї, якому дедалі більше загрожують знавіснілі фурболґи Вузлошкіри. Виконавши завдання, ви дізнаєтеся, як Архідруїд Фандрал Стаґгелм згуртував нічних ельфів, щоб виростити Тельдрассил після зникнення Малфуріона Стормрейджа.",h="«Корона Землі» — завдання Альянсу від Корітраса Мунрейджа в Доланаарі.",kw={"корона землі","корітрас мунрейдж","озерця арлітрієну","фандрал стаґгелм","вузлошкіри","місячний колодязь","тельдрассил"},ang={["class:Druid"]="Розкол Кола Кенарія під проводом Фандрала Стаґгелма стає зрозумілішим, коли Корітрас розповідає про відчайдушне прагнення повернути давнє безсмертя.",["race:NightElf"]="Цей відтинок вашої подорожі пояснює суперечливий політичний поштовх, що породив Тельдрассил після раптового зникнення Малфуріона."},sec={{t="Небезпечний місячний колодязь",b="Корітрас Мунрейдж доручає вам віднести турмалінову фіалу до місячного колодязя на південний схід від входу в Дарнасус, на берегах Озерець Арлітрієну. Дорога зовсім не спокійна. Колись мирні фурболґи Вузлошкіри піддалися раптовій кривавій люті: вони нападають на мандрівників із засідок і виснажують патрулі Вартових по всьому краю. Те, що перші звіти списували на окремі сутички, переросло в повсюдну загрозу, яка переслідує нову домівку нічних ельфів."},{t="Амбіції Фандрала Стаґгелма",b="Одержавши наповнену фіалу, Корітрас ділиться важливою історією створення Тельдрассила. Після Третьої війни Шан'до Малфуріон Стормрейдж зник, і друїди Кола Кенарія лишилися без проводу, розколоті. За його відсутності мантію лідера перебрав Архідруїд Фандрал Стаґгелм. Стаґгелм переконав Коло Древніх у Темному Узбережжі, що нічні ельфи не можуть дозволити собі бездіяльної жалоби: їм треба повернути втрачене безсмертя й зцілити свою цивілізацію, висадивши нове величезне Світове Дерево."}},fp="18,377,19.474.0,27.513.0,37.131.0,41.317.0,37.210.0,32.292.0"}
P.entries["quest:934"] = {n="Корона Землі",s="«Корона Землі» — ключовий крок у ланцюжку завдань Доланаара, що досліджує недуги Тельдрассила. Корітрас Мунрейдж доручає шукачам пригод набрати води зі священного місячного колодязя на Галявині Оракула, а подорож використовує, щоб відкрити тривожну правду про створення Світового Дерева.",h="«Корона Землі» — ключовий крок у ланцюжку завдань Доланаара, що досліджує недуги Тельдрассила.",kw={"корона землі","галявина оракула","аметистова фіала","фандрал стаґгелм","ноздорму","алекстраза","корітрас мунрейдж"},ang={["class:Druid"]="Для Кола Кенарія відвідини Дерева Оракула підкреслюють ідейний розкол між наполегливими амбіціями Фандрала Стаґгелма й природною рівновагою, яку традиційно беріг Малфуріон Стормрейдж.",["faction:Alliance"]="Розуміння крихкого стану Тельдрассила пояснює невідступну пошесть і безумство створінь, що мучать найновішу столичну землю Альянсу.",["race:NightElf"]="Подорож торкається надій нічних ельфів на Тельдрассил після жертви Нордрассила в Третій війні."},sec={{t="Галявина Оракула",b="Корітрас Мунрейдж скеровує мандрівників далеко на північний захід Тельдрассила, під величну крону Галявини Оракула. Просто під могутнім гіллям Дерева Оракула лежить перший і найпотужніший місячний колодязь, зведений на острові. Наповнивши Аметистову Фіалу з його мерехтливих вод, шукачі опиняються віч-на-віч із головним святилищем, звідки друїди й саме дерево стежать за здоров'ям нової батьківщини."},{t="Відмовлене благословення",b="Коли ви повертаєте фіалу до Доланаара, Корітрас відкриває темну ваду у величному задумі Архідруїда Фандрала Стаґгелма. Після жертви Нордрассила на горі Гіджал Стаґгелм прагнув повернути нічним ельфам безсмертя: висадити Тельдрассил і попросити благословення Драконячих Аспектів. Але Ноздорму Позачасний відмовив, дорікнувши Стаґгелмові за його зухвалу пиху. Королева Алекстраза вчинила так само й не дала життєво важливого благословення Аспекта Життя — тож ріст Тельдрассила лишився бурхливим, недосконалим і вразливим до глибокого зіпсуття."}},fp="18,298,16.444.0,19.546.1,43.172.0,26.202.0,45.164.0,62.186.0"}
P.entries["quest:935"] = {n="Корона Землі",s="«Корона Землі» — вінець обрядів очищення священних місячних колодязів Тельдрассила. Передання зібраних вод Архідруїдові Фандралу Стаґгелму в Дарнасусі підкреслює дедалі більшу тривогу через хибне, неблагословенне існування Світового Дерева.",h="«Корона Землі» — вінець обрядів очищення священних місячних колодязів Тельдрассила.",kw={"корона землі","фандрал стаґгелм","архідруїд","ценаріонський анклав","місячні колодязі","аспекти","дарнасус"},ang={["class:Druid"]="Несучи води місячних колодязів Архідруїдові Кола Кенарія, ви стаєте просто перед Фандралом Стаґгелмом і бачите гострий політичний і духовний розкол, що охопив друїдський провід за відсутності Малфуріона.",["faction:Alliance"]="Для ширшого Альянсу Дарнасус — величава столиця давніх таємниць, та зіпсуті хащі довкола неї доводять, що й нічні ельфи стикаються з внутрішніми загрозами на власній священній землі.",["race:NightElf"]="Цей обряд оголює тиху тривогу під вашою новою домівкою: Тельдрассил висадили з гордині, без благословення Драконячих Аспектів, і його дедалі тяжча хвороба нагадує, який крихкий новий початок вашого народу."},sec={{t="Хибний початок",b="Тельдрассил виростили після Третьої війни, щоб дати нічним ельфам нову домівку й повернути втрачене безсмертя. Та Великі Аспекти Алекстраза й Ноздорму відмовили в благословенні й не схвалили створення дерева. Без їхнього божественного захисту Тельдрассил став жертвою повзучої хвороби: з гілля виринають химерні створіння, а колись мирні племена фурболґів поринають у безумство."},{t="Доставка Архідруїдові",b="Корітрас Мунрейдж доручає юним шукачам пригод збирати воду з місячних колодязів по всьому острову, щоб стежити за недугами гілля й гамувати їх. Злив ці зразки в одну посудину, Корітрас посилає гінця вглиб Дарнасуса, до Ценаріонського Анклаву. Там сидить Архідруїд Фандрал Стаґгелм, творець Тельдрассила, який бачить у повзучому зіпсутті не знамення гордині, а прикрий тягар, який мусить нести він сам."}},fp="18,263,16.435.0,26.439.1,51.316.0,58.332.0,45.167.0,26.282.0,41.251.1,64.307.0"}
P.entries["quest:937"] = {n="Зачарований гай",s="На Галявині Оракула, на північному заході Тельдрассила, Вартова Аринія Клаудзбрейк силкується захистити прадавнє Дерево Оракула від агресивних гарпій Кривавого Пера. Після того як посланого до Дарнасуса гінця вбили, захисників кличуть ударити у відповідь по гніздах гарпій і принести на доказ їхні пояси.",h="На Галявині Оракула, на північному заході Тельдрассила, Вартова Аринія Клаудзбрейк силкується захистити...",kw={"зачарований гай","галявина оракула","дерево оракула","гарпії кривавого пера","аринія клаудзбрейк","тельдрассил"},ang={["class:Druid"]="Друїди глибоко шанують розумних древнів; очищення гаю від гарпій, що загрожують Дереву Оракула, береже природну рівновагу галявини.",["faction:Alliance"]="Допомога Вартовим в убезпеченні священних гаїв Тельдрассила зміцнює зв'язки з проводом нічних ельфів у сусідньому Дарнасусі.",["race:NightElf"]="Захищати прадавніх духів Світового Дерева й берегти Вартових від наруги гарпій — урочистий обов'язок кожного калдорея."},sec={{t="Галявина в облозі",b="Галявина Оракула — одна зі священних обителей Тельдрассила, осердям якої є велетенський прадавній древень, відомий як Дерево Оракула. Вартову Аринію Клаудзбрейк відрядили з загоном воїнів пильнувати цей шанований стовбур. На жаль, дикі гарпії Кривавого Пера вдерлися до западин, агресивно гніздяться по всій довколишній кроні й загрожують кожному, хто наблизиться."},{t="Перерваний зв'язок із Дарнасусом",b="Напруга сягнула краю, коли Дерево Оракула спробувало послати до столиці, Дарнасуса, гінця з терміновою доповіддю. Посланець так і не вибрався з гілля: гарпії влаштували засідку й розтерзали його, перш ніж доповідь покинула галявину. У відповідь Аринія доручила місцевим шукачам пригод прорідити зграю й добути пояси Кривавого Пера, щоб відтіснити наступ."},{t="Виклик від Дерева",b="Щойно безпосередню загрозу від сусідніх гнізд зменшено, відгукується саме прадавнє дерево. Дерево Оракула скидає уламок своєї зачарованої кори, шукаючи посланця, що передасть його послання до рук найвищого проводу калдорей."}},fp="19,311,19.405.0,26.391.0,23.248.1,43.222.0,35.216.0,46.163.0,24.185.0,45.153.0,39.192.1"}
P.entries["quest:938"] = {n="Імла",s="«Імла» — завдання-супровід у тінистому гіллі Тельдрассила. Знайшовши глибоко в лісі покинуту поранену сіру шаблезубу кішку, мандрівники мають безпечно провести її назад до Вартової Аринії Клаудзбрейк, що чекає біля місячного колодязя неподалік.",h="«Імла» — завдання-супровід у тінистому гіллі Тельдрассила.",kw={"імла","шаблезуба кішка","супровід","аринія клаудзбрейк","гарпії","тельдрассил"},ang={["class:Hunter"]="Кожен володар звірів упізнає люту відданість і розумний погляд в очах Імли, тож безпечно повернути її партнерці — справа професійної честі.",["faction:Alliance"]="Допомога Вартовим у Тельдрассилі зміцнює життєво важливу прихильність між молодим Альянсом і калдореями — захисниками Світового Дерева.",["race:NightElf"]="Зв'язок між Вартовою і шаблезубом — наріжний камінь військової справи й лісових переказів нічних ельфів; порятунок Імли підтримує це давнє священне товариство."},sec={{t="Поранена супутниця",b="У дикому підліску Тельдрассила причаїлася Імла — примітна сіра шаблезуба кішка з глибокими рваними ранами на спині й череві. Замість поводитися як дикий звір, Імла виявляє дивовижний спокій, а в її синіх очах світиться жвавий розум: вона одразу шукає в доброзичливих мандрівників проводу й захисту."},{t="Ціна засідки",b="Імла — улюблена супутниця Вартової Аринії Клаудзбрейк. Патрулюючи велике гілля біля Дерева Оракула, Аринія потрапила в засідку мерзенних відьом-гарпій, які напали на них обох і розлучили. Гадаючи, що її вірна улюблениця загинула кривавою смертю, Аринія в горі відступила до тихого місцевого місячного колодязя, де всупереч усьому відчайдушно сподівалася, що Імла вижила."}},fp="4,224,19.349.0,19.377.0,12.194.0,17.199.0,30.123.0,35.197.0,50.196.0,52.185.0"}
P.entries["quest:94"] = {n="Пильне око",s="«Пильне око» — завдання Альянсу від чарівника Теокрітуса з Вежі Азори в Лісі Елвінн. Налагодивши базовий ворожильний зв'язок проти свого суперника Морґанта, Теокрітус посилає шукачів пригод на схід, у Гори Редріджу, щоб помістити зачарований фокус на стародавню статую лева, що дивиться на Вежу Ілґалара.",h="«Пильне око» — завдання Альянсу від чарівника Теокрітуса з Вежі Азори в Лісі Елвінн.",kw={"пильне око","теокрітус","морґант","гліф азори","вежа ілґалара","статуя лева","ворожіння"},ang={["class:Mage"]="Для адептів чародійства ця місія показує далеке провидіння й ворожильні ретранслятори та протиставляє впорядковані академічні методи Теокрітуса з Елвінну беззаконному чаклунству Морґанта.",["faction:Alliance"]="Знешкодити людей-чаклунів-відступників на кшталт Морґанта конче потрібно, щоб убезпечити кордон між Лісом Елвінн і обложеними поселеннями Гір Редріджу."},sec={{t="Суперництво через кордон",b="Зі своєї вежі на сході Лісу Елвінн маг Теокрітус пильно стежить за темним чаклунством, що визріває в сусідніх пагорбах. Його головний ворог — Морґант, лютий чаклун грізної сили, який захопив Вежу Ілґалара серед скель Гір Редріджу. Прагнучи розкрити зловісні задуми Морґанта, перш ніж вони перехлюпнуть через кордон, Теокрітус створив Око Азори, щоб стежити за чарівником-відступником здалеку."},{t="Варта лева",b="Зорове ворожіння дає певні відомості, та їх замало, щоб прозирнути глибші задуми Морґанта. Теокрітус довіряє мандрівникам Гліф Азори й наказує дістатися до підніжжя Вежі Ілґалара. Там десятиліттями несе самотню варту Стара Статуя Лева. Вкладений у стерту заглибину біля основи статуї гліф пробуджує чародійний канал, що з'єднує камінь з Азорою й дає Теокрітусу змогу зазирнути просто в розум суперника."}},fp="14,324,27.449.0,16.474.0,18.237.0,16.241.0,37.230.0,32.265.0,29.193.0,35.193.0"}
P.entries["quest:940"] = {n="Тельдрассил",s="Після очищення околиць Дерева Оракула від здичавілих гарпій Вартова Аринія Клаудзбрейк довіряє вам доставити звіт до Дарнасуса. Списана письменами кора адресована Архідруїдові Фандралу Стаґгелму й несе звістки про стан гілля та зіпсуття, що й далі мучить Світове Дерево.",h="Після очищення околиць Дерева Оракула від здичавілих гарпій Вартова Аринія Клаудзбрейк довіряє вам доставити...",kw={"тельдрассил","дерево оракула","аринія клаудзбрейк","фандрал стаґгелм","звіт","дарнасус"},ang={["class:Druid"]="Нести слово прадавнього Дерева Оракула просто до проводиря Кола Кенарія — значить побачити безнастанну боротьбу за очищення природної рівноваги Тельдрассила.",["faction:Alliance"]="Для звитяжців Альянсу, що завершують свої перші обов'язки на острові, ця місія — офіційне знайомство зі столицею нічних ельфів та її суворим проводом.",["race:NightElf"]="Доставивши цей звіт, ви стаєте віч-на-віч з Архідруїдом Стаґгелмом і бачите його особисту одержимість — повернути калдореям безсмертя через хворе гілля Тельдрассила."},sec={{t="Гонець до кам'яного міста",b="Глибоко в гіллі Тельдрассила Дерево Оракула пильнує ліс. Очистивши Зачарований гай від гнізд гарпій, Вартова Аринія Клаудзбрейк вирішує, що нарешті безпечно послати звістку проводові калдорей. Довіривши вам шматок списаної кори, вона посилає вас через хащі до Дарнасуса — великого «лісу з каменю», — щоб передати звіт Дерева Оракула просто в руки Архідруїда Фандрала Стаґгелма."},{t="Амбіції й розчарування Стаґгелма",b="Одержавши звіт, Фандрал Стаґгелм приймає його зі змішаними почуттями. Він вдячний за звістку, що гарпій відтіснили, та звіт підкреслює глибшу правду: щойно одну загрозу на Тельдрассилі зменшено, на її місці гноїться інша. Для Стаґгелма, який просував висадження нового Світового Дерева, щоб повернути нічним ельфам утрачене безсмертя, невідступні недуги гілля — гірке нагадування, що його великий труд ще далекий від завершення."}},fp="10,307,29.453.0,35.481.0,46.270.0,35.212.0,51.265.0,68.291.0,48.246.0,47.191.0"}
P.entries["quest:941"] = {n="Посадити серце",s="«Посадити серце» — завдання для травника Деналана на березі Озера Ал'Амет у Тельдрассилі. Зчистивши задушливий мох із дивного дерев'яного серця, взятого із зіпсутого деревляника, Деналан перевіряє, чи зможе його особливо збагачений ґрунт очистити й зцілити скверну, що досі в ньому жевріє.",h="«Посадити серце» — завдання для травника Деналана на березі Озера Ал'Амет у Тельдрассилі.",kw={"посадити серце","деналан","деревляник","блекмосс смердючий","ґрунт","озеро ал'амет","тельдрассил"},ang={["class:Druid"]="Для друїда бачити, як осердя зіпсутого деревляника очищається в багатій землі, — підбадьорливий знак: неприродну скверну, що вразила гілля Світового Дерева, ще можна повернути назад природною турботою.",["profession:Herbalism"]="Майстерність Деналана в поживному ґрунті й оживленні рослин показує життєво важливий зв'язок між вивченням землі й зціленням пошкодженої флори.",["race:NightElf"]="Відновлення живої деревини й пробудження життя в полеглих лісових духах відображає відданість калдорей опіці над природою навіть попри тривожні недуги Тельдрассила."},sec={{t="Другий шанс на життя",b="Оглядаючи дивний дерев'яний орган, здобутий із зіпсутого деревляника на ім'я Блекмосс Смердючий, Деналан спромігся зішкребти мерзенний мох, що душив його поверхню. Та попри всі зусилля в деревині й далі пульсує глибша, неприродна скверна. Замість спалити чи викинути серце, Деналан покладається на свою довічну майстерність ботаніка й доглядача ґрунту. Він велить мандрівникам закопати серце просто у свій особистий ящик для розсади, довіряючи багатим поживним речовинам, які він змішав, повернути до здоров'я ту природну силу, що ще лишилася."},{t="Диво збагаченої землі",b="Коли почорніле дерев'яне серце кладуть у ящик Деналана, стається несподіване. Щойно торкнувшись родючого ґрунту, серце заривається в землю, немов кероване первісним інстинктом. За мить воно знову виринає на поверхню — очищене від мерзенного зіпсуття, з лагідним, дружнім теплом усередині. Очистивши зерня полеглого зараженого створіння, Деналан доводить: навіть коли дикі мешканці Тельдрассила стають жертвами неприродної пошесті, дбайливий догляд і священна земля ще здатні повернути злагоду."}},fp="18,318,23.539.0,29.534.1,40.198.0,15.256.0,56.209.0,37.184.1,49.213.0,45.192.0"}
P.entries["quest:95041"] = {n="Збирачі даних",s="«Збирачі даних» — завдання від Джемми Квіксвіч, гномки-вигнанки, що мешкає в Айронфорджі. Під час відчайдушної евакуації з Гномреґану вона переписала найцінніші родинні архіви на перфокарти, та загубила кілька з них у крижаних заметах біля міських брам. Повернути ці втрачені картки — означає врятувати все: від передових схем корабельної інженерії до незамінних родинних рецептів.",h="«Збирачі даних» — завдання від Джемми Квіксвіч, гномки-вигнанки, що мешкає в Айронфорджі.",kw={"перфокарти","квіксвіч","гномреґан","айронфордж","дані","архів","гноми"},ang={["faction:Alliance"]="Альянс значною мірою покладається на гномську винахідливість; допомагаючи переселенцям зберегти воєнні інженерні записи, ви рятуєте цінні технічні знання Альянсу від вічного забуття.",["profession:Cooking"]="Поряд зі світового рівня інженерними схемами лежить особистий рецепт чилі бабусі Квіксвіч — доказ, що добра їжа має не меншу сентиментальну цінність, ніж військова наука.",["profession:Engineering"]="Інженери оцінять величезну цінність, приховану на цих картках: справжні креслення корпусів субмарин Другої війни та складні арканотехнічні рівняння.",["race:Gnome"]="Для гномів-шукачів пригод повернення цих перфокарт — справа збереження культури: важливі винаходи й родинні спогади не повинні згинути в радіоактивних руїнах батьківщини."},sec={{t="Метушня в снігу",b="Коли навала трогів і радіаційна катастрофа, що настала за нею, вигнали гномів із Гномреґану, тисячі втікали з тим, що встигли вхопити в метушні. Джемма Квіксвіч завбачливо перенесла знання кількох поколінь родини на фізичні архіви з перфокарт. На лихо, з пошкодженої сумки кілька ключових карток випали на снігові поля довкола загиблого міста. Без цих перфокарт решта даних читається як нерозбірлива тарабарщина, і інтелектуальна спадщина родини опиняється під загрозою зникнення."},{t="Рівняння і чилі",b="Гномські архіви даних відображають химерну широту пріоритетів їхньої цивілізації. Записи родини Квіксвіч містять глибокі арканотехнічні польові рівняння, життєво важливі креслення корпусів субмарин часів Другої війни та секретний рецепт чилі бабусі Квіксвіч. Сторонньому поєднання військової інженерії з домашньою кухнею може здатися дивним, та для біженців в Айронфорджі зберегти домашній затишок не менш важливо, ніж технологічні дива."}},fp="13,403,22.544.0,19.469.0,24.143.0,38.187.0,34.180.0,66.192.0,65.204.0,45.234.0"}
P.entries["quest:95314"] = {n="Той зелений еліксир з Тіньової Долини",s="Каролай Еніс із Брілла шукає здобич із покинутого поселення Тіньова Долина, схованого глибоко в усамітненому Шепітливому Лісі. До падіння королівства село було горезвісне тим, що гнало Шепітливий Еліксир із дивних місцевих трав — міцне питво, яке цінували на чорному ринку навіть після заборони в Лордероні.",h="Каролай Еніс із Брілла шукає здобич із покинутого поселення Тіньова Долина, схованого глибоко в усамітненому...",kw={"зелений еліксир","тіньова долина","шепітливий ліс","каролай еніс","шепітливий еліксир","прокляття"},ang={["class:Rogue"]="Шепітливий Еліксир здавна цінували нелегальні отруйники й пройдисвіти, що діяли поза увагою колишніх магістратів Лордерону.",["profession:Herbalism"]="Еліксир завдячує своєю силою особливим травам, що буяють лише під моторошним склепінням усамітненого Шепітливого Лісу.",["race:Undead"]="Для Відступників повернення забутих настоянок Лордерону служить і прибутковій торгівлі, і аптекарським експериментам у молодому Андерсіті."},sec={{t="Заборонене вариво",b="Задовго до Третьої війни й приходу Погибелі відлюдкуваті мешканці Тіньової Долини варили особливу суміш, відому як Шепітливий Еліксир. Виготовлене з рідкісних трав, що ростуть лише в Галявинах Тірісфалю, питво здобуло лиху славу по всій півночі Лордерону. Попри офіційну заборону в Столиці — стольному місті королівства, — його незвичайні властивості робили його жаданим для містиків, отруйників і аптекарів-практиків, готових обійти королівські укази."},{t="Руїни в Шепітливому Лісі",b="Тіньова Долина ховається глибоко в Шепітливому Лісі на заході Тірісфалю. Її мешканці здавна були замкнутим, недовірливим людом, що рідко вітав чужинців. Після вторгнення Погибелі поселення запалося в руїну, та серед уламків досі лежать забуті запаси витриманого зеленого еліксиру. Каролай Еніс працює з Брілла і, користуючись стійким попитом підпілля, платить шукачам пригод, готовим кинути виклик моторошній тиші лісу."},{t="Шепітливе прокляття",b="Каролай воліє відмахуватися від чуток як від простих забобонів, та Шепітливий Ліс має темну славу. Місцеві перекази твердять, що сама земля й коріння лісу отруєні стародавнім прокляттям, яке просочується просто в рослини, що їх збирали броварі Тіньової Долини. Хай яка залишкова злоба навідує покинуте сільце, вона мало вгамувала апетит далеких покупців на його розлиті в пляшки рештки."}},fp="28,340,13.457.0,30.465.0,20.427.1,19.249.0,26.193.0,21.218.0,46.329.0,50.219.0,39.131.0"}
P.entries["quest:96047"] = {n="Табірна наука 101: перша допомога",s="Це завдання спрямовує медиків-новачків у Дун Мороґу розширити своє вміння виживати далі за прості бинти. Звернувшись до Тамнера Пола в Хараносі, шукачі пригод учаться збирати повноцінну Аптечку, щоб зберегти життя табірникам у полі.",h="Це завдання спрямовує медиків-новачків у Дун Мороґу розширити своє вміння виживати далі за прості бинти.",kw={"перша допомога","аптечка","табір","тамнер пол","харанос","виживання"},ang={["faction:Alliance"]="Новобранці Альянсу, що проходять вишкіл у замерзлому серці Каз Модану, рано засвоюють: самодостатність і польова медицина — життєво важливі навички для будь-якого військового чи дослідницького загону.",["race:Dwarf"]="Дворфійські горяни, патрулюючи високі засніжені перевали Дун Мороґу, покладаються на міцне, практичне спорядження, тож табірна аптечка — неодмінна річ для виживання.",["race:Gnome"]="Біженцям і гномським мандрівникам, що діють із Хараноса, дієва польова медицина безцінна, поки вони виживають поза втраченими залами Гномреґану."},sec={{t="Лікування ран у нетрях",b="Шукачі пригод, які наважуються на замерзлі простори Дун Мороґу, швидко з'ясовують, що лляні клапті й поспішні шви — лише початок медицини виживання. Справжнє виживання в нетрях часто залежить від заздалегідь підготованих запасів на місці відпочинку. Тих, хто виявляє хист до базового лікування, спрямовують до ремісничих наставників у Хараносі, які навчать перетворювати сирі медичні припаси на повні набори для виживання в таборі."},{t="Уроки Хараноса",b="У гамірному селищі Харанос Тамнер Пол передає практичні прийоми оснащення експедиційних стоянок припасами на випадок біди. Уміння зібрати належну польову аптечку гарантує, що весь загін зможе перев'язати рани й відновити сили разом біля вогнища, перш ніж знову вирушити в пронизливий холод."}},fp="22,236,26.437.0,23.337.0,33.161.0,19.174.0,36.111.0,38.218.0,62.176.0,39.143.0"}
P.entries["quest:96390"] = {n="Задушити в зародку",s="«Задушити в зародку» — завдання від Провидця Землі Фарсена: знищити шпигунів Темного Заліза, що проникли в Дун Мороґ. Таємних агентів помітили біля Поселення Айронбенда, і вони загрожують безпеці батьківщини Бронзбірдів.",h="«Задушити в зародку» — завдання від Провидця Землі Фарсена: знищити шпигунів Темного Заліза, що проникли в...",kw={"темне залізо","шпигуни","фарсен","айронбенд","дун мороґ","карта"},ang={["faction:Alliance"]="Знешкодження ворожих розвідників у Дун Мороґу береже важливі шляхи постачання Айронфорджа й довколишні застави від диверсій.",["race:Dwarf"]="Для дворфів Бронзбірдів вичистити лазутчиків Темного Заліза з гір предків — справа захисту дому й давньої кланової помсти."},sec={{t="Очі на морозі",b="Дун Мороґ здавна був укріпленим прихистком дворфів Айронфорджа, та давня ворожнеча між дворфійськими кланами ніколи не спить по-справжньому. Лазутчики Темного Заліза прослизнули через високі перевали й засніжені скелі та підозріло скрадаються біля важливих розкопок і поселень. Провидець Землі Фарсен розуміє: навіть кілька прихованих спостерігачів можуть провіщати нищівний удар, — і кличе стійких захисників Альянсу викорінити їх, перш ніж їхні задуми вкореняться."},{t="Загроза біля Поселення Айронбенда",b="Шпигуни зосередили свої виправи довкола Поселення Айронбенда — важливого місця на сході Дун Мороґу. Хоч Фарсен спершу не може розгадати їхніх точних намірів, знищення таємних агентів дає речовий доказ їхнього більшого задуму. В обшуканих розвідників знаходять Карту Підземелля, і стає ясно: їхнє вторгнення — не просто розвідка, а підготовка, пов'язана з давніми підземними таємницями, як-от Зала Танів."}},fp="18,247,16.475.0,31.452.1,40.132.0,38.228.0,38.121.0,26.137.0,44.134.1,24.146.0"}
P.entries["quest:96391"] = {n="Карта Підземелля",s="Карта Підземелля, здобута в шпигунів, що проникли до Поселення Айронбенда, відкриває таємні мережі тунелів, прокопаних до коренів Айронфорджа. Її зубчасті руни Темного Заліза окреслюють прихований підземний шлях, що пронизує гору просто до давніх покоїв під нею. Доставити її Провидцю Землі Фарсену — перший крок до розкриття навислого вторгнення знизу.",h="Карта Підземелля, здобута в шпигунів, що проникли до Поселення Айронбенда, відкриває таємні мережі тунелів...",kw={"карта підземелля","темне залізо","тунелі","айронфордж","фарсен","шпигуни"},ang={["class:Shaman"]="Легкий порив вітру, що веде вас до Провидця Землі Фарсена, натякає на духів стихій, які застерігають про неприродні підземні розкопки під Дун Мороґом.",["faction:Alliance"]="Знешкодити цей підземний шлях проникнення конче потрібно, щоб зберегти безпеку Айронфорджа — північного якоря Альянсу.",["race:Dwarf"]="Для дворфів Бронзбірдів виявлення тунелів Темного Заліза, прорубаних просто до підвалин Айронфорджа, — грубе порушення недоторканності столиці."},sec={{t="Креслення проникнення",b="Пергамент, відібраний у шпигунів Темного Заліза біля Поселення Айронбенда, показує хитромудрий лабіринт підземних доріг. Накреслені різкими зубчастими рунами, властивими лише клану Темного Заліза, схеми позначають глибокі підземні ходи, що сходяться просто під Айронфорджем. Мета цих прокопаних тунелів безпомилково ворожа: Темне Залізо діяльно прокладає прихований чорний хід просто під столицею Бронзбірдів."},{t="Шепіт на вітрі",b="Коли ви вивчаєте грубу картографію, неприродний порив вітру доносить ледь чутний шепіт дворфійського голосу, що закликає діяти негайно. Містичний знак ясно вказує, хто має почути про це першим: Провидець Землі Фарсен. Доповідь про ці відомості викриває перші кроки до давніх зал, запечатаних глибоко під містом, і загрозу прихистку гірського королівства."}},fp="15,383,27.456.0,20.344.1,41.165.0,23.157.0,24.216.0,49.158.0,29.201.1,45.173.0"}
P.entries["quest:96392"] = {n="Спостереження Фарсена",s="«Спостереження Фарсена» — завдання-спостереження від Провидця Землі Фарсена, гостя-шамана з клану Вайлдгаммерів, що розташувався високо над Кар'єром Гол'Болар. Завдяки шаманському далекозору провидця шукачі пригод на власні очі бачать, як дворфи Темного Заліза дедалі глибше проникають у серце Дун Мороґу. Цей важливий огляд — ранній крок на шляху до Зали Танів.",h="«Спостереження Фарсена» — завдання-спостереження від Провидця Землі Фарсена, гостя-шамана з клану...",kw={"фарсен","провидець землі","вайлдгаммер","гол'болар","темне залізо","далекозір","шаман"},ang={["class:Shaman"]="Провидці землі з клану Вайлдгаммерів показують земний і духовний зір своєї традиції — погляд на дворфійський шаманізм, вкорінений у скелях Орлиного Піку.",["faction:Alliance"]="Викриття змов Темного Заліза в Дун Мороґу життєво важливе для безпеки Айронфорджа та довколишніх гірських перевалів для всіх подорожніх Альянсу.",["race:Dwarf"]="Для захисників Бронзбірдів попередження від родича з Орлиного Піку показує, якою зухвалою стала інфільтрація Темного Заліза на їхню батьківщину."},sec={{t="Очі над хребтом",b="Умостившись над заметеними снігом розкопками Кар'єру Гол'Болар, Провидець Землі Фарсен пильно стежить за нижніми землями Дун Мороґу. Прибувши з півночі, зі скель Орлиного Піку, гість із клану Вайлдгаммерів приносить гостре духовне чуття в землі, які зазвичай патрулюють горяни Айронфорджа. Замість покладатися на простих розвідників, Фарсен уживає традиційні мистецтва свого клану, щоб стежити за підземним гуркотом і несподіваним рухом на схилах."},{t="Позичений зір",b="Щоб переконати мандрівників у близькій небезпеці, Фарсен позичає їм свій далекозір — шаманський дар, що переносить свідомість на величезні відстані. Крізь духовну лінзу стає очевидно: біди Дун Мороґу сягають далеко за неслухняних трогів і диких звірів. Дворфи Темного Заліза підібралися впритул до промислового серця Айронфорджа й окопуються для операції, яку треба зупинити негайно, доки вона не вкоренилася."}},fp="14,364,21.463.0,17.448.0,24.219.0,33.127.0,31.165.0,44.164.0,59.191.0,52.174.0"}
P.entries["quest:96393"] = {n="Вторгнення у Старий Айронфордж",s="«Вторгнення у Старий Айронфордж» — кульмінація розслідування про лазутчиків Темного Заліза, що причаїлися глибоко під Айронфорджем. За вказівкою Провидця Землі Фарсена герої спускаються в давню Залу Танів під Старим Айронфорджем, щоб знищити ворожого командира Дурґена Дерджгаммера й доповісти про загрозу особисто Королю Маґні Бронзбірду.",h="«Вторгнення у Старий Айронфордж» — кульмінація розслідування про лазутчиків Темного Заліза, що причаїлися...",kw={"старий айронфордж","зала танів","дерджгаммер","темне залізо","фарсен","король маґні"},ang={["faction:Alliance"]="Зупинивши вторгнення, ви запобігаєте нищівному раптовому удару по головній твердині Альянсу у Східних Королівствах.",["race:Dwarf"]="Для Бронзбірдів лазутчики Темного Заліза, що причаїлися в забутих склепіннях під Високим Престолом, — нестерпне осквернення фортеці предків."},sec={{t="Прорив у склепіння",b="Після знахідки підземної карти, що розкрила пересування Темного Заліза, Провидець Землі Фарсен визначає натхненника підземного вторгнення. Глибоко в давніх кам'яних залах Старого Айронфорджа лежить вхід до Зали Танів. Поки верхнє місто клопочеться поверхневими справами, підступні сили прослизнули в ці заснулі печери просто під ногами королівства."},{t="Дурґен Дерджгаммер",b="Переклад захоплених документів Темного Заліза, зроблений Фарсеном, указує на єдиного командира, що керує операцією: Дурґена Дерджгаммера. Засівши глибоко в нижніх склепіннях, Дерджгаммер становить пряму загрозу серцю гірського королівства Бронзбірдів. Щоб зламати хребет вторгненню, шукачі пригод мають пірнути в глибини, здолати його і віднести його відрубану голову нагору, Королю Маґні Бронзбірду."},{t="Аудієнція в короля",b="Голова Дурґена Дерджгаммера, піднесена Королю Маґні Бронзбірду, підтверджує похмуру правду про загрозу Темного Заліза, що повзе крізь давнє коріння міста. Принісши і моторошний доказ перемоги, і особисте вітання від його давнього друга Фарсена, шукачі пригод офіційно завершують розслідування і впевнюються, що Маґні знає, що чаїться внизу."}},fp="23,341,20.394.0,18.411.1,22.347.1,32.237.0,33.165.0,26.200.0,41.150.0,50.117.0,63.190.0"}
P.entries["quest:96408"] = {n="Гість у Дун Мороґу",s="«Гість у Дун Мороґу» — завдання-розслідування від Белдіна Стілґрілла біля Хараноса. Горяни доповіли про незнайоме багаття високо на скелях над Кар'єром Гол'Болар, і треба розвідати, чи не загрожує чужинець місцевим дворфам.",h="«Гість у Дун Мороґу» — завдання-розслідування від Белдіна Стілґрілла біля Хараноса.",kw={"гість","дун мороґ","фарсен","стілґрілл","гол'болар","багаття","харанос"},ang={["class:Shaman"]="Зустріч із Провидцем Землі Фарсеном напряму пов'язана з духовним єднанням із гірським камінням — рідкісне видовище на засніжених висотах Дун Мороґу.",["faction:Alliance"]="Допомога місцевим горянам біля Хараноса гарантує, що шляхи постачання й робітники кар'єру лишаться в безпеці від непередбачених загроз.",["race:Dwarf"]="Для дворфів Бронзбірдів нагляд за непроханими спостерігачами над великими копальнями, як-от Гол'Болар, — звичайна безпекова справа для захисту кордонів Каз Модану."},sec={{t="Стовп диму на висотах",b="Горяни Дун Мороґу пильно стежать за скелями й засніженими долинами довкола Айронфорджа. Коли високо над Кар'єром Гол'Болар раптом з'явилося багаття, в Хараносі здивовано звели брови. Белдін Стілґрілл, стривожений незвичним табором просто над важливою дворфійською копальнею, наймає мандрівників, щоб ті вибралися на гребені й з'ясували, хто цей таємничий незнайомець — мирний подорожній чи зайда."},{t="Зустріч із провидцем землі",b="Розвідка гребеня показує, що мандрівник — це Провидець Землі Фарсен, містик, який розбив табір на продутих вітрами висотах. Далеко не мародер-трог і не відверто ворожий шпигун, цей таємничий спостерігач має глибокий духовний зв'язок із землею. Його присутність на кручі над кар'єром починає шлях до розкриття глибших заворушень, прихованих під Каз Моданом, що зрештою сплітається з таємницею Зали Танів."}},fp="23,274,28.427.0,21.440.1,41.138.0,41.132.0,42.114.1,48.212.0,31.154.1,46.153.1"}
P.entries["quest:96607"] = {n="Широкі простори",s="«Широкі простори» — вступний урок виживання, який бувалі мандрівники дають новоспеченим подорожнім по всьому Азероту. Присівши на хвилину біля теплого багаття, новачки дізнаються, як добрий відпочинок і підготовка зберігають життя шукачеві пригод поза міськими мурами. Це перший крок до опанування виживання в дикій природі й облаштування польових таборів.",h="«Широкі простори» — вступний урок виживання, який бувалі мандрівники дають новоспеченим подорожнім по всьому...",kw={"широкі простори","виживання","багаття","табір","відпочинок","ремесла","азерот"},ang={["faction:Alliance"]="У безпечному Лісі Елвінн люди-мандрівники засвоюють ці основи виживання від досвідчених подорожніх, перш ніж зіткнутися з суворішими загрозами, що чигають у Вестфолі й Редріджі.",["faction:Horde"]="Чи то перетинаючи посушливі рівнини Дуротару, чи обвітрені плато Малгору, знавці виживання Орди прищеплюють кожному молодому воїнові вміння розводити вогонь і дисципліну життя просто неба.",["profession:Cooking"]="Кожен табір у глушині починається з вогню, тож кулінарія — природна супутниця виживання просто неба. Після цього уроку майстри табірної справи одразу спрямовують вас на придорожню науку куховарства."},sec={{t="Уроки дороги",b="Хоч який гострий ваш клинок і хоч яка могутня магія, нетрі Азерота швидко стирають на порох кожного, хто нехтує основами виживання. Бувалі мандрівники, що стоять біля придорожніх галявин, дають цей простий урок подорожнім, які вирушають із рідних долин. Відпочинок біля багаття не лише дає перепочити натрудженим ногам — він заспокоює розум і готує дух до суворої дороги попереду. Лише ті, хто опанував дисципліну регулярного відпочинку й підготовки, мають шанс прожити досить довго, щоб здобути багатство й славу."},{t="Дім далеко від дому",b="Щойно шукач пригод усвідомлює цінність тріскучого вогню й доброго відпочинку, наставники відсилають його просто до міських ремісників. Табір у полі рідко обмежується жаринкою й постіллю; виживання вимагає практичних ремесел. Чи то кувати запасні заклепки, чи готувати похідні харчі, чи зашивати порване спорядження під зорями — кожне ремесло дає особливі табірні речі, що перетворюють голий схил на самодостатню стоянку."}},fp="18,359,20.539.0,21.445.0,40.310.0,47.231.0,35.262.0,52.261.0,61.278.0,59.186.0"}
P.entries["quest:96627"] = {n="Шукач пригод",s="«Шукач пригод» — завдання-дороговказ від Маршала Макбрайда в Долині Нортширу. Визнавши вашу ранню вправність, Макбрайд посилає вас за межі відлюдних земель абатства до Ґолдшира — придивитися до новоприбулого на ім'я Сем Сарсапарілла.",h="«Шукач пригод» — завдання-дороговказ від Маршала Макбрайда в Долині Нортширу.",kw={"шукач пригод","маршал макбрайд","сем сарсапарілла","ґолдшир","нортшир","дороговказ"},ang={["faction:Alliance"]="Для свіжих новобранців Альянсу, що завершують службу в Нортширі, це перший офіційний крок у ширше королівство Лісу Елвінн.",["race:Human"]="Захисники з людей, виходячи з Абатства Нортшира, роблять перші кроки до Ґолдшира — гамірного серця Елвінну."},sec={{t="Прощання з долиною",b="Щойно новобранці очищають Долину Нортширу від найближчих загроз — місцевих Дефіас і шкідників, — Маршал Макбрайд починає дивитися далі дорогою. Регулярні сили Стормвінда розтягнуті по всьому королівству, тож місцевий гарнізон мусить покладатися на перспективних бійців, щоб наглядати за подорожніми й мандрівниками, які блукають довколишніми лісами."},{t="Цікавий новачок",b="Замість військового наказу чи полювання за винагороду Макбрайд дає вам незвичне доручення: перевірити одного нового шукача пригод, поміченого біля Ґолдшира, на ім'я Сем Сарсапарілла. Це прохання стає переходом із відлюдної долини Нортширу в ширші й небезпечніші простори Лісу Елвінн."}},fp="14,244,18.338.0,18.303.0,26.159.0,24.165.0,33.105.0,56.225.0,52.129.0,63.210.0"}
P.entries["quest:96628"] = {n="Шукач пригод",s="«Шукач пригод» — місцеве доручення від Горянина Талоса біля південної брами Дун Мороґу. Перш ніж пропустити мандрівників гірським тунелем до Хараноса, Талос просить віднести пакунок припасів Еріку Брайтгаммеру — новоприбулому, що отаборився одразу за селищем.",h="«Шукач пригод» — місцеве доручення від Горянина Талоса біля південної брами Дун Мороґу.",kw={"шукач пригод","талос","брайтгаммер","харанос","припаси","горянин","дун мороґ"},ang={["faction:Alliance"]="Горяни покладаються на новобранців Альянсу, щоб ті носили важливі припаси крижаними дорогами і союзники-мандрівники за Хараносом не лишалися без провізії.",["race:Dwarf"]="Для юних дворфів, що покидають Долину Холодного Хребта, доставка провізії Еріку Брайтгаммеру — перша спільна справа з горянами у ширшому краї Дун Мороґу."},sec={{t="Послуга для горян",b="Охорона високих перевалів і тунелів між Долиною Холодного Хребта та ширшими сніговими просторами Дун Мороґу — важка праця для горян Айронфорджа. Стоячи на прикордонній брамі, Горянин Талос пильнує і місцеві небезпеки, і мандрівників на втоптаній стежці. Коли на пост доходить звістка про самотнього шукача пригод, що прибув до Хараноса, Талос просить надійних перехожих віднести потрібні припаси далі, щоб підтримати новачків, які вирушають у замерзлі скелі."},{t="Припаси для Хараноса",b="Дорога, що спускається з південного перевалу, в'ється до селища Харанос — головного осередку дворфійського ремесла й подорожей у центральному Дун Мороґу. Ерік Брайтгаммер нещодавно облаштувався одразу на околиці селища. Доставивши йому пакунок провізії від горян, мандрівники допомагають налагодити важливий зв'язок між вартовими на далеких гребенях і тими, хто мандрує нетрями."}},fp="14,279,28.484.0,21.418.0,36.140.0,25.178.0,36.132.0,43.199.0,27.102.0,41.118.0"}
P.entries["quest:96630"] = {n="Шукач пригод",s="«Шукач пригод» — коротке завдання в Тельдрассилі, що починається зі знахідки покинутого щоденника в хащах. Простий записник оповідає про скромні мандри й ночівлі під відкритим небом невідомого мандрівника; його належить доставити Ліріні Даскблейд поблизу Доланаара.",h="«Шукач пригод» — коротке завдання в Тельдрассилі, що починається зі знахідки покинутого щоденника в хащах.",kw={"шукач пригод","щоденник","ліріна даскблейд","доланаар","тельдрассил"},ang={["faction:Alliance"]="Для новачків Альянсу, що лише освоюються під Світовим Деревом, повернення загублених речей місцевим розвідникам допомагає підтримувати лад у гаях.",["race:NightElf"]="Юні нічні ельфи, що патрулюють Тельдрассил, часто знаходять сліди мандрівників і передають загублені особисті речі вартовим, як-от Ліріні Даскблейд."},sec={{t="Щоденник мандрівника",b="Серед густого гілля й сплетеного коріння Тельдрассила мандрівники часом натрапляють на покинуті особисті речі. Цей простий щоденник оповідає про непримітні, але щирі блукання безіменного шукача пригод. Замість великих подвигів чи небезпечних полювань на чудовиськ більшість його сторінок захоплено описує прості радощі ночівлі під сутінковою кроною."},{t="Доставка до Доланаара",b="Замість лишити особисту пам'ятку мокнути у вологих хащах, той, хто її знайшов, відчуває потяг віднести її до Доланаара. Ліріна Даскблейд, що стоїть на посту біля поселення нічних ельфів, приймає загублені сторінки — можливо, щоб дати завершення цій історії або з'ясувати, чиї мандри лишилися позаду."}},fp="14,259,20.373.0,20.307.0,43.220.0,25.128.0,33.135.0,56.177.0,27.153.0,36.218.0"}
P.entries["quest:96652"] = {n="Шукач пригод",s="Досліджуючи суворі пустки Дуротару, подорожні натрапляють на простий покинутий щоденник, що описує тихі мандри незнайомої постаті. Його сторінки тепло оповідають про життя просто неба й ночівлі під зорями; щоденник чекає, щоб його віднесли Бракку біля Гострого Пагорба.",h="Досліджуючи суворі пустки Дуротару, подорожні натрапляють на простий покинутий щоденник, що описує тихі...",kw={"щоденник","бракк","гострий пагорб","мандрівник","табір","дуротар"},ang={["class:Hunter"]="Мисливці, що все життя живуть із дарів землі, легко зрозуміють теплі записи щоденника, що раз у раз повертаються до радощів ночівлі в дикій природі.",["faction:Horde"]="Посушливими стежками Дуротару ходить багато новобранців; повернення загублених речей і доповідь розвідникам біля Гострого Пагорба допомагають тримати лад на центральному рубежі."},sec={{t="Нотатки мандрівника",b="Дуротар — суворий край, де виживання зазвичай важливіше за неквапливі подорожі, тож знайти книгу мандрівного літописця — незвична річ. Скромний щоденник, що лежав без нагляду в червоній пилюці, містить роздуми й пригоди когось геть невідомого героям Орди. Замість кривавих битв чи великих походів його сторінки зупиняються на простих радощах: спати під відкритим небом і розбивати табір у дикій природі."},{t="Доставка Бракку",b="Хто б не писав ці записи, він лишив досить вражень — чи зв'язків, — щоб вони вказували на Бракка, орка біля поселення Гострий Пагорб. Віднести особисті речі загублених подорожніх тутешнім розвідникам і робітникам табору — часто єдиний спосіб, щоб розсіяні мандрівники колись знову з'єдналися зі своїм майном або принаймні щоб їх пам'ятали ті, хто пильнує запилені дороги."}},fp="14,268,18.468.0,17.374.0,32.220.0,22.178.0,13.98.0,27.130.0,39.185.0,41.252.0"}
P.entries["quest:96656"] = {n="Шукач пригод",s="Шукач пригод — вступне завдання, яке Екзекутор Аррен дає загартованим молодим поборникам Відступників за межами Похоронного Подзвону. Довівши надійність в ударах по Багряному Хрестовому Походу, ви вирушаєте дорогою до Брілла — розвідати, що за незнайомка крутиться біля поселення. Замість чергової шпигунки-фанатички завдання знайомить вас з Елеанор Шеклтон — незалежною мандрівницею, яка радо навчить практичних навичок виживання в дикій природі.",h="Шукач пригод — вступне завдання, яке Екзекутор Аррен дає загартованим молодим поборникам Відступників за...",kw={"шукач пригод","елеанор шеклтон","аррен","мандрівниця","виживання","брілл"},ang={["faction:Horde"]="Поки Екзекутор Аррен стереже молоді кордони володінь Відступників, мирний діалог із мандрівними виживальниками дає новачкам Орди цінні практичні навички.",["race:Undead"]="Для свіжих Відступників, що виходять за межі Похоронного Подзвону, зустріч із нейтральними мандрівниками на кшталт Елеанор — ранній урок: не кожен живий смертний у Лордероні одразу здіймає зброю на повернутих мерців."},sec={{t="Підозріла варта",b="Екзекутор Аррен пильно стежить за Похоронним Подзвоном і підступами до нього. Поки Багряний Хрестовий Похід активно шпигує в краї та просочується на північ Лордерону, кожен новоприбулий, помічений біля Брілла, заслуговує негайної перевірки. Побачивши вашу відданість у знищенні загроз від хрестоносців уздовж кордону, Аррен доручає вам тихо розвідати про невідому постать і з'ясувати, чи не становить вона прихованої небезпеки для Відступників."},{t="Мандрівниця в лісі",b="Коли ви знаходите Елеанор Шеклтон на узбіччі дороги біля Брілла, її наміри виявляються дуже далекими і від фанатичних змов Хрестового Походу, і від некромантії Погибелі. Незалежна мандрівниця, що перепочиває перед наступною подорожжю в дику глушину, Елеанор не має жодної ворожості до повсталих мерців. Натомість вона впізнає іскру шукача пригод у тих, кого послали її перевірити, і пропонує поділитися практичними основами виживання у відкритій глушині й облаштування табору."}},fp="14,455,18.461.0,23.448.0,50.208.0,26.227.0,44.151.0,27.143.0,38.99.0,51.172.0"}
P.entries["quest:96658"] = {n="Табірна наука 101: кулінарія",s="«Табірна наука 101: кулінарія» навчає шукачів пригод-початківців найважливішого мистецтва — розпалювати вогонь і готувати їжу в дикій природі. Цей урок, доступний у початкових поселеннях і Альянсу, і Орди, знайомить із багаттям як головною опорою будь-якого похідного табору просто неба.",h="«Табірна наука 101: кулінарія» навчає шукачів пригод-початківців найважливішого мистецтва — розпалювати...",kw={"табірна наука","кулінарія","багаття","табір","виживання","вогонь"},ang={["faction:Alliance"]="Новачків, що покидають Нортшир, Дун Мороґ чи Тельдрассил, ведуть до таких містечок, як Ґолдшир, Харанос і Доланаар, — учитися самостійності, перш ніж іти в нетрі.",["faction:Horde"]="Виживання для Орди — друга натура, і молодих бійців у Дуротарі, Малгорі та Тірісфалі одразу спрямовують до багать у Гострому Пагорбі, Селі Бладгуф і Бріллі.",["profession:Cooking"]="Кулінарія — буквально іскра табірного життя: вона дає і життєво важливу їжу для відновлення сил, і центральне багаття, без якого не розбити стоянку просто неба."},sec={{t="Вогнище глушини",b="Щоб вижити поза укріпленими мурами, кожен мандрівник мусить уміти розпалити вогонь. Звичайне багаття не лише кип'ятить воду й смажить м'ясо — це життєво важлива основа, щоб розбити табір на незвіданій землі. Без відкритого полум'я, що відганяє холод і темряву, поставити бодай якийсь прихисток неможливо."},{t="Від жарин до таборів",b="Кухарі-підмайстри здатні підтримувати лише скромний вогонь із мінімальним облаштуванням, а опанування кулінарного мистецтва дає змогу розпалювати більші вогнища, здатні підтримувати складніші табори. Ба більше, шукачі пригод, що беруться й за інші практичні ремесла, відкривають способи виготовляти корисні речі, які доповнюють їхні стоянки."}},fp="20,286,28.307.0,26.338.0,34.189.0,35.222.0,39.155.0,36.144.0,36.149.0,44.181.0"}
P.entries["quest:96659"] = {n="Шукач пригод",s="Коли молоді таурени готуються покинути прабатьківські навчальні угіддя на Плато Червоної Хмари, Вождь Гоквінд просить їх про останню послугу. Він довіряє їм клунок необхідних припасів для Каґи Вайлдгуф — досвідченої мандрівниці, що отаборилася біля Села Бладгуф і колись допомогла вождеві в його минулому.",h="Коли молоді таурени готуються покинути прабатьківські навчальні угіддя на Плато Червоної Хмари, Вождь Гоквінд...",kw={"шукач пригод","каґа вайлдгуф","вождь гоквінд","припаси","плато червоної хмари","село бладгуф","малгор"},ang={["faction:Horde"]="Вождь Гоквінд дбає, щоб мандрівні союзники Орди, покидаючи стартове плато, рано зав'язували стосунки з досвідченими мандрівниками й заставами Малгору.",["race:Tauren"]="Для молодих тауренів, що вперше виходять за межі Табору Нарачі, віддати борг честі Гоквінда Казі Вайлдгуф — перше служіння родичам на широких рівнинах Малгору."},sec={{t="Борг вождя",b="Перш ніж мандрівники зійдуть стежкою з плато на широкі рівнини Малгору, Вождь Гоквінд зупиняється, щоб залагодити незакриті особисті борги. Задовго до того, як він узявся вести нові покоління мисливців і шаманів у Таборі Нарачі, Гоквінд перетнувся з Каґою Вайлдгуф. Вождь каже про неї як про досвідчену шукачку пригод: Вайлдгуф надала вкрай потрібну допомогу, коли він найбільше її потребував. Почувши, що вона розбила табір одразу за Селом Бладгуф, Гоквінд користається відходом щойно випробуваних новачків, щоб послати харчі своїй давній добродійниці."},{t="Прощання з плато",b="Це доручення — ключовий обряд посвяти для молодих звитяжців Орди, що покидають Плато Червоної Хмари. Стежка вниз із плато веде просто до Села Бладгуф — культурного й господарського серця центрального Малгору. Несучи клунок із припасами через рівнини, ви з'єднуєте затишне навчальне життя плато з ширшою, дикішою боротьбою Об'єднаних Племен Тауренів."}},fp="14,306,23.521.0,16.370.0,21.217.0,44.208.0,38.139.0,38.157.0,48.133.0,43.148.0"}
P.entries["quest:97279"] = {n="Заблукала зброя",s="Заблукала зброя — раннє тренувальне завдання в Долині Випробувань, яке дає наглядач Ґорнек. Молоді воїни прибувають юрбами, щоб служити Орді, і зброї не вистачає. Щоб довести свою дисципліну й підтримати табір, новобранці обшукують чагарі, збираючи спорядження, покинуте менш здібними попередниками.",h="Заблукала зброя — раннє тренувальне завдання в Долині Випробувань, яке дає наглядач Ґорнек.",kw={"заблукала зброя","ґорнек","кзан торнслеш","зброяр","долина випробувань","новобранці"},ang={["class:Warrior"]="Повага до зброї — основа для будь-якого воїна. Збирання зброї, яку покидали невдалі новобранці, наголошує на дисципліні й самостійності ще до справжнього бою.",["faction:Horde"]="Орда виживає в Дуротарі завдяки впертості й кмітливості, відмовляючись марнувати зброю навіть тоді, коли її покинули ті, хто не гідний її носити.",["profession:Blacksmithing"]="У Дуротарі на вагу золота кожен клапоть металу. Допомога Кзанові зібрати зіпсоване спорядження відображає обов'язок коваля повертати залізо й перековувати побиті леза на придатні знаряддя війни."},sec={{t="Озброїти нову кров",b="Долина Випробувань — кузня, де сирих новобранців гартують суворі червоні пустки Дуротару. Безліч претендентів виходить уперед, щоб присягнути своїми клинками вождю, і запаси зброї в таборі напружені до краю. Зброяр Кзан Торнслеш ледве встигає за попитом, особливо коли перші уроки виявляються смертельними або принизливими для неготових."},{t="Випробування кмітливості",b="Наглядач Ґорнек обертає цю нестачу на практичне випробування. Замість марнувати новий метал, він посилає новоприбулих збирати покинуті клинки й тупу тренувальну зброю, залишену невдахами, що впали або втекли в пилюці. Доставка зібраної зброї Кзанові дає ковалеві змогу полагодити й загартувати її для наступної хвилі, а новачків навчає: виживання в Орді вимагає не лише махати сталлю, а й збирати її."}},fp="15,323,20.384.0,25.431.0,62.279.0,23.243.0,21.204.0,46.201.0,33.160.0,54.215.0"}
P.entries["quest:97558"] = {n="Шкури для Відступників",s="Похмура необхідність існування нежиті в Галявинах Тірісфалю, де Відступники мусять добувати звірині шкури, щоб заміняти свою зотлілу плоть. Шелін Робарт доручає шукачам пригод зібрати шкури темних гончаків, перетинки крил сутінкових кажанів і шкіру мурлоків, щоб латати пошкоджені тіла.",h="Похмура необхідність існування нежиті в Галявинах Тірісфалю, де Відступники мусять добувати звірині шкури...",kw={"шкури","шелін робарт","темні гончаки","сутінкові кажани","мурлоки","латки","плоть"},ang={["profession:Tailoring"]="Кравецтво Відступників часто межує з ремеслом трунаря: навички шиття потрібні не лише для одягу, а й щоб пришивати сирі звірині перетинки до зотлілих тіл.",["race:Undead"]="Суворе нагадування про практичний тягар стану Відступників, де виживання вимагає ручного догляду й пересаджених клаптів замість природного загоєння."},sec={{t="Ціна нежиття",b="Плоть Відступників не загоюється сама. Тілесні рани лишають гнилі прогалини, які не відновлюються звичайним біологічним шляхом. Щоб зберігати форму й підтримувати тіла в робочому стані, Відступники мусять добувати органічний матеріал зі світу живих і нашивати на свої ушкодження латки."},{t="Особливі матеріали",b="Не кожна шкура служить тій самій анатомічній меті. Товста шкура темного гончака дає міцність для широких, надійних латок. Ніжні перетинки крил сутінкових кажанів досить легкі й податливі, щоб укривати обличчя та пальці, не створюючи цупких, незграбних шарів. А гнучку шкіру мурлоків Темноплавців збирають, щоб вистилати внутрішні оболонки й чутливі місця — як-от внутрішній бік щік і рот."}},fp="22,266,20.316.0,21.383.0,38.240.0,23.247.0,51.273.0,29.175.0,32.197.0,46.256.0"}
P.entries["quest:97919"] = {n="Табірна наука 101: перша допомога",s="«Табірна наука 101: перша допомога» знайомить шукачів пригод-початківців у Лісі Елвінн із практичним мистецтвом виживання — польовою медициною. Урок спрямовує мандрівників до Мішель Белль у Ґолдширі, щоб навчитися готувати Аптечку для таборів у глушині.",h="«Табірна наука 101: перша допомога» знайомить шукачів пригод-початківців у Лісі Елвінн із практичним...",kw={"табірна наука","перша допомога","аптечка","мішель белль","ґолдшир","бинти"},ang={["class:Rogue"]="Діючи в тіні, далеко від підтримки, розбійники залежать від польової медицини: перев'язати кровоточиві рани, перш ніж рушити до наступної цілі.",["class:Warrior"]="Не маючи вроджених цілющих заклять, бійці передової значною мірою покладаються на бинти й польові аптечки, щоб пережити тривалі походи в дикій природі.",["faction:Alliance"]="Ґолдшир лишається ключовим перехрестям для мандрівників Альянсу, що починають свій шлях із Нортширу в ширше королівство Елвінну."},sec={{t="Польова медицина в дорозі",b="Шукачі пригод, що мандрують Лісом Елвінн, швидко дізнаються: бої й суворе виживання в дикій природі дорого коштують. Міські цілителі й корчми дають перепочинок, та подорож небезпечними землями часто вимагає негайної самостійної допомоги. Перша допомога — практичний засіб від кровотеч і травм, що дає змогу гоїти рани, не покладаючись на чародійські ритуали чи святі молитви."},{t="Припаси для табору",b="Надійний табір — це більше, ніж вогонь і постіль; це тимчасовий прихисток від небезпек глушини. Навчаючись у Мішель Белль у ґолдширській Корчмі «Лев'яча Гордість», вправні цілителі вчаться збирати спеціальні аптечки. Медичні припаси під рукою в таборі дають утомленому загону змогу обробити поранення й відновити сили, перш ніж зустріти небезпеки попереду."}},fp="22,239,26.409.0,25.391.0,34.232.0,41.207.0,41.226.0,27.208.0,47.151.0,42.221.0"}
P.entries["quest:97920"] = {n="Табірна наука 101: риболовля",s="«Табірна наука 101: риболовля» знайомить рибалок-початківців у Лісі Елвінн із практичним ремеслом виживання в глушині й облаштування табору. Розшукавши місцевого знавця риболовлі Лі Брауна біля Ґолдшира, мандрівники вчаться застосовувати рибальські знання для виготовлення затишних дрібниць для стоянки — як-от декоративного акваріума, що підбадьорює шукачів пригод.",h="«Табірна наука 101: риболовля» знайомить рибалок-початківців у Лісі Елвінн із практичним ремеслом виживання в...",kw={"табірна наука","риболовля","лі браун","акваріум","ґолдшир","табір"},ang={["faction:Alliance"]="Люди-мандрівники, що починають свої пригоди в Лісі Елвінн, можуть покластися на знайомі води Ґолдшира, щоб опанувати основи самостійного життя в глушині."},sec={{t="Табірне ремесло для рибалок",b="Риболовлю часто вважають самотньою розвагою для тихих берегів озер і річок, та бувалі знавці виживання розуміють: табірне життя потребує більшого, ніж їжа й дах. Затишні речі на кшталт акваріума приносять легкість і бадьорість утомленим мандрівникам, що відпочивають між вилазками, і підтверджують переконання: ясний розум і високий дух гартують грізних бійців."},{t="Досвід Лі Брауна",b="Бувалий рибалка Лі Браун, що оселився біля води за Ґолдширом, допомагає рибалкам-новачкам, які прагнуть розширити своє ремесло. Тих, хто виявив достатню вправність із вудкою й волосінню, направляють до нього — навчитися, як простий улов і базові матеріали перетворити на корисні поліпшення для табору."}},fp="20,358,21.392.0,21.312.0,34.220.0,17.215.0,40.218.0,36.123.0,50.138.0,29.187.0"}
P.entries["quest:97957"] = {n="Табірна наука 101: травництво",s="Табірна наука 101: травництво скеровує травників-початківців до місцевих наставників ремесла по всьому Азероту — як-от до Фарузи у Бріллі, — щоб опанувати виготовлення Ароматичних Свічок. Ці запашні вироби дають життєво важливу відновлювальну підтримку заклиначам, які відпочивають у таборах серед дикої природи.",h="Табірна наука 101: травництво скеровує травників-початківців до місцевих наставників ремесла по всьому...",kw={"табірна наука","травництво","фаруза","ароматичні свічки","табір","елеанор шеклтон"},ang={["class:Mage"]="Заклиначі цінують травників, які виготовляють Ароматичні Свічки: їхній заспокійливий дим допомагає відновити зосередженість і дух далеко від затишку таверни.",["profession:Herbalism"]="Замість просто варити зілля чи продавати стебла, травники можуть прямо підтримувати загони шукачів пригод, виготовляючи запашні Ароматичні Свічки для багаття.",["race:Undead"]="Мандрівники з Відступників, що діють із Похоронного Подзвону та Брілла, вчаться у Фарузи робити практичні похідні речі з усохлої рослинності Тірісфалю."},sec={{t="Зілля для табору",b="Травництво зазвичай мають за підґрунтя алхімії, та практичне виживання в полі не менше залежить від зібраних коренів і квітів. Досвідчені мандрівники скеровують охочих збирачів до майстрів-травників краю — навчитися готувати Ароматичні Свічки. У Галявинах Тірісфалю Елеанор Шеклтон посилає перспективних збирачів до Фарузи у Бріллі, щойно ті покажуть базову вправність."},{t="Пожива для розуму",b="Життя в дорозі тяжко виснажує розум заклиначів і духовників. Ароматичні Свічки виділяють відновлювальні пахощі, покликані підняти дух і заспокоїти втомлений розум. Насичуючи свічки сушеними рослинами, збирачі дають важливу підтримку цілителям і магам, чиї магічні запаси вичерпуються в тривалих мандрах, — варто лише розбити табір і запалити свічку."}},fp="22,259,18.400.0,23.318.0,34.223.0,41.136.0,31.176.0,38.256.0,56.196.0,58.140.0"}
P.entries["quest:97960"] = {n="Табірна наука 101: білування",s="Табірна наука 101: білування — вступна настанова з виживання для збирачів-початківців у Галявинах Тірісфалю і по всьому Азероту. Вона скеровує білувальників, що вже попрактикувалися у своєму ремеслі, до майстрів краю — навчитися робити міцний похідний стілець із добутих шкур.",h="Табірна наука 101: білування — вступна настанова з виживання для збирачів-початківців у Галявинах Тірісфалю і...",kw={"табірна наука","білування","ранд робарт","стілець","шкури","табір"},ang={["faction:Horde"]="Мисливці й збирачі Орди використовують кожен клапоть убитого звіра, щоб ніщо не пропало марно на безжальній дорозі.",["race:Undead"]="Навіть Відступники, вільні від смертної втоми, бачать практичну користь у впорядкованому похідному таборі, полюючи на зачумлених звірів Тірісфалю."},sec={{t="Затишок у глушині",b="Виживання в глушині вимагає більшого, ніж гострий клинок: треба вміти берегти сили між випробуваннями. Шукачі пригод на кшталт Елеанор Шеклтон наголошують, що звірині шкури дають більше, ніж просто крам на продаж. Опанувавши базові польові навички, білувальники можуть робити з вичинених шкур необхідні табірні вигоди — як-от стільці, — щоб утомлені мандрівники могли як слід відпочити й відновитися перед наступною небезпечною зустріччю."},{t="Опанування ремесла",b="У Галявинах Тірісфалю молодих білувальників з Відступників, що досягли початкової вправності, скеровують до Ранда Робарта, який веде своє ремесло при дорозі між Бріллом і руїнами Столиці над Андерсіті. Робарт ділиться практичними прийомами перетворення грубої шкіри на зручне табірне сидіння — мистецтво, яке повторюють майстри білування по всіх землях і Орди, і Альянсу."}},fp="21,270,20.439.0,19.382.0,34.152.0,44.157.0,51.149.0,32.127.0,51.169.0,36.153.0"}
P.entries["quest:98389"] = {n="Світло в темряві",s="Це завдання від Араміса Гаммергенда в Похоронному Подзвоні доручає шукачам пригод із Відступників врятувати новопідняту нежить, що потрапила в пастку в Лощині Нічної Павутини. Воно висвітлює делікатні стосунки між носіями Святого Світла з нежиті та людом, який їм глибоко не довіряє. Допомагаючи полеглим родичам, ці носії святої сили сподіваються довести свою вірність Сильвані та справі Відступників.",h="Це завдання від Араміса Гаммергенда в Похоронному Подзвоні доручає шукачам пригод із Відступників врятувати...",kw={"світло в темряві","араміс гаммергенд","лощина нічної павутини","павуки","порятунок","святе світло"},ang={["class:Priest"]="Для Відступників, які спрямовують святу енергію, ця місія ілюструє тонку линву між залишковою смертною вірою і суворою дійсністю нежиття.",["race:Undead"]="Це завдання показує складну внутрішню боротьбу Відступників — те, як окремі з них долають упередження серед власного щойно повсталого народу."},sec={{t="Хистка віра",b="Святе Світло горезвісно болісне й небезпечне для нежиті, та дехто з Відступників зберігає зв'язок зі священною магією, якою володів за життя. У Похоронному Подзвоні такі постаті, як Араміс Гаммергенд, прагнуть довести, що їхня віра не обернула їх проти власного народу. Щоб розвіяти підозру, нібито носії святої сили повернуться проти іншої нежиті як проти потвор, вони діяльно використовують свої вміння й співчуття, щоб захищати родичів."},{t="Лощина Нічної Павутини",b="На північний захід від Похоронного Подзвону лежить Лощина Нічної Павутини — вогка печера, що кишить лютими павуками. Свіжопіднята нежить, ще спантеличена пробудженням і не здатна себе захистити, раз у раз забрідає в лощину й опиняється в коконах липкого павутиння. Порятунок цих нещасних Відступників служить подвійній меті: зберегти новобранців для Темної Леді й довести очільникам на кшталт Екзекутора Аррена, що носії Світла — віддані слуги Відступників."}},fp="23,388,18.444.0,18.480.0,44.104.0,36.90.0,51.201.0,40.137.0,63.169.0,43.194.0"}
P.entries["quest:98576"] = {n="Гліфічний Пергамент",s="Гліфічний Пергамент — вступний виклик для майбутніх магів у Долині Випробувань. Передане через Ґорнека, письмове послання веде новачків до Май'ї, наставниці магів-тролів біля Лігва, щоб розпочати їхню дисципліну в таємній магії.",h="Гліфічний Пергамент — вступний виклик для майбутніх магів у Долині Випробувань.",kw={"маг","май'а","гліфічний пергамент","долина випробувань","таємна магія","ґорнек"},ang={["class:Mage"]="Це послання знаменує ваше офіційне визнання учнем таємної магії й скеровує вас до Май'ї, щоб почати вчитися й розширювати свою книгу заклинань.",["faction:Horde"]="Наставництво в Долині Випробувань дбає, щоб навіть такі мінливі мистецтва, як таємна магія, плекалися з дисципліною на зміцнення майбутнього Орди.",["race:Troll"]="Май'а втілює дедалі міцніші традиції таємної магії Темного Списа: вона ділиться своїм космічним знанням, щоб вести і тролів-одноплемінників, і новобранців-союзників."},sec={{t="Виклик до навчання",b="Поки нові новобранці доводять свою тілесну стійкість у сутичках із тутешніми шкідниками Дуротару, ті, хто має хист до таємної магії, не можуть покладатися лише на грубу силу. Ґорнек передає письмове повідомлення, списане рунами, яке велить чарівникам-початківцям розшукати Май'ю — вона наглядає за першим магічним навчанням найновіших новобранців Орди."},{t="Шлях таємної магії",b="Стоячи одразу біля входу до Лігва, Май'а стримує амбіції молодих чарівників. Замість безоглядно жбурляти сире чаклунство, вона наголошує на терпінні, вчасності й виваженому розумі. Під її проводом новачки вчаться бачити всесвіт як тонкі нитки, які треба ткати, а не як буремну стихію, яку треба спустити з ланцюга."}},fp="17,250,18.345.0,21.326.0,32.183.0,26.132.0,34.186.0,37.221.0,54.209.0,41.159.0"}
P.entries["quest:98601"] = {n="Важкий шлях",s="Важкий шлях — формальний початок навчання паладина Відступників в Похоронному Подзвоні. Упоравшись із безтямною нежиттю, що повстає зі склепів, щойно пробуджені поборники Світла отримують наказ з'явитися до Араміса Гаммергенда в сільській церкві, щоб зіткнутися з болісною дійсністю володіння святою енергією в нежитті.",h="Важкий шлях — формальний початок навчання паладина Відступників в Похоронному Подзвоні.",kw={"важкий шлях","араміс гаммергенд","паладин","освячений сувій","сарвіс","горнило"},ang={["class:Paladin"]="Це завдання — засадниче випробування паладина Відступників: свята сила тут не легке благословення, а болісне горнило дисципліни й витривалості.",["race:Undead"]="Для Відступників звернення до Світла доводить, що відданість і дисципліна здатні пережити фізичну смерть, навіть якщо магія діяльно спалює посудину, яка її спрямовує."},sec={{t="Смердючий сувій",b="Коли щойно пробуджений паладин Відступників закінчує винищувати здичавілу нежить біля склепу, Жрець Тіні Сарвіс вручає несподівану посилку. Освячений Сувій випромінює святу енергію так потужно, що жрець тіні помітно сахається й прямо просить носія відійти. Для адепта тіні й тління сама аура Святого Світла — як відкритий вогонь."},{t="Горнило святого вогню",b="В оскверненій церкві Похоронного Подзвону чекає Араміс Гаммергенд, наставник паладинів Відступників. Там, де інші раси володіють Світлом природно й радісно, нежить, що звертається до нього, зазнає пекучих, нутряних мук. Араміс не пом'якшує удару: спрямовувати святу силу крізь гниючу посудину — чиста мука, та він вимагає, щоб його учні приймали біль, а не сахалися від нього, і використовували його як горнило, що гартує їхню новознайдену рішучість."}},fp="16,322,16.384.0,25.449.0,49.238.0,54.230.0,25.226.0,33.179.0,63.159.0,35.256.0"}
P.entries["quest:99141"] = {n="Терпіння",s="Терпіння — завдання від Екзекутора Зиґанда в Галявинах Тірісфалю, яке вимагає суворої військової звітності заради Темної Леді. Оскільки чергові польові донесення запізнюються, Зиґанд відряджає шукача пригод зібрати звіти від сусідніх Вартових Смерті та одного незвичайного вартового. Доручення підкреслює сувору, безкомпромісну дисципліну, яку насаджують по всіх володіннях Відступників.",h="Терпіння — завдання від Екзекутора Зиґанда в Галявинах Тірісфалю, яке вимагає суворої військової звітності...",kw={"терпіння","зиґанд","донесення","діллінджер","крістоф","ґордо","ставок тихої води"},ang={["faction:Horde"]="Завдання дає гостям з Орди зазирнути в похмуру, суворо дисципліновану командну структуру, яку офіцери Сильвани Віндраннер насаджують по всьому Тірісфалю.",["race:Undead"]="Для щойно звільнених Відступників виконання наказів Зиґанда закріплює сувору дійсність виживання в Лордероні: цілковита відданість Темній Леді й нульова терпимість до невдач."},sec={{t="Воля Темної Леді",b="Екзекутор Зиґанд командує місцевою безпекою в Галявинах Тірісфалю і не терпить жодних послаблень пильності. Для Зиґанда служити Леді Сильвані означає ніщо інше, як цілковиту ефективність. Коли чергові польові донесення не надходять на його пост вчасно, він бачить у цьому неприпустиме порушення обов'язку, а не дрібну затримку. Замість покинути пост і розбиратися самому, він посилає новоприбулих агентів Відступників приструнити недбалих підлеглих і пересвідчитися, що кордони в безпеці."},{t="Вартові галявин",b="Донесення стосуються вартових на ключових спостережних пунктах довкола Брілла. Вартовий Смерті Діллінджер пильнує цвинтар на заході, де часто ворушаться здичавіла нежить і недобитки Погибелі. На сході Вартовий Смерті Крістоф наглядає за заставою, що стереже підступи до Столиці — колишнього стольного міста — і східні дороги. Найнезвичайніший серед них — Ґордо, здоровенна гидота, що тиняється біля Ставка Тихої Води: з його простим розумом військове діловодство — вельми сумнівне сподівання."}},fp="8,361,30.486.0,23.490.0,23.260.0,54.244.0,43.288.1,38.153.0,38.157.0,46.224.1"}
P.entries["quest:99142"] = {n="Могильне зілля",s="Могильне зілля — алхімічне завдання від Молодшого Аптекаря Голланда в Галявинах Тірісфалю. Голланд видозмінював дике Зілля Приречення і пересаджував його на проклятому Хуторі Балнірів, вирощуючи сильний новий зразок, що несподівано приваблює місцеву Погибель.",h="Могильне зілля — алхімічне завдання від Молодшого Аптекаря Голланда в Галявинах Тірісфалю.",kw={"могильне зілля","гробнична трава","голланд","хутір балнірів","зілля приречення","алхімія"},ang={["profession:Herbalism"]="Гробнична Трава показує, як штучне алхімічне втручання може докорінно змінити властивості й поведінку спустошених трав на кшталт Зілля Приречення.",["race:Undead"]="Дослідження Молодшого Аптекаря Голланда показують невпинне прагнення аптекарів Відступників перетворювати спустошену флору Тірісфалю на алхімічні знаряддя на замовлення."},sec={{t="Вирощування Голланда",b="Молодший Аптекар Голланд не задовольняється простим збиранням місцевих трав для Королівського Аптекарського Товариства — він плекає власні великі амбіції. Зібравши Зілля Приречення й піддавши його незначним алхімічним змінам, він пересадив ці пагони в землю Хутора Балнірів, щоб вивести вдосконалений зразок, який охрестив Гробничною Травою. Голланд бачить у цій гібридній рослині осердя своєї праці й провісника власної долі."},{t="Небажана принада",b="Голланд розраховував на алхімічну силу, та пересадження Гробничної Трави на Хутір Балнірів дало непередбачений побічний ефект. Блукаючі недобитки Погибелі, що кишать на спустошених полях, виявили до буйної рослини моторошний, нездоланний потяг. Голланд покладається на перехожих мандрівників: ті мають пробитися крізь нежить, що насідає, і зібрати дозрілий урожай, щоб він міг продовжити експерименти."}},fp="9,263,21.442.0,21.406.0,18.223.0,33.257.0,25.149.0,43.180.0,48.250.0,34.179.0"}
P.entries["quest:99156"] = {n="Тиловий патруль",s="Тиловий патруль — важливе оборонне доручення від Вартової Смерті Ліннеї в Галявинах Тірісфалю. Замість відбиватися від звичайних заблукалих гулів, патрульним доручають вистежити Ріптіра — гидоту, що блукає біля Долини Отруйного Павутиння, хоч ніколи не мала пройти повз Заслон.",h="Тиловий патруль — важливе оборонне доручення від Вартової Смерті Ліннеї в Галявинах Тірісфалю.",kw={"тиловий патруль","ріптір","гидота","ліннея","заслон","долина отруйного павутиння"},ang={["faction:Horde"]="Безпека східного кордону Тірісфалю гарантує, що лінії постачання Заслону й Андерсіті не підірвуть здичавілі жахіття.",["race:Undead"]="Відступники не можуть дозволити собі війну на два фронти; будь-який витвір Погибелі, що блукає за їхніми оборонними загорожами, — смертельна небезпека для їхнього королівства."},sec={{t="Пролом на кордоні",b="Заслон — єдина укріплена перепона, що відділяє Галявини Тірісфалю від жахіть, якими повняться Західні Чумні Землі. Стратегія війська Відступників тримається на суворо одному фронті. Якщо безтямна нежить прослизне в тил, лінії постачання фронту можна задушити за мить. Поодинокі духи чи гулі зрідка обходять загорожі, та звістки про гидоту, що блукає галявинами, свідчать про серйозний провал стримування."},{t="Загроза Ріптіра",b="Потвору-відступника на ім'я Ріптір бачили, як вона сунула поблизу Долини Отруйного Павутиння, за передовими редутами Заслону. Гидоти — величезні машини різанини, зшиті з трупів і темної некромантії. Вони не проходять укріплені вузькі проходи непоміченими, тож Вартову Смерті Ліннею глибоко тривожить, як саме істота перетнула периметр. Ліннея вимагає серце Ріптіра як беззаперечне підтвердження його знищення."}},fp="17,285,24.457.0,21.441.1,39.121.0,16.124.0,53.248.0,33.117.0,44.112.0,40.189.0"}
P.entries["quest:997"] = {n="Земля Деналана",s="«Земля Деналана» — доручення, що веде на південь від поселення Доланаар до тихих вод Озера Ал'Амет. Сірал Блейдліф просить мандрівників власноруч доставити затриману посилку з рідкісним збагаченим ґрунтом її колезі-ботаніку Деналану, який вивчає гілля та флору нового Світового Дерева.",h="«Земля Деналана» — доручення, що веде на південь від поселення Доланаар до тихих вод Озера Ал'Амет.",kw={"земля деналана","деналан","сірал блейдліф","ґрунт","озеро ал'амет","доланаар"},ang={["class:Druid"]="Друїди мають природну спорідненість із працею Деналана, адже стеження за ростом і рівновагою флори Тельдрассила — запорука захисту природи на новому гіллі.",["profession:Herbalism"]="Травникам припаде до душі озерний прихисток Деналана, адже його досліди зосереджені на розумінні крихкого молодого рослинного життя, властивого лише щойно вирослому Світовому Дереву.",["race:NightElf"]="Для нічних ельфів, що виходять із Тінедола, допомога Сірал і Деналанові — раннє знайомство з ширшою опікою, потрібною, щоб підтримувати Тельдрассил."},sec={{t="Кур'єр для Доланаара",b="Коли мандрівники проходять через Доланаар, прямуючи на південь до Озера Ал'Амет, Сірал Блейдліф зупиняє їх із задавненим дорученням. Її колега-дослідник Деналан замовив особливий пакунок рідкісної землі аж із Дарнасуса для своїх ботанічних досліджень. Посилка затрималася в дорозі й лише нещодавно прибула до Доланаара. Щоб багатий ґрунт не зіпсувався й не лежав без діла, Сірал шукає люб'язного кур'єра, готового віднести його лісовою стежкою до озерного табору Деналана."},{t="Вирощуючи Тельдрассил",b="Деналан тримає самотню робітню на східному березі Озера Ал'Амет, де спостерігає, як укорінюється молода екосистема Тельдрассила. Тельдрассил юний — він стрімко виріс після катаклізму на горі Гіджал, і його флора поводиться несподівано. Деналан випробовує унікальні суміші ґрунту й зразки, щоб перевірити життєвість і поведінку острівних деревляників і місцевих рослин, тож свіжа посилка рідкісної землі вкрай важлива для його дослідів."}},fp="15,297,22.508.0,22.469.0,15.208.0,33.178.0,32.234.0,23.118.0,26.178.0,40.181.1"}
P.entries["quest:cutting-teeth"] = {n="Проба зубів",s="Проба зубів — перше випробування для новобранців, що прибувають у Долину Випробувань у Дуротарі. Наглядач Ґорнек доручає новачкам прорідити плямистих вепрів, які блукають сусідніми кактусовими городами на червоній землі, і так перевіряє їхню базову бойову готовність. Пройти цей скромний обряд посвяти — означає довести, що майбутній воїн чи чарівник має хребет, потрібний для служби Орді.",h="Проба зубів — перше випробування для новобранців, що прибувають у Долину Випробувань у Дуротарі.",kw={"проба зубів","вепри","ґорнек","долина випробувань","новобранці","перше завдання"},ang={["faction:Horde"]="Кожен молодий герой, що ступає в Дуротар, має починати від самої землі, доводячи, що майбутнє Орди тримається на крові й поті, а не на незаслуженій славі.",["race:Orc"]="Орківська культура понад усе цінує практичне виживання й воїнську честь; навіть скромне винищення вепрів — священний перший крок у доросле життя й службу новій державі Тралла.",["race:Troll"]="Поки плем'я Темного Списа відбудовується поруч з орками-союзниками, молоді тролівські розвідники й містики теж мають довести свою самостійність серед безжальних хижаків Дуротару."},sec={{t="Міра хребта",b="Долина Випробувань не потурає мріям про велич. Хоч молоді новобранці можуть марити полюванням на велетенських звірів у Пустках чи славою на полях битв, наглядач Ґорнек починає їхню оцінку зі значно приземленіших справ. Проріджування плямистих вепрів довкола городів долини — базова перевірка: вона показує, чи вміє новобранець тримати зброю або накласти закляття, чи впорається з дикою люттю й чи має досить глузду, щоб пережити свою найпершу сутичку."},{t="Приборкання червоного пилу",b="Окрім перевірки сирих новобранців, винищення плямистих вепрів має й практичну господарську мету для поселення в червоній пустелі. Здичавілі свині блукають городами на північ і північний схід від табору, риють кактусові грядки й загрожують убогим припасам, вирощеним на суворому ґрунті Дуротару. Посилаючи претендентів їх вибити, табір тримає місцевих шкідників у шорах і водночас кує з молодих орків і тролів умілих захисників нової держави."}},fp="13,382,21.488.0,19.449.0,67.301.0,36.136.0,55.225.0,23.166.0,56.205.0,46.182.0"}
P.entries["quest:galgar-s-cactus-apple-surprise"] = {n="Сюрприз із Кактусових Яблук від Ґалґара",s="Сюрприз із Кактусових Яблук від Ґалґара — просте доручення для молодих воїнів і новачків у випаленій сонцем Долині Випробувань. Шукаючи порятунку від нищівної спеки Дуротару, орк Ґалґар просить подорожніх назбирати диких кактусових яблук, щоб приготувати свої знамениті освіжні ласощі. Завдання навчає новобранців збирати харч і виживати в посушливому краї.",h="Сюрприз із Кактусових Яблук від Ґалґара — просте доручення для молодих воїнів і новачків у випаленій сонцем...",kw={"ґалґар","кактусові яблука","сюрприз","кулінарія","долина випробувань","спека"},ang={["faction:Horde"]="Кожен новобранець, що ступає в Долину Випробувань, швидко дізнається: витримати нищівне сонце Дуротару — така сама частина вишколу, як і бій.",["profession:Cooking"]="Страва Ґалґара показує винахідливість, потрібну, щоб із жорсткої колючої пустельної рослинності приготувати поживну їжу й освіжні ласощі.",["race:Orc"]="Освоєння Дуротару означало пристосуватися до посушливого краю, і прості страви з місцевих кактусів утілюють практичну здатність орків процвітати на новій землі."},sec={{t="Виживання в червоних пустках",b="Багряна земля Долини Випробувань славиться своєю безжальністю. Між виснажливими бойовими вправами й лютими сутичками з тутешніми звірами виснаження й зневоднення настають швидко. Для молодих орків і тролів Темного Списа, що роблять перші кроки як захисники Орди, навчитися жити з дарів землі не менш важливо, ніж махати сокирою. Кактуси по всій долині родять стиглі, соковиті яблука, що дають негайний перепочинок від гнітючого пустельного сонця."},{t="Делікатес долини",b="Ґалґар, що стоїть на тренувальних землях, перетворив збирання місцевих плодів на мистецтво. Його знаменитий Сюрприз із Кактусових Яблук став легендою серед мешканців долини: він остуджує швидше, ніж стрибок у річкову воду. Наймаючи завзятих новобранців збирати колючі плоди з сусідніх кактусів, Ґалґар тримає свою кухню повною й дбає, щоб жоден новий мандрівник не вирушав у Дуротар із порожнім шлунком."}},fp="30,363,24.470.0,17.431.0,14.265.0,30.242.0,30.154.0,44.257.0,46.178.0,50.231.0"}
P.entries["quest:lazy-peons"] = {n="Ліниві пеони",s="Наглядачеві Тазз'рілу вже несила терпіти, що робітники Долини Випробувань засинають на роботі. Отримавши його обтяжений кийок, молоді новобранці обходять долину, щоб привести до тями сплячих пеонів і подбати, щоб життєво важлива деревина й далі текла до поселень Дуротару.",h="Наглядачеві Тазз'рілу вже несила терпіти, що робітники Долини Випробувань засинають на роботі.",kw={"пеони","наглядач тазз'ріл","кийок наглядача","деревина","долина випробувань","робітники"},ang={["faction:Horde"]="Кожна застава в Дуротарі покладається на деревину, яку рубають ці пеони, тож базова дисципліна робітників — справа спільного виживання.",["race:Orc"]="Для молодих орків, що дорослішають, дисциплінувати робочу силу власних родичів — ранній урок суворих реалій і практичної дисципліни, потрібних, щоб вирізьбити державу з дикої землі.",["race:Troll"]="Тролі Темного Списа, що навчаються поруч із союзниками, на власні очі бачать дивне поєднання грубої сили й управлінського відчаю, яке визначає орківське будівництво."},sec={{t="Байдики на сонці",b="Будівництво нового дому на посушливих рівнинах Дуротару вимагає величезної кількості деревини, каменю й просто важкої праці. Більша частина цього тягаря лягає на касту пеонів — орків, яким бракує воїнської вправності, та які становлять працьовитий хребет Орди. На лихо Наглядача Тазз'ріла, пекуча спека й виснажлива праця в Долині Випробувань роблять надто легкою спокусу для цих робітників ушитися під тінисте дерево на самовільну дрімоту."},{t="Швидка побудка",b="Замість дозволити продуктивності зупинитися, Наглядач Тазз'ріл вдається до доволі прямолінійного способу керування — Кийка Наглядача. Довіривши цей тупий дисциплінарний інструмент новобранцям Орди, він посилає їх долиною гамселити сплячих робітників по голові. Злякано прокинувшись, очманілі пеони поспіхом повертаються рубати дрова, нагадавши собі, що лінивим рукам немає місця у виживанні Дуротару."}},fp="10,277,19.426.0,20.419.0,33.197.0,25.186.0,32.185.0,37.227.0,35.162.0,42.146.1"}
P.entries["quest:sarkoth"] = {n="Саркот",s="Високо на південному плато Долини Випробувань чаїться Саркот — надзвичайно лютий скорпід, чиє отруйне жало поставило молодого мисливця Темного Списа на поріг смерті. Лежачи пораненим під деревом, умирущий троль Гана'зуа благає перехожого воїна вбити звіра й принести його скалічений пазур, щоб урятувати його честь.",h="Високо на південному плато Долини Випробувань чаїться Саркот — надзвичайно лютий скорпід, чиє отруйне жало...",kw={"саркот","гана'зуа","скорпід","плато","долина випробувань","честь","пазур"},ang={["faction:Horde"]="У безжальному середовищі Долини Випробувань прийти на поміч полеглим товаришам — ось що визначає силу громади, яку прагне плекати Орда Тралла.",["race:Orc"]="Орки розуміють муку смерті без перемоги; помста за Гана'зуа дарує невипробуваному розвідникові воїнське вдоволення бачити свого ворога поваленим.",["race:Troll"]="Для одноплемінника з Темного Списа відгукнутися на благання Гана'зуа — урочистий обов'язок спорідненості: подбати, щоб гідний опір члена племені визнали, а не загубили в пісках Дуротару."},sec={{t="Справа честі",b="Випробування в долині мають гартувати майбутніх воїнів Орди, та сувора пустеля рідко дає другий шанс. Вистежуючи отруйну тутешню звірину долини, молодий троль-розвідник Гана'зуа натрапив на скорпіда, значно більшого й смертоноснішого за решту. Хоч він і завдав важкого удару, що скалічив одну з клешень, хвіст Саркота впився йому в груди, і він лишився стікати кров'ю в сухій червоній пилюці. Перед лицем того, що здається кінцем його життя, у нього лишилося єдине бажання: щоб звір не пережив його."},{t="Жах плато",b="Саркот нишпорить піднесеним плато над південними околицями Долини Випробувань. Позначений розтрощеною клешнею від удару Гана'зуа, страхітливий звір панує на високому хребті й кидається на кожного, кому стане зухвалості піднятися кам'янистою стежкою. Убивство створіння й повернення його пошрамованого пазура Гана'зуа дає пораненому розвідникові гірку розраду — відчутний доказ того, що його останній відчайдушний удар послабив чудовисько настільки, щоб його можна було здолати."}},fp="7,323,17.545.0,18.451.0,25.181.0,16.238.0,38.247.0,33.217.1,49.201.0,49.183.1"}
P.entries["quest:your-place-in-the-world"] = {n="Твоє місце у світі",s="Цей простий обряд посвяти — мить, коли молодий майбутній герой виходить уперед, щоб служити Орді. Його дає Калтунк у Долині Випробувань, посилаючи невипробуваних новобранців просто до Ґорнека, щоб розпочати базовий бойовий вишкіл. Це найперший крок до честі й виживання в суворих землях Дуротару.",h="Цей простий обряд посвяти — мить, коли молодий майбутній герой виходить уперед, щоб служити Орді.",kw={"калтунк","ґорнек","долина випробувань","новобранець","перше завдання","орда"},ang={["faction:Horde"]="Кожен молодий новобранець Орди в Дуротарі має довести, що має досить впертості боронити свою молоду державу, перш ніж узяти зброю в ім'я Вождя.",["race:Orc"]="Для орків досягти повноліття й з'явитися на службу в Долину Випробувань — глибоко культурна віха, зосереджена на особистій честі й воїнській готовності.",["race:Troll"]="Оселившись у Дуротарі поруч з орками-союзниками, тролі Темного Списа навчаються тут пліч-о-пліч із побратимами, щоб кувати єдність і спільне виживання."},sec={{t="Дорослішання в Дуротарі",b="У посушливому каньйоні Долини Випробувань молоді орки й тролі Темного Списа мають довести свою гідність, перш ніж ступити в ширший світ. Життя під владою Вождя Тралла вимагає сили, пильності й дисципліни. Калтунк оцінює кожного завзятого новобранця, стримано остуджуючи його мрії про боротьбу з демонами й драконами, щоб спрямувати до посильних обов'язків. Кожен легендарний герой Орди починає саме тут — учиться смирення, перш ніж здобути славу."},{t="Прибуття до Ґорнека",b="За кілька кроків від Калтунка сидить Ґорнек — суворий ветеран біля табірного вогнища. Ґорнек оцінює новоприбулих скептичним оком, часто бурчачи про жалюгідний матеріал, що прибуває до табору. Та саме його обов'язок — загартувати цих бійців-початківців суворими випробуваннями, починаючи з винищення тутешніх шкідників, що загрожують припасам табору."}},fp="23,330,24.462.0,19.377.0,34.217.0,15.200.0,14.215.0,32.168.0,46.217.0,47.152.0"}
P.entries["subzone:agamand-family-crypt"] = {n="Родинний Склеп Аґамандів",s="Родинний Склеп Аґамандів, схований у пагорбах одразу на північ від Млинів Аґаманда, — давнє місце спочинку однієї з найзаможніших фермерських династій Тірісфалю. Тепер його захопила Погибель під проводом Капітана Дарґола: гробниці розкрито, а сплячих предків піднято безтямними страхіттями.",h="Родинний Склеп Аґамандів, схований у пагорбах одразу на північ від Млинів Аґаманда, — давнє місце спочинку...",kw={"родинний склеп аґамандів","аґаманди","склеп","капітан дарґол","погибель","некромантія","тірісфаль"},ang={["race:Undead"]="Для Відступників захоплення склепу Капітаном Дарґолом — нестерпна присутність Погибелі в Тірісфалі, що глумиться з мертвих і загрожує північному кордону Андерсіті."},sec={{t="Неспокійні предки",b="До Третьої війни родина Аґамандів володіла великими маєтками по північних Галявинах Тірісфалю й ховала своїх предків у цьому мавзолеї на схилі пагорба. Коли Чума принесла королівству руїну, склеп потрапив у лабети Капітана Дарґола, агента Погибелі. Замість дати заможному роду спочивати з миром, Дарґол темною некромантією пробудив поховані скелети й мстиві привиди, перетворивши священне поховання на войовничий плацдарм Погибелі просто на краю земель Відступників."}},fp="20,295,18.535.0,42.109.0,33.129.0,39.175.0,57.144.0"}
P.entries["subzone:agamand-mills"] = {n="Млини Аґаманда",s="Млини Аґаманда — розлогий комплекс ферм і вітряків на північних висотах Галявин Тірісфалю. Колись гордий маєток заможної династії Аґамандів, він занепав і став найбільшою твердинею Погибелі в краї.",h="Млини Аґаманда — розлогий комплекс ферм і вітряків на північних висотах Галявин Тірісфалю.",kw={"млини аґаманда","аґаманди","вітряки","погибель","твердиня","капітан дарґол","девлін аґаманд","тірісфаль"},ang={["race:Undead"]="Для Відступників повернення Млинів Аґаманда — не просто тактика; це особиста помста Погибелі й зведення рахунків колишніми слугами маєтку, як-от Коулменом Фартінґом."},sec={{t="Дім, розділений зсередини",b="Століття тому заможні дворяни-переселенці зі Строму заснували маєток Аґамандів і збудували розгалужену мережу млинів по північному Тірісфалю. Коли спалахнула Третя війна й Погибель прокотилася Лордероном, патріарх Ґреґор Аґаманд відмовився тікати: він укріпив садибу й переконав челядь і робітників стати на бій. Їхні припаси й кам'яні стіни могли б вистояти, та наймолодший син, Девлін Аґаманд, зрадив свою кров. Девлін перебив вартових маєтку й упустив ходячих мерців до спалень. Підкошені зсередини, решта захисників були винищені, а родина поповнила безтямні лави нежиті."},{t="Бастіон гнилі",b="Сьогодні Млини Аґаманда — найукріпленіший бастіон Погибелі в Галявинах Тірісфалю, що становить пряму загрозу державі Відступників. Гнилі вітряки крутяться над зараженими полями, де кишать примари, зомбі й кістяні страхіття. Під маєтком Капітан Дарґол командує гарнізоном із глибин Родинного Склепу Аґамандів, вправляючись у некромантії, щоб воскрешати покоління предків Аґамандів. З Брілла Магістрат Севрен і Вартові Смерті ведуть діяльну кампанію, щоб зачистити млини й викорінити присутність Погибелі, перш ніж вона рушить на Андерсіті."}},fp="13,244,15.662.0,16.563.0,42.290.0,33.222.0,42.218.0,27.266.0"}
P.entries["subzone:aldrassil"] = {n="Алдрассил",s="Алдрассил — велетенське дерево-оселя й поселення в серці Тінедолу на північному сході Тельдрассила. Головний прихисток і місце навчання молодих калдореїв; у його вирізьблених порожнинах знайшли притулок наставники, крамарі та місцеве керівництво.",h="Алдрассил — велетенське дерево-оселя й поселення в серці Тінедолу на північному сході Тельдрассила.",kw={"алдрассил","тінедол","тельдрассил","дерево","наставники","тенарон стормґріп"},ang={["class:Druid"]="Алдрассил показує схильність калдореїв до живої архітектури, виплеканої з живого дерева без порушення рівноваги лісу.",["race:NightElf"]="Для багатьох молодих калдореїв вирізьблені порожнини й пандуси Алдрассила — перший спогад про громадське життя й основа їхнього раннього навчання."},sec={{t="Серце Тінедолу",b="Здіймаючись над відлюдною долиною Тінедолу, Алдрассил — водночас прихисток і громадський осередок для молодих нічних ельфів, що роблять перші кроки у світі. Усередині й довкола велетенського стовбура цього прадавнього дерева в'ються пандуси, що ведуть повз наставників класів і ремісників до високого сідала, звідки Тенарон Стормґріп наглядає за безпекою гаю. Поки Світове Дерево Тельдрассил тягнеться через увесь обрій, Алдрассил дає безпечну, надійну крону, де новачки опановують своє мистецтво, перш ніж спуститися в неспокійні хащі Калімдору."}},fp="9,254,19.549.0,18.215.0,38.156.0,32.205.0"}
P.entries["subzone:amberstill-ranch"] = {n="Ранчо Амберстілл",s="Ранчо Амберстілл — тиха дворфська садиба при засніженій дорозі на Лох Модан, просто на північ від Кар'єру Гол'Болар. Це головне місце, де розводять і тренують славетних гірських баранів Айронфорджа. Шукачі пригод навідуються сюди, щоб придбати витривалого дворфського скакуна, навчитися верхової їзди або допомогти родині захистити худобу від місцевих хижаків.",h="Ранчо Амберстілл — тиха дворфська садиба при засніженій дорозі на Лох Модан, просто на північ від Кар'єру...",kw={"ранчо амберстілл","барани","скакуни","верхова їзда","дун мороґ","вендіго"},ang={["faction:Alliance"]="Міцні барани, вирощені Амберстіллами, дають Альянсу надійну кавалерію для холодного клімату, придатну для суворої гірської місцевості.",["race:Dwarf"]="Для дворфських шукачів пригод ранчо — предмет гордості й культурна основа: саме тут молоді герої здобувають свого першого барана породи Барак Тор'ол."},sec={{t="Домівка гірських баранів",b="Притулившись до скель Дун Мороґу, Ранчо Амберстілл славиться на весь Хаз Модан найвитривалішими гірськими баранами Східних Королівств. Родина Амберстіллів порядкує в стайнях і загонах, навчаючи цих твердоногих тварин долати підступні снігові перевали й круті альпійські урвища. Окрім постачання їздових скакунів і свійської худоби, родині часто доводиться відбиватися від дикої звірини пагорбів — особливо від вендіго, яких приваблює запах свіжої отари."}},fp="16,374,25.495.0,35.200.0,37.240.0,33.228.0,42.163.0"}
P.entries["subzone:bael-dun-digsite"] = {n="Розкопки Бел'дуну",s="Розкопки Бел'дуну — дворфійська копальня, вирубана глибоко в горах уздовж західного краю Малгору. Закладена загоном Шукача Хазґорма з Бель Модану, вона в очах місцевих тауренів — пряме осквернення прабатьківської землі й образа Земній Матері.",h="Розкопки Бел'дуну — дворфійська копальня, вирубана глибоко в горах уздовж західного краю Малгору.",kw={"бел'дун","розкопки","дворфи","ліга дослідників","бель модан","малгор","титани"},ang={["faction:Alliance"]="Хоч копачами Бел'дуну рухає щира жага історичних відкриттів, вони зайшли надто глибоко в суверенні землі Орди, спричинивши криваві сутички з місцевими.",["race:Tauren"]="Рубці від вторгнення на західних пагорбах Малгору роблять Бел'дун прямою образою Земній Матері, що вимагає рішучих дій — захистити прабатьківську землю від чужинського осквернення."},sec={{t="Вторгнення в пагорби",b="Розкопки Бел'дуну, що примостилися на гірських схилах західного Малгору, — найпівденніший форпост експедиції дворфійської Ліги Дослідників, яка базується в Бель Модані в південних Пустках. Не зважаючи ні на кордони, ні на духовні традиції щойно осілих племен, дворфійські шукачі прибули з кирками, лопатами й вибуховим порохом, аби видобути стародавні реліквії титанів, поховані під рівнинами."},{t="Захист Земної Матері",b="Плем'я Бладгуф сприйняло ці загарбницькі розкопки як відвертий напад на Земну Матір. Бейн Бладгуф спершу закликав до обережності й намагався застерегти зайд, та дворфи навідріз відмовилися покинути свої траншеї. Дійшовши висновку, що дипломатія зазнала поразки, таурени постановили потрощити знаряддя експедиції й силою вигнати копачів, поки їхнє руйнівне копання не роздерло священну землю Малгору ще глибше."}},fp="16,299,22.420.0,26.432.0,35.308.0,52.266.0,55.172.0,59.263.0"}
P.entries["subzone:balnir-farmstead"] = {n="Хутір Балнірів",s="Хутір Балнірів — занедбаний маєток у східних Галявинах Тірісфалю, на північний схід від Руїн Лордерона. Колись славний розведенням знаменитих білих коней, яких любила королівська родина Лордерона, тепер він лежить у руїнах, заполонений блукаючою Погибеллю. Сьогодні маєток — сумний пам'ятник ранньому життю принца Артаса Менетіла й місце, де той здобув свого скакуна-нежить.",h="Хутір Балнірів — занедбаний маєток у східних Галявинах Тірісфалю, на північний схід від Руїн Лордерона.",kw={"хутір балнірів","артас менетіл","інвінсібл","коні","погибель","чумні землі","тірісфаль"},ang={["class:Mage"]="Магів Відступників посилають на ці уражені землі збирати вцілілі ротики Балнірів і вивчати їх, щоб виявити залишкову магічну заразу Погибелі.",["race:Undead"]="Для Відступників цей хутір — гірке нагадування про принца, який прирік Лордерон, а також набридлива прогалина в обороні, крізь яку Погибель із Чумних Земель прослизає за Оплот."},sec={{t="Спадщина королівських скакунів",b="Поколіннями родина Балнірів розводила легендарних білих жеребців Лордерона на своїй садибі серед хвилястих пагорбів Тірісфалю. Хлопчиком принц Артас Менетіл часто навідувався на ферму, тікаючи від придворного життя, і заприятелював із молодим Джарімом Балніром. Саме тут Артас допоміг прийняти лоша, яке назвав Інвінсіблом. Через роки, коли трагічний нещасний випадок під час верхової їзди обірвав життя скакуна, Інвінсібла на особисте прохання Артаса поховали в землі хутора."},{t="Спустошення й проникнення Погибелі",b="Коли принц Артас повернувся з Нортренду й сплюндрував столичне місто Лордерона, Погибель без жалю винищила родину Балнірів. Щойно ставши лицарем смерті, Артас рушив на хутір, щоб викопати й воскресити Інвінсібла Фростморном, лишивши по собі розриту, сплюндровану могилу. Після Третьої війни руїни правлять за плацдарм безтямної Погибелі, що прослизає повз Оплот. Вартові Смерті Відступників насторожено стежать за фермою, а маги Андерсіті збирають у саду вцілілі ротики, щоб перевірити, як глибоко чумна скверна проникла в ґрунт."}},fp="16,385,24.502.0,35.561.0,57.306.0,45.263.0,45.283.0,46.212.0"}
P.entries["subzone:ban-ethil-barrow-den"] = {n="Курганне Лігво Бан'етіл",s="Курганне Лігво Бан'етіл — священне підземне святилище, видовбане в корінні Тельдрассила. Створене як місце спочинку для сплячих Друїдів Кігтя, печерний комплекс нещодавно поринув у хаос. Зіпсуті фурболги племені Вузлошкірів заполонили його зали, перетворивши місце мирного сну на небезпечне лігво божевілля.",h="Курганне Лігво Бан'етіл — священне підземне святилище, видовбане в корінні Тельдрассила.",kw={"курганне лігво бан'етіл","бан'етіл","друїди кігтя","фурболги","вузлошкіри","смарагдовий сон","тельдрассил"},ang={["class:Druid"]="Бан'етіл — священна земля для Кола Кенарія, збудована саме для того, щоб захищати Друїдів Кігтя, поки ті єднаються зі Смарагдовим Сном.",["race:NightElf"]="Захоплення Бан'етілу зіпсутими фурболгами-Вузлошкірами — тривожна ознака хвороби, що шириться їхньою новою домівкою, Тельдрассилом."},sec={{t="Осквернене святилище",b="Курганні лігва — священні покої спочинку, де друїди нічних ельфів сплять, посилаючи свій дух у Смарагдовий Сон. Курганне Лігво Бан'етіл було призначене саме для Друїдів Кігтя, що єднаються з природою. Поділене на верхні й нижні підземні покої, лігво колись бриніло тихою задумою й глибокою магією медитації. Та недуга, що охопила живність Тельдрассила, не оминула й фурболгів-Вузлошкірів: вони вдерлися до комплексу й перетворили його видовбані зали на укріплене кубло."},{t="Вторгнення Вузлошкірів",b="Збожеволілі від таємничої скверни, що пускає коріння по всьому Світовому Дереву, Вузлошкіри вигнали сплячих друїдів із Бан'етілу або поставили їх під загрозу. Тепер фурболги люто стережуть звивисті тунелі й нападають на кожного нічного ельфа, що наближається. Для захисників Тельдрассила повернути курганне лігво — нагальне завдання: не лише щоб відігнати ворожих фурболгів, а й щоб захистити вразливих друїдів і священні реліквії, замкнені в нижніх глибинах."}},fp="20,368,19.540.0,23.472.0,29.189.0,51.224.0,40.159.0,43.209.0"}
P.entries["subzone:ban-ethil-hollow"] = {n="Лощина Бан'етіл",s="Лощина Бан'етіл — скелястий яр, що врізається в ліс одразу на південь від головної дороги між Доланааром і Дарнасусом. Вона стала небезпечним прихистком для зіпсутих, агресивних фурболгів, які постійно загрожують подорожнім. У глибині яру ховається вхід до Курганного Лігва Бан'етіл.",h="Лощина Бан'етіл — скелястий яр, що врізається в ліс одразу на південь від головної дороги між Доланааром і...",kw={"лощина бан'етіл","бан'етіл","яр","фурболги","доланаар","дарнасус","тельдрассил"},ang={["class:Druid"]="Лощина ховає вхід до Курганного Лігва Бан'етіл — священної землі, де друїди традиційно спочивають, єднаючись зі Смарагдовим Сном, а тепер їм загрожує скажена живність.",["race:NightElf"]="Бачити, як фурболги божеволіють так близько до дороги між Доланааром і Дарнасусом, — похмурий знак дедалі тяжчої хвороби Тельдрассила, що вимагає втручання молодих вартових і друїдів."},sec={{t="Небезпечний яр",b="Лощина Бан'етіл, що лежить осторонь шляху між Доланааром і Дарнасусом, — різке нагадування, що гілля Тельдрассила не зовсім безпечне. Фурболги, збожеволілі від дивної недуги, яка мучить Світове Дерево, знайшли притулок по всьому скелястому спуску. Вони часто чатують біля стежки, вичікуючи необачних гінців і мандрівних вартових, щоб напасти із засідки. У глибині яру — поріг Курганного Лігва Бан'етіл, де сплячі друїди й давні тунелі потерпають від навали знавіснілих звірів іззовні."}},fp="16,317,17.529.0,34.165.0,34.262.0,66.236.0,44.239.0"}
P.entries["subzone:bladefist-bay"] = {n="Затока Блейдфіст",s="Затока Блейдфіст — суворий відтинок узбережжя на сході Дуротару, одразу за брамою Оргріммара. Названа на честь Карґата Блейдфіста, затока служить природною гаванню, зверненою до Великого Моря, у тіні скелястих круч і сусідніх південних берегів Азшари.",h="Затока Блейдфіст — суворий відтинок узбережжя на сході Дуротару, одразу за брамою Оргріммара.",kw={"затока блейдфіст","узбережжя","гавань","карґат","розтрощена рука","оргріммар","дуротар"},ang={["class:Rogue"]="Розтрощена Рука діє в тінях Оргріммара як гільдія злодіїв і вбивць Орди, тож для таємних агентів це узбережжя має тихий відгомін.",["race:Orc"]="Затока носить горде й жорстоке ім'я Карґата Блейдфіста, нагадуючи про випробування клану Розтрощеної Руки на Дренорі."},sec={{t="Гавань на Великому Морі",b="Простягшись уздовж північно-східного краю Дуротару, Затока Блейдфіст відкривається просто в неосяжні води Великого Моря. Затиснута скелястими урвищами й підступним прибоєм, вона є головним морським порогом столиці Орди — Оргріммара. Припливи раз у раз викидають на берег плавник, океанське сміття та уламки, тож серед місцевих затока має славу природного збірника морського непотребу. Просто на північ, через воду, височіють прадавні червоні скелі й руїни Азшари, роблячи затоку важливим морським кордоном Дуротару."},{t="Тінь Розтрощеної Руки",b="Затока вшановує Карґата Блейдфіста — славетного вождя клану Розтрощеної Руки, який відтяв собі руку, щоб замінити її клинком під час випробувань старої Орди на Дренорі. Близькість затоки до місць на кшталт Череп-скелі, де в тіні діють культисти й приховані мережі розбійників, перегукується з лютою та безжальною спадщиною клану, чий вождь дав цим водам ім'я."}},fp="13,267,25.553.0,28.387.0,33.157.0,31.129.0,39.148.0,46.175.0"}
P.entries["subzone:bloodhoof-village"] = {n="Село Бладгуф",s="Село Бладгуф — центральне тауренське поселення на берегах Озера Кам'яного Бика в Малгорі. Назване на честь племені Бладгуф, воно стає першим великим осередком для молодих мисливців і сміливців, що прямують із Табору Нарачі до Тандер Блафа. Під проводом Бейна Бладгуфа село узгоджує місцеву оборону, торгівлю й традиційні обряди по всіх рівнинах.",h="Село Бладгуф — центральне тауренське поселення на берегах Озера Кам'яного Бика в Малгорі.",kw={"село бладгуф","бейн бладгуф","озеро кам'яного бика","малгор","таурени","поселення"},ang={["faction:Horde"]="Це мирне поселення — важлива зупинка й сполучна ланка між південними рівнинами Малгору та столицею Орди в Тандер Блафі.",["race:Tauren"]="Для молодих тауренів вхід до Села Бладгуф — перший справжній крок із юності до ширшої відповідальності перед племенем і духовної зрілості."},sec={{t="Серце рівнин",b="Розташоване довкола прозорих вод Озера Кам'яного Бика, Село Бладгуф — жвавий осередок торгівлі, ремесла й обрядів у центрі Малгору. Молоді таурени, що пройшли випробування в Таборі Нарачі, приходять сюди відточити вміння, перш ніж рушити далі, до великих плато Тандер Блафа. Село також відоме по всьому Калімдору своїми майстрами-барабанниками й терплячими заводчиками, що приручають диких кодо для подорожей."},{t="Проводирі та обряди",b="Повсякденне врядування й оборона краю лежать на Бейні Бладгуфі, синові Верховного Вождя Кайрна Бладгуфа. Під його пильним оком сміливців посилають убезпечувати пасовища від агресивних звірів, зазіхань шипогривів і тіньової присутності Венчурної Компанії. Поруч із Бейном духовні провідники, як-от Зарлман Ту-Мунс, дбають про внутрішнє життя племені й ведуть новачків через священні мандри на кшталт Обряду Видіння."}},fp="17,379,19.417.0,20.454.0,28.141.0,36.160.0,43.146.0,55.142.0"}
P.entries["subzone:brackwell-pumpkin-patch"] = {n="Гарбузова Ділянка Брекуеллів",s="Гарбузова Ділянка Брекуеллів — захоплена ферма на південному сході Лісу Елвінн. Колись домівку родини Брекуеллів, її поля й хатину цілком прибрало до рук Братство Дефіас як робочий сховок. Тут зустрічаються змовники-розбійники й звідси переправляють украдене золото.",h="Гарбузова Ділянка Брекуеллів — захоплена ферма на південному сході Лісу Елвінн.",kw={"гарбузова ділянка брекуеллів","ферма","братство дефіас","розбійники","принцеса","сурена каледон","ліс елвінн"},ang={["class:Warlock"]="У халупі на фермі переховується втікачка-учениця Сурена Каледон, чиє вкрадене кольє з кривавика потрібне, щоб зв'язати блукача Порожнечі.",["faction:Alliance"]="Захоплена ділянка — одна з найсхідніших робочих баз Дефіасів в Елвінні, що безпосередньо загрожує сусіднім фермам і торговим шляхам."},sec={{t="Розбійницький прихисток",b="Ферма Брекуеллів на південний схід від садиби Стоунфілдів колись була родючим клаптем елвіннської землі. Нині її законні господарі зникли безслідно — їх вигнала, а може, й гірше, хвиля злочинності, що здіймається. За їхньої відсутності Братство Дефіас захопило міцну хатину й зарослі поля ферми. Місце працює як схованка й перевалочний пункт, де розбійники перегруповуються подалі від пильних очей патрулів Ґолдшира. Помітні змовники на кшталт Морґана Збирача використовують відлюдну ділянку, щоб приймати партії золота, незаконно вкраденого з лісових копалень."},{t="Свині й темна магія",b="Дефіаси — не єдині бешкетники, що нишпорять серед гарбузового бадилля. Брекуелли лишили по собі величезну свиню-рекордистку на ім'я Принцеса, яка блукає ділянкою й без упину тероризує сусідні поля. Тим часом горище хатини та господарські будівлі приховують небезпечні особисті справи: розбійник Ерлан Драджмур звабив Сурену Каледон — ученицю-чорнокнижницю, що втекла від свого наставника в Стормвінді з украденим артефактом-кривавиком, і так привернув до сховку увагу темних практиків."}},fp="23,317,14.602.0,19.504.1,38.236.0,46.283.0,16.221.0,42.276.0"}
P.entries["subzone:brambleblade-ravine"] = {n="Яр Тернистого Клинка",s="Яр Тернистого Клинка — скелястий каньйон, що врізається в північно-східний край Плато Червоної Хмари. Це укріплене лігво шипогривів племені Щетиноспинних, які раз у раз нападають на сусіднє тауренське поселення, Табір Нарачі. Молодих тауренських сміливців посилають сюди довести свою силу й захистити батьківщину від цих лютих зайд.",h="Яр Тернистого Клинка — скелястий каньйон, що врізається в північно-східний край Плато Червоної Хмари.",kw={"яр тернистого клинка","шипогриви","щетиноспинні","плато червоної хмари","табір нарачі","шарптаск торнмантл"},ang={["faction:Horde"]="Зачистка войовничих Щетиноспинних у Яру Тернистого Клинка допомагає Орді закріпити перші позиції по всьому Малгору.",["race:Tauren"]="Для молодих тауренів, що дорослішають у Таборі Нарачі, похід у Яр Тернистого Клинка — одне з найперших випробувань бойової та духовної витривалості на захист племені."},sec={{t="Скалка в боці плато",b="Вирізьблений у випаленій сонцем землі Плато Червоної Хмари, Яр Тернистого Клинка густо заріс колючими хащами й усіяний стійбищами шипогривів. Плем'я Щетиноспинних використовує цю природну фортецю як плацдарм для наскоків на Табір Нарачі, загрожуючи безпеці молодих тауренів, що входять у зрілий вік. Шамани й воїни Щетиноспинних на чолі з Вождем Шарптаском Торнмантлом живуть у глибині яру серед вишколених бойових вепрів. Для Шу'хало удар у саме серце каньйону — водночас важливий обряд посвяти й сувора необхідність, щоб убезпечити рівнини."}},fp="19,341,26.544.0,28.181.0,53.214.0,46.147.0,41.199.0"}
P.entries["subzone:brewnall-village"] = {n="Село Брюнолл",s="Село Брюнолл — невелике дворфське поселення в Долині Холодного Вітерцю, неподалік входу до Гномреґану. Засноване родиною Барліброю, воно служить полігоном для сміливих пивоварних дослідів і місцевої оборони від диких звірів. Хоч його й називають селом, насправді це радше сільський табір у засніжених гномських низинах Дун Мороґу.",h="Село Брюнолл — невелике дворфське поселення в Долині Холодного Вітерцю, неподалік входу до Гномреґану.",kw={"село брюнолл","барліброю","пивовари","долина холодного вітерцю","гномреґан","дун мороґ"},ang={["race:Dwarf"]="Для дворфів пошук Барліброю досконалого рецепта — почесна справа, що підтримує одну з найкращих традицій Айронфорджа.",["race:Gnome"]="Розташоване поруч із Гномреґаном, село — несподівана дворфська застава глибоко в гномських долинах західного Дун Мороґу."},sec={{t="Гірке варево в долині",b="Сховане серед заметів Долини Холодного Вітерцю, Село Брюнолл лежить просто посеред споконвічних гномських земель західного Дун Мороґу. Тут живе клан Барліброю — непохитні дворфські пивовари, віддані вдосконаленню прадавніх рецептів і створенню найкращого стауту. Хоч це й зветься селом, застава складається здебільшого з наметів і просто неба розставленого пивоварного начиння, а не з кам'яних будівель. Випробовуючи дослідні партії елю й відбиваючись від лютих тутешніх вовків та ведмедів, Барліброю чимало покладаються на мандрівних горян, які збирають рідкісні інгредієнти й охороняють долину."}},fp="16,380,27.637.0,25.243.0,53.234.0,57.266.0,36.244.0"}
P.entries["subzone:brightwater-lake"] = {n="Озеро Світлої Води",s="Озеро Світлої Води — найбільша водойма Галявин Тірісфалю, що простягається оповитими імлою низинами на північний схід від Брілла. Колись тихий притулок королівства Лордерон, тепер його води холодні й темні, а посередині лежить острів, де некромант-вигнанець веде свої заборонені дослідження.",h="Озеро Світлої Води — найбільша водойма Галявин Тірісфалю, що простягається оповитими імлою низинами на...",kw={"озеро світлої води","тірісфаль","брілл","ґунтер арканус","притулок ґунтера","некромант","мурлоки"},ang={["class:Mage"]="Озеро зберігає рештки чарів давніх битв, що точилися в Тірісфалі, а також унікальну, нікому не підвладну майстерність чарівника-відступника Ґунтера Аркануса.",["race:Undead"]="Для Відступників убезпечити Озеро Світлої Води важливо, щоб боронити східні підступи до Брілла й з'ясувати, чи самостійний некромант Ґунтер Арканус стане надбанням або ворогом."},sec={{t="Води півночі",b="Озеро Світлої Води, що розкинулося північними рівнинами між містечком Брілл і Багряною Сторожовою Заставою, — тихий і моторошний орієнтир у серці Тірісфалю. Тисячі років тому його імлисті береги бачили давні битви, зокрема ранні сутички з повелителем жаху Катра'натіром. У мирні століття під владою Королівства Лордерон озеро було мальовничим сільським затишком. Сьогодні, як і решта галявин, воно давно втратило свою первозданність. Чумні Землі лежать недалеко на схід, а каламутні холодні води відбивають лише сіре небо, усохлі дерева й постійну загрозу мандрівних мурлоків і ворожої нежиті."},{t="Притулок самітника",b="Посеред Озера Світлої Води здіймається острів, відомий як Притулок Ґунтера. Тут живе Ґунтер Арканус — могутній некромант, що вирвався з хватки Короля-Ліча власною незламною волею. Недовірливий до Темної Леді й новоутворених Відступників в Андерсіті, Ґунтер обрав усамітнення замість служби й підняв власних скелетів-захисників стерегти береги острова. Його вперта незалежність викликає гострий інтерес магістратів Відступників, які прагнуть або залучити його грізні таланти, або переконатися, що його самостійне існування не загрожує державі Сильвани."}},fp="16,307,19.652.0,19.595.1,34.247.0,50.296.0,41.243.0,57.266.0"}
P.entries["subzone:brill"] = {n="Брілл",s="Брілл — головне поселення Відступників в серці Галявин Тірісфалю, одразу на північ від Руїн Лордерона. Колись квітуче людське містечко, тепер воно править за адміністративний і військовий осередок для щойно пробуджених мерців, що виходять за межі Похоронного Подзвону.",h="Брілл — головне поселення Відступників в серці Галявин Тірісфалю, одразу на північ від Руїн Лордерона.",kw={"брілл","тірісфаль","відступники","цепелін","магістрат севрен","таверна шибеничний кінець","культ проклятих"},ang={["faction:Horde"]="Пристань цепелінів за містом — головна ланка північної Орди між Лордероном і союзними твердинями в Калімдорі та Східних Королівствах.",["race:Undead"]="Для Відступників, що вирушають із Похоронного Подзвону, Брілл — перший проблиск цивілізації й місце, де починають доводити вірність Темній Леді."},sec={{t="Від чумної землі до бастіону",b="До Третьої війни Брілл був жвавим селом під владою місцевих дворян — родин Барових і Аґамандів. Цьому добробуту настав кінець, коли Кел'Тузад обрав ці місця для найперших дослідів Культу Проклятих із Чумою Нежиті. Спустошлива пошесть прокотилася населенням так швидко, що місцеве ополчення було вибите, а по собі лишила величезне братське кладовище.\n\nТепер, відбудований Відступниками під проводом Магістрата Севрена, Брілл зберігає обвітрену лордеронську архітектуру під покровом похмурої цілеспрямованості. Містечко править за командний центр краю, координуючи оборону від вторгнень Багряного Хрестового Походу, мандрівних решток Погибелі та місцевих звірів, спотворених некромантичним тлінням."},{t="Перехрестя північного Лордерона",b="Окрім місцевої оборони, Брілл — важливе перехрестя, що з'єднує Галявини Тірісфалю з рештою Орди. Над головою гоблінська вежа цепелінів забезпечує сполучення на південь, до Дуротару, і вглиб Долини Стренглторну. У самому поселенні Таверна «Шибеничний Кінець» править не лише за темний прихисток для подорожніх, а й за імпровізовану лабораторію, де полонених багряних фанатиків допитують і піддають аптекарським дослідам."}},fp="5,273,29.744.0,32.429.0,16.135.0,52.252.0,37.176.0,54.164.0"}
P.entries["subzone:brill-town-hall"] = {n="Ратуша Брілла",s="Ратуша Брілла — адміністративне серце поселення Брілл у центральних Галявинах Тірісфалю. Найпомітніша будівля містечка, вона править за цивільний штаб, звідки Відступники керують своїми місцевими володіннями й координують оборону галявин.",h="Ратуша Брілла — адміністративне серце поселення Брілл у центральних Галявинах Тірісфалю.",kw={"ратуша брілла","брілл","магістрат севрен","відступники","врядування","тірісфаль"},ang={["faction:Horde"]="Союзники Орди, прибувши в Тірісфаль, можуть завітати до ратуші, щоб зрозуміти, як Відступники підтримують цивільну владу й військовий лад на своїх потемнілих рідних землях.",["race:Undead"]="Для Відступників, що вирушають із Похоронного Подзвону, ратуша — перший смак упорядкованого цивільного врядування в державі Королеви Сильвани, де офіційно організовують місцеву оборону й відновлення."},sec={{t="Цивільний осідок Відступників",b="Поки значна частина Лордерона лежить розбита й зруйнована, Ратуша Брілла досі стоїть як діючий громадський центр під владою нежиті. Усередині Магістрат Севрен керує справами містечка зі свого подіуму, роздаючи шукачам пригод Відступників важливі доручення й розпорядження. Якщо не рахувати Лігва Осквернителя в Аратійському нагір'ї, це одна з небагатьох визнаних ратуш у відомому світі, якою справді керують Відступники, — похмура пародія й водночас дієве продовження міської бюрократії старого Лордерона."}},fp="15,278,26.509.0,37.251.0,22.176.0,49.226.0"}
P.entries["subzone:burning-blade-coven"] = {n="Ковен Палаючого Клинка",s="Схований у північних скелях Долини Випробувань, Ковен Палаючого Клинка — заражена мережа печер, що загрожує найновішим новобранцям Орди. Усередині чаяться осквернені культисти й прикликані демони, перетворивши стару мінеральну печеру на плацдарм темної магії просто на порозі Дуротару.",h="Схований у північних скелях Долини Випробувань, Ковен Палаючого Клинка — заражена мережа печер, що загрожує...",kw={"ковен палаючого клинка","культисти","демони","біси","печера","долина випробувань","ярроґ бейншедов"},ang={["class:Warlock"]="Демонічні біси й темні обряди тут — ранній застережливий погляд на те, що стається, коли силу Скверни пускають у хід безоглядно, у відкритому непослуху Орді.",["race:Orc"]="Присутність культу Палаючого Клинка так близько до Долини Випробувань — нестерпна образа для нової Орди Тралла й суворе нагадування про поклоніння демонам, яке орки так боролися залишити позаду."},sec={{t="Тінь над полігоном",b="Запилені червоні гори, що обступають Долину Випробувань, колись були просто дикою місциною для випробувань молодих орків і тролів Темного Списа, які робили перші кроки на службі Орді. Та нещодавно північні печери охопили темні обряди. З гирла печери висипають біси та дрібні демони, сіючи хаос і загрожуючи новобранцям. Культ Палаючого Клинка на чолі з потаємним чорнокнижником Ярроґом Бейншедовом міцно окопався в глибині, перетворивши колись звичайний тренувальний майданчик на справжнє поле бою з демонічним скверненням."},{t="Скверна в скелях",b="Ще до того, як тут укорінилися демони, печери привернули увагу місцевих наглядачів, що сподівалися добути сировину для поселення. Наглядач Тазз'ріл спустився вглиб із мінеральною розвідкою, та його поспіхом вигнали, і він покинув цінне спорядження, коли культисти дали про себе знати. Нині відтіснити ковен Бейншедова — найголовніше випробування для майбутніх воїнів, розбійників і чаклунів, перш ніж їх визнають готовими вийти в ширший Дуротар."}},fp="19,297,33.554.0,23.490.0,41.117.0,28.118.0,34.127.0,37.216.0"}
P.entries["subzone:camp-narache"] = {n="Табір Нарачі",s="Табір Нарачі — відлюдне селище на Плато Червоної Хмари в південному Малгорі. Це прабатьківська домівка племені Гоквінд і місце випробувань, де молоді таурени починають навчання. Високо над рівнинами табір береже давні традиції й невпинно стереже від зазіхань шипогривів і не зниклої загрози кентаврів.",h="Табір Нарачі — відлюдне селище на Плато Червоної Хмари в південному Малгорі.",kw={"табір нарачі","плато червоної хмари","малгор","таурени","гоквінд","стартова зона","шипогриви"},ang={["class:Shaman"]="Молоді шамани роблять тут найперші кроки духовним шляхом: проходять випробування, щоб здобути свій Тотем Землі й заговорити напряму зі стихіями плато.",["race:Tauren"]="Для тауренів Табір Нарачі — кінець дитинства: священна земля, де ви проходите перші обряди полювання й налаштовуєтеся на духів предків під пильним оком старійшин Гоквіндів."},sec={{t="Серце племені Гоквінд",b="Табір Нарачі, що лежить на північному краю піднесеного Плато Червоної Хмари, — головне поселення племені Гоквінд. Селище складається з кількох великих шкіряних осель і наметів: тут є спільний намет для поранених сміливців, зброярня, пекарський намет і духовний куточок для роздумів і спілкування з предками. У центрі табору колом стоять старійшини племені й наставники шляхів; тут досі дає поради поважна Прамати Гоквінд, скеровуючи щойно посвячену молодь, яка стає на шлях захисників Земної Матері."},{t="Місце випробувань під загрозою",b="Хоч табір природно укріплений стрімкими урвищами плато, спокою Табору Нарачі бракує. Шипогриви Щетиноспинних із Яру Тернистого Клинка невпинно зазіхають на землі Гоквіндів, а віддалік чатують розвідники кентаврів. Молоді мисливці, шамани, друїди й воїни гартуються тут, виполюючи агресивну місцеву живність, захищаючи криницю селища та відбиваючи наскоки шипогривів, перш ніж спуститися великим шляхом у ширші долини Малгору."}},faq={{q="Що таке Табір Нарачі?",a="Табір Нарачі — стартове селище молодих тауренів на вершині Плато Червоної Хмари в південному Малгорі. Це головне стійбище племені Гоквінд, прихисток, де мисливці, воїни, друїди й шамани-початківці опановують своє ремесло, перш ніж вирушити до Села Бладгуф і Тандер Блафа.",al={"що таке табір нарачі","лор нарачі","стартове місто тауренів"}},{q="Хто очолює селище?",a="Вождь Гоквінд веде сміливців племені й керує обороною плато разом із шанованою старійшиною племені, Праматір'ю Гоквінд. Наставники й старійшини племені збираються в центрі табору, щоб навчати молодих шукачів пригод.",al={"хто очолює табір нарачі","вождь табору нарачі","ватажок гоквінд"}},{q="Які загрози чигають на табір?",a="Стійбищу постійно дошкуляють шипогриви Щетиноспинних, що діють із Яру Тернистого Клинка на сході. Окрім здичавілих бойових вепрів і довгоступів, що блукають довколишніми кручами, не зникла небезпека хижих ватаг кентаврів, і це тримає сміливців Гоквіндів у постійній готовності.",al={"вороги табору нарачі","хто нападає на табір нарачі","загрози плато"}},{q="Чи легко мандрівникам залишити плато?",a="Плато Червоної Хмари з усіх боків оточене стрімкими урвищами. Єдиний спуск до великих рівнин Малгору — гірська стежка, що веде на північ під охороною сміливців Гоквіндів, які не дають ворожим звірам і шипогривам влаштовувати засідки на подорожніх.",al={"як залишити плато червоної хмари","вихід із табору нарачі","стежка з плато"}}},fp="12,358,27.590.0,29.487.0,21.318.0,22.237.0,32.285.0,36.250.0"}
P.entries["subzone:chill-breeze-valley"] = {n="Долина Холодного Вітерцю",s="Долина Холодного Вітерцю — суворий засніжений перевал на заході Дун Мороґу, що сполучає дворфське поселення Харанос зі змученим боями містом Гномреґан. Головний її шлях — жвава дорога для молодих мандрівників і біженців, та в її відлюдних закутках чаяться небезпечні звірі й криваві лігва.",h="Долина Холодного Вітерцю — суворий засніжений перевал на заході Дун Мороґу, що сполучає дворфське поселення...",kw={"долина холодного вітерцю","перевал","вендіго","харанос","гномреґан","дун мороґ"},ang={["race:Dwarf"]="Горяни та молоді дворфські мисливці випробовують себе, винищуючи лютих вендіго, які загрожують життєво важливому проходу між центральним Дун Мороґом і західним високогір'ям.",["race:Gnome"]="Для гномських біженців, що тікають від наслідків катастрофи Гномреґану до безпечних Хараноса й Айронфорджа, пережити перехід повз хижаків Долини Холодного Вітерцю — важливий перший крок."},sec={{t="Перехрестя снігу й пазурів",b="Долина Холодного Вітерцю прорізає гори західного Дун Мороґу Т-подібним рівчаком. Головною стежкою зі сходу на захід постійно снують дворфи та гноми-новачки, мандруючи між Хараносом і околицями Гномреґану. Але звернути в північно-південне відгалуження долини — зовсім інша справа. Усіяні плямами крові й понівеченими тушами, ці похмурі закутки ховають лютих хижаків — насамперед диких вендіго, що гніздяться в глибоких крижаних печерах і полюють на кожного, хто необачно забреде в їхні мисливські угіддя."}},fp="19,303,30.543.0,37.192.0,49.302.0,42.178.0"}
P.entries["subzone:cleft"] = {n="Розколина",s="Розколина — темна улоговина на північний захід від Доланаара на Тельдрассилі. Колись тихий куточок гілля, вона дісталася зіпсутим фурболгам-Вузлошкірам, які зробили з неї твердиню для засідок на подорожніх, що йдуть головним шляхом до Дарнасуса.",h="Розколина — темна улоговина на північний захід від Доланаара на Тельдрассилі.",kw={"розколина","фурболги","вузлошкіри","доланаар","дарнасус","засідка","тельдрассил"},ang={["class:Druid"]="Зіпсуті Вузлошкіри загрожують безпеці подорожніх на дорозі до Дарнасуса.",["race:NightElf"]="Розколина — болісна трагедія для нічних ельфів: вони бачать, як їхні давні союзники-фурболги піддаються божевіллю й нападають на подорожніх."},sec={{t="Лігво скверни",b="Розколина осторонь шляху між Доланааром і Дарнасусом стала одним із найнебезпечніших лігв на Світовому Дереві. Збожеволілі від нечистої зарази, що шириться Тельдрассилом, тутешні фурболги-Вузлошкіри укріпили цю улоговину. Із цього редуту знавіснілі звірі тероризують місцеві дороги, загрожуючи відрізати Доланаар від столиці."},{t="Засідки на дорозі",b="Загроза з Розколини стала такою серйозною, що Місячна Жриця Амара та її вартові мусили виставити оборонну варту на дорозі біля її входу. Очищення Розколини конче потрібне Вартовим, щоб убезпечити головну артерію, яка з'єднує селища Тельдрассила з Дарнасусом."}},fp="5,265,19.366.0,21.295.1,18.143.0,23.104.0,38.157.0,44.185.0"}
P.entries["subzone:cold-hearth-manor"] = {n="Маєток Холодного Вогнища",s="Маєток Холодного Вогнища — уражений чумою хутір одразу на захід від Брілла, біля головної дороги Галявин Тірісфалю. Колись жвавий, гостинний маєток, славний щедрими врожаями, він утратив усіх мешканців зі спалахом Чуми Нежиті, а довколишні поля заполонила безтямна Погибель. Сьогодні Відступники убезпечили головний будинок як заставу й перевалочний пункт для подорожніх.",h="Маєток Холодного Вогнища — уражений чумою хутір одразу на захід від Брілла, біля головної дороги Галявин...",kw={"маєток холодного вогнища","хутір","брілл","чума","погибель","застава","тірісфаль"},ang={["faction:Horde"]="Маєток дає надійну точку огляду на дорозі між Бріллом і східними краями Тірісфалю — безпечний перепочинок для подорожніх, що пробираються зачумленою околицею.",["race:Undead"]="Для Відступників повернення таких місць, як Маєток Холодного Вогнища, — гірке нагадування про втрачене смертне життя: колишні людські прихистки обертаються на похмурі оборонні застави проти Погибелі й Багряного Хрестового Походу."},sec={{t="Охололе вогнище",b="До Третьої війни ця садиба славилася теплом і гостинністю, даючи багаті врожаї в серці Лордерона. Коли Чума прокотилася королівством, уся родина та її робітники загинули й повстали знову — порожніми оболонками, прив'язаними до Погибелі. Здичавіла нежить досі шкутильгає зруйнованими полями, та сили Відступників зуміли витіснити безтямних мерців із головного будинку й повернули будівлю, зробивши з неї торговий пост і опору на дорозі до східних галявин."}},fp="17,390,16.513.0,43.236.0,35.230.0,33.229.0,44.297.0"}
P.entries["subzone:coldridge-pass"] = {n="Перевал Холодного Кряжа",s="Перевал Холодного Кряжа — суворий засніжений тунель, пробитий крізь південний гірський хребет Дун Мороґу. Це єдиний сухопутний шлях, що сполучає відлюдні тренувальні угіддя Долини Холодного Хребта з рештою королівства і виходить поблизу гамірного містечка Харанос. Та оскільки прохід захопили ворожі троги, кожному мандрівникові доводиться або пробиватися з боєм, або відчайдушно бігти на той бік.",h="Перевал Холодного Кряжа — суворий засніжений тунель, пробитий крізь південний гірський хребет Дун Мороґу.",kw={"перевал холодного кряжа","тунель","троги","долина холодного хребта","харанос","дун мороґ"},ang={["race:Dwarf"]="Для дворфських горян і новобранців перехід через Перевал Холодного Кряжа означає, що ви залишаєте навчання новачка в Анвілмарі й стаєте на дійсну службу в землях Айронфорджа.",["race:Gnome"]="Гноми-вигнанці, що прагнуть допомогти Альянсу, мусять пробитися крізь цю повну трогів горловину, щоб дістатися Хараноса й гірської дороги на Айронфордж."},sec={{t="Брама з долини",b="Для молодих дворфських новобранців і гномів-новачків, що роблять перші кроки за межі Долини Холодного Хребта, Перевал Холодного Кряжа — суворий обряд посвяти. Висічений просто в скелі, цей тунель — головна ланка, що веде щойно навчених шукачів пригод на схід, до прикордонного осередку Харанос. Колись безпечний гірський коридор перетворився на небезпечну вузьку горловину, кишить лютими трогами, які вилізли з темних підземель і загрожують кожному, хто намагається пройти між захищеною долиною і ширшими просторами Дун Мороґу."}},fp="14,440,29.541.0,31.157.0,39.231.0,41.190.0,33.179.0"}
P.entries["subzone:coldridge-valley"] = {n="Долина Холодного Хребта",s="Долина Холодного Хребта — захищена засніжена долина, схована серед південно-західних височин Дун Мороґу. Її серце — селище Анвілмар, і саме тут молоді дворфи та гномські біженці вперше беруться за зброю на службі Айронфорджу. Єдиний тунель, Перевал Холодного Кряжа, сполучає цю відлюдну улоговину з рештою гірського краю.",h="Долина Холодного Хребта — захищена засніжена долина, схована серед південно-західних височин Дун Мороґу.",kw={"долина холодного хребта","стартова локація","анвілмар","дворфи","гноми","троги","морозогриви"},ang={["race:Dwarf"]="Як споконвічне місце початку шляху для горян і кліриків Бронзбірдів, долина — це перші кроки дворфа від рідного вогнища на службу Високому Престолу.",["race:Gnome"]="Для гномів-вигнанців, змушених залишити Гномреґан, сніги Долини Холодного Хребта — безпечний притулок, де можна опанувати чари й механізми пліч-о-пліч із дворфськими господарями."},sec={{t="Відлюдний полігон",b="Оточена прямовисними гірськими скелями, Долина Холодного Хребта лишається здебільшого відрізаною від жвавих торгових шляхів Дун Мороґу. У її серці стоїть Анвілмар — міцна кам'яна зала й селище, де бувалі дворфські наставники та гноми-вчені, що втратили дім, навчають новобранців мистецтва бою, скритності й чарів. За межами теплих вогнищ Анвілмара дно долини вкрите глибоким снігом, а в ньому нишпорять вепри та голодні зимові вовки — так новачки вперше по-справжньому куштують виживання на порубіжжі."},{t="Вороги насуваються",b="Попри відлюдність, Долині Холодного Хребта безпосередньо загрожують два невтомні вороги. Тутешні тролі Морозогриви розбили табори на кшталт Халупи Морозогривів, нападають на горян і боронять свої прадавні володіння від дворфського наступу. Та ще гірше: дикі троги з племені Кам'янощелепів захопили Перевал Холодного Кряжа — природний тунель, що сполучає долину з Хараносом. Доки цих підземних тварюк не відтіснять, ані мандрівники, ані припаси не зможуть вільно рухатися між долиною та високим престолом Айронфорджа."}},faq={{q="Як вийти з Долини Холодного Хребта?",a="Єдиний сухопутний шлях із долини веде через Перевал Холодного Кряжа — засніжений тунель, пробитий крізь гірський хребет на північний схід. За перевалом дорога прямує на схід, просто до містечка Харанос, а далі — до великої брами Айронфорджа.",al={"вихід із холодного хребта","як вибратися","шлях до хараноса"}},{q="Чому гноми починають тут разом із дворфами?",a="Після трагічного падіння Гномреґану, захопленого трогами й отруєного радіацією, уцілілі гноми втекли до Дун Мороґу як біженці. Король Маґні Бронзбірд прийняв народ Великого Тінкера Меккаторка, тож багато гномських учнів-вигнанців тепер навчаються пліч-о-пліч із молодими дворфами в Анвілмарі.",al={"гноми в долині холодного хребта","чому тут гноми","стартова локація гномів"}},{q="Які загрози турбують долину?",a="Долині загрожують дві головні напасті: ворожі тролі Морозогриви, яким ненависні дворфські поселення на їхніх гірських землях, і грубі троги з племені Кам'янощелепів, що вилізли з надр землі й перекрили Перевал Холодного Кряжа. Тутешні хижаки — вовки та вепри — теж не дають спокою необачним мандрівникам.",al={"вороги холодного хребта","загрози долини","хто нападає"}},{q="Що таке Анвілмар?",a="Анвілмар — центральна фортеця-оселя й поселення Долини Холодного Хребта. Тут розташувалися наставники класів, майстри-ковалі та офіцери місцевих горян, які керують обороною долини й готують щойно загартованих шукачів пригод до великого світу.",al={"містечко анвілмар","що це за містечко тут"}}},fp="16,350,25.508.0,16.522.0,34.256.0,47.293.0,38.283.0,17.249.0"}
P.entries["subzone:crusader-outpost"] = {n="Застава Хрестоносців",s="Застава Хрестоносців — укріплена сторожова вежа на скелястих пагорбах східних Галявин Тірісфалю. Її тримають ревні члени Багряного Хрестового Походу, охороняючи підступи до своєї твердині — Багряного Монастиря. З цієї висоти хрестоносці стежать за рухом на дорозі й готові відбити будь-яке вторгнення Відступників.",h="Застава Хрестоносців — укріплена сторожова вежа на скелястих пагорбах східних Галявин Тірісфалю.",kw={"застава хрестоносців","багряний хрестовий похід","сторожова вежа","багряний монастир","капітан вашон","тірісфаль"},ang={["faction:Horde"]="Східними стежками Тірісфалю треба йти обережно: багряні вартові на цьому пагорбі миттю нападуть на кожного, хто прямує до Монастиря.",["race:Undead"]="Ця сторожова вежа стоїть на самому краю земель Відступників — гірке нагадування, що ревні живі хрестоносці досі тримають суверенні острівці в галявинах."},sec={{t="Очі над Тірісфалем",b="Збудована на кручах над східною дорогою, Застава Хрестоносців — головний пост раннього попередження Багряного Хрестового Походу. З високої вежі вартові стежать за рухом між Бріллом і східними краями Лордерона, щоб мандрівну нежить чи розвідувальні загони помічали задовго до того, як ті дістануться брами Монастиря. Вежа також дає гарнізону змогу вдарити з флангу по будь-якому війську, що спробує піднятися долиною до їхнього святого бастіону."},{t="Скалка в боці Темної Леді",b="Під командуванням багряних офіцерів на кшталт Капітана Вашона тутешній гарнізон зберігає непохитну пильність. Довколишні ліси для них — не суверенна земля Відступників, а неосвячений ґрунт, украдений у людства чудовиськами. Для мандрівників, вірних Андерсіті, застава — повсякчасне місце засідки, де арбалетні болти й очисна сталь чекають на кожного, хто надто наблизиться до круч."}},fp="16,340,18.492.0,31.433.0,29.184.0,26.156.0,41.232.0,31.150.0"}
P.entries["subzone:crusader-s-outpost"] = {n="Застава Хрестоносця",s="Застава Хрестоносця — укріплена розвідувальна вежа Багряного Хрестового Походу в західних Галявинах Тірісфалю. Поруч із нею лежить Хутір Соллідена, а сама вежа — найзахідніша позиція Хрестового Походу в усьому Лордероні. Небезпечна віддаленість від головних багряних бастіонів лишає її гарнізон відрізаним у серці ворожих земель Відступників.",h="Застава Хрестоносця — укріплена розвідувальна вежа Багряного Хрестового Походу в західних Галявинах Тірісфалю.",kw={"застава хрестоносця","багряний хрестовий похід","сторожова вежа","хутір соллідена","похоронний подзвін","тірісфаль"},ang={["faction:Horde"]="Застава — гірке нагадування про фанатичну відмову Багряного Хрестового Походу поступитися Тірісфалем Відступникам та їхнім союзникам з Орди.",["race:Undead"]="Для щойно воскреслих Відступників, що виходять із Похоронного Подзвону, ця сусідня вежа й багряні фанатики, що її стережуть, — безпосередня смертельна загроза просто на їхньому кордоні."},sec={{t="Самотня сторожова вежа",b="Ця кам'яна вежа на західних пагорбах Тірісфалю, одразу на захід від Похоронного Подзвону, — крайня межа влади Багряного Хрестового Походу в Лордероні. Тутешній гарнізон діє разом із уцілілими людськими робітниками сусіднього Хутора Соллідена, намагаючись стримати нежить, що насувається. З вершини вежі дозорці пильнують довколишні гарбузові поля й лісові стежки, остерігаючись і мандрівних почвар Погибелі, і патрулів з Андерсіті."},{t="Відрізані в тилу ворога",b="Утримувати західний кордон украй небезпечно. Відрізані від своїх головних твердинь — Багряного Монастиря й далекої Руки Тіра на сході, — хрестоносці цієї застави не можуть сподіватися на швидке підкріплення, якщо напад проломить частокіл. Будь-яка облога силами Відступників, що збираються по всьому Тірісфалю, означає або втримати вежу самотужки, або бути знищеними дощенту, перш ніж допомога взагалі надійде."}},fp="18,343,19.496.0,27.411.0,68.253.0,58.229.0,66.221.0,47.160.0"}
P.entries["subzone:crystal-lake"] = {n="Кришталеве Озеро",s="Кришталеве Озеро — водойма просто на схід від Ґолдшира, у серці Лісу Елвінн. Колись мирне місце, нині його береги заполонили войовничі мурлоки, перетворивши озеро на постійну небезпеку для місцевих селян і перехожих мандрівників.",h="Кришталеве Озеро — водойма просто на схід від Ґолдшира, у серці Лісу Елвінн.",kw={"кришталеве озеро","озеро","мурлоки","кришталеві водорості","могила","ґолдшир","ліс елвінн"},ang={["faction:Alliance"]="Навала мурлоків так близько до Ґолдшира підкреслює, як тонко розтягнуте військо королівства в охороні його серцевинних земель.",["profession:Herbalism"]="На прісноводних мілинах водяться кришталеві водорості, хоч здебільшого їх забирають просто в тутешніх мурлоків, які збирають їх з озерного дна."},sec={{t="Неспокійний берег",b="Кришталеве Озеро за кілька хвилин ходи від корчми «Лев'яча Гордість» мало б бути ідилічним сільським прихистком, та його дошкуляє небезпечна звірина. Племена прісноводних мурлоків захопили берег і мілководдя й нападають на кожного, хто підійде надто близько. Місцевий алхімік Вільям Пестл часто наймає перехожих шукачів пригод вирушити до води, перемогти створінь і зібрати кришталеві водорості, які ті носять, для його дослідних сумішей."},{t="Мовчазний острів",b="Посеред озера тихо лежить крихітний відлюдний острівець. Самотній і зарослий, він береже просту могилу з ніжним написом: «Глибоко сумуємо, ніколи не забудемо». Хто спочиває під цією землею, у міських книгах не записано, тож серед кумкання прибережних мурлоків лишається сумна таємниця."}},fp="12,248,16.478.0,17.352.0,30.154.0,41.227.0,41.198.0,43.203.0"}
P.entries["subzone:darkspear-strand"] = {n="Побережжя Темного Списа",s="Побережжя Темного Списа — відтинок узбережжя на півдні Дуротару, куди тролів Темного Списа винесло на берег після вигнання з Островів Відлуння. Цей пляж просто поруч із Селом Сен'джин знаменує гіркий початок материкового притулку племені під проводом Вол'джина.",h="Побережжя Темного Списа — відтинок узбережжя на півдні Дуротару, куди тролів Темного Списа винесло на берег...",kw={"побережжя темного списа","пляж","тролі","вигнання","село сен'джин","острови відлуння","дуротар"},ang={["faction:Horde"]="Побережжя позначає південний берег, де Темний Спис закріпився на материку Калімдору поруч зі своїми союзниками-орками після втрати острівного поселення.",["race:Troll"]="Для тролів Темного Списа ступити на цей берег — відчути біль зради Залазана й гірко-солодкий спогад про те, як вони врятувалися живими й заснували Село Сен'джин."},sec={{t="Берег вигнання",b="Коли знахар Залазан збожеволів і захопив владу над Островами Відлуння, уцілілі тролі Темного Списа були змушені залишити свій дім за морем. Зневірені біженці перетнули вузьку протоку й висадилися на цьому вибіленому сонцем узбережжі. Замість розсіятися ворожими червоними пустками Дуротару, вцілілі гуртом збудували Село Сен'джин за кілька кроків від берегової лінії. Нині побережжя лишається тихим нагадуванням про вигнання, дивлячись через прибій на острови, які вони досі сподіваються повернути."}},fp="16,286,16.539.0,34.270.0,43.233.0,52.206.0"}
P.entries["subzone:darnassus"] = {n="Дарнасус",s="Високо серед розлогого гілля Тельдрассила стоїть Дарнасус — столичний прихисток калдорей. Зведений уздовж тихих вод і зелених гаїв, він є духовним серцем нічних ельфів і головним бастіоном Альянсу на півночі Калімдору. Звідси Верховна Жриця Тіранда Віспервінд та Архідруїд Фандрал Стаґгелм ведуть свій народ крізь випробування новознайденої смертності.",h="Високо серед розлогого гілля Тельдрассила стоїть Дарнасус — столичний прихисток калдорей.",kw={"дарнасус","столиця","нічні ельфи","тіранда віспервінд","фандрал стаґгелм","храм місяця","тельдрассил"},ang={["faction:Alliance"]="Для мандрівників зі Східних Королівств Дарнасус — відлюдна, безтурботна гавань, що є неодмінним якорем Альянсу на континенті Калімдор.",["race:NightElf"]="Дарнасус — культурна й політична столиця калдорей, новий початок вашого народу й суверенний прихисток після тяжких жертв Третьої війни."},sec={{t="Прихисток у гіллі",b="Збудований після Третьої війни, Дарнасус був заснований на честь виживання народу нічних ельфів після втрати безсмертя, яке дарувало їхнє священне Світове Дерево Нордрассил. На відміну від щільних кам'яних метрополій Айронфорджа чи Стормвінда, Дарнасус — відкрите, тихе поселення з дерев'яних осель, сяйливих святинь і аркових мостів над кришталевими озерами. Пильні Вартові, велетенські древні війни й друїди, що формують дерева, стережуть стежки, дбаючи, щоб мирна тиша природи зберігалася в межах міста."},{t="Розділений провід",b="Дарнасус утілює єдність калдорей, та його врядування відображає тонкі тріщини. Верховна Жриця Тіранда Віспервінд керує цивільними й військовими справами з осяйного Храму Місяця в оточенні Сестер Елуни. Тим часом справи Кола Кенарія перебувають у віданні Архідруїда Фандрала Стаґгелма, який просував висадження Тельдрассила, щоб повернути ельфам утрачене безсмертя. Поки Малфуріон Стормрейдж спить таємничим сном і Смарагдовий Сон не відпускає його, напориста візія Стаґгелма щодо їхнього майбутнього раз у раз спричиняє тертя з терплячішим жрецтвом."}},fp="9,392,23.569.0,20.599.0,20.268.0,57.227.0,38.291.0,29.213.0"}
P.entries["subzone:deadeye-shore"] = {n="Берег Дедай",s="Берег Дедай — обвіяний вітрами відтинок узбережжя на східному краю Дуротару, просто на схід від Яру Сухої Балки. Названі на згадку про легендарного вождя клану Кривавої Западини Кілроґґа Дедая, ці пустельні піски населяють здебільшого дикі раптори, скорпіди та здичавілі вепри.",h="Берег Дедай — обвіяний вітрами відтинок узбережжя на східному краю Дуротару, просто на схід від Яру Сухої...",kw={"берег дедай","узбережжя","кілроґґ","кривава западина","раптори","скорпіди","дуротар"},ang={["race:Orc"]="Для орків, що будують нову державу в Дуротарі, берег ушановує Кілроґґа Дедая, нагадуючи про старих вождів, які творили історію Орди під час воєн на Азероті."},sec={{t="Берег Кривавої Западини",b="Берег Дедай під червоними кручами центрального Дуротару дістав своє ім'я від Кілроґґа Дедая — одноокого вождя клану Кривавої Западини, що бився в Першій та Другій війнах. Згори пісок і скелясті виступи ледь помітно нагадують обрис черепа з порожньою очницею. Хоч тут немає великих поселень чи військових застав, берег аж ніяк не мирний: на пісках панує войовнича звірина, а потаємні культисти Палаючого Клинка, як відомо, спускаються до води зі своїх сховків у сусідніх ярах."}},fp="13,271,34.569.0,31.205.0,30.263.0,44.243.0"}
P.entries["subzone:deathknell"] = {n="Похоронний Подзвін",s="Похоронний Подзвін — укріплене село у відлюдній долині південно-західних Галявин Тірісфалю. Це головне місце пробудження щойно звільненої нежиті, що виривається з хватки Короля-Ліча, аби приєднатися до Відступників. В облозі безтямних решток Погибелі, місцевих фанатиків і агресивної живності, поселення — суворе місце випробувань для тих, хто претендує на місце в королівстві Сильвани Віндраннер.",h="Похоронний Подзвін — укріплене село у відлюдній долині південно-західних Галявин Тірісфалю.",kw={"похоронний подзвін","стартова зона","відступники","нежить","тірісфаль","багряний хрестовий похід","лощина нічної павутини"},ang={["faction:Horde"]="Хоч відлюдна й темна, ця долина — брама до королівства Відступників, що постачає свіжих вояків для зміцнення плацдарму Орди в Східних Королівствах.",["race:Undead"]="Кожен шукач пригод з-поміж Відступників починає тут: підводиться з холодної землі Тіньової Могили, щоб знайти мету й прихисток під рукою Леді Сильвани після жаху Чуми."},sec={{t="Колиска Відступників",b="Схований за зубчастими пагорбами одразу на північ від кордону Срібнолісся, Похоронний Подзвін — місце, де щойно пробуджені мерці вперше розплющують очі на свою безрадісну дійсність. На відміну від більшості поселень Галявин Тірісфалю, що зберегли людські назви з часів загиблого Королівства Лордерон, Похоронний Подзвін свідомо перейменувала нежить, яка його зайняла. Саме містечко розколоте навпіл: Відступники вперто тримаються південної частини довкола старої церкви, а північна половина — разом із сільською кузнею — лишається заполонена безтямними зомбі Погибелі й здичавілими гулями. Добірні Вартові Смерті надійно тримають вузьку ущелину з долини замкненою від зайд, щоб місцеві доглядачі могли посвячувати новоприбулих у службу Королеві Баньші."},{t="Долина в облозі",b="Вижити в Похоронному Подзвоні нелегко. На північному заході Лощину Нічної Павутини — золоту копальню, життєво важливу для молодого господарства Відступників, — захопили страхітливі павуки. На південному сході войовничий табір Багряного Хрестового Походу невпинно стежить, обмінюється гінцями зі своїми твердинями на сході й промацує оборону долини. Тим часом доглядачі села мусять безперестанку відбивати безтямну нежить, що блукає північними руїнами, і збирати металобрухт, знаряддя й припаси, щоб спорядити щойно воскреслі душі на довгу дорогу."}},faq={{q="Чому містечко перейменували на Похоронний Подзвін?",a="Похоронний Подзвін перейменували після того, як він став поселенням нежиті, — на відміну від більшості громад Тірісфалю, що зберегли людські назви. Причина нової назви невідома.",al={"походження назви похоронний подзвін","чому називається похоронний подзвін","стара назва похоронного подзвону"}},{q="Чому північну половину містечка заполонила нежить?",a="Не кожен труп, піднятий після Третьої війни, вирвався на волю зі здоровим глуздом. Північний майдан села й кузню заполонили «Безтямні» — здичавілі зомбі, гулі й скелети, якими досі рухає залишкова воля Погибелі. Захисники Відступників регулярно вичищають їх, щоб роздобути спорядження й захистити церкву.",al={"чому в похоронному подзвоні зомбі","погибель у похоронному подзвоні","безтямні похоронний подзвін"}},{q="Що робить Багряний Хрестовий Похід біля Похоронного Подзвону?",a="Загін Багряного Хрестового Походу тримає табір у пагорбах на південний схід від села. Фанатично віддані знищенню всієї нежиті без розбору, вони стежать за проходом, нападають із засідки на щойно пробуджених Відступників й обмінюються розвідданими з багряними твердинями в інших куточках Лордерона.",al={"багряний табір похоронний подзвін","хрестоносці біля похоронного подзвону","багряний хрестовий похід долина тірісфалю"}},{q="Чому Відступники не можуть користуватися місцевою золотою копальнею?",a="Лощину Нічної Павутини — золоту копальню в скелях на північний захід від села — цілком заполонили агресивні павуки. Здобувати природні ресурси на кшталт золота вкрай важливо для воєнних зусиль Відступників, та поки навалу не вичищено, поселення не може розробляти жилу.",al={"копальня похоронного подзвону","лощина нічної павутини","павуча копальня тірісфаль"}}},fp="10,405,22.740.0,20.560.0,36.169.0,55.350.0,50.302.0,47.283.0"}
P.entries["subzone:dolanaar"] = {n="Доланаар",s="Доланаар — тихе поселення нічних ельфів у центрально-східному гіллі Тельдрассила. Розташоване на південний захід від Тінедолу, воно стає першим справжнім містечком, яке бачать молоді калдореї, залишивши захищені землі навчання. Тут збираються слідопити, друїди й ремісники, щоб скеровувати новачків і давати раду дивним недугам, що насуваються на Світове Дерево.",h="Доланаар — тихе поселення нічних ельфів у центрально-східному гіллі Тельдрассила.",kw={"доланаар","поселення","нічні ельфи","тельдрассил","перехрестя","навчання"},ang={["class:Druid"]="Доланаар — важлива зупинка для посвячених, які шукають настанов щодо недуг Тельдрассила й учаться налаштовувати свій дух на природну рівновагу.",["race:NightElf"]="Для молодих нічних ельфів Доланаар — перші кроки в ширший світ, випробування їхніх обітниць берегти природу, коли вони бачать, як росте скверна на Світовому Дереві."},sec={{t="Перехрестя гілля",b="Доланаар, що лежить під пишною кроною на південний захід від Тінедолу, — важливе перехрестя для мандрівників Тельдрассила. Збудований у традиційній манері нічних ельфів, він гармонійно вплітає свої оселі й помости в ліс. Селище дає новачкам перше повне навчання в ремеслах, бойовому мистецтві й природних уміннях і стоїть на дорозі до столиці — Дарнасуса. Завдяки центральному розташуванню звістки про зіпсуту живність, агресивних фурболгів і нечистий мох із довколишнього гілля неминуче потрапляють до ради Доланаара."}},fp="8,383,22.588.0,32.257.0,26.158.0,44.137.0,29.176.0"}
P.entries["subzone:drygulch-ravine"] = {n="Яр Сухої Балки",s="Яр Сухої Балки — сувора прихована ущелина серед скелястих круч східного Дуротару. Потрапити сюди можна лише через непримітний печерний прохід із Каньйону Гострого Вітру або небезпечним стрибком згори. У цьому скелястому рові гніздяться гарпії Пилового Вітру, що загрожують сусіднім обозам із припасами.",h="Яр Сухої Балки — сувора прихована ущелина серед скелястих круч східного Дуротару.",kw={"яр сухої балки","ущелина","гарпії","пиловий вітер","припаси","каньйон гострого вітру","дуротар"},ang={["faction:Horde"]="Зачистка гнізд у яру й повернення вкрадених припасів допомагає убезпечити внутрішні торгові шляхи Дуротару від постійного розбою.",["race:Orc"]="Яр Сухої Балки — випробування витривалості на порубіжжі, де молоді орки доводять свою вправність у боротьбі з лютими гарпіями, що засіли на скелястих кручах батьківщини."},sec={{t="Розбійницький прихисток серед червоних скель",b="Глибоко врізаний у скелі на схід від Оргріммара, Яр Сухої Балки майже повністю відрізаний від звичайних мандрівників. Єдиний наземний доступ — тісний природний тунель, що веде з Каньйону Гострого Вітру. У цій захищеній западині, яку живить невелика річка, колись мирно жили орки, та дикі звірі й гарпії Пилового Вітру, які тут гніздяться, перетворили її на беззаконний закуток Дуротару. Крилаті падложерки влаштовують на крутих скелях гнізда для виводків і складають награбоване з обозів Орди, що проходять місцевими стежками."},{t="Скалка в боці Дуротару",b="Життя в Яру Сухої Балки давно хитке. Невдовзі після Третьої війни околицям загрожували громові ящери, що втекли з Громового Хребта, і про це попереджали Вождя Тралла в Оргріммарі. Нині головна небезпека — гарпії. Їхні матріархині люто боронять кладки яєць на високих уступах, тож розвідники Орди часто посилають молодих воїнів прорідити зграю, повернути награбовані торгові ящики й вирвати яр із пазурів гарпій."}},fp="15,284,31.536.0,25.467.0,36.152.0,39.141.0,42.189.0,43.203.0"}
P.entries["subzone:dustwind-cave"] = {n="Печера Пилового Вітру",s="Печера Пилового Вітру — відлюдна западина на вершині скель Каньйону Гострого Вітру, просто на північний схід від Гострого Пагорба. Вона служить діючим тренувальним майданчиком і таємним притулком для посвячуваних лиховісного культу Палаючого Клинка, що діє в Дуротарі.",h="Печера Пилового Вітру — відлюдна западина на вершині скель Каньйону Гострого Вітру, просто на північний схід...",kw={"печера пилового вітру","культисти","палаючий клинок","демонологія","гострий пагорб","каньйон гострого вітру","дуротар"},ang={["class:Warlock"]="Чорнокнижники Орди впізнають темні обряди, що відбуваються в Печері Пилового Вітру, та Палаючий Клинок обертає свої дари Скверни на бунт, а не на службу новому ладу Тралла.",["faction:Horde"]="Печера Пилового Вітру — ганебний і небезпечний внутрішній пролом: тут переховуються культисти демонів за крок від Гострого Пагорба."},sec={{t="Тінь у скелях",b="Печера Пилового Вітру, що височіє над Каньйоном Гострого Вітру, — одна з найближчих і найнебезпечніших загроз Гострому Пагорбу. Багато хто гадає, що демонічні культисти збираються лише в глибоких підземеллях, та тут Палаючий Клинок навчає новобранців просто під носом у влади Орди. Потаємні культисти навчають посвячуваних забороненої темної магії та демонології, готуючи їх підривати молоду орківську державу зсередини кордонів самого Дуротару."},{t="Споганена кров",b="Хто вдереться до печери, ризикує зазнати небезпечного скверніння культистів. Ті, хто практикує всередині, спрямовують мінливі темні мистецтва на кшталт недуг скверної крові, показуючи, як міцно Палаючий Клинок чіпляється за демонічну спадщину, яку Тралл так тяжко боровся вигнати. Знищити тутешню кабалу вкрай важливо, щоб зберегти хиткий мир Дуротару."}},fp="13,245,22.435.0,18.354.0,31.116.0,27.158.0,40.198.0,42.166.0"}
P.entries["subzone:eastvale-logging-camp"] = {n="Лісозаготівельний Табір Східної Долини",s="Лісозаготівельний Табір Східної Долини — важливе лісорубне поселення у східних лісах Лісу Елвінн, поблизу кордону з Горами Редріджу. Табір постачає конче потрібну деревину Стормвінду й навколишнім поселенням, та його роботі невпинно заважають голодні хижаки, що нишпорять довколишніми лісами.",h="Лісозаготівельний Табір Східної Долини — важливе лісорубне поселення у східних лісах Лісу Елвінн, поблизу...",kw={"лісозаготівельний табір східної долини","деревина","лісоруби","стайні","скакуни","вовки","ліс елвінн"},ang={["faction:Alliance"]="Лісозаготівельний Табір Східної Долини — одне з найкращих місць у Лісі Елвінн, де члени Альянсу можуть придбати надійних стормвіндських коней.",["race:Human"]="Для людей Стормвінда Східна Долина дає конче потрібну деревину, яка й далі відбудовує та підтримує поселення королівства."},sec={{t="Важливий промисел в облозі",b="Замовлення на деревину безперервно надходять до Лісозаготівельного Табору Східної Долини від покупців з усього королівства Стормвінд, та вкластися в суворі терміни — справа нелегка. Густі хащі довкола табору кишать лютими вовками й ведмедями, які раз у раз проганяють лісорубів із ділянок, і цінний зрубаний ліс лишається покинутим у хащах. Під керівництвом Наглядачки Рейлен табір часто покладається на мандрівних шукачів пригод, щоб винищити звірину, яка насувається, і забрати повалені колоди, поки доставки не відстали безнадійно."},{t="Життя на східному порубіжжі",b="Попри віддаленість, Східна Долина — більше ніж просто лісорубна застава. Тут є кілька житлових осель і жваві стайні, де мандрівники можуть придбати добрих скакунів. Тутешня торгівля деревиною тісно пов'язана зі знаттю Стормвінда, зокрема з лордом Джораном Тремейндом, чия родина має чималий інтерес у лісозаготівлі табору. На сусідньому пагорбі над ділянкою стоїть тихий маєток відставного Маршала Гаґґарда — колишнього очільника вартових Стормвінда, що перебрався до цієї сільської застави доживати віку подалі від столичної політики."}},fp="21,317,29.561.0,28.585.0,50.232.0,50.259.0,23.203.0,44.137.0"}
P.entries["subzone:echo-isles"] = {n="Острови Відлуння",s="Острови Відлуння — гроно тропічних островів просто біля південно-східного узбережжя Дуротару. Спершу їх заселили тролі Темного Списа, що втекли зі своїх прадавніх островів, та нині архіпелаг втрачено: відступник-знахар Залазан вигнав свій народ темною магією та поневоленими поплічниками.",h="Острови Відлуння — гроно тропічних островів просто біля південно-східного узбережжя Дуротару.",kw={"острови відлуння","залазан","тролі","темний спис","вуду","архіпелаг","дуротар"},ang={["faction:Horde"]="Убезпечити Острови Відлуння вкрай важливо, щоб стабілізувати південне узбережжя Дуротару, захистити Село Сен'джин і зміцнити кордони молодої Орди проти морських загроз і містиків-відступників.",["race:Troll"]="Острови Відлуння — водночас обіцяний дім Темного Списа на Калімдорі й гіркий біль зради Залазана. Повернути їх — справа виживання племені й особистої честі."},sec={{t="Розколотий притулок",b="Після втечі через Велике Море разом із Траллом плем'я Темного Списа обрало Острови Відлуння своїм новим домом. Та їхній мир руйнували знову і знову: спершу флот Великого Адмірала Деліна Праудмура під час вторгнення Кул Тірасу в Дуротар, а потім — зрада зсередини. Невдовзі після того, як тролі відбили флот Праудмура, один з їхніх власних знахарів, Залазан, узявся за темні мистецтва, щоб поневолити розум одноплемінників. Вождь Вол'джин і вільні тролі Темного Списа були змушені знову залишити острови й шукати тимчасового притулку по той бік вузької протоки, у Селі Сен'джин."},{t="Хватка Залазана",b="Нині тропічне гроно заполонили войовничі хижаки, споганена звірина й невільники Залазана. Зловісними насланнями, фетишами вуду та купами джу-джу, розставленими по островах, зрадливий знахар підкорює звірів і полонених тролів своїй волі. Зі свого табору на Побережжі Темного Списа розвідники та воїни Вол'джина часто роблять вилазки на острови, сповнені рішучості забрати рештки полеглих і вбити божевільного містика, що вкрав їхній дім."}},fp="10,320,21.590.0,15.488.0,51.308.0,16.224.0,32.185.0,63.214.0"}
P.entries["subzone:echo-ridge-mine"] = {n="Шахта Ехо-Рідж",s="Шахта Ехо-Рідж — невелика розробка, вирубана в північно-західних скелях Долини Нортширу. Багата на камінь і руду, вона нещодавно потрапила в лапи руйнівної навали кобольдів, що зупинила місцевий промисел Нортширу.",h="Шахта Ехо-Рідж — невелика розробка, вирубана в північно-західних скелях Долини Нортширу.",kw={"шахта ехо-рідж","кобольди","шахта","нортшир","руда","маршал макбрайд","ліс елвінн"},ang={["profession:Mining"]="Штольні Ехо-Ріджу багаті на перші мінеральні поклади, та кожному шукачеві руди спершу доведеться пробитися крізь орди кобольдів зі свічками.",["race:Human"]="Для новобранців, що відгукнулися на поклик Стормвінда, зачистка Шахти Ехо-Рідж — важливе бойове хрещення на захист Абатства Нортшира."},sec={{t="Опора для погані",b="Схована в пагорбах над Абатством Нортшира, Шахта Ехо-Рідж мала постачати долині корисний камінь і метал. Натомість тунелі заполонили спритні кобольди й вигнали місцевих робітників. Маршал Макбрайд вважає цю навалу неприпустимою загрозою безпеці Нортширу та набору новобранців, тож посилає новачків просто в тунелі, щоб прорідити кобольдів і повернути шахту."},{t="Загроза під Нортширом",b="Захоплення Ехо-Ріджу — частина ширшої навали кобольдів, що шириться Лісом Елвінн. Якщо цю підземну погань не стримати на північно-західному хребті, вона загрожує порушити мирні тренувальні угіддя Нортширу й перекрити надходження важливих ресурсів до абатства."}},fp="15,235,21.427.0,29.298.0,35.177.0,41.203.0,33.146.0"}
P.entries["subzone:faol-s-rest"] = {n="Спочинок Фаола",s="Спочинок Фаола — тихе, занедбане поховання у східних Галявинах Тірісфалю, одразу на південний захід від Багряного Монастиря. Його звели як гробницю Архієпископа Алонсуса Фаола — шанованого духовного патріарха, що заснував Лицарів Срібної Длані. Сьогодні, занедбане під ураженою чумою кроною, воно править за цвинтар, де повертаються до життя ті, хто загинув біля монастиря.",h="Спочинок Фаола — тихе, занедбане поховання у східних Галявинах Тірісфалю, одразу на південний захід від...",kw={"спочинок фаола","алонсус фаол","архієпископ","гробниця","срібна рука","багряний монастир","тірісфаль"},ang={["class:Paladin"]="Кожен паладин завдячує своїм покликанням Архієпископу Фаолу, який першим зібрав Утера та його побратимів, щоб поєднати бойове мистецтво зі Святим Світлом. Стояти перед його занедбаною гробницею — тверезе нагадування про витоки ордену.",["class:Priest"]="Як верховний очільник Церкви Святого Світла в Другу війну, Фаол був пастирем усього жрецтва Лордерона; бачити його пам'ятник у руїнах — усе одно що бачити трагічну руїну церкви на півночі."},sec={{t="Гробниця Архієпископа",b="До того як Третя війна спустошила Лордерон, ця відлюдна улоговина була місцем урочистого паломництва. Тут стоїть кам'яна гробниця Архієпископа Алонсуса Фаола, який вів Церкву Святого Світла крізь темні дні Другої війни й заснував орден паладинів, щоб захищати людство. Фаол мирно відійшов до приходу Погибелі, уникнувши смертної муки бачити падіння свого королівства. У ті світліші роки скорботні регулярно йшли дорогою зі столичного міста Лордерона, щоб лишити дари й ушанувати улюбленого патріарха."},{t="Пустка в тіні Монастиря",b="Коли Чума Нежиті прокотилася Лордероном, Тірісфаль усох, а паломники зникли. Сьогодні пам'ятник стоїть покинутий і потрісканий у тінях під високими кручами Багряного Монастиря. Дикі хащі відвоювали стежки, а сама гробниця лежить нерухомо серед вологої імли. Для шукачів пригод, що б'ються з фанатиками Багряного Хрестового Походу чи рештками жахів Тірісфалю, це забуте місце спочинку тепер слугує здебільшого тихим порогом, де полеглі духи ненадовго збираються з силами, перш ніж повернутися в бій."}},fp="11,371,22.547.0,41.541.0,21.325.0,56.301.0,37.280.0,60.263.0"}
P.entries["subzone:fargodeep-mine"] = {n="Копальня Фарґодіп",s="Копальня Фарґодіп — покинута золота копальня в центральному Лісі Елвінн, на південь від Ґолдшира. Колись прибуткове джерело багатства королівства Стормвінд, нещодавно її захопив войовничий клан кобольдів.",h="Копальня Фарґодіп — покинута золота копальня в центральному Лісі Елвінн, на південь від Ґолдшира.",kw={"копальня фарґодіп","кобольди","золото","копальня","золотозуб","ґолдшир","ліс елвінн"},ang={["faction:Alliance"]="Очистити Копальню Фарґодіп від погані вкрай важливо, щоб убезпечити шляхи постачання та ферми в найближчих околицях Ґолдшира.",["profession:Mining"]="Хоч копальня й кишить поганню, скелясті тунелі Фарґодіпу лишаються багатими на доступні мідні жили для шахтарів-початківців."},sec={{t="Втрачена жила",b="Копальня Фарґодіп колись давала сталий потік золота до скарбниці Стормвінда, та через дедалі меншу військову присутність королівства в Елвінні віддалені ресурси лишилися беззахисними. Кобольди швидко заполонили темні тунелі й облаштували під пагорбами гамірне кубло. Маршал Дуґан і місцева влада Ґолдшира дивляться на навалу з глибокою тривогою — не лише через втрачену руду, а й тому, що знахабнілі створіння тепер загрожують сусіднім садибам на кшталт володінь Стоунфілдів і Маклюрів."},{t="Глибини кубла",b="Копальня має кілька рівнів, а нижні штольні звиваються глибоко під лісовим ґрунтом. Кобольди-робітники та погань снують дерев'яними риштуваннями, люто боронячи свій зібраний віск і золотий пил. Глибше чаїться Золотозуб — особливо хитрий ватажок кобольдів, відомий тим, що збирає дрібнички, поцуплені в необачних мандрівників і навколишніх мешканців."}},fp="14,222,11.492.0,20.361.0,41.252.0,55.222.0,17.171.0,52.251.0"}
P.entries["subzone:fel-rock"] = {n="Скеля Скверни",s="Скеля Скверни — уражена печера, схована в лісі одразу на північ від Доланаара на гіллі Тельдрассила. Колись тиха улоговина, вона занепала під впливом сатира Лорда Меленаса та його орди лютих ґреллів.",h="Скеля Скверни — уражена печера, схована в лісі одразу на північ від Доланаара на гіллі Тельдрассила.",kw={"скеля скверни","печера","сатир","лорд меленас","ґрелли","доланаар","тельдрассил"},ang={["class:Druid"]="Друїди Кола Кенарія бачать у Скелі Скверни гнійну рану на молодому Світовому Дереві, яку треба негайно вичистити, поки демонічна скверна не поширилася.",["race:NightElf"]="Для калдореїв присутність такого сатира, як Лорд Меленас, так близько до Доланаара — тривожна образа Тельдрассилу, що вимагає швидкої відплати."},sec={{t="Лігво скверни",b="Скеля Скверни в лісистих пагорбах на північ від Доланаара колись була звичайною мирною печерою, вирізьбленою в дереві й камені Тельдрассила. Сьогодні це тривожне нагадування про заразу, що підкрадається до Світового Дерева. Покручене коріння й неприродні тіні панують у нутрі печери, яку заполонили рої диких ґреллів і ґреллят."},{t="Твердиня сатира",b="Скверна в Скелі Скверни походить від Лорда Меленаса — лихого сатира, що зробив улоговину своєю твердинею. З глибини печери він керує поширенням злої зарази просто під пильним оком вартових нічних ельфів. Друїди з Доланаара, насамперед Таллонкай Свіфтрут, активно залучають здібних захисників очистити печеру й убити Меленаса, перш ніж його нечиста пошесть пошириться далі в довколишні ліси."}},fp="8,238,19.354.0,16.468.0,26.110.0,19.133.0,40.244.0,39.111.0"}
P.entries["subzone:forest-s-edge"] = {n="Узлісся",s="Узлісся — лісистий клин землі на південно-західному порубіжжі Лісу Елвінн, обабіч якого течуть річки в бік Вестфолу. З півночі його прикриває Гарнізон Вестбрук, та ці дикі землі небезпечно заполонили гноли Річколапи під проводом горезвісного Гоґґера.",h="Узлісся — лісистий клин землі на південно-західному порубіжжі Лісу Елвінн, обабіч якого течуть річки в бік...",kw={"узлісся","гоґґер","гноли","річколапи","вестфол","гарнізон вестбрук","ліс елвінн"},ang={["faction:Alliance"]="Для новобранців, розквартированих у Лісі Елвінн, зачистка Узлісся й перемога над Гоґґером — одне з перших великих випробувань, що доводять короні їхню бойову готовність.",["profession:Herbalism"]="Тихі береги й тінисті гаї Узлісся дають звичайні лісові трави, та збирати їх часто доводиться, ухиляючись від войовничих патрулів гнолів."},sec={{t="Спірне порубіжжя",b="Узлісся на південний захід від Стормвінда, між Садом Дзеркального Озера та річками на кордоні з Вестфолом, утворює природний лісистий півострів. Попри близькість Гарнізону Вестбрук, рідкі лави армії Стормвінда лишили цей край беззахисним перед дикими звірами й загонами нападників. Серед дерев і вздовж берегів блукають вепри, та справжня загроза — скупчення гнолів Річколапів, які зробили ці ліси своїм плацдармом."},{t="Твердиня Гоґґера",b="Ліси Узлісся — мисливські угіддя Гоґґера, величезного й жорстокого ватажка гнолів. Армія Стормвінда призначила за його голову чималу винагороду, а Гоґґер тим часом керує своєю зграєю, яка нападає на мандрівників і грабує сусідні ферми, перетворюючи те, що могло б бути мирним лісом, на смертельний полігон для молодих шукачів пригод Альянсу."}},fp="13,287,20.464.0,19.341.0,31.181.0,30.221.0,14.212.0,47.232.0"}
P.entries["subzone:frostmane-hold"] = {n="Твердиня Морозогривів",s="Твердиня Морозогривів — укріплений табір і печерний комплекс, який крижані тролі Морозогриви захопили на заході Дун Мороґу. Схована серед скель на південь від Гномреґану, вона є головним плацдармом тролів-нападників, що насуваються на дворфські землі. Вартові Айронфорджа пильно стежать за твердинею, щоб оцінити зростання тролячої загрози.",h="Твердиня Морозогривів — укріплений табір і печерний комплекс, який крижані тролі Морозогриви захопили на...",kw={"твердиня морозогривів","тролі","морозогриви","печери","дун мороґ","набіги"},ang={["race:Dwarf"]="Морозогриви століттями змагаються за Дун Мороґ, і зачистка Твердині Морозогривів — обряд посвяти для горян, які прагнуть убезпечити засніжене серце земель Айронфорджа.",["race:Gnome"]="Розташована просто на південь від Гномреґану, твердиня — ще один небезпечний ворожий фронт на кордоні з колишньою гномською столицею, що й досі потерпає від боїв."},sec={{t="Троляча твердиня серед снігів",b="Вирубана в морозних скелях західного Дун Мороґу, Твердиня Морозогривів складається з грубих споруд просто неба та звивистої системи печер. Для племені Морозогривів це головний оплот, який густо охороняють шкуродери та мисливці за головами. Звідси тролі влаштовують набіги на навколишні долини, випробовуючи оборону поселень на кшталт Хараноса й загрожуючи мандрівникам на гірських перевалах."},{t="Скалка в боці Хараноса",b="Що більше наростає напруга в Дун Мороґу, то дужче дворфських командирів у Хараносі непокоїть розмах скупчення Морозогривів. Молодих горян і шукачів пригод раз у раз посилають розвідати внутрішні печери, скласти карту оборони та винищити бойові загони, перш ніж плем'я зможе зібратися на злагоджений наступ проти дворфських застав."}},fp="14,338,28.417.0,25.349.0,28.164.0,32.122.0,44.207.0,35.189.0"}
P.entries["subzone:frostmane-hovel"] = {n="Халупа Морозогривів",s="Халупа Морозогривів — суворе печерне лігво, сховане серед південних скель Долини Холодного Хребта в Дун Мороґу. Воно служить укріпленим притулком для войовничих тролів Морозогривів, які напирають просто на дворфські тренувальні угіддя.",h="Халупа Морозогривів — суворе печерне лігво, сховане серед південних скель Долини Холодного Хребта в Дун...",kw={"халупа морозогривів","печера","тролі","морозогриви","долина холодного хребта","дун мороґ"},ang={["faction:Alliance"]="Невідступна присутність Морозогривів просто під Анвілмаром показує: навіть серцю земель Айронфорджа доводиться повсякчас боронитися від місцевих супротивників.",["race:Dwarf"]="Для молодих новобранців Бронзбірдів, що навчаються в Долині Холодного Хребта, захист околиць від ворожого племені Морозогривів у таких печерах — обов'язковий обряд посвяти."},sec={{t="Троляче лігво в долині",b="Вирубана в південних горах, що обступають Долину Холодного Хребта, Халупа Морозогривів дає прихисток тутешнім тролям Морозогривам, які відмовляються поступитися високими снігами Айронфорджу. З грубих печер, як-от ця, тролі влаштовують безперервні набіги на місцеві дворфські табори й перерізають шляхи постачання в долину."}},fp="15,218,25.313.0,28.167.0,41.227.0,23.139.0"}
P.entries["subzone:gallows-end-tavern"] = {n="Таверна «Шибеничний Кінець»",s="Таверна «Шибеничний Кінець» — головна корчма Брілла й серце гостинності Відступників в Галявинах Тірісфалю. Окрім притулку й трунків для втомлених подорожніх, вона править за важливий осередок наставників класів, учителів ремесел і таємних допитів.",h="Таверна «Шибеничний Кінець» — головна корчма Брілла й серце гостинності Відступників в Галявинах Тірісфалю.",kw={"таверна шибеничний кінець","корчма","брілл","відступники","наставники","полонені","підвал"},ang={["faction:Alliance"]="Під підлогою пивниці Відступники тримають полонених розвідників Альянсу й фанатиків Багряного Хрестового Походу — для відомостей і допитів.",["race:Undead"]="Перша велика корчма за межами Похоронного Подзвону, Таверна «Шибеничний Кінець» — культурне й практичне перехрестя для щойно пробуджених Відступників, що виходять у широкий світ."},sec={{t="Місце зібрань мертвих",b="Таверна «Шибеничний Кінець», що стоїть на видноті біля дороги в Бріллі, — головне місце зібрань щойно пробуджених Відступників, які залишають Похоронний Подзвін і прямують на південь, до Андерсіті. Попри своє нежиття, Відступники й далі навідуються до її зал заради товариства, торгівлі й прихистку. У корчмі мешкають наставники різних класів — вони навчають молодих воїнів, жерців, магів, розбійників і чорнокнижників, — а також крамарі й лікарі."},{t="Таємниці в підвалі",b="Під рипучими мостинами й тавернячим сміхом криється куди похмуріше призначення. У підвалах Відступники тримають зв'язаних військовополонених під вартою, подалі від сторонніх очей. Серед них — полонений Багряний Фанатик і дворфійський гірський стрілець, яких тримають під таверною для допитів і дослідів, поки Відступники борються за свої кордони і з ревними хрестоносцями, і з розвідниками Альянсу."}},fp="19,258,30.446.0,21.405.0,41.114.0,40.248.0,34.165.0,45.170.0"}
P.entries["subzone:garren-s-haunt"] = {n="Лігво Гаррена",s="Лігво Гаррена — покинутий хутір у північних Галявинах Тірісфалю. Колись квітуча людська садиба, ферма занепала, коли Погибель винищила родину Гарренів, і зарослі землі заполонили здичавілі гнилошкірі гноли.",h="Лігво Гаррена — покинутий хутір у північних Галявинах Тірісфалю.",kw={"лігво гаррена","хутір","гноли","гнилошкури","червиве око","погибель","тірісфаль"},ang={["race:Undead"]="Зруйнована ферма — суворе нагадування про різанину, що породила Відступників, а зачистка гидких гнилошкірих гнолів допомагає убезпечити північний Тірісфаль для Темної Леді."},sec={{t="Уражена чумою садиба",b="До Третьої війни цей хутір годував родину й давав щедрі врожаї під владою Королівства Лордерон. Коли Чума Нежиті прокотилася околицями, Погибель упала на ферму й вирізала Гаррена з усім родом. Сьогодні поля лежать сірі й усохлі, а будинок і клуня трухлявіють у вічному мороці Тірісфалю."},{t="Гнилошкірі загарбники",b="Замість звичайних патрулів Погибелі Лігво Гаррена захопили гнилошкірі гноли — зграя заражених нежиттю падложерів на чолі з лютим Червивим Оком. Ці падложери запекло боронять відвойовану територію, обдирають рештки ферми й роздирають усіх подорожніх та патрулі Відступників, що проходять північним Тірісфалем."}},fp="14,244,20.360.0,22.348.0,15.228.0,35.177.0,32.199.0,38.254.0"}
P.entries["subzone:gnomeregan"] = {n="Гномреґан",s="Гномреґан був величною підземною столицею гномського народу, що славилася по всьому Азероту механічним генієм і технологічними дивами. Нині це радіоактивна гробниця, захоплена підземними трогами, знавіснілими захисними автоматами й божевільними прокаженими гномами після того, як відчайдушна оборона скінчилася катастрофою.",h="Гномреґан був величною підземною столицею гномського народу, що славилася по всьому Азероту механічним генієм...",kw={"гномреґан","гноми","радіація","троги","термаплаґґ","меккаторк","дун мороґ"},ang={["profession:Engineering"]="Навіть задушений радіоактивною отрутою, Гномреґан лишається найбільшим зібранням схем, передових запчастин і справних промислових машин у Східних Королівствах.",["race:Gnome"]="Кожен гном носить у собі травму втрати Гномреґану. Увійти в опромінені зали — скорботне паломництво, щоб знищити узурпатора Термаплаґґа й повернути втрачені механічні реліквії."},sec={{t="Диво інженерії",b="Вирубаний у засніжених скелях західного Дун Мороґу, Гномреґан був збудований століття тому з допомогою дворфів Айронфорджа. Усередині масивні парові шестерні, хитромудрі мідні трубопроводи та величезні складальні зали утворювали інтелектуальне й промислове серце гномського роду. Саме з цих підземних зал гномські винаходи, літальні машини та складне озброєння постачалися Альянсу впродовж Другої війни, а місто вистояло навіть під облогою Орди Орґріма Думгаммера."},{t="Падіння й отруєні зали",b="Під час Третьої війни з глибин землі вирвалася підземна навала трогів і прорвалася в найнижчі покої міста. Не бажаючи відволікати армії Альянсу від різанини в Лордероні, Верховний Механік Ґелбін Меккаторк спробував упоратися з кризою сам. За порадою свого головного інженера Сікко Термаплаґґа Меккаторк наказав пустити радіоактивний газ у нижні покої, щоб винищити дикунів. План обернувся жахом: газ лише посилив багатьох трогів, а вбив майже вісімдесят відсотків гномського населення. Ті, хто зазнав опромінення й не загинув, мутували в спотворених прокажених гномів, а Термаплаґґ захопив владу над отруєними руїнами."}},fp="10,327,23.491.0,31.662.0,36.338.0,39.260.0,28.256.0,65.251.0"}
P.entries["subzone:gol-bolar-quarry"] = {n="Кар'єр Гол'Болар",s="Кар'єр Гол'Болар — дворфські розробки, вирубані в засніжених пагорбах південно-східного Дун Мороґу. Багатий на камінь і руду, цей колись жвавий промисел зупинився, коли його захопили люті троги, що ринули з глибин.",h="Кар'єр Гол'Болар — дворфські розробки, вирубані в засніжених пагорбах південно-східного Дун Мороґу.",kw={"кар'єр гол'болар","троги","видобуток","камінь","руда","дун мороґ","шукач ґен"},ang={["profession:Mining"]="Відкриті скельні уступи й сусідні тунелі багаті на мінеральні жили, та щоб дістатися до них, шукачам доведеться пробиватися крізь троги, що міцно тут окопалися.",["race:Dwarf"]="Зачистка Кар'єру Гол'Болар — справа і господарської потреби, і кланової гордості: Айронфордж не може дозволити грубим трогам прибрати до рук багатства його гір."},sec={{t="Кар'єр в облозі",b="Кар'єр Гол'Болар на південний схід від Хараноса заклали дворфи Айронфорджа, щоб добувати з гір цінний камінь і мінеральні багатства. Та глибокі розкопки відкрили підземні нори й випустили на волю орду ворожих трогів, які швидко вигнали шахтарів. Нині верхній табір став осадженим плацдармом, де наглядачі, ремісники та Шукач Ґен збирають дворфських і гномських новобранців, щоб відтіснити тварюк і повернути кар'єр."}},fp="16,238,20.470.0,25.217.0,34.226.0,23.195.0"}
P.entries["subzone:gol-bolar-quarry-mine"] = {n="Шахта Кар'єру Гол'Болар",s="Шахта Кар'єру Гол'Болар — захоплена розробка в самому серці Кар'єру Гол'Болар на сході Дун Мороґу. Дворфські шахтарі, що колись тут працювали, пробили тунелі в підземні печери трогів і випустили на волю шалену навалу, яка поглинула всю ділянку. Нині найглибші штольні служать оплотом бойовому загону трогів на чолі зі звірюкою Молотохребтом.",h="Шахта Кар'єру Гол'Болар — захоплена розробка в самому серці Кар'єру Гол'Болар на сході Дун Мороґу.",kw={"шахта кар'єру гол'болар","молотохребет","троги","шахта","тунелі","дун мороґ"},ang={["profession:Mining"]="Суворе нагадування про небезпеки підземних розробок: ця шахта лишатиметься повністю перекритою ворожими трогами, доки не буде зачищено її найглибші тунелі.",["race:Dwarf"]="Кожен удар кайла в гору може розбудити те, що спить унизу. Повернути Шахту Гол'Болар — справа і господарської потреби, і дворфської гордості."},sec={{t="Пролом у глибині",b="Шахту заклали дворфи Айронфорджа, що шукали камінь і багаті поклади руди під скелястими вершинами Дун Мороґу. Робота обірвалася раптово й криваво, коли кайла проламали стіну в прадавню систему підземних печер, де жили троги. Хлинувши з темряви, підземні тварюки зім'яли робочі бригади й змусили їх поспіхом відступити, а зрештою вихлюпнулися назовні й захопили ще й навколишній кар'єр."},{t="Лігво Молотохребта",b="Поки молодші, слабші троги блукають освітленими сонцем терасами кар'єру, у самій шахті засіли найлютіші бійці загону. Глибоко в тісних тунелях, освітлених смолоскипами, чаїться їхній жорстокий ватажок Молотохребет. Повернути цінний кар'єр — нагальна потреба для місцевих горян, та щоб викорінити навалу, доведеться спуститися в найчорніші глибини шахти й знищити тварюк біля самого їхнього джерела."}},fp="21,366,20.435.0,19.432.0,31.222.0,50.145.0,50.192.0,27.181.0"}
P.entries["subzone:golden-plains"] = {n="Золоті Рівнини",s="Золоті Рівнини — просторе, залите сонцем пониззя, що простягається на південний схід від Тандер Блафа в центральному Малгорі. Таурени плекають ці розлогі пасовища як найкращі мисливські угіддя та життєво важливе пасовисько для мандрівних стад кодо.",h="Золоті Рівнини — просторе, залите сонцем пониззя, що простягається на південний схід від Тандер Блафа в...",kw={"золоті рівнини","кодо","арра'чеа","полювання","малгор","тандер блаф"},ang={["class:Hunter"]="Безкраї простори й мандрівні стада кодо роблять ці рівнини чудовим полігоном для слідопитів, що шукають легендарних звірів на кшталт Арра'чеа.",["race:Tauren"]="Для тауренів Золоті Рівнини — незмінний символ щедрості батьківщини, священні мисливські угіддя в тіні Тандер Блафа."},sec={{t="Серце полювання",b="Розкинувшись під високими плато Тандер Блафа, Золоті Рівнини — неприборкане серце Малгору. Мінливе море золотавої й зеленої трави дає щедрий прихисток місцевій живності, тож це одні з найцінніших традиційних мисливських угідь кочових тауренів. Хвилястим пониззям бродять великі стада кодо, а мисливці переповідають історії про легендарну здобич — насамперед про великого кодо Арра'чеа, що тихо мандрує серед високих стебел."}},fp="13,248,17.476.0,27.198.0,36.204.0,41.199.0"}
P.entries["subzone:goldshire"] = {n="Ґолдшир",s="Ґолдшир — важливе людське містечко на перехресті в центральному Лісі Елвінн, що сполучає Стормвінд із Вестфолом, Редріджем і південним порубіжжям. Відбудоване після знищення в Першій війні, нині це гамірна проміжна станція, серце якої — славетна корчма «Лев'яча Гордість», а захист — украй виснажений загін вартових Стормвінда.",h="Ґолдшир — важливе людське містечко на перехресті в центральному Лісі Елвінн, що сполучає Стормвінд із...",kw={"ґолдшир","містечко","перехрестя","лев'яча гордість","маршал дуґан","перша війна","ліс елвінн"},ang={["faction:Alliance"]="Ґолдшир — важливий транзитний вузол, що сполучає столицю Альянсу з навколишнім порубіжжям Вестфолу, Редріджу й Сутінколісся.",["race:Human"]="Для людей, що щойно вийшли з Абатства Нортшира, Ґолдшир — перший справжній смак королівства за стінами монастиря і протверезний погляд на напружені кордони Стормвінда."},sec={{t="Перехрестя під напругою",b="Ґолдшир, що стоїть там, де сходяться королівські шляхи, здавна був громадським і торговим серцем сільського Елвінну. Та за сільським чаром містечка ховається дедалі більша небезпека 25 року від відкриття Темного Порталу. Військові сили Стормвінда розтягнуті до краю, Король Варіан Рінн загадково зник, і Маршал Дуґан мусить покладатися на перехожих шукачів пригод, а не на регулярні війська, щоб стримувати довколишні загрози. Войовничі гноли Річколапи напирають із західного кордону, а люті мурлоки захопили береги Озера Кам'яного Кургану та Кришталевого Озера, відбираючи життя королівських вартових і підступаючи небезпечно близько до центру містечка."},{t="Шрами великих воєн",b="За тихою атмосферою Ґолдшира ховається жорстока військова історія. Близько 75 року до відкриття Темного Порталу поселення відбивало люті штурми під час війни з гнолами. Десятиліття по тому, у Першій війні, Ґолдшир і Мунбрук стали останніми твердинями, які зім'яла Орда орків, коли Вождь Блекхенд відрізав Короля Ллейна Рінна I від його королівства, перш ніж сплюндрувати Фортецю Стормвінда. Містечко обернулося на попіл і стояло пусткою аж до кінця Другої війни, коли Альянс Лордерону під проводом Верховного Командувача Туралйона профінансував і організував його відбудову, щоб повернути людських біженців на південь."}},fp="9,343,25.618.0,23.574.0,40.247.0,45.284.0,48.250.0,39.271.0"}
P.entries["subzone:grizzled-den"] = {n="Сиве Лігво",s="Сиве Лігво — печера серед засніжених пагорбів на південний захід від Хараноса. Вона відома як лігво лютих вендіго з крижаним подихом, що водяться в Дун Мороґу.",h="Сиве Лігво — печера серед засніжених пагорбів на південний захід від Хараноса.",kw={"сиве лігво","вендіго","печера","харанос","мідь","дун мороґ"},ang={["profession:Mining"]="У зовнішніх і внутрішніх тунелях лігва є відкриті поклади міді, тож це непогане місце для перших розробок — якщо зумієте відбитися від вендіго.",["race:Dwarf"]="Зачистка Сивого Лігва — майже обряд посвяти для молодих дворфських горян, що навчаються довкола Хараноса."},sec={{t="Морозне лігво",b="Вирубане глибоко в скелях на південний захід від Хараноса, Сиве Лігво відоме серед місцевих горян як місце, де гніздяться зграї вендіго Дун Мороґу. Ці люті мавпоподібні звірі обдають непроханих гостей крижаним подихом і гуртуються, щоб боронити свої нори. Попри небезпеку, відважні мисливці часто спускаються в глибини печери по густі гриви вендіго, за які добре платять ремісники, що оббивають теплим хутром холодні крісла та сидіння карет."},{t="Приховані скарби",b="Окрім грізних мешканців, звивисті тунелі Сивого Лігва ваблять шукачів природних багатств. Старателі часто заходять далі за вхід, щоб відбити мідь із жил, які випинаються з промерзлих кам'яних стін, а заповзятливі розвідники нишпорять темними закутками в пошуках покинутих скринь. Та варто заглибитися в дальні закутки — і ви неодмінно зіткнетеся з найбільшими й найлютішими хижаками лігва, що чаяться в тінях."}},fp="12,183,20.488.0,16.464.0,34.113.0,40.158.0,44.225.0"}
P.entries["subzone:gunther-s-retreat"] = {n="Притулок Ґунтера",s="Притулок Ґунтера — відлюдне острівне святилище посеред Озера Світлої Води в центральних Галявинах Тірісфалю. Це сховок Ґунтера Аркануса — некроманта-відступника, що вирвався з-під влади Погибелі самою лише силою волі. Недовірливий до всіх чужинців, самітник оточив свій табір вірними поплічниками-нежиттю, щоб тримати зайд на відстані.",h="Притулок Ґунтера — відлюдне острівне святилище посеред Озера Світлої Води в центральних Галявинах Тірісфалю.",kw={"притулок ґунтера","ґунтер арканус","острів","озеро світлої води","некромант","король-ліч","тірісфаль"},ang={["class:Mage"]="Чародії оцінять рідкісний подвиг Ґунтера: його магічна воля виявилася досить грізною, щоб цілком самотужки розірвати ментальну хватку Короля-Ліча.",["race:Undead"]="Ґунтер Арканус віддзеркалює трагедію самих Відступників: вільний від Короля-Ліча, та підозріливий і насторожений до світу, який, як він гадає, досі в рабстві Погибелі."},sec={{t="Самітник на Озері Світлої Води",b="Притулок Ґунтера посеред імлистих вод Озера Світлої Води — непримітний острівний табір, який легко сплутати з іще одним гніздом Погибелі. Його господар, Ґунтер Арканус, досяг того, що вдавалося небагатьом смертним чаклунам: піднятий нежиттю, він завдяки своїй таємній майстерності вирвав власну душу із залізної хватки Короля-Ліча без жодної сторонньої допомоги. Нікому не довіряючи, Ґунтер вирішив, що решта нежиті, яка блукає Лордероном, досі маріонетки Погибелі. Він усамітнився на цьому безлюдному острові, щоб у спокої вправлятися у своєму ремеслі, і виставив вартових-зомбі роздирати кожного, хто перетне воду."}},fp="17,338,29.608.0,31.204.0,41.230.0,37.249.0,49.191.0"}
P.entries["subzone:hall-of-arms-northshire"] = {n="Зала Зброї (Нортшир)",s="Зала Зброї — військове крило Абатства Нортшира, на південь від Головної Зали. Тут бувалі наставники муштрують найновіших новобранців армії Стормвінда в мистецтві меча, щита та святого бою.",h="Зала Зброї — військове крило Абатства Нортшира, на південь від Головної Зали.",kw={"зала зброї","абатство нортшира","воїни","паладини","муштра","новобранці","нортшир"},ang={["class:Paladin"]="Зала Зброї поєднує святу відданість із військовим гартом, даючи паладинам-початківцям основи володіння Світлом поруч із бойовою зброєю.",["class:Warrior"]="Для воїнів з людей, що стають на службу, саме в цьому крилі ви отримуєте найперші уроки стійки, володіння зброєю та військової дисципліни армії Стормвінда."},sec={{t="Основа варти",b="Поки клірики та вчені гортають давні фоліанти по той бік двору, у Бібліотечному Крилі, Зала Зброї дзвенить брязкотом затупленої сталі та важким ритмом військової муштри. Розташована з південного боку Абатства Нортшира, ця зала — головне місце підготовки необтесаних бійців з людей і побожних прагнучих, що беруться за зброю заради армії Стормвінда. Тут загартовані бойові наставники й паладини-ментори навчають основних стійок, дисципліни та засад, потрібних, щоб боронити Ліс Елвінн від кобольдів, розбійників Дефіас і гнолів-нападників, що насуваються."}},fp="25,215,23.586.0,40.248.0,34.184.0,58.171.0"}
P.entries["subzone:helm-s-bed-lake"] = {n="Озеро Ложа Гелма",s="Озеро Ложа Гелма — замерзла водойма серед південно-східних пагорбів Дун Мороґу. Доглянута ополонка в товстій кризі дає місцевим горянам і мандрівникам украй потрібну прісну воду. Та береги стали небезпечними через хижу звірину, трогів, що насуваються, і ворожих лазутчиків Темного Заліза.",h="Озеро Ложа Гелма — замерзла водойма серед південно-східних пагорбів Дун Мороґу.",kw={"озеро ложа гелма","крига","ополонка","темне залізо","троги","дун мороґ"},ang={["faction:Alliance"]="Розвідники Альянсу, що прямують на схід до Лох Модану, мають тут бути насторожі: південна стежка проходить неприємно близько до засідок Темного Заліза.",["race:Dwarf"]="Для дворфів Айронфорджа Озеро Ложа Гелма — водночас і важливе джерело прісної води, і прикрий провал у безпеці, бо диверсанти Темного Заліза й троги просуваються дедалі глибше в серце Дун Мороґу."},sec={{t="Підступний берег",b="Озеро Ложа Гелма тихо лежить під товстим шаром зимової криги на південному сході Дун Мороґу. Місцеві дворфи підтримують прорубану в кризі ополонку, щоб черпати чисту прісну воду. Переходити замерзле плесо досить безпечно, а от затримуватися біля берегів стає дедалі ризикованіше. Узліссям блукають дикі звірі, по хребтах нишпорять зігнані з місця троги, а осередок ворожих дворфів Темного Заліза захопив покинуту оселю просто на південь від води і люто нападає з засідки на кожного, хто проходить повз."}},fp="15,328,23.514.0,59.157.0,41.227.0,18.193.0,56.188.0"}
P.entries["subzone:heroes-vigil"] = {n="Дозор Героїв",s="Дозор Героїв — тиха священна галявина на центральному острові Озера Кам'яного Кургану на сході Лісу Елвінн. Її серце — пам'ятник, відомий як Камінь Пам'яті, присвячений полеглим у Першій війні. Та нині святиня здебільшого занедбана Стормвіндом і захоплена небезпечними чародіями-відступниками.",h="Дозор Героїв — тиха священна галявина на центральному острові Озера Кам'яного Кургану на сході Лісу Елвінн.",kw={"дозор героїв","меморіал","камінь пам'яті","перша війна","чародії-відступники","озеро кам'яного кургану","ліс елвінн"},ang={["class:Mage"]="Чародії-відступники, що отаборилися на цій священній землі, практикують небезпечні, неконтрольовані мистецтва без дисципліни й дозволу Академії Таємних Наук.",["race:Human"]="Для людей Стормвінда це священне кам'яне коло — гірке нагадування про криваву ціну Першої війни й про нинішню нездатність королівства захистити власну спадщину."},sec={{t="Забутий меморіал",b="Зведений після Першої війни, Дозор Героїв зосереджений довкола Каменя Пам'яті — кам'яного кола з написами на честь солдатів і городян, убитих, коли Стара Орда плюндрувала Ґолдшир і навколишні долини. Колись шанований як священний оплот віри й жертовності, дозор поступово випав з уваги нинішніх правителів Стормвінда, і його освячена земля заросла й лишилася без нагляду солдатів королівства."},{t="Захоплений відступниками",b="Оскільки королівство не поставило на острові жодного гарнізону, меморіал захопили вигнанці. Кабала чародіїв-відступників нині контролює Озеро Кам'яного Кургану й територію пам'ятника, практикуючи дику, недисципліновану магію подалі від нагляду Кірін-Тору та Академії Таємних Наук. Осквернення стає ще гіркішим через трагічні жертви біля каменів — зокрема тіло Гензе Фолка, — і мандрівникам лишається гадати, чи повернеться колись до святині спокій."}},fp="13,356,20.458.0,20.488.0,22.195.0,47.190.0,33.201.0,38.225.0,19.180.0"}
P.entries["subzone:hidden-path"] = {n="Прихована Стежка",s="Прихована Стежка — відлюдна гірська стежина, що в'ється скелями над Долиною Випробувань у Дуротарі. Для майбутніх шаманів, що шукають священний Камінь Духів, це обряд посвяти, а ще звідси відкривається непомічений краєвид на суворі кордони Пусток.",h="Прихована Стежка — відлюдна гірська стежина, що в'ється скелями над Долиною Випробувань у Дуротарі.",kw={"прихована стежка","шамани","камінь духів","долина випробувань","стежина","степи","дуротар"},ang={["class:Shaman"]="Прихована Стежка — ваш перший справжній підйом, тілесний і духовний: вона випробовує вашу уважність, перш ніж ви поспілкуєтеся з духами землі біля Каменя Духів.",["faction:Horde"]="Хоч стежка й священна для шаманів, цей неукріплений прохід — сліпа пляма в безпеці над Долиною Випробувань, яка вимагає пильного ока."},sec={{t="Священний підйом",b="Прорізана в червоних вершинах довкола Долини Випробувань, Прихована Стежка навмисне така, щоб її було важко помітити з дна каньйону. Наставники скеровують сюди молодих шаманів, щоб ті довели свою уважність і дисципліну, перш ніж спілкуватися з духами біля Каменя Духів. На найвищих відтинках стежки мандрівникам відкриваються широкі краєвиди, що тягнуться на захід, до хвилястих саван Пусток."},{t="Стратегічна вразливість",b="Окрім духовного значення, стежка пробиває небезпечний пролом у природних укріпленнях, що оточують долину. Низький перевал на її шляху дає прямий чорний хід у бік Раджета й дороги на Оргріммар. Оскільки він оминає звичайні застави в каньйоні, пильні захисники побоюються, що зухвалі лазутчики Альянсу можуть скористатися цією тихою стежкою, щоб прослизнути просто на головний полігон Орди."}},fp="11,276,15.419.0,23.422.0,32.217.0,38.238.0,65.250.0,42.174.0"}
P.entries["subzone:iceflow-lake"] = {n="Озеро Крижаного Потоку",s="Озеро Крижаного Потоку — холодна, частково замерзла водойма на заході Дун Мороґу, просто на північ від Села Брюнолл. Попри невпинний мороз, місцеві горяни підтримують ополонки в суцільній кризі, щоб мати прісну воду й рибу. На засніжених островах посеред озера нишпорять люті зимові вовки та їхній ватажок Тімбер.",h="Озеро Крижаного Потоку — холодна, частково замерзла водойма на заході Дун Мороґу, просто на північ від Села...",kw={"озеро крижаного потоку","вовки","тімбер","ворг","ополонка","село брюнолл","дун мороґ"},ang={["class:Hunter"]="Засніжені береги й центральні острови озера — чудові угіддя для вистежування витривалих зимових звірів, зокрема грізного ватажка воргів Тімбера.",["race:Dwarf"]="Для горян Села Брюнолл Озеро Крижаного Потоку — і життєво важливе джерело прісної води, і постійна небезпека, що вимагає повсякчасної пильності проти хижих вовків, які переходять кригу."},sec={{t="Крижані глибини й острівні хижаки",b="Розкинувшись на заході Дун Мороґу одразу за Селом Брюнолл, Озеро Крижаного Потоку цілий рік бореться з лютим кліматом Хаз Модану. Товсті крижані пласти невпинно наповзають на поверхню, тож місцеві мешканці, як-от Пакстон Ґантер, мусять раз у раз прорубувати ополонки для підлідної риболовлі та питної води. Берег дає харч, а от острови посеред озера значно менш гостинні. Люта зграя диких вовків зробила ці крижані горби своєю територією, а верховодить нею горезвісно дикий сірий ворг на ім'я Тімбер."}},fp="12,366,34.523.0,45.245.0,21.200.0,40.220.0"}
P.entries["subzone:ironband-s-compound"] = {n="Поселення Айронбенда",s="Поселення Айронбенда — укріплена застава серед засніжених пагорбів на південь від Озера Ложа Гелма на сході Дун Мороґу. Колись домівка шукача Стурджі Айронбенда, табір захопили ворожі дворфи Темного Заліза, які нападають на кожного, хто підійде надто близько.",h="Поселення Айронбенда — укріплена застава серед засніжених пагорбів на південь від Озера Ложа Гелма на сході...",kw={"поселення айронбенда","темне залізо","застава","озеро ложа гелма","дун мороґ","воїни"},ang={["class:Warrior"]="Воїнів-початківців сюди посилають бувалі наставники Айронфорджа, щоб вони довели свою вправність, допомігши полеглим товаришам і зібравши докази присутності Темного Заліза.",["race:Dwarf"]="Для Бронзбірдів те, що віроломне Темне Залізо окопується всередині кордонів Дун Мороґу, — пряма образа й постійна небезпека для рідного краю."},sec={{t="Падіння перед Темним Залізом",b="Це поселення на південь від Озера Ложа Гелма заснував Стурджі Айронбенд, і колись воно було опорним пунктом у засніженій глушині Дун Мороґу. Усе змінилося, коли лазутчики Темного Заліза просунулися глибоко в землі Бронзбірдів і захопили його для себе. Нині поселення, повне ворожих дворфів, служить передовою базою противника, що загрожує мандрівникам і сусіднім селищам просто під носом в Айронфорджа."},{t="Загроза Айронфорджу",b="Укріплений табір Темного Заліза всередині кордонів самого Дун Мороґу — серйозна провокація. Айронфордж не зводить із поселення насторожених очей і посилає бувалих воїнів забрати полеглих розвідників і здобути важливі відомості, які доведуть розмах загрози Темного Заліза в гірському королівстві."}},fp="19,261,24.428.0,21.297.0,41.128.0,37.133.0,37.96.0,55.201.0"}
P.entries["subzone:ironforge"] = {n="Айронфордж",s="Айронфордж — підземна столиця дворфів, вирубана глибоко в камені гори Айронфордж у Дун Мороґу. Зосереджений довкола ревучої Великої Кузні, він слугує політичним і торговим якорем Королівства Каз Модан і твердинею Альянсу.",h="Айронфордж — підземна столиця дворфів, вирубана глибоко в камені гори Айронфордж у Дун Мороґу.",kw={"айронфордж","дворфи","велика кузня","каз модан","король маґні","містечко майстрів","столиця"},ang={["race:Dwarf"]="Айронфордж — столиця предків і серце клану Бронзбірдів, де дворфійське ремесло, звитяга й історія вирізьблені просто в живому гірському камені.",["race:Gnome"]="Втративши Гномреґан через трогів і радіацію, гноми зробили Містечко Майстрів своїм тимчасовим прихистком і плацдармом для спроб повернути батьківщину."},sec={{t="Гірська фортеця",b="Вирубане в підземних глибинах гори Айронфордж, місто розташоване концентричними кам'яними кільцями, що розходяться від монументальної Великої Кузні. Засноване тисячоліття тому, коли дворфи пробудилися й переселилися з Ульдаману, воно пережило цілі епохи історії, зокрема давню Війну Трьох Молотів, після якої клан Бронзбірдів лишився одноосібним господарем. Живлене потоками розплавленої магми й укріплене масивними кам'яними брамами, печерне місто — водночас промислова потуга й неприступний бастіон. Окрім дворфійських ремісників і воїнів, у його залах після недавнього падіння Гномреґану живе й чимале населення гномів-вигнанців."},{t="Серце торгівлі Альянсу",b="У 25 році після відкриття Темного Порталу Айронфордж — чи не найжвавіший осередок торгівлі та промисловості в усьому Альянсі. Король Маґні Бронзбірд править Каз Моданом із Високого Престолу, а дворфійські старателі, гірники та інженери працюють пліч-о-пліч із гномськими біженцями, що оселилися в Містечку Майстрів. Підземний Глибинний трамвай — безперервна швидкісна лінія під горами просто до Стормвінда, що міцно єднає обидві столиці торгівлею, пересуванням військ і спільною обороною."}},fp="9,278,21.676.0,23.498.0,30.189.0,49.238.0,45.194.0,50.210.0"}
P.entries["subzone:ironforge-airfield"] = {n="Летовище Айронфорджа",s="Сховане високо серед засніжених вершин на північний схід від Айронфорджа, це віддалене дворфське летовище служить полігоном і плацдармом для гномських літальних машин та дворфських горян. Не позначене на головних дорогах, плато височіє над зубчастими скелями Дун Мороґу і крутим спуском до Багнокраю.",h="Сховане високо серед засніжених вершин на північний схід від Айронфорджа, це віддалене дворфське летовище...",kw={"летовище айронфорджа","літальні машини","гноми","інженери","морозогриви","дун мороґ"},ang={["profession:Engineering"]="Для тінкерів злітна смуга — вершина гномської авіації: тут стоять повністю зібрані літальні машини, що працюють у крайніх морозних умовах.",["race:Dwarf"]="Свідчення дворфської територіальної пильності: летовище доводить, що горяни Айронфорджа стоять на чатах навіть на найнеприступніших висотах Хаз Модану."},sec={{t="Прихований редут серед скель",b="Високогірне летовище, що здійнялося далеко над уторованими стежками Дун Мороґу, — тихе диво співпраці в Альянсі. Під захистом навколишніх вершин дворфська кладка закріплює вітряні гребені, а гномські літальні машини стоять уздовж відкритих злітних смуг. Горяни стежать за околицями пліч-о-пліч з інженерами, що на лютому морозі закручують шестерні й оглядають двигуни, які пихкають парою."},{t="Прикордонні сутички й замерзлі долини",b="Попри відлюдність, летовище аж ніяк не спокійне. У навколишній долині — замерзлі води й скелі, за які змагаються тролі Морозогриви: вони живуть у сусідніх печерах і невпинно дошкуляють дворфським вартовим. У тіні вершин дворфські захисники та патрулі Штормпайків раз у раз сходяться з тролями-нападниками на кризі, тож віддалена застава живе в стані тихого, пильного протистояння."}},fp="18,304,29.419.0,38.403.0,34.276.0,34.225.0,41.167.0,44.184.0"}
P.entries["subzone:jaggedswine-farm"] = {n="Ферма Зубчастого Вепра",s="Ферма Зубчастого Вепра — скромна тваринницька садиба на півночі Дуротару, просто на південь від головного входу до Оргріммара. Вона складається з дерев'яної комори, просторого загону та багнистого водопою і є важливим джерелом харчів: тут вирощують витривалих свиней для сусідньої столиці Орди.",h="Ферма Зубчастого Вепра — скромна тваринницька садиба на півночі Дуротару, просто на південь від головного...",kw={"ферма зубчастого вепра","свині","ферма","харчі","оргріммар","кулінарія","дуротар"},ang={["faction:Horde"]="Налагодити стале постачання м'яса в посушливих пустках Дуротару — справа виживання, тож застави на кшталт Ферми Зубчастого Вепра життєво важливі для підтримання військової сили Оргріммара.",["profession:Cooking"]="Для кухарів Орди, що опановують ремесло в Дуротарі, численні свині довкола Ферми Зубчастого Вепра — головне місцеве джерело ніжних реберець, свинини та кулінарного жиру."},sec={{t="Харчі для столиці",b="Вирвана в нещадної, випаленої сонцем землі Дуротару, Ферма Зубчастого Вепра втілює сувору правду про те, чого вартує прогодувати таку міську твердиню, як Оргріммар. Червоний ґрунт краю дає скупі врожаї, тож міцна худоба конче потрібна, щоб нагодувати тисячі орківських воїнів і робітників. Серце ферми — дерев'яна комора, широкий дерев'яний загін і природний ставок-водопій, де свиней зганяють, розводять і забивають, щоб комори Орди не порожніли."},{t="Тихе порубіжжя",b="Хоч ферма тиха й на сухій спеці часто здається напівзанедбаною, це звичне місце для тутешніх свинопасів і патрулів бійців Оргріммара. Дикі й дорослі свині блукають і всередині загонів, і поза ними, часом випробовуючи терпіння сусідніх вартових. Ділянка на самому порозі долини, що веде до столиці, лишається непримітною, але незамінною заставою в щоденному постачанні Дуротару."}},fp="16,287,26.461.0,16.432.0,40.145.0,42.139.0,41.213.0,41.171.0"}
P.entries["subzone:jasperlode-mine"] = {n="Яшмова копальня",s="Яшмова копальня — розробка заліза й мінералів у північно-центральному Лісі Елвінн, що колись постачала Стормвінду життєво важливі ресурси. Нині штольні заполонили рої кобольдів і смертоносні велетенські павуки, і королівство, якому бракує ресурсів, не може її повернути.",h="Яшмова копальня — розробка заліза й мінералів у північно-центральному Лісі Елвінн, що колись постачала...",kw={"яшмова копальня","кобольди","павуки","мати іклань","копальня","залізо","ліс елвінн"},ang={["faction:Alliance"]="Добування сирого металу з Яшмової копальні вкрай важливе для постачання спорядження Стормвінда в час, коли кордонам королівства постійно загрожує небезпека.",["profession:Mining"]="Багата на мінеральні жили, Яшмова копальня лишається спокусливою метою для шукачів, готових пробитися крізь кайла кобольдів і павутиння, щоб застовпити ділянку."},sec={{t="Втрачений ресурс Елвінну",b="Яшмова копальня історично була одним із найприбутковіших гірничих промислів Стормвінда, даючи сталі мінеральні багатства поруч із сусіднім Фарґодіпом. Коли військо королівства розтягнулося до краю, обороняючись від зовнішніх загроз і заворушень, місцеві гарнізони не змогли захистити штольні. Кобольди скористалися нагодою, зарилися всередину, вигнали людей-шахтарів і почали складати вкрадене золото й лойові свічки."},{t="Небезпеки в глибині",b="Навала в Яшмовій копальні не обмежується простою поганню. У найглибших, найтемніших коридорах під дерев'яними кріпленнями вкорінилася войовнича колонія шахтних павуків. Під проводом величезної матріархині, яку місцеві звуть Мати Іклань, павуки мають кобольдів-порушників — і будь-яких необачних шукачів — за легку здобич, тож будь-яка спроба врятувати копальню надзвичайно небезпечна."}},fp="15,272,25.414.0,19.391.0,31.218.0,56.215.0,35.162.0,43.235.0"}
P.entries["subzone:jerod-s-landing"] = {n="Пристань Джерода",s="Пристань Джерода — скромний річковий причал на елвіннському березі річки Назферіті. Нині захоплена Братством Дефіас, застава служить таємним перевалочним пунктом для незаконних вантажів, які переправляють водними шляхами королівства.",h="Пристань Джерода — скромний річковий причал на елвіннському березі річки Назферіті.",kw={"пристань джерода","причал","братство дефіас","контрабанда","назферіті","si:7","ліс елвінн"},ang={["class:Rogue"]="Розбійників на службі SI:7 посилають на Пристань Джерода випробувати скритність, обчистити кишені начальника пристані Дефіас і здобути важливі торгові облікові книги.",["faction:Alliance"]="Захоплення Пристані Джерода показує, як ґрунтовно Дефіас узяли під контроль внутрішні водні шляхи між Елвінном і Редріджем просто під носом у Стормвінда."},sec={{t="Перевалка контрабандистів",b="Схована на східних водах річки Назферіті, Пристань Джерода дає річковий доступ, що сполучає Ліс Елвінн із сусідніми землями. Колись звичайний човновий причал, нині місце міцно опинилося в руках Братства Дефіас. Під пильним оком начальника пристані з Дефіас розбійники використовують причал як вузол, куди надходять товари, награбовані в Горах Редріджу, і звідки річкові вантажі непомітно сплавляють униз за течією до володінь на кшталт Вежі Клейвена у Вестфолі."},{t="Очі в тінях",b="Через стратегічне розташування на річці Пристань Джерода привернула увагу SI:7 — таємної розвідувальної мережі Стормвінда. Агенти, що стежать за діями Дефіас, вважають пристань важливою ланкою в шляхах постачання синдикату й посилають винахідливих розбійників проникнути на причал, викрасти облікові книги річкових перевезень і розплутати ширшу змову, що душить королівство."}},fp="15,255,21.490.0,19.384.1,33.175.0,29.163.0,48.194.0,42.163.0"}
P.entries["subzone:kharanos"] = {n="Харанос",s="Харанос — гамірне гірське поселення в засніженому серці Дун Мороґу, трохи нижче дорогою від Айронфорджа. Головний осередок для мандрівників, що залишають Долину Холодного Хребта, містечко має кузню, гномські майстерні та славетну Ґуральню Тандербрю.",h="Харанос — гамірне гірське поселення в засніженому серці Дун Мороґу, трохи нижче дорогою від Айронфорджа.",kw={"харанос","містечко","ґуральня тандербрю","кузня","дун мороґ","осередок"},ang={["race:Dwarf"]="Для дворфів, що залишають захищені скелі Перевалу Холодного Кряжа, Харанос — перший смак ширшого королівства, повний димних кузень і легендарного стауту клану Тандербрю.",["race:Gnome"]="Біженці та майстровиті гноми з Гномреґану часто влаштовуються в Хараносі й довкола нього, працюють разом із місцевими ковалями та діють із сусідніх складів."},sec={{t="Затишний прихисток на порубіжжі",b="Харанос стоїть при головній дорозі Дун Мороґу — це перше справжнє містечко, що вітає новобранців з Анвілмара. Попри лютий холод і пронизливі вітри, поселення процвітає завдяки дворфській упертості та гномській винахідливості. Його серце — ревуча громадська кузня та Ґуральня Тандербрю, що славиться на всі східні гори одним із найкращих елів Хаз Модану. Між заклопотаними ремісниками та втомленими мандрівниками, що шукають тепла, містечко лишається головним плацдармом для будь-яких справ у нижніх горах."},{t="На сторожі низин",b="За затишними вогнищами Харанос ховає роль важливої військової застави, що має тримати гірські перевали під охороною. Люті тутешні вендіго нишпорять замерзлими печерами просто на захід, а войовничі тролі Морозогриви міцно засіли на Мерехтливому Хребті на північному заході. Оскільки регулярні сили Айронфорджа розтягнуті по всьому королівству, містечко чимало покладається на заїжджих шукачів пригод і місцевих вартових, щоб відбивати загони нападників, винищувати небезпечних хижаків і тримати торгові шляхи відкритими."}},fp="8,268,23.544.0,21.508.0,17.221.0,45.237.0,31.190.0,26.173.0"}
P.entries["subzone:kodo-rock"] = {n="Камінь Кодо",s="Камінь Кодо — природний кам'яний монумент на рівнинах Плато Червоної Хмари, між Табором Нарачі та Яром Тернистого Клинка. Тихо стоячи серед трав Малгору, він слугує раннім місцем паломництва для молодих тауренських шаманів, що вчаться спілкуватися з духами землі. Через скромний силует на тлі хвилястого краєвиду мандрівникам треба добре придивлятися, щоб його помітити.",h="Камінь Кодо — природний кам'яний монумент на рівнинах Плато Червоної Хмари, між Табором Нарачі та Яром...",kw={"камінь кодо","плато червоної хмари","шамани","стихії","табір нарачі","орієнтир"},ang={["class:Shaman"]="Для тауренських шаманів-новачків, що починають духовний шлях у Таборі Нарачі, Камінь Кодо — важливий орієнтир для налаштування на світ стихій.",["race:Tauren"]="Ця кам'яна брила — знайомий орієнтир на рівнинах Плато Червоної Хмари, що відображає священний зв'язок між Шу'хало та звірами Малгору."},sec={{t="Орієнтир на плато",b="Камінь Кодо стоїть приблизно на півдорозі між Табором Нарачі та ворожими землями шипогривів у Яру Тернистого Клинка; біля його підніжжя помітна латка витоптаної землі. Йому бракує величі високих круч, що оточують Плато Червоної Хмари, але своїм обрисом він нагадує шанованих кодо, що бродять пасовищами. Для мандрівних одноплемінників це тихий природний маяк серед обвітрених рівнин Малгору."},{t="Духовне значення",b="Для Шу'хало природні утворення часто мають духовну вагу. Камінь Кодо особливо шанують молоді тауренські шамани, що лише починають духовну путь. Новачків посилають сюди на перших обрядах посвяти: самотній кам'яний монумент стає для них священним місцем, де вони спілкуються зі стихіями й ушановують природу, перш ніж вирушити в небезпечніші краї континенту."}},fp="9,395,22.444.0,22.386.0,27.206.0,30.240.0,45.214.0,32.197.0"}
P.entries["subzone:kolkar-crag"] = {n="Круча Колкарів",s="Круча Колкарів — випалена сонцем зубчаста ущелина на півдні Дуротару, яку захопили ворожі кентаври клану Колкар. Цей анклав під проводом Воєначальника Колканіса служить плацдармом для злагоджених набігів на сусідні поселення Орди.",h="Круча Колкарів — випалена сонцем зубчаста ущелина на півдні Дуротару, яку захопили ворожі кентаври клану...",kw={"круча колкарів","кентаври","колкар","воєначальник колканіс","ущелина","набіги","дуротар"},ang={["faction:Horde"]="Убезпечення південного Дуротару від вторгнень кентаврів захищає шляхи постачання між Селом Сен'джин і дорогою на Оргріммар.",["race:Orc"]="Присутність кентаврів так близько до Долини Випробувань загрожує посвяті молодих орків, тож утихомирити Кручу Колкарів — нагальна справа оборони рідної землі."},sec={{t="Скалка в боці Дуротару",b="Схована в суворих каньйонах південного Дуротару, Круча Колкарів — опорна база войовничого клану Колкар. Попри посушливу й нещадну місцевість, ці кентаври укріпили природні горловини ущелини. З цього яру їхні розвідники та грабіжники пильно стежать за навколишніми рівнинами, шукаючи слабких місць у володіннях орків і Темного Списа. Для молодих воїнів, що навчаються в Долині Випробувань або патрулюють південне узбережжя, Круча Колкарів — найближчий організований фронт ворожих кентаврів."},{t="Задуми вторгнення",b="Під командуванням Воєначальника Колканіса кентаври, що окопалися на кручі, плекають задуми значно масштабніші за прості сутички. Здобуті плани нападу розкривають змови проти Долини Випробувань, Села Сен'джин, Гострого Пагорба та зухвалі удари, націлені просто на браму Оргріммара. Щоб зупинити ці плани, потрібні рішучі випереджувальні удари вглиб яру: убити Колканіса й зірвати збір, перш ніж їхні бойові загони прокотяться долинами."}},fp="11,219,25.544.0,19.461.1,25.181.0,45.217.0,27.170.0"}
P.entries["subzone:lake-al-ameth"] = {n="Озеро Ал'Амет",s="Озеро Ал'Амет — одна з найбільших прісних водойм високо в гіллі Тельдрассила, одразу на південь від Доланаара. Колись тиха пристань, де не було нічого, крім простого дерев'яного причалу, тепер має небезпечні береги через буйне збурення місцевої рослинності.",h="Озеро Ал'Амет — одна з найбільших прісних водойм високо в гіллі Тельдрассила, одразу на південь від Доланаара.",kw={"озеро ал'амет","деревляники","похмуродуб","доланаар","тельдрассил","скверна","насіння"},ang={["class:Druid"]="Дикі деревляники довкола озера дають друїдам змогу на власні очі вивчати неприродну скверну, що підточує флору й фауну Тельдрассила.",["race:NightElf"]="Для калдореїв Доланаара Озеро Ал'Амет — тривожна ознака недуг, що мучать їхню новорослу домівку, і молодим захисникам доводиться охороняти довколишню дорогу."},sec={{t="Неспокійний берег",b="Озеро Ал'Амет одразу на південь від селища Доланаар — важлива природна улоговина в серці Тельдрассила. Попри тихі води й майже відсутні поселення, спокою тут не стало. Зграї збурених деревляників і паростків деревляників нишпорять край води, збожеволілі від неприродної хвороби, що шириться Світовим Деревом. Друїди й дослідники з Доланаара часто посилають мандрівників на ці береги збирати насіння й виполювати агресивних створінь, перш ніж скверна пошириться глибше в довколишній ліс."},{t="Коріння гніву",b="Ворожість довкола Озера Ал'Амет напряму пов'язана з тим, що лісові духи втрачають рівновагу. Величезні зіпсуті древні на кшталт Похмуродуба чаяться в сусідніх гаях, а тутешні деревляники кидаються на кожного, хто наблизиться. Для Кола Кенарія розпізнати й зцілити гниль довкола Озера Ал'Амет — нагальна перевірка того, чи взагалі можна втримати неблагословенне творіння — Тельдрассил."}},fp="13,291,20.551.0,18.386.0,31.96.0,51.198.0,45.136.0,18.173.0"}
P.entries["subzone:library-wing-northshire"] = {n="Бібліотечне Крило (Нортшир)",s="Бібліотечне Крило — тихе, заставлене книжками південне крило Абатства Нортшира в Лісі Елвінн. Це прихисток для вчених, де жерці та маги-початківці, що долучаються до оборони Стормвінда, отримують перші настанови.",h="Бібліотечне Крило — тихе, заставлене книжками південне крило Абатства Нортшира в Лісі Елвінн.",kw={"бібліотечне крило","бібліотека","абатство нортшира","жерці","маги","жриця анетта","келден бремен"},ang={["class:Mage"]="Келден Бремен навчає магів-новачків у цих тихих залах, викладаючи основоположні дисципліни вогню та морозу.",["class:Priest"]="Тут перебуває Жриця Анетта, що дає жерцям-початківцям найперші уроки спрямування Святого Світла для зцілення ран і каральних ударів по ворогах."},sec={{t="Прихисток таємних і божественних студій",b="Бібліотечне Крило, що відгалужується на південь від Головної Зали Абатства Нортшира, вміщує запилені полиці, пюпітри для читання й тихі ніші, присвячені розумовій і духовній підготовці. Поки військові новобранці муштруються в північній Залі Зброї, майбутні маги та жерці збираються тут, щоб осягнути основи таємної магії та Святого Світла. Нині Жриця Анетта наставляє жерців-новачків у справах віри та зцілення, а Келден Бремен навчає магів-початківців надавати форму первісній стихійній енергії."}},fp="25,224,32.500.0,34.152.0,33.189.0"}
P.entries["subzone:lion-s-pride-inn"] = {n="Корчма «Лев'яча Гордість»",s="Корчма «Лев'яча Гордість» — гамірна таверна та громадський осередок Ґолдшира в Лісі Елвінн. Поколіннями її тримає родина Фарлі, і це головне місце перепочинку, зустрічей і найму для мандрівників, що вирушають на південь від Стормвінда.",h="Корчма «Лев'яча Гордість» — гамірна таверна та громадський осередок Ґолдшира в Лісі Елвінн.",kw={"корчма лев'яча гордість","корчма","таверна","ґолдшир","шинкар фарлі","перепочинок","ліс елвінн"},ang={["faction:Alliance"]="Як головна корчма за брамою Стормвінда, вона є гамірною проміжною станцією, де мандрівники Альянсу узгоджують патрулі й торгівлю по серцевинних землях.",["race:Human"]="Для людей, що виходять з Абатства Нортшира, корчма «Лев'яча Гордість» — перша зустріч із ширшим життям і клопотами королівства за стінами монастиря."},sec={{t="Серце Ґолдшира",b="Корчма «Лев'яча Гордість» на перехресті Лісу Елвінн — жвавий центр Ґолдшира. Її тримає Шинкар Фарлі під традиційним гаслом закладу — «Відпочинок і спокій для втомлених і змерзлих», — пропонуючи теплі вогнища, міцні напої та кімнати втомленим шукачам пригод, що щойно вийшли з Нортширу. Родина Фарлі з гордістю порядкує тут уже багато поколінь, ще з часів правління Короля Ллейна Рінна I. Оскільки Ґолдшир лежить на важливих торгових шляхах між Стормвіндом, Вестфолом, Редріджем і Сутінколіссям, корчма — незамінне місце збору, де міські маршали, місцеві ремісники й бувалі наставники діляться новинами та наймають перехожих найманців."}},fp="16,263,18.715.0,39.209.0,43.208.0,44.279.0,42.104.0"}
P.entries["subzone:maclure-vineyards"] = {n="Виноградники Маклюрів",s="Виноградники Маклюрів — розлогий сільськогосподарський маєток на півдні Лісу Елвінн, що належить родині Маклюрів. Відомий виноградом і вином для королівства Стормвінд, маєток не менш сумнозвісний через тривалу запеклу ворожнечу з сусідньою родиною Стоунфілдів.",h="Виноградники Маклюрів — розлогий сільськогосподарський маєток на півдні Лісу Елвінн, що належить родині...",kw={"виноградники маклюрів","виноград","вино","ворожнеча","стоунфілди","мейбелл маклур","ліс елвінн"},ang={["faction:Alliance"]="Маєток — важлива житниця й виноградник, що постачає сусідні Ґолдшир і Стормвінд харчами та напоями.",["race:Human"]="Для людей Стормвінда ворожнеча на виноградниках — класичний приклад сільської впертості; вона нагадує мандрівникам, що навіть у серці королівства сусіди часто сваряться через паркани, поки назріває більша небезпека."},sec={{t="Гіркий урожай",b="Виноградники Маклюрів серед буйних пагорбів південного Лісу Елвінн мали б бути мирним прихистком виноробства та хліборобства. Натомість щоденну працю затьмарює люте давнє суперництво зі Стоунфілдами, що живуть трохи далі дорогою. Між господарствами глибоко вкорінилися звинувачення в крадіжках і злопам'ятство, і пристрасті не вщухають навіть тоді, коли спільні біди — голодні вепри та кобольди, що насуваються, — загрожують обом садибам."},{t="Заборонене кохання",b="Попри люту ворожнечу двох патріархів, юне кохання перетнуло межу. Мейбелл Маклур і Томмі Джо Стоунфілд таємно покохали одне одного й зустрічаються в потаємних гаях подалі від підозріливих батьківських очей. Ті, хто проходить через виноградники, часто виявляють, що вже носять таємні записки, залагоджують дрібні образи й намагаються допомогти юній парі вирватися з тіні родинної ворожнечі."}},fp="17,281,16.441.0,19.440.1,46.246.0,23.216.0,35.187.0,34.148.0"}
P.entries["subzone:main-hall-northshire"] = {n="Головна Зала (Нортшир)",s="Головна Зала — центральна вхідна зала Абатства Нортшира в Лісі Елвінн. Це головне перехрестя, що сполучає подвір'я абатства з його верхньою вежею, Залою Зброї та Бібліотечним Крилом. Сюди з'являються щойно набрані шукачі пригод з людей, щоб отримати перші доручення на службі королівству Стормвінд.",h="Головна Зала — центральна вхідна зала Абатства Нортшира в Лісі Елвінн.",kw={"головна зала","абатство нортшира","вхід","новобранці","доручення","нортшир","стормвінд"},ang={["race:Human"]="Для людей королівства Головна Зала Абатства Нортшира знаменує початок їхнього шляху на службі Стормвінду та Святому Світлу."},sec={{t="Серце абатства",b="Ступивши крізь величні арки Абатства Нортшира, відвідувачі одразу потрапляють до Головної Зали. Як центральний вузол будівлі, вона спрямовує прибулих учнів і церковний люд між окремими крилами абатства: військовою Залою Зброї з одного боку, ученим Бібліотечним Крилом з іншого та сходами, що ведуть у вежу абатства. Тихе святилище зали затьмарює безперервна боротьба в долині, бо офіцери скликають дужих новоприбулих боронити кордони королівства."}},fp="22,334,18.494.0,37.202.0,30.208.0"}
P.entries["subzone:mirror-lake"] = {n="Дзеркальне Озеро",s="Дзеркальне Озеро — мальовнича водойма на північному заході Лісу Елвінн, біля саду. Живлене лагідним водоспадом під скелями Стормвінда, його спокійне плесо приховує небезпеки на берегах — від розбійників Дефіас, що тут нишпорять, до дивних збурень у місцевих лей-лініях.",h="Дзеркальне Озеро — мальовнича водойма на північному заході Лісу Елвінн, біля саду.",kw={"дзеркальне озеро","озеро","водоспад","дефіас","лей-лінії","маги","ліс елвінн"},ang={["class:Mage"]="Учнів Святилища Чародія в Стормвінді посилають сюди брати проби води, щоб вони на власні очі побачили, як бурхливі таємні канали просочуються в природне довкілля.",["faction:Alliance"]="Хоч озеро й лежить поруч із високими стінами столиці, воно нагадує, як тонко розтягнуті вартові королівства перед розбійниками Дефіас."},sec={{t="Неспокійна ідилія",b="Дзеркальне Озеро під високими валами Стормвінда мало б бути мирним прихистком для рибалок і втомлених мандрівників. Натомість довколишніми садами скрадаються розбійники Братства Дефіас, тож будь-яке тривале перебування тут небезпечне для місцевих. Ще гірше: містичні збурення по всьому Азероту почали викривлювати природні канали таємної енергії по всьому лісу. Маги зі Святилища Чародія пильно наглядають за озером і посилають учнів брати проби його течій, щоб переконатися, що хаотичні таємні стоки не отруюють громади нижче за течією."}},fp="11,296,15.590.0,29.236.0,35.262.0,50.177.0"}
P.entries["subzone:mirror-lake-orchard"] = {n="Сад Дзеркального Озера",s="Сад Дзеркального Озера — тихий гай із хатиною на південному березі Дзеркального Озера на заході Лісу Елвінн. Колись мирна садиба біля Громових водоспадів, нині він у руках розбійників Дефіас, які визискують околицю, поки вартові Стормвінда дивляться деінде.",h="Сад Дзеркального Озера — тихий гай із хатиною на південному березі Дзеркального Озера на заході Лісу Елвінн.",kw={"сад дзеркального озера","сад","хатина","дефіас","розбійники","громові водоспади","ліс елвінн"},ang={["class:Rogue"]="Сад показує класичну стратегію Дефіас: захоплювати зручні для оборони, непомітні маєтки біля води та скель, щоб стежити за дорогами й уникати міських патрулів.",["faction:Alliance"]="Для мандрівників Альянсу захоплений сад — ще одна гірка ознака зухвалого розростання Братства Дефіас у серці королівства."},sec={{t="Захоплений гай",b="Схований біля спадаючих вод Громових водоспадів, Сад Дзеркального Озера колись був родючою садибою, що користалася чистими водами Дзеркального Озера. Нині мирна хатина захоплена спритними злодіями й розбійниками під кольорами Братства Дефіас. Поки військо королівства розтягнуте до краю, а Король Варіан Рінн зник, сільські маєтки на кшталт цього саду стали легкою здобиччю для злочинців, що шукають сховків по всій елвіннській околиці."}},fp="19,281,21.494.0,43.208.0,37.161.0,43.283.0,61.185.0"}
P.entries["subzone:misty-pine-refuge"] = {n="Притулок Туманних Сосен",s="Притулок Туманних Сосен — невелика будівля-застава Срібного світанку серед морозних снігів центрального Дун Мороґу.",h="Притулок Туманних Сосен — невелика будівля-застава Срібного світанку серед морозних снігів центрального Дун...",kw={"притулок туманних сосен","срібний світанок","отець ґевін","застава","дун мороґ","жрець"},ang={["class:Priest"]="Скромний пост Отця Ґевіна показує, що служіння Світлу часто полягає в тихій пильності далеко від полів битв."},sec={{t="Прихисток серед снігів",b="Розташований серед обвіяних вітрами пагорбів Дун Мороґу, Притулок Туманних Сосен — непримітна застава Срібного світанку в дворфському краї. Поки навколишні скелі патрулюють горяни Айронфорджа, у притулку живе Отець Ґевін, єдиний представник ордену в цих краях, що дає тихе вогнище посеред лютої негоди й небезпек, які загрожують гірським дорогам."}},fp="17,118,19.366.0,26.118.0,42.164.0,24.99.0"}
P.entries["subzone:night-web-s-hollow"] = {n="Лощина Нічної Павутини",s="Лощина Нічної Павутини — запала долина й покинута золота копальня одразу на північний захід від Похоронного Подзвону в Галявинах Тірісфалю. Густо заполонена павуками, вона править за полігон для щойно пробуджених Відступників, яких посилають винищити гидь і довести бойову готовність.",h="Лощина Нічної Павутини — запала долина й покинута золота копальня одразу на північний захід від Похоронного...",kw={"лощина нічної павутини","павуки","золота копальня","похоронний подзвін","випробування","тірісфаль"},ang={["profession:Mining"]="Хоч шахти спершу копали заради золота, видобуток тут давно припинено через смертоносну павучу навалу.",["race:Undead"]="Для щойно воскреслих лощина — одне з ваших найперших випробувань. Убивство павуків доводить, що ви маєте зосередженість і силу волі, потрібні для служби Темній Леді."},sec={{t="Заражена копальня",b="Лощина Нічної Павутини в північних пагорбах Похоронного Подзвону колись була звичайною людською золотою копальнею, поки чума не прокотилася Лордероном. Після падіння королівства шахти цілком покинули напризволяще. Сьогодні товсті пасма павутиння вкривають кам'яні стіни, а задушливі тіні ховають буйну колонію агресивних павуків нічної павутини. Щойно воскреслих Відступників регулярно висилають у лощину та її підземні тунелі винищувати молодняк, убити ненажерливу матку й загартувати волю, перш ніж рушити далі в Галявини Тірісфалю."}},fp="18,266,17.588.0,27.197.0,46.233.0,39.208.0,29.221.0"}
P.entries["subzone:nightmare-vale"] = {n="Долина Жахіть",s="Долина Жахіть — тіниста улоговина в південно-західних Галявинах Тірісфалю, одразу на захід від Застави Хрестоносця. Колись пишний лісовий притулок, тепер її дерева всохли від пошесті, а серед покручених стовбурів нишпорять люті хижаки.",h="Долина Жахіть — тіниста улоговина в південно-західних Галявинах Тірісфалю, одразу на захід від Застави...",kw={"долина жахіть","темні гончаки","кажани-вампіри","рессан колій","тірісфаль","застава хрестоносця"},ang={["class:Hunter"]="У долині водяться люті темні гончаки й кажани-вампіри, зокрема рідкісний білий кажан Рессан Колій, тож це примітний полігон для мисливців, які шукають грізних звірів.",["race:Undead"]="Покручена живність Долини Жахіть нагадує про незгладний слід чуми по всьому Тірісфалю й становить пряму загрозу мандрівникам з-поміж Відступників, що вирушають за межі Брілла."},sec={{t="Струхлявіла пуща",b="До Третьої війни ця долина була зеленою частиною сільського Тірісфалю, повною співочих птахів і звичайної лісової дичини. Після чуми Погибелі рослинність почорніла й згнила. Ненажерливі темні гончаки й величезні кажани-вампіри пожерли місцеву живність, обернувши улоговину на похмурий притулок падложерів і хижих звірів."},{t="Мисливці улоговини",b="У тінях Долини Жахіть чаїться Рессан Колій — незвично великий блідий кажан-вампір, сумнозвісний серед місцевих подорожніх. Незатишно затиснута між примарною пущею й ревними вартовими сусідньої Застави Хрестоносця, долина — безжальний простір, де необачні шукачі пригод швидко стають здобиччю."}},fp="14,238,20.366.0,22.325.0,32.111.0,40.250.0,35.196.0,26.126.0"}
P.entries["subzone:north-coast"] = {n="Північне Узбережжя",s="Північне Узбережжя — похмура, оповита туманом смуга берега, що позначає північний край Галявин Тірісфалю вздовж Великого Моря. Отруєні падінням Лордерона, холодні пляжі всіяні гнилою морською живністю, і їх запекло боронять племена ворожих мурлоків.",h="Північне Узбережжя — похмура, оповита туманом смуга берега, що позначає північний край Галявин Тірісфалю...",kw={"північне узбережжя","берег","мурлоки","мерзенний плавець","діб","тірісфаль","велике море"},ang={["race:Undead"]="Поки патрульні маршрути Відступників тримаються дороги через Брілл, зачистка Північного Узбережжя від мурлоків, що насуваються, тримає північний фланг Галявин Тірісфалю у відносній безпеці."},sec={{t="Уражений чумою берег",b="До Третьої війни ці північні води й кам'янисті пляжі були частиною мирного північного рубежу Лордерона. Коли Чума Нежиті прокотилася континентом, її згубна пошесть стекла з круч і отруїла узбережжя. Води стали холодними й каламутними, викидаючи туші велетенських морських створінь, що тепер гниють на піску серед вічного прибережного туману."},{t="Берег Темноплавців",b="Коли людське королівство було розбите, а Відступники зосередили увагу довкола Брілла й столичного міста, прибережні мурлоки захопили безлюдні піски. Місцеве плем'я Темноплавців тримає хатини вздовж прибою й використовує сусідні мілини як нерестовища. Зграї ненажерливих мурлоків, серед них помітні постаті на кшталт Діба й численні пуголовки, що підростають, люто стережуть лінію припливу від усіх, хто живе на суходолі."}},fp="11,272,20.385.0,18.410.0,39.165.0,12.119.0,46.192.0,51.162.0"}
P.entries["subzone:north-gate-outpost"] = {n="Застава Північної Брами",s="Застава Північної Брами — укріплений дворфський табір високо на Перевалі Північної Брами в Дун Мороґу. Охороняючи суворий шлях між засніженим серцем земель Айронфорджа та Лох Моданом, тутешні горяни боронять мандрівників від ворожої звірини, якою кишать скелі.",h="Застава Північної Брами — укріплений дворфський табір високо на Перевалі Північної Брами в Дун Мороґу.",kw={"застава північної брами","перевал","горяни","лох модан","патрулі","дун мороґ"},ang={["race:Dwarf"]="Застава показує стоїчну відданість горян Айронфорджа, які тримають суворі високогірні перевали відкритими попри мороз і хижаків.",["race:Gnome"]="Розселившись по Дун Мороґу, гноми часто допомагають дворфському гарнізонові своєю кмітливістю та влучністю, вистежуючи зниклі патрулі."},sec={{t="Варта перевалу",b="Розташоване посеред Перевалу Північної Брами, це невелике поселення — північно-східний поріг Дун Мороґу. Дворфські горяни, що стоять тут, очищають головну дорогу від хижаків і стежать за рухом крізь гірські тунелі до Лох Модану. Суворий клімат і круті яри роблять патрулювання небезпечним, тож гарнізон часто просить мандрівників обшукати навколишні хребти в пошуках зниклих патрулів і небезпечних хижаків."}},fp="18,261,18.469.0,36.233.0,42.175.0,49.223.0"}
P.entries["subzone:northshire-abbey"] = {n="Абатство Нортшира",s="Абатство Нортшира — історичний монастир у Долині Нортширу серед північних передгір'їв Лісу Елвінн. Відбудоване після знищення в Першій війні, воно є духовним серцем Братства Нортшира й головним осередком підготовки нових захисників, що відгукнулися на поклик королівства Стормвінд.",h="Абатство Нортшира — історичний монастир у Долині Нортширу серед північних передгір'їв Лісу Елвінн.",kw={"абатство нортшира","монастир","стартова локація","люди","братство нортшира","клірики","ліс елвінн"},ang={["class:Paladin"]="Нортшир утілює спадок Архієпископа Алонсуса Фаола й перших кліриків, чиї жертви заклали підвалини Лицарів Срібної Длані.",["race:Human"]="Для людей Стормвінда Абатство Нортшира — колиска вашого шляху, де історія стійкості й відданості королівства вітає кожного новобранця, що береться за зброю."},sec={{t="Спадок віри й руїни",b="Століття тому клірики з Лордерону вирушили на південь, у королівство Стормвінд, щоб ширити поклоніння Святому Світлу, і заснували Святий Орден Нортширських Кліриків та їхнє абатство. Монастир швидко став опорою життя королівства: він дбав про хворих і навіть доглядав юного Вартового Медіва в роки його коми. Під час Першої війни абатство зазнало повторюваних нападів розбійників і Орди орків, що завершилися його цілковитим знищенням. Коли Альянс Лордерону звільнив цей край у Другій війні, Архієпископ Алонсус Фаол допоміг відбудувати святиню й наново заснував її захисників як Братство Нортшира."},{t="Тренувальний майданчик",b="Нині Абатство Нортшира — місце, звідки починають добровольці, ополченці та новачки, що прагнуть боронити обложений Стормвінд. Поділене на Головну Залу, Залу Зброї та Бібліотечне Крило, воно вміщує наставників військових, таємних і святих мистецтв, а розвідники й розбійники тренуються на зовнішніх подвір'ях. Попри пильну присутність Лицарів Срібної Длані, мир тут лишається хитким. Кобольди заполонили сусідні копальні, войовничі вовки блукають садами, а агенти Братства Дефіас скрадаються дорогами долини, крадучи давні сувої та священні лібрами зі славетних архівів абатства."}},faq={{q="Що таке Братство Нортшира?",a="Братство Нортшира — релігійний орден кліриків, жерців і паладинів з осідком в Абатстві Нортшира. Спершу його століття тому заснували клірики-місіонери з Лордерону, а після Першої війни Архієпископ Алонсус Фаол заснував його наново, щоб готувати вірних захисників і зберігати священне писання.",al={"хто керує абатством нортшира","нортширські клірики","лор братства нортшира"}},{q="Чому Абатство Нортшира зруйнували в Першій війні?",a="Під час Першої війни абатство мало для Стормвінда стратегічне й духовне значення. Орки підбурили людських розбійників напасти на нього, а після того, як напіворчиху Ґарону ненадовго тримали тут у полоні, потужний натиск Орди зрівняв святу землю з землею. Абатство лишалося в руїнах до кінця війни, доки Альянс не вигнав орківські клани й не відбудував його.",al={"хто зруйнував абатство нортшира","нортшир перша війна","що сталося з нортширом"}},{q="Чому біля абатства розбійники Дефіас і кобольди?",a="Військо Стормвінда розтягнуте до краю, захищаючи далекі кордони, тож околиці охороняються погано. Спритні кобольди заполонили місцеві золоті копальні, а Братство Дефіас користається прогалинами, щоб грабувати мандрівників, дошкуляти тутешнім виноградникам і спустошувати бібліотеку абатства заради таємних фоліантів і святих реліквій.",al={"чому нортшир атакують","кобольди в нортширі","дефіас біля нортширу"}},{q="Що пов'язує Абатство Нортшира з Мертвими Копальнями?",a="Під час Першої війни вождь огрів на ім'я Турок викрав з Абатства Нортшира священний Фоліант Божественності й сховався в Мертвих Копальнях. Сер Андуїн Лотар очолив похід у глибини, щоб повернути святе писання, і потрапив у пастку, доки королівський рятувальний загін не визволив його й не повернув фоліант під опіку абатства.",al={"фоліант божественності нортшир","лор нортшир мертві копальні","андуїн лотар мертві копальні"}}},fp="16,322,26.656.0,20.618.0,38.314.0,52.351.0,59.321.0,66.320.0"}
P.entries["subzone:northshire-valley"] = {n="Долина Нортширу",s="Сховавшись у північних горах Лісу Елвінн, Долина Нортширу — мирна колиска й тренувальна база для наймолодших захисників королівства Стормвінд. Оточена природними перешкодами, вона дає прихисток старовинному Абатству Нортшира, родючим виноградникам і багатій Шахті Ехо-Рідж. Та попри спокійний вигляд, долині дедалі дошкуляють розбійники, кобольди й витіснені з лісів хижаки.",h="Сховавшись у північних горах Лісу Елвінн, Долина Нортширу — мирна колиска й тренувальна база для наймолодших...",kw={"нортшир","долина нортширу","абатство нортшира","виноградники нортшира","дефіас","кобольди"},sec={{t="Відлюдний прихисток",b="Долину Нортширу обрамляють майже неприступні гірські хребти, і єдина дорога веде звідси на південь, крізь укріплену браму, до Ґолдшира та решти Лісу Елвінн. Пасовищами в'ється прозора річка, що далі на південь впадає в Кришталеве Озеро. У серці долини стоїть Абатство Нортшира — давнє святилище, де навчають Святого Світла, а рекрутів тренують Лицарі Срібної Длані та досвідчені ветерани. За мурами абатства лежать щедрі Виноградники Нортшира й Шахта Ехо-Рідж: разом вони утворюють самодостатній куточок земель Стормвінда, що здається далеким від воєн решти світу."},{t="Нові загрози",b="Навіть цей затишний прихисток відчув, як розтягнуто оборону Стормвінда. Маршал Макбрайд і його загін Варти Стормвінда ледве втримують лад у долині. Зграї вовків, витіснені на північ із ураженого Сутінколісся, нишпорять довколишніми лісами, а кобольди, наче шкідники, заполонили тунелі Шахти Ехо-Рідж. Ба гірше: замасковані головорізи з Братства Дефіас відкрито нападають на виноградники й загрожують землям абатства, тож місцеві командири змушені вербувати кожного здатного тримати зброю, хто дістається до їхніх воріт."}},fp="17,423,20.635.0,20.549.0,44.358.0,49.250.0,42.256.0,44.204.0,50.196.0,35.215.0"}
P.entries["subzone:northshire-vineyards"] = {n="Виноградники Нортшира",s="Виноградники Нортшира — доглянуті виноградні поля просто на схід від Абатства Нортшира, у захищеній улоговині долини. Колись мирне джерело вина для кліриків, нині поля опинилися під владою Братства Дефіас та їхніх місцевих розбійників.",h="Виноградники Нортшира — доглянуті виноградні поля просто на схід від Абатства Нортшира, у захищеній улоговині...",kw={"виноградники нортшира","виноград","дефіас","розбійники","ґаррик педфут","міллі осворт","нортшир"},ang={["faction:Alliance"]="Заворушення на цих мирних виноградних полях показують, як глибоко беззаконня проникло навіть у найзахищеніші закутки королівства Стормвінд.",["race:Human"]="Для багатьох молодих людей, що вирушають у світ, захоплені виноградники — перша пряма зустріч із гіркотою та розмахом Братства Дефіас."},sec={{t="Пограбований урожай",b="Виноградники Нортшира на схід від Абатства Нортшира, за струмком, утілюють тихе хліборобське життя долини. Поля доглядають місцеві робітники, як-от Міллі Осворт, та через дедалі більші заворушення вони лишилися беззахисними. Розбійники, пов'язані з Братством Дефіас, яких на місці очолює горлоріз на ім'я Ґаррик Педфут, захопили угіддя. Злодії зайняли поля не заради простого вандалізму: вони грабують урожай і позбавляють місцевих хліборобів засобів до існування, даючи новобранцям Братства легку опору просто під носом в абатства."}},fp="20,269,19.577.0,48.206.0,59.276.0,21.227.0"}
P.entries["subzone:oracle-glade"] = {n="Галявина Оракула",s="Галявина Оракула в північно-західному Тельдрассилі — священне лісове святилище, домівка дивовижного Дерева Оракула й найголовнішого місячного колодязя Світового Дерева. Попри мирне призначення — бути осередком єднання й пильності — галявина потерпає від постійних наскоків гарпій Кривавого Пера.",h="Галявина Оракула в північно-західному Тельдрассилі — священне лісове святилище, домівка дивовижного Дерева...",kw={"галявина оракула","дерево оракула","місячний колодязь","гарпії","кривавого пера","тельдрассил","дарнасус"},ang={["class:Druid"]="Для друїдів дикої природи Дерево Оракула — живий партнер у служінні, що дає письмові звіти про здоров'я землі просто зі своєї кори.",["race:NightElf"]="Галявина Оракула втілює ніжну турботу, потрібну, щоб виплекати Тельдрассил: тут наймогутніший місячний колодязь крони й мовчазний спостерігач, що говорить напряму з проводирями Кола Кенарія."},sec={{t="Серце лісу",b="Галявина Оракула тихо лежить між Дарнасусом і Озером Джерела — важливий вузол єднання нічних ельфів із природою. У її центрі стоїть Дерево Оракула, прадавній велет, чиє могутнє гілля нагадує обриси орла, що сидить на ведмеді. Поруч мерехтить перший і наймогутніший зі священних місячних колодязів Тельдрассила — оаза місячної магії, омита ласкою Елуни. Разом із Колом Древніх Дерево Оракула наглядає за гіллям острова, скидаючи кору з написами, що правлять за важливі послання Архідруїду Фандралу Стаґгелму про здоров'я Світового Дерева."},{t="Гілля в облозі",b="Спокій галявини крихкий. Агресивні гарпії Кривавого Пера злетілися в гай, звили гнізда серед високих гілок і загрожують священному дереву. Вартові, послані з Дарнасуса, насилу викорінюють крилатих падложерів, що нападають на мандрівних друїдів і споганюють природну тишу місячного колодязя. Мандрівникам у північному гіллі слід ступати обережно: гарпії блискавично б'ють кожного, хто наблизиться до їхніх гнізд."}},fp="12,297,21.596.0,16.473.0,24.279.0,43.245.0,53.253.0,34.178.0"}
P.entries["subzone:orgrimmar"] = {n="Оргріммар",s="Оргріммар — грізна столиця воїнів Нової Орди, вирубана в звивистих червоних каньйонах північного Дуротару. Заснований Вождем Траллом і названий на честь Орґріма Думхаммера, він є серцем відродження орків і спільного виживання племен на Калімдорі.",h="Оргріммар — грізна столиця воїнів Нової Орди, вирубана в звивистих червоних каньйонах північного Дуротару.",kw={"оргріммар","столиця","орда","тралл","дуротар","орґрім думхаммер"},ang={["faction:Horde"]="Як найвище осердя влади Орди, Оргріммар — головний плацдарм для військових кампаній, союзів кланів і дипломатичних стосунків по всьому Калімдору й за його межами.",["race:Orc"]="Для орків Оргріммар — утілення їхньої спокути: тут вони скинули спадок демонічного прокляття, щоб будувати чесне, незалежне майбутнє."},sec={{t="Твердиня в камені",b="Після Третьої війни й перемоги на горі Гіджал Вождь Тралл привів свій уцілілий народ на південь, щоб заснувати постійну батьківщину в Дуротарі. Угніздившись у природній перепоні з прямовисних гірських круч, Оргріммар був збудований так, щоб витримати облогу: шпичасті дерев'яні частоколи, кам'яні сторожові вежі та глибокі печери, вирубані в горі. Зведена спільно з тролями Темного Списа, тауренськими каменярами й гоблінськими інженерами, твердиня перетворила безлюдну пустку на неприступний бастіон сили."},{t="Серце Нової Орди",b="Звільнені від демонічної жаги крові, що колись їх сковувала, орки збудували Оргріммар як маяк честі, спільноти й виживання. Нині, у 25 році після відкриття Темного Порталу, місто дає притулок не лише оркам і тролям Темного Списа, а й вітає посланців тауренів із Малгору та посланців нових союзників — Відступників. У його укріплених каньйонах шамани навчають нове покоління рівноваги предків, а ветерани б'ються на гладіаторських аренах, гартуючи військо, що береже крихкий мир Калімдору."}},fp="9,274,25.514.0,22.488.0,29.268.0,26.292.0,32.271.0,34.176.0"}
P.entries["subzone:palemane-rock"] = {n="Скеля Пейлмейн",s="Скеля Пейлмейн — печера й стійбище в західних горах Малгору. Це головна твердиня войовничого племені гнолів Пейлмейн, що постійно дошкуляє й загрожує сусіднім тауренам із Села Бладгуф.",h="Скеля Пейлмейн — печера й стійбище в західних горах Малгору.",kw={"скеля пейлмейн","гноли","печера","малгор","село бладгуф"},ang={["faction:Horde"]="Убезпечити кордони Малгору від таких місцевих шкідників, як гноли Пейлмейн, конче потрібно, щоб батьківщина тауренів лишалася безпечною й міцною.",["race:Tauren"]="Гноли Пейлмейн, що засіли в цих західних печерах, — постійна скалка в боці вашого народу: вони загрожують дичині й необачним мандрівникам на пасовищах Малгору."},sec={{t="Твердиня гнолів",b="Скеля Пейлмейн лежить на західному краю трав'янистих рівнин Малгору: розлоге стійбище просто неба перед глибокою тінистою печерою, вирубаною в гірському схилі. Гноли Пейлмейн оголосили своїми і нутро печери, і передгір'я одразу за нею. Ворожі й ревниві до своєї території, вони люто боронять лігво й нападають на мисливців, подорожніх і розвідників, що підходять до їхнього скелястого притулку занадто близько."}},fp="13,242,18.449.0,22.113.0,27.172.0,44.172.0"}
P.entries["subzone:pools-of-arlithrien"] = {n="Озерця Арлітрієну",s="Озерця Арлітрієну — скупчення відлюдних джерел у західному Тельдрассилі, одразу на південь від брами Дарнасуса. Колись тихий притулок довкола священного місячного колодязя, це місце занепало й стало небезпечним, коли на нього посунули місцева живність і ворожі фурболги-Вузлошкіри.",h="Озерця Арлітрієну — скупчення відлюдних джерел у західному Тельдрассилі, одразу на південь від брами...",kw={"озерця арлітрієну","місячний колодязь","джерела","дарнасус","фурболги","вузлошкіри","тельдрассил"},ang={["class:Druid"]="Друїди, що вивчають розлади Тельдрассила, бачать у некерованій живності й занедбаному місячному колодязі ще один знак, що Великому Дереву бракує справжнього благословення природи.",["race:NightElf"]="Покинутий святий місячний колодязь так близько до Дарнасуса — тривожне нагадування нічним ельфам про скверну й розлад, що повзуть Тельдрассилом."},sec={{t="Неспокійне святилище",b="Озерця Арлітрієну в тінистому гіллі на південь від Дарнасуса задумували як тихе місце природної гармонії. У їхньому серці — кам'яний місячний колодязь, посудина для вод, сповнених ласки Елуни. Та попри близькість до столиці нічних ельфів святилище стало небезпечним. Збурені звірі бродять мілководдям, а невпинна ворожість витіснених фурболгів-Вузлошкірів змусила нічних ельфів облишити звичний догляд за місцем, і мирне диво опинилося в тіні недуги, що охоплює острів."}},fp="19,305,20.549.0,42.146.0,36.216.0,45.190.0,62.185.0"}
P.entries["subzone:ravaged-caravan"] = {n="Сплюндрований Караван",s="Сплюндрований Караван — димуче згарище на північно-східному березі Озера Кам'яного Бика в Малгорі. Колись це була валка з припасами для копалень Наглядача Фіззпрокета, та її перехопили й знищили місцеві таурени, сповнені рішучості покласти край гоблінському визиску їхньої батьківщини.",h="Сплюндрований Караван — димуче згарище на північно-східному березі Озера Кам'яного Бика в Малгорі.",kw={"сплюндрований караван","озеро кам'яного бика","венчурна компанія","фіззпрокет","гобліни","малгор"},ang={["class:Druid"]="Чорний дим, що душить берег Озера Кам'яного Бика, — суворе нагадування про безоглядну шкоду, якої гоблінські машини завдають природній рівновазі.",["race:Tauren"]="Обвуглені вози — це негайна й рішуча відмова вашого народу дозволити чужинським промисловим синдикатам плюндрувати священні пасовища Малгору."},sec={{t="Дим над Озером Кам'яного Бика",b="Сплюндрований Караван на пагорбі над Озером Кам'яного Бика — свідчення ранньої сутички між тауренами Села Бладгуф і Венчурною Компанією, що насувалася на край. Валка везла шахтарське спорядження, креслення й обладнання на розкопки Наглядача Фіззпрокета, але тауренські захисники відрізали її й розтрощили, перш ніж вона дісталася мети. Попри розгром, уперті вцілілі з Венчурної Компанії досі чіпляються за розбиті вози й тліючі ящики, ревно стережучи рештки вантажу."}},fp="15,284,25.507.0,30.244.0,28.156.0,30.162.0,63.237.0"}
P.entries["subzone:razor-hill"] = {n="Гострий Пагорб",s="Гострий Пагорб — головне поселення Орди в центральному Дуротарі, що лежить на стратегічному перехресті між Долиною Випробувань, Пустками та Оргріммаром. Збудоване довкола помітних укріплених казарм, воно є плацдармом і навчальним осередком для молодих воїнів з орків і тролів, які випробовують себе в суворій глушині.",h="Гострий Пагорб — головне поселення Орди в центральному Дуротарі, що лежить на стратегічному перехресті між...",kw={"гострий пагорб","поселення","казарми","орки","перехрестя","дуротар","орда"},ang={["faction:Horde"]="Як перше справжнє містечко на шляху після тренувальних угідь, Гострий Пагорб — стартовий майданчик для молодих солдатів Орди, що доводять вірність новій державі Тралла.",["race:Orc"]="Гострий Пагорб — свідчення нового життя, яке орки вирвали собі в Дуротарі, проміняв демонічне рабство на міцні землянки й тяжко здобуте виживання."},sec={{t="Серце Дуротару",b="Збудований на важливому географічному вузлі, Гострий Пагорб сполучає північний Дуротар із прибережними поселеннями на півдні та розлогими рівнинами Пусток за Річкою Південної Люті. Поселення, над яким височіють казарми з каменю та дерева й класичні орківські землянки, заклали ще на зорі заснування Дуротару. Невдовзі після Третьої війни людські війська з Кул Тірасу заманили Орду в засідку саме тут під виглядом зустрічі посланців — напад зірвався, бо замість Тралла пішов Рекссар. Нині застава повністю укріплена проти нових вторгнень із узбережжя."},{t="Варта на порубіжжі",b="Під командуванням бувалих офіцерів, як-от Ґар'Ток, Гострий Пагорб координує місцеву оборону проти кількох навислих загроз. Рештки людської морської піхоти досі утримують Фортецю Тіраґард на східному узбережжі, а войовничі племена шипогривів і гарпій дошкуляють місцевим шляхам постачання. Значно підступніша присутність культу Палаючого Клинка, чиї потаємні обряди та осквернені агенти в сусідніх скелях пильно вистежують і викорінюють слідчі на кшталт Орґніла Соулскара."}},fp="10,337,16.588.0,21.469.0,40.259.0,49.233.0,28.164.0,48.210.0"}
P.entries["subzone:razor-hill-watchtower"] = {n="Сторожова вежа Гострого Пагорба",s="Ця міцна застава на червоних кам'яних кручах над Гострим Пагорбом служить постом раннього попередження для серця Дуротару. Фурл Скорнброу пильно стежить за запиленими рівнинами й узбережжям, оберігаючи поселення внизу від загроз, що насуваються.",h="Ця міцна застава на червоних кам'яних кручах над Гострим Пагорбом служить постом раннього попередження для...",kw={"сторожова вежа гострого пагорба","вежа","дозор","фурл скорнброу","гострий пагорб","дуротар"},ang={["class:Hunter"]="Висока точка дає безперешкодний огляд навколишніх скель — ідеально для спостерігачів, що вистежують здобич і пересування звірів по Дуротару.",["faction:Horde"]="Для молодих воїнів і розвідників, що виходять із Долини Випробувань, сторожова вежа — підбадьорливий орієнтир, який свідчить про безпеку й силу молодої Орди."},sec={{t="Очі над Дуротаром",b="Збудована з грубого дерева й залізного каркаса, Сторожова вежа Гострого Пагорба охороняє поселення Гострий Пагорб і навколишні каньйони. Дуротару невпинно загрожують морські піхотинці Кул Тірасу на східному березі, шипогриви-нападники, що нишпорять чагарниками, та культисти Палаючого Клинка, які чаяться в сусідніх скелях. З цієї піднесеної точки на гребені дозорець помічає бойові загони, димові сигнали та вторгнення задовго до того, як вони дістануться брами поселення."}},fp="21,275,17.485.0,49.259.0,26.186.0,38.184.0"}
P.entries["subzone:razormane-grounds"] = {n="Угіддя Гостроманів",s="Угіддя Гостроманів — передовий табір шипогривів Гостроманів, що пробиваються зі Пусток на схід, у центральний Дуротар. Забитий колючими чагарями й обгризеними тушами дичини, цей наїжачений табір є передовою у нескінченній війні шипогривів з орками Оргріммара.",h="Угіддя Гостроманів — передовий табір шипогривів Гостроманів, що пробиваються зі Пусток на схід, у центральний...",kw={"угіддя гостроманів","шипогриви","гостромани","табір","колючки","річка південної люті","дуротар"},ang={["faction:Horde"]="Тримати Угіддя Гостроманів під контролем вкрай важливо, щоб убезпечити дороги й шляхи постачання між Пустками та столицею Орди — Оргріммаром.",["race:Orc"]="Для орків Дуротару Угіддя Гостроманів — невідступна загроза в самому серці нової батьківщини, тож молоді воїни доводять свою вправність, винищуючи шипогривів."},sec={{t="Скалка в боці Дуротару",b="Розкинувшись під червоними скелями центрального Дуротару, Угіддя Гостроманів позначають найдальшу східну межу просування шипогривів зі Пусток. Обплутаний густими колючками й оточений вибіленими кістками, табір — постійна небезпека для мандрівників уздовж Річки Південної Люті. Його очолюють такі постаті, як Капітан Флет Таск із бойової варти та Геолорд Моттл, що влаштовують набіги на сусідні орківські поселення й обози. Попри регулярні патрулі з Гострого Пагорба та сусідніх застав, Гостромани невтомно поповнюють лави, проростаючи з колючок швидше, ніж Орда встигає їх викорчувати."}},fp="17,305,25.653.0,30.148.0,39.180.0,48.140.0,44.174.0"}
P.entries["subzone:razorwind-canyon"] = {n="Каньйон Гострого Вітру",s="Каньйон Гострого Вітру — звивиста скеляста балка, розділена головною дорогою між Гострим Пагорбом і Оргріммаром. Заселений войовничими гарпіями Пилового Вітру, каньйон становить постійну небезпеку для мандрівників, що прямують на північ, до столиці Орди.",h="Каньйон Гострого Вітру — звивиста скеляста балка, розділена головною дорогою між Гострим Пагорбом і...",kw={"каньйон гострого вітру","гарпії","пиловий вітер","дорога","гострий пагорб","оргріммар","дуротар"},ang={["faction:Horde"]="Очистити Каньйон Гострого Вітру від гарпій Пилового Вітру вкрай важливо, щоб головний шлях між Гострим Пагорбом і столицею Оргріммаром лишався безпечним для гінців і новобранців.",["race:Orc"]="Гарпії, що гніздяться просто біля центральної дороги Дуротару, — образа для безпеки орківської батьківщини, тож молодим воїнам доводиться проріджувати їхні лави."},sec={{t="Загроза на великій дорозі",b="Каньйон Гострого Вітру обступає центральну артерію, що з'єднує Гострий Пагорб з Оргріммаром, прорізаючи шляхи і в східні кручі, і в західні чагарники в бік Ферми Тор'крена. Каньйон — місце гніздування гарпій Пилового Вітру, територіальних створінь, які без вагань нападають на мандрівників, що підійдуть надто близько до їхніх сідал. Їхня присутність так близько до торгових шляхів столиці робить зачистку цих балок постійною потребою для захисників Дуротару."},{t="Проходи та яри",b="Окрім гнізд гарпій, звивини Каньйону Гострого Вітру служать прихованими шляхами крізь червоні скелясті пагорби Дуротару. Східне відгалуження глибоко врізається в скелі й через печеру веде до Яру Сухої Балки. Оскільки гарпії сидять на високих сідалах і спускаються зграями, необачні шукачі пригод, що йдуть цими проходами, легко можуть опинитися в оточенні й бути порубаними."}},fp="16,239,25.462.0,20.394.0,34.240.0,40.189.0,45.204.0,45.160.0"}
P.entries["subzone:red-rocks"] = {n="Червоні Скелі",s="Червоні Скелі — висока піщаникова круча в північно-східному Малгорі, священне прабатьківське поховальне місце тауренів. Тут полеглих звитяжців ввіряють Земній Матері через очисне полум'я, а молоді сміливці підіймаються на тихі висоти шукати мудрості предків.",h="Червоні Скелі — висока піщаникова круча в північно-східному Малгорі, священне прабатьківське поховальне місце...",kw={"червоні скелі","поховання","предки","шипогриви","тандер блаф","малгор","осквернення"},ang={["class:Shaman"]="Вітер несе скорботу неупокоєних духів, яких потривожило осквернення шипогривів, і закликає до шаманських обрядів, щоб відновити рівновагу стихій і спокій предків.",["race:Tauren"]="Для вашого народу Червоні Скелі — священна земля. Те, що мерзенні шипогриви риються серед погребальних вогнищ ваших шанованих предків, — відверте блюзнірство, яке вимагає очищення."},sec={{t="Освячене каміння й погребальні вогнища предків",b="Багряні скельні утворення Червоних Скель, що здіймаються над рівнинами північно-східного Малгору, позначають священний поріг між світом живих і наступним. Тауренська традиція береже цю урочисту землю для найдоблесніших героїв — вождів, захисників і звитяжців, що віддали життя, засновуючи й боронячи Тандер Блаф. Їхні рештки ввіряють небу й землі на обрядових вогнищах, повертаючи духи Земній Матері та Небесному Батькові. Та це й місце духовного початку: тут молоді таурени завершують обряди посвяти, вшановуючи могили предків і спілкуючись із вітром."},{t="Осквернення шипогривами",b="Одвічний спокій Червоних Скель розбили шипогриви Щетиноспинних. Виповзши зі своїх лігв, ці агресивні падложери заполонили піщаникові уступи й споганили погребальні вогнища предків нечистотами. Таке блюзнірство глибоко ображає духовні традиції Тандер Блафа. Шамани й хранителі переказів тепер кличуть на допомогу, щоб очистити кручі, вигнати Щетиноспинних і повернути святість місцю спочинку мертвих."}},fp="9,293,35.621.0,24.440.0,33.290.0,36.229.0,27.224.0,35.216.0"}
P.entries["subzone:ridgepoint-tower"] = {n="Вежа Ріджпойнт",s="Вежа Ріджпойнт — укріплений вартовий пост, що стереже східне порубіжжя Лісу Елвінн. Її тримають вартові Стормвінда, і вона служить оплотом раннього попередження проти ворожих вторгнень, що загрожують серцю королівства. Її вартові пильнують небезпечні проходи до сусідніх диких земель.",h="Вежа Ріджпойнт — укріплений вартовий пост, що стереже східне порубіжжя Лісу Елвінн.",kw={"вежа ріджпойнт","сторожова вежа","вартові стормвінда","східний кордон","редрідж","сутінколісся","ліс елвінн"},ang={["class:Warrior"]="І солдати, і найманці можуть шанувати стоїчну рішучість вартових, що тримають таку відкриту прикордонну заставу проти ворогів з усіх боків.",["faction:Alliance"]="Для мандрівників Альянсу Вежа Ріджпойнт — підбадьорливий маяк безпеки й порядку перед переходом у небезпечні перевали Редріджу чи на примарні дороги Сутінколісся."},sec={{t="Сторож східного кордону",b="Вежа Ріджпойнт, що стоїть на чатах на височині східного Лісу Елвінн, позначає останній бастіон прямої влади Стормвінда, перш ніж починаються неприборкані нетрі. Розквартирований тут гарнізон невпинно стежить за навколишніми долинами та дорогами. Поки напруга на континенті зростає, ця кам'яна сторожова вежа дбає, щоб загрози, які насуваються, помічали й зупиняли, перш ніж вони зможуть зашкодити фермам і поселенням ближче до Нортширу та Ґолдшира."},{t="Загрози на кожному обрії",b="Вежа Ріджпойнт зазнає тиску з кількох фронтів водночас. На сході лежать Гори Редріджу — домівка войовничих зграй гнолів і орків-нападників із клану Блекрок, які випробовують людську оборону. За південною річкою височіє похмурий ліс Сутінколісся з його хижими жахіттями нежиті. Ближче до дому розбійники Братства Дефіас нишпорять дикими таборами, прагнучи скористатися будь-якою прогалиною в лінії оборони варти."}},fp="16,309,30.471.0,24.421.0,25.209.0,32.143.0,45.206.0,34.155.0"}
P.entries["subzone:rocktusk-farm"] = {n="Ферма Кам'яного Ікла",s="Ферма Кам'яного Ікла — невелике свиняче ранчо на півночі Дуротару, трохи далі дорогою за брамою Оргріммара. Притулена до укріплених підступів до столиці, садиба постачає мешканцям міста конче потрібне м'ясо та харчі.",h="Ферма Кам'яного Ікла — невелике свиняче ранчо на півночі Дуротару, трохи далі дорогою за брамою Оргріммара.",kw={"ферма кам'яного ікла","свині","ферма","харчі","оргріммар","кулінарія","дуротар"},ang={["faction:Horde"]="Свині, вирощені тут, просто за столицею, — важливий харч для воїнів і робітників, що служать в Оргріммарі.",["profession:Cooking"]="Свиней із цієї ферми цінують кухарі Орди, яким потрібні свіжа свинина, реберця та смачні шматки для смаження."},sec={{t="Харчі для столиці",b="Вирвана в посушливій землі Дуротару, Ферма Кам'яного Ікла розводить витривалих свиней, пристосованих до суворого пустельного клімату. Через горезвісно сухий і кам'янистий ґрунт Дуротару вирощувати збіжжя важко, тож свинарські ферми — життєво важлива нитка, що годує дедалі численніше населення Оргріммара. Притулена до укріплених околиць столиці, садиба тішиться безпекою, якої рідко знайдеш у суворих нетрях червоних каньйонів."}},fp="13,241,26.449.0,31.159.0,31.140.0,34.187.0"}
P.entries["subzone:rolling-plains"] = {n="Хвилясті Рівнини",s="Хвилясті Рівнини розкинулися на південних просторах Малгору, між Селом Бладгуф і кордоном Пусток. На цих обвітрених пасовищах буяють стада дичини, та вони ж вимагають постійної пильності через ватаги кентаврів, що нишпорять довкола, і агресивних гарпій.",h="Хвилясті Рівнини розкинулися на південних просторах Малгору, між Селом Бладгуф і кордоном Пусток.",kw={"хвилясті рівнини","малгор","кентаври","гарпії","полювання","кодо","довгоступи"},ang={["class:Hunter"]="Із рясними стадами кодо, довгоступів, вовків і пум Хвилясті Рівнини — ідеальна дика місцина, щоб відточувати вміння слідопита, запасатися харчем і приборкувати перших звірів-супутників.",["race:Tauren"]="Хвилясті Рівнини дають щойно об'єднаним племенам життєво важливі мисливські угіддя, та вторгнення одвічних ворогів-кентаврів так близько до Села Бладгуф робить охорону цього південного коридору питанням виживання племені."},sec={{t="Серце південного Малгору",b="Простягаючись на південь від Села Бладгуф до природних земляних воріт у Пустки, Хвилясті Рівнини втілюють безмежні простори тауренської батьківщини. Край кишить дичиною, без якої племенам не вижити: тут водяться степові вовки, стада кодо, рівнинні пуми й прудкі довгоступи. Для молодих мисливців, що доводять свою вартість старійшинам, ці розлогі савани — незамінний полігон, де випробовують уміння вистежувати, терпіння й шану до природи."},{t="Небезпеки, що насуваються",b="Попри природне кільце круч, що укріплює Малгор, Хвилясті Рівнини лишаються надзвичайно вразливими до зовнішніх загроз. Це єдиний кордон, де агресивним вершникам-кентаврам вдалося пробитися крізь оборонні рубежі й дошкуляти подорожнім і мисливським загонам. На додачу в східних кручах гніздиться зграя хижих гарпій Вітрофурій, що кидаються згори на заблукалу дичину й беззахисні кочові табори."}},fp="14,296,25.493.0,19.418.0,48.256.0,53.268.0,49.179.0,42.122.0"}
P.entries["subzone:rut-theran-village"] = {n="Селище Рут'теран",s="Селище Рут'теран — прибережна пристань біля південного підніжжя Тельдрассила. Головна морська гавань Дарнасуса, вона з'єднує відлюдне Світове Дерево з материковим Калімдором поромом і маршрутами гіпогрифів.",h="Селище Рут'теран — прибережна пристань біля південного підніжжя Тельдрассила.",kw={"селище рут'теран","пристань","пором","гіпогрифи","портал","дарнасус","тельдрассил","обердайн"},ang={["class:Druid"]="Друїди, що проходять через Селище Рут'теран, можуть сісти на гіпогрифа й полетіти просто через північний Калімдор до священного святилища — Місячного Гаю.",["race:NightElf"]="Для молодих нічних ельфів, що залишають Тельдрассил допомагати Альянсу, Селище Рут'теран — останнє прощання з кроною Світового Дерева перед відплиттям на материковий Калімдор."},sec={{t="Брама до Світового Дерева",b="Селище Рут'теран край води, під височенним Тельдрассилом, — поріг між столицею нічних ельфів і широким світом. Поки Дарнасус спочиває в гіллі високо вгорі, Рут'теран дає господарську основу, потрібну, щоб його утримувати. Під деревами вигинається містичний портал, що вмить переносить подорожніх між берегом і Дарнасусом. Для морських мандрівок із пристані селища ходить пором просто до Обердайна на материку, на Темному Узбережжі, а наставники польотів доглядають сідала навчених гіпогрифів."}},fp="18,232,25.597.0,36.205.0,37.144.0,64.242.0,29.199.0"}
P.entries["subzone:scarlet-monastery"] = {n="Багряний Монастир",s="Багряний Монастир, що стоїть на північно-східних пагорбах Галявин Тірісфалю, колись був мирним осередком науки й богослужіння Церкви Святого Світла. Після падіння Лордерону він став добре укріпленою твердинею фанатичного Багряного Хрестового Походу. Кожного, хто наближається без червоних барв, мають за заразного носія чуми і страчують на місці.",h="Багряний Монастир, що стоїть на північно-східних пагорбах Галявин Тірісфалю, колись був мирним осередком...",kw={"багряний монастир","багряний хрестовий похід","моґрейн","вайтмейн","монастир","собор","тірісфаль"},ang={["class:Paladin"]="Колись цей комплекс готував паладинів під проводом Срібної Длані, тож його переродження на нетерпимий бастіон фанатизму — гірке видовище для вірних святих воїнів.",["faction:Horde"]="Монастир стоїть просто на порозі Андерсіті, тож його добре озброєні хрестоносці — діяльна, смертельна загроза землям Відступників."},sec={{t="Від святині до твердині",b="До Третьої війни цей комплекс знали просто як Старий Монастир. Під опікою духівництва Лордерону й покровительством шляхетних домів він був важливим осередком богословських студій, священних архівів і вишколу паладинів. Коли Королівство Лордерон упало перед Погибеллю, уцілілі рештки Срібної Длані повернули собі це місце як передовий бастіон для ударів по нежиті, що зайняла Столицю — стольне місто королівства. Коли ж захисники виродилися в ревний Багряний Хрестовий Похід, вони укріпили обитель, обернувши її мирні бібліотеки, сади й собор на озброєну цитадель."},{t="Бастіон фанатизму",b="Поділений на чотири окремі крила — осквернений цвинтар, простору бібліотеку, збройову палату й великий собор, — Монастир нині вміщує величезний гарнізон під командою Багряного командира Моґрейна та Верховної інквізиторки Вайтмейн. Тутешні хрестоносці бачать у всіх чужинцях — живих чи нежиті, Альянсі чи Орді — носіїв чуми. Поки Відступники прагнуть знищити гарнізон, що загрожує самому їхньому порогу, провід Альянсу дедалі більше вважає жорстокий екстремізм Хрестового Походу небезпечним збоченням Світла."}},fp="17,382,28.595.0,23.524.0,34.281.0,53.264.0,42.212.0,39.286.0"}
P.entries["subzone:scarlet-watch-post"] = {n="Багряна Сторожова Застава",s="Багряна Сторожова Застава — відособлена сторожова вежа на скелястих пагорбах північно-східних Галявин Тірісфалю, одразу на північ від Багряного Монастиря. Її тримає пильний гарнізон хрестоносців, і єдине її призначення — берегти вразливий північний фланг монастиря від обхідних нападів.",h="Багряна Сторожова Застава — відособлена сторожова вежа на скелястих пагорбах північно-східних Галявин...",kw={"багряна сторожова застава","багряний хрестовий похід","сторожова вежа","багряний монастир","капітан мелраш","тірісфаль"},ang={["faction:Horde"]="Хрестоносці вважають усіх чужинців — живих чи мертвих — зараженими носіями нежиті, тож ця сторожова застава — суто ворожа земля для будь-яких мандрівників Орди, що зважаться на ці пагорби.",["race:Undead"]="Для Відступників Багряний Хрестовий Похід — смертельна загроза просто на порозі Андерсіті; зачистка таких відособлених веж розриває мережу зв'язку фанатиків і убезпечує північний Тірісфаль."},sec={{t="Охорона північного підступу",b="Багряна Сторожова Застава на скелястих висотах за Багряним Монастирем — важливий бастіон раннього попередження для фанатиків унизу. Поки південна дорога до монастирської брами людна й добре укріплена, скелясті кручі вздовж північного узбережжя Тірісфалю дають спокусливий обхідний шлях для диверсантів. Щоб закрити цю сліпу пляму, Багряний Хрестовий Похід тримає цю укріплену кам'яну вежу — одну з кількох застав хрестоносців, розкиданих по Галявинах Тірісфалю. Під суворим командуванням Капітана Мелраша змішаний загін неофітів, передових бійців і побожних братів-ченців невпинно пильнує кручі, щоб ні Погибель, ні Відступники не заскочили орден зі спини."}},fp="18,297,30.721.0,46.327.0,36.192.0,66.241.0"}
P.entries["subzone:scuttle-coast"] = {n="Дріботливе Узбережжя",s="Дріботливе Узбережжя — побитий хвилями східний берег Дуротару між Гострим Пагорбом і Фортецею Тіраґард. Скелястий пляж усіяний затонулими уламками флоту Кул Тірасу під проводом Адмірала Деліна Праудмура, тож це жваве місце для збирачів Орди й невідступне нагадування про недавню морську війну.",h="Дріботливе Узбережжя — побитий хвилями східний берег Дуротару між Гострим Пагорбом і Фортецею Тіраґард.",kw={"дріботливе узбережжя","уламки","кораблі","кул тірас","праудмур","краби","макрури","дуротар"},ang={["faction:Horde"]="Розбиті корпуси, якими всіяний цей пляж, стоять суворими пам'ятниками обороні Дуротару від загарбницького флоту Деліна Праудмура.",["profession:Engineering"]="У затоплених трюмах Альянсу вздовж берега лишилися покинуті гномські пристрої, металобрухт і хитромудрі механізми, що так і просяться на розбирання й вивчення."},sec={{t="Уламки флоту",b="Дріботливе Узбережжя, що тягнеться вздовж східного краю Дуротару до Великого Моря, набуло свого похмурого вигляду під час вторгнення Великого Адмірала Деліна Праудмура. Коли флот Кул Тірасу напав на молоду державу Дуротар, люті бої з Ордою загнали чимало людських кораблів на зубчасті мілини й розтрощили їх на тріски. Нині берег завалений порослими мушлями колодами, поламаним такелажем і врятованими бочками з вантажем. Для сусідніх таборів Гострого Пагорба узбережжя — водночас і невідступна загроза безпеці, і цінне джерело віднайдених припасів та покинутих механізмів Альянсу."},{t="Збирачі та припливи",b="Назва Дріботливого Узбережжя нагадує не лише про затоплені кораблі, навмисне пущені на дно чи посаджені на мілину під час боїв, а й про рої крабів та макрур, які порпаються в гниючому мотлосі. Хоч прибережна звірина й небезпечні припливи відлякують випадкових мандрівників, збирачі Орди час від часу прочісують уламки, щоб дістати цінне спорядження, зокрема гномські технічні деталі, покинуті в трюмах затонулих кораблів."}},fp="13,315,21.634.0,20.450.0,41.229.0,35.198.0,46.153.0,36.187.0"}
P.entries["subzone:sen-jin-village"] = {n="Село Сен'джин",s="Село Сен'джин — прибережне поселення на південних берегах Дуротару, притулок для тролів Темного Списа. Засноване Вождем Вол'джином після того, як його народ вигнали з прадавнього дому на Островах Відлуння, селище вшановує його полеглого батька, знахаря Сен'джина. Нині це крихкий прихисток, зосереджений на виживанні, травництві й поверненні вкраденого.",h="Село Сен'джин — прибережне поселення на південних берегах Дуротару, притулок для тролів Темного Списа.",kw={"село сен'джин","тролі","темний спис","вол'джин","притулок","травництво","острови відлуння","дуротар"},ang={["profession:Herbalism"]="Село — важливий початковий осередок природної медицини, оточений прибережним мирноцвітом, срібнолистом і земнокоренем, якими місцеві знахарі лікують отруту й прокляття.",["race:Troll"]="Для тролів Темного Списа, що виходять із Долини Випробувань, цей притулок — живе серце їхнього вигнаного народу, що береже пам'ять про втраченого вождя й незгасний біль зради Залазана."},sec={{t="Берег біженців",b="Коли темний знахар Залазан зрадив Темний Спис і захопив владу над Островами Відлуння, Вождь Вол'джин був змушений перевести вцілілих через протоку на материк Дуротару. Там, під прибережними скелями, з видом на воду, вони поставили грубі хатини й заснували Село Сен'джин. Поселення носить ім'я батька Вол'джина — шанованого старійшини, що пожертвував собою під час Третьої війни, рятуючи свій народ від прибережних мурлоків. Попри тісний союз з Ордою Тралла, тутешні тролі живуть у тіні вигнання, щодня дивлячись через мілини на втрачений дім."},{t="Очі на острови",b="Щоденне життя Села Сен'джин обертається довкола підготовки й оборони. Між набігами місцевих кентаврів, лютими морськими тварюками й насланнями Залазана, що сягають через море, селяни чимало покладаються на трав'яні ліки та варіння міцних алхімічних настоянок. Поки Вол'джин керує ширшою обороною племені зі столиці Орди, місцеві шамани, мисливці та розвідники збираються тут, щоб залучати нових мандрівників, які виходять із Долини Випробувань. Їхня мета ясна: зібрати ресурси, захистити південний фланг Дуротару й підготувати неминуче падіння зрадника Залазана."}},fp="15,393,15.634.0,17.569.0,49.282.0,16.271.0,53.258.0,50.247.0"}
P.entries["subzone:shadow-grave"] = {n="Тіньова Могила",s="Тіньова Могила — кам'яний склеп на вершині похилого цвинтаря над Похоронним Подзвоном у Галявинах Тірісфалю. Це фізична точка пробудження, де щойно звільнені Відступники скидають заціпеніння смерті й послаблену владу, яку над ними мав Король-Ліч.",h="Тіньова Могила — кам'яний склеп на вершині похилого цвинтаря над Похоронним Подзвоном у Галявинах Тірісфалю.",kw={"тіньова могила","склеп","пробудження","похоронний подзвін","гробар мордо","відступники","тірісфаль"},ang={["race:Undead"]="Кожен шукач пригод з-поміж Відступників починає свою путь на холодних кам'яних плитах цього склепу, розплющуючи очі на похмуру дійсність нежиття й вільної волі."},sec={{t="Колиска Відступників",b="Тіньова Могила, схована в скелястих передгір'ях за Могилами Похоронного Подзвону, — простий кам'яний мавзолей із надзвичайним призначенням. У його вологих склепіннях трупи, підняті для безтямної служби Погибелі, поступово пробуджуються до вільної волі. Під пильним оком доглядачів на кшталт Гробаря Мордо ці щойно звільнені мерці підводяться з кам'яних плит і роблять перші тремтливі кроки у світ, що їх зневажає, рушаючи стежкою вниз до Похоронного Подзвону, щоб присягнути Королеві Баньші."}},fp="12,244,22.531.0,34.255.0,34.217.0,37.174.0"}
P.entries["subzone:shadowglen"] = {n="Тінедол",s="Тінедол — відлюдна сутінкова долина в північно-східному гіллі Тельдрассила. Над нею височіє велике дерево-курган Алдрассил; це безпечний прихисток, де молоді нічні ельфи роблять перші кроки на службі, перш ніж вирушити в широкий світ.",h="Тінедол — відлюдна сутінкова долина в північно-східному гіллі Тельдрассила.",kw={"тінедол","алдрассил","стартова зона","нічні ельфи","тельдрассил","печера тіньової нитки","долина"},ang={["faction:Alliance"]="Розташований високо в гіллі Тельдрассила й далеко за охоронюваними портами, Тінедол — одна з найзахищеніших і найвідособленіших долин-святилищ Альянсу.",["race:NightElf"]="Кожен молодий нічний ельф починає свою діяльну путь тут, серед захищеного коріння Алдрассила, отримуючи перші благословення й настанови, перш ніж зустріти небезпеки Калімдору."},sec={{t="Захищена колиска",b="Тінедол, схований у північно-східній кроні Тельдрассила, оточений високими хребтами, що відгороджують його від решти світу. Залита вічними сутінками долина зосереджена довкола Алдрассила — велетенського дерева-кургану, у чиєму видовбаному стовбурі живуть старійшини, жриці й наставники молодих нічних ельфів, що починають навчання. Єдиний шлях із долини веде на південь вузьким гірським проходом до Села Зоряного Вітерця й Доланаара, тож Тінедол — одне з найзахищеніших самою природою й наймирніших святилищ Світового Дерева."},{t="Тіні підкрадаються",b="Попри тихе усамітнення, Тінедол не зовсім вільний від небезпек. На крайньому північному заході лежить Печера Тіньової Нитки — темна печера, що кишить отруйними павуками, які постійно загрожують тихому гаю. Навіть на незайманих гілках Тельдрассила потрібна пильність, і захисникам-початківцям доручають відганяти набридливу гидь і дику живність, перш ніж вирушати в ширші простори гілля."}},faq={{q="Що таке Тінедол?",a="Тінедол — захищений стартовий гай нічних ельфів у північно-східній частині Тельдрассила. Це мирний, відлюдний прихисток довкола великого дерева Алдрассил, де новачки навчаються в наставників, перш ніж вирушити мандрувати Світовим Деревом.",al={"що це за місце","лор тінедолу","про тінедол"}},{q="Що за величезне дерево в центрі долини?",a="Це Алдрассил — дерево-курган, що становить серце Тінедолу. Його видовбане нутро править за оселю громади й осередок навчання, де нічні ельфи-новачки зустрічають наставників класів, учителів і доглядачів.",al={"велике дерево в тінедолі","алдрассил","дерево тінедолу"}},{q="Які загрози є в Тінедолі?",a="Головна загроза — на північному заході, у Печері Тіньової Нитки: печера кишить отруйними павуками, що раз у раз виповзають у гай. Молодим захисникам доручають винищувати павуків і втихомирювати неспокійну місцеву живність.",al={"чому тут павуки","небезпеки тінедолу","печера тіньової нитки"}},{q="Як вийти з Тінедолу?",a="Тінедол повністю оточений хребтами, за винятком єдиної стежки на південь. Цей вузький гірський прохід веде на південь, до Села Зоряного Вітерця й поселення Доланаар.",al={"вихід із тінедолу","куди веде стежка","як вибратися з тінедолу"}}},fp="10,269,18.533.0,16.444.0,19.264.0,51.216.0,33.239.0,28.197.0"}
P.entries["subzone:shadowthread-cave"] = {n="Печера Тіньової Нитки",s="Печера Тіньової Нитки — волога печера в північно-західних скелях Тінедолу на Тельдрассилі. Здавна заселена тутешніми павуками Вебвуда, вона нещодавно стала небезпечно агресивною під владою їхньої матки — Ґітіісс Мерзенної.",h="Печера Тіньової Нитки — волога печера в північно-західних скелях Тінедолу на Тельдрассилі.",kw={"печера тіньової нитки","павуки","вебвуд","ґітіісс мерзенна","тінедол","тельдрассил","виводок"},ang={["class:Druid"]="Нестримна агресія виводку Вебвуда в Печері Тіньової Нитки — тривожний знак для друїдів, що природна гармонія Тельдрассила глибоко порушена.",["race:NightElf"]="Для молодих нічних ельфів очищення Печери Тіньової Нитки та вбивство Ґітіісс Мерзенної — одне з найперших випробувань у захисті священної домівки від скверни, що підкрадається."},sec={{t="Неспокійний виводок",b="Печера Тіньової Нитки в тінистій околиці Тінедолу здавна була природним лігвом велетенських павуків Тельдрассила. Раніше ці павуки тихо співіснували з молодим гіллям Світового Дерева. Та віднедавна їхня вдача стала люто територіальною. Товсті шари павутиння Вебвуда тепер душать кам'яні коридори, а агресивність виводку становить пряму загрозу молодим калдореям, що роблять перші кроки за межі Алдрассила."},{t="Ґітіісс Мерзенна",b="Головна загроза, що чаїться в найтемніших закутках печери, — Ґітіісс Мерзенна, жахлива матка виводку, чия лють далеко перевершує звичайних павуків Вебвуда. Вартових і друїдів нічних ельфів-новачків посилають до печери стримати навалу павуків і вбити Ґітіісс, щоб скверна, яка торкнулася живності Тельдрассила, не поглинула святилище Тінедолу цілком."}},fp="17,263,24.490.0,17.400.0,35.151.0,46.192.0,25.200.0,48.183.0"}
P.entries["subzone:shimmer-ridge"] = {n="Мерехтливий Хребет",s="Мерехтливий Хребет — суворе високогір'я на півночі Дун Мороґу, просто на захід від Брами Айронфорджа. Скелясті висоти, зайняті ворожими тролями Морозогривами, складаються з двох таборів, з'єднаних хистким мостом, і славляться як єдине місце, де можна зібрати потужне мерехтливе зілля.",h="Мерехтливий Хребет — суворе високогір'я на півночі Дун Мороґу, просто на захід від Брами Айронфорджа.",kw={"мерехтливий хребет","мерехтливе зілля","морозогриви","тролі","травництво","дун мороґ"},ang={["profession:Herbalism"]="Поки звичайні рослини ледве животіють у морозному кліматі Дун Мороґу, лише на Мерехтливому Хребті ростуть цінні кошики мерехтливого зілля, доглянуті серед таборів Морозогривів.",["race:Dwarf"]="Мерехтливий Хребет у тіні брами Айронфорджа — прикре нагадування про невідступну загрозу Морозогривів і небезпечне джерело добірного мерехтливого зілля для легендарного дворфського стауту."},sec={{t="Твердиня Морозогривів",b="Мерехтливий Хребет на скелястих схилах одразу на захід від величної брами Айронфорджа служить дієвим редутом племені тролів Морозогривів. Поділений на два табори обабіч провалля й з'єднаний дерев'яним прогоном, анклав пильно охороняють тролі-збирачі та їхні приручені гірські вепри. Близькість до головної дороги та дворфської столиці робить його постійною загрозою для мандрівників і гірських патрулів, які мусять повсякчас остерігатися зухвалих набігів із висоти."},{t="Ціна мерехтливого зілля",b="Окрім вигідного розташування, хребет славиться мерехтливим зіллям — рослиною, яку вирощують тролі Морозогриви. Місцеві дворфські пивовари цінують його для міцних, насичених високогірних елів, а деінде його так просто не збереш. Відважні горяни та молоді новобранці часто ризикують потрапити в засідку Морозогривів чи під ікла диких вепрів лише заради того, щоб зібрати свіжі кошики дорогоцінної рослини просто з тролячих грядок."}},fp="13,282,22.510.0,24.439.0,31.140.0,27.168.0,47.205.0,54.202.0"}
P.entries["subzone:shrine-of-the-dormant-flame"] = {n="Святиня Приспаного Полум'я",s="На найвищій вершині на північний захід від Долини Випробувань стоїть Святиня Приспаного Полум'я — відлюдне святилище, яке шанують шамани Орди. Під проводом його самотнього хранителя Телфа Джулама посвячувані здійснюють небезпечний підйом, щоб поспілкуватися зі стихією вогню й довести свою духовну майстерність.",h="На найвищій вершині на північний захід від Долини Випробувань стоїть Святиня Приспаного Полум'я — відлюдне...",kw={"святиня приспаного полум'я","шамани","вогонь","вогняний тотем","телф джулам","вершина","дуротар"},ang={["class:Shaman"]="Кожен молодий шаман з орків чи тролів має здійснити виснажливий підйом на цю скелю, щоб розпалити духовний зв'язок із вогнем і здобути свій Вогняний Тотем.",["faction:Horde"]="Схована в горах над Дуротаром, ця відлюдна святиня зберігає прадавні стихійні обряди, життєво важливі для духовного серця нової Орди."},sec={{t="Вершина випробування й полум'я",b="Щоб дістатися Святині Приспаного Полум'я, треба здолати вузьку звивисту стежку, що починається біля Річки Південної Люті на південно-західному краю її водозбору. Високо над червоними скелями Дуротару гірська вершина відкриває панорамний краєвид на околиці, та один хибний крок над прірвою означає певну смерть. У цьому тихому прихистку блукає Телф Джулам — самотній відлюдник, якому доручено наглядати за священними обрядами. Для майбутніх шаманів з орків і тролів, що проходять обряд Поклику Вогню, жаровня святині — горнило, де вони мають розпалити приспане вугілля жариною переможеного елементаля, доводячи, що здатні спілкуватися з руйнівними духами полум'я й шанувати їх."}},fp="27,297,27.723.0,49.218.0,39.242.0,19.211.0,41.245.0"}
P.entries["subzone:skull-rock"] = {n="Череп-скеля",s="Череп-скеля — печера в східних прибережних скелях Дуротару, просто на схід від Оргріммара. Вона служить укріпленим ковеном демонічного культу Палаючого Клинка просто під носом у столиці.",h="Череп-скеля — печера в східних прибережних скелях Дуротару, просто на схід від Оргріммара.",kw={"череп-скеля","печера","культисти","палаючий клинок","ґазз'уз","чорнокнижник","дуротар"},ang={["class:Warlock"]="Темні мистецтва, що практикують у Череп-скелі, показують нестримне поширення демонічного впливу, який Орда Тралла прагне викорінити й узяти під контроль.",["faction:Horde"]="Очистити Череп-скелю від культистів украй важливо, щоб убезпечити прибережні підступи до Дуротару й захистити Оргріммар від підривної діяльності зсередини."},sec={{t="Лігво культистів",b="Схована під скелями північно-східного Дуротару, Череп-скеля — одна з найнебезпечніших твердинь культу Палаючого Клинка в цьому краї. Темні культисти, орки-шанувальники Скверни та прикликачі збираються глибоко у звивистих тунелях, щоб практикувати демонічні мистецтва й плести змови проти молодої Орди. Осередок очолює небезпечний чорнокнижник Ґазз'уз, чиї дії безпосередньо загрожують сусідній брамі Оргріммара та мандрівникам на східному узбережжі."}},fp="10,195,17.478.0,19.183.0,24.118.0,40.175.0"}
P.entries["subzone:solliden-farmstead"] = {n="Хутір Соллідена",s="Хутір Соллідена — діюча людська гарбузова ферма в західних Галявинах Тірісфалю, одразу на північ від Похоронного Подзвону. Це рідкісний виняток у північному Лордероні: живі тутешні фермери, що пережили Чуму Нежиті й запекло тримаються своєї землі під тінню Багряного Хрестового Походу.",h="Хутір Соллідена — діюча людська гарбузова ферма в західних Галявинах Тірісфалю, одразу на північ від...",kw={"хутір соллідена","гарбузи","живі фермери","багряний хрестовий похід","нова чума","аптекар йогаан","тірісфаль"},ang={["faction:Alliance"]="Бачити живих людей, що обробляють землю Лордерона, — проблиск надії, та гірка правда в тому, що ці відрізані від світу вцілілі дивляться на громадян Стормвінда з тією ж ксенофобською ненавистю, що й на нежить.",["race:Undead"]="Для щойно воскреслих Відступників Хутір Соллідена — негайний урок реальної політики: живі лордеронці, що зневажають те, ким ви стали, слугують водночас сировиною для аптекарських отрут і потенційним південним плацдармом."},sec={{t="Непокірний залишок",b="Поки більша частина Лордерона обернулася на руїну й гниль, поля Хутора Соллідена досі дають здорові врожаї. Поселення веде свій родовід від тих століть, коли дворянські родини-переселенці зі Строму придбали піонерські наділи по всьому Тірісфалю. Сьогодні ці вцілілі люди-фермери живуть під пильним щитом Багряного Хрестового Походу, що патрулює з сусідньої вежі. Травмовані й замкнуті, вони боронять свою садибу з непохитною ворожістю, нападаючи на всіх чужинців, що наближаються, — і з Орди, і з Альянсу."},{t="Очі в Андерсіті",b="Для Відступників, що лише виходять із Похоронного Подзвону, Солліден — і загроза, і ресурс. Королівське Аптекарське Товариство накинуло оком на бездоганні гарбузи ферми як на першокласний органічний матеріал для випробувань своєї Нової Чуми. Тим часом офіцери Відступників на кшталт Вартового Смерті Сіммера посилають новобранців-початківців грабувати поля, красти ці гарбузи для Аптекаря Йогаана в Бріллі й провчити живих."}},fp="18,295,17.511.0,21.395.0,55.257.0,57.315.0,58.243.0,58.238.0"}
P.entries["subzone:spirit-rock"] = {n="Камінь Духів",s="Камінь Духів — священна скеля на суворих кручах над Долиною Випробувань у Дуротарі. Дістатися до неї можна звивистою стежкою, відомою як Прихована Стежка; це відлюдне святе місце, де посвячувані безпосередньо спілкуються зі стихійними силами землі.",h="Камінь Духів — священна скеля на суворих кручах над Долиною Випробувань у Дуротарі.",kw={"камінь духів","шамани","духи землі","сапта","прихована стежка","долина випробувань","дуротар"},ang={["class:Shaman"]="Камінь Духів — важливий обряд посвяти для молодих шаманів з орків і тролів, які піднімаються Прихованою Стежкою, щоб випити Земляну Сапту й укласти перший зв'язок із духами каменю та ґрунту."},sec={{t="Святилище стихій",b="Над червоним каньйоном, де молоді воїни та розвідники Орди починають навчання, Камінь Духів стоїть як вівтар єднання з духами. Відокремлений від гамору Долини Випробувань, він доступний лише Прихованою Стежкою, що в'ється скелястим гребенем. Майбутні шамани здійснюють паломництво до цього пустельного виступу, щоб випити традиційну сапту й, пронизавши завісу тілесного світу, почути гуркіт і шепіт самої землі."}},fp="11,255,27.445.0,29.236.0,29.217.0,16.204.0"}
P.entries["subzone:starbreeze-village"] = {n="Село Зоряного Вітерця",s="Село Зоряного Вітерця — покинуте поселення нічних ельфів на схід від Доланаара на Тельдрассилі. Колись тихе лісове сільце, воно нещодавно дісталося збожеволілим фурболгам племені Вузлошкірів. Зруйноване поселення тепер стоїть як кричущий символ скверни, що просочується в коріння Світового Дерева.",h="Село Зоряного Вітерця — покинуте поселення нічних ельфів на схід від Доланаара на Тельдрассилі.",kw={"село зоряного вітерця","покинуте село","фурболги","вузлошкіри","фероцитас","урусон","тельдрассил"},ang={["class:Druid"]="Божевілля, що пожирає фурболгів-Вузлошкірів, і осквернення Села Зоряного Вітерця — прямий виклик обов'язку Кола Кенарія відновити рівновагу живності Тельдрассила.",["race:NightElf"]="Бачити, як ельфійське поселення так близько до Доланаара обертається на руїну, — болісне нагадування про хистке становище Тельдрассила й скверну, що гризе Світове Дерево."},sec={{t="Занепале сільце",b="Село Зоряного Вітерця, що лежить на південний схід від Тінедолу, просто за дорогою від Доланаара, колись було домівкою мирних родин нічних ельфів під гіллям Тельдрассила. Сьогодні село в руїнах, а його дерев'яні будівлі заполонили агресивні фурболги-Вузлошкіри. Здичавілі від лиховісної скверни, що вразила гілля Світового Дерева, звіролюди вигнали ельфійських мешканців і тепер люто боронять зруйновані землі."},{t="Загроза Фероцитаса",b="Присутність Вузлошкірів у селі — не звичайний територіальний наскок. На околиці поселення чаїться Фероцитас, Пожирач Снів — загадкова зіпсута сутність, чия присутність свідчить, що фурболгів зводить з розуму темна, нечиста магія. Разом із такими здоровенними звірами, як Урусон, що нишпорить стежками, ці загарбники роблять Село Зоряного Вітерця справжньою небезпекою для мандрівників східного Тельдрассила."}},fp="18,322,15.444.0,23.426.1,36.225.0,36.174.0,36.104.0,33.169.0"}
P.entries["subzone:steelgrill-s-depot"] = {n="Склад Стілґрила",s="Склад Стілґрила — гамірна інженерна майстерня й ремонтна станція просто на схід від Хараноса в Дун Мороґу. Під наглядом Белдіна Стілґрілла та його бригади майстрів вона служить передовим осередком обслуговування машин, постачання для тінкерів і збору брухту.",h="Склад Стілґрила — гамірна інженерна майстерня й ремонтна станція просто на схід від Хараноса в Дун Мороґу.",kw={"склад стілґрила","інженерія","майстерня","белдін стілґрілл","харанос","дун мороґ"},ang={["profession:Engineering"]="Склад — лабораторія просто неба, оточена паровими машинами й припасами для майстрування, тож для інженерів-початківців, що мандрують Дун Мороґом, це природне місце перепочинку.",["race:Gnome"]="Тісно співпрацюючи з дворфськими господарями, гномські тінкери-вигнанці часто користуються вогнями кузні складу та запасними деталями, щоб їхні врятовані механізми не зупинялися."},sec={{t="Оплот пари та сталі",b="Склад Стілґрила трохи осторонь засніженої дороги на схід від Хараноса гуде брязкотом металу, шипінням парових клапанів і гулом дослідних двигунів. Дворфські шахтарі та дивакуваті гноми-інженери збираються тут серед важкої техніки, крокуючих механізмів і купи сирої руди, вивезеної з сусідніх кар'єрів. Поки Дун Мороґ потерпає від невпинних безчинств трогів і нестачі деталей, Белдін Стілґрілл зі своєю бригадою підтримує машини Альянсу в робочому стані, тож для мандрівників, яким на лютому морозі потрібні запчастини чи технічна порада, склад — незамінна зупинка."}},fp="18,272,28.601.0,27.200.0,19.189.0,33.150.0"}
P.entries["subzone:stillwater-pond"] = {n="Ставок Тихої Води",s="Ставок Тихої Води — тиха застояна водойма одразу на захід від Брілла в Галявинах Тірісфалю. Колись улюблене місце пікніків і купання живих дітей Лордерона, він перетворився на каламутну калюжу, де водяться кістяні риби й нишпорять небезпечні падложери.",h="Ставок Тихої Води — тиха застояна водойма одразу на захід від Брілла в Галявинах Тірісфалю.",kw={"ставок тихої води","ставок","брілл","пікніки","кістяні риби","бейн","темні гончаки","тірісфаль"},ang={["class:Hunter"]="Уражена чумою живність довкола ставка, зокрема здичавілі темні гончаки на кшталт Бейна, робить цю місцину небезпечними мисливськими угіддями для розвідників, що патрулюють околиці Брілла.",["race:Undead"]="Для Відступників, що зберегли спогади про життя в Лордероні, Ставок Тихої Води — похмуре нагадування про втрачені дитячі дні пікніків і купання на його колись прозорих берегах."},sec={{t="Зруйнований перепочинок",b="До Третьої війни й спустошень Чуми Нежиті Ставок Тихої Води був тихим прихистком для люду Галявин Тірісфалю. Родини з сусідніх сіл збиралися на його трав'янистих берегах на пообідні пікніки, а діти, замалі для підступних глибин Озера Світлої Води, вчилися плавати на його мілинах. Сьогодні ідилічні води стали мертвими й сірими. Живі давно зникли, лишивши тільки кістяних риб, що шмигають під поверхнею, і блукаючу нежить, що тиняється довколишніми лісами."},{t="Нишпорки в імлі",b="Хоч тут спокійніше, ніж на обложених дорогах і спірних фермах Тірісфалю, Ставок Тихої Води має власні небезпеки. Каламутні води напувають лише уражених чумою звірів галявин — насамперед лютого темного гончака на ім'я Бейн, що нишпорить берегом. Мандрівникам, які зрізають шлях західними луками дорогою до Брілла, слід ступати обережно: хижі звірі й безцільні зомбі часто тиняються край води."}},fp="15,272,16.533.0,20.437.0,48.231.0,42.196.0,46.178.0,33.129.0"}
P.entries["subzone:stone-cairn-lake"] = {n="Озеро Кам'яного Кургану",s="Озеро Кам'яного Кургану — кільцеподібна водойма на північному сході Лісу Елвінн. У його центрі лежить острів, увінчаний Дозором Героїв — меморіалом полеглим у Першій війні. Колись тихе місце для роздумів, нині озеро тривожать ворожі мурлоки на берегах і чародії-відступники, що зайняли острів.",h="Озеро Кам'яного Кургану — кільцеподібна водойма на північному сході Лісу Елвінн.",kw={"озеро кам'яного кургану","озеро","дозор героїв","мурлоки","чародії-відступники","мідь","ліс елвінн"},ang={["profession:Mining"]="Кручі й пагорби довкола Озера Кам'яного Кургану мають одне з найгустіших скупчень покладів міді в усьому Лісі Елвінн, тож це вигідна зупинка для майбутніх ковалів та інженерів.",["race:Human"]="Центральний острів — глибоко особистий меморіал для королівства Стормвінд, що вшановує загиблих, коли королівство впало під час Першої війни."},sec={{t="Пам'ятник в облозі",b="Озеро Кам'яного Кургану завдячує назвою помітному кам'яному меморіалу, зведеному на великому острові в його центрі. Цей пам'ятник, відомий як Дозор Героїв, поставили на честь тяжких людських втрат у Першій війні проти Орди орків. Колись родини та прочани безпечно діставалися острова, щоб ушанувати полеглих, дивлячись через спокійні води на урочисту кам'яну кладку. Та нині небезпечні чародії-відступники розбили табір просто біля меморіалу, перетворивши місце священної пам'яті на ворожий редут."},{t="Береги озера",b="Довкола кільцеподібного озера тягнеться мальовничий берег, що стає дедалі небезпечнішим для місцевих і мандрівників. Плем'я войовничих мурлоків захопило південні береги, поставило вздовж води грубі хатини й дошкуляє кожному, хто наблизиться. Окрім небезпек, пагорби й виступи довкола озера багаті на мінеральні жили, тож околиця — часта мета шукачів і шахтарів, готових знехтувати тутешніми загрозами."}},fp="16,325,19.553.0,18.454.0,34.181.0,46.140.0,42.160.0,42.110.0"}
P.entries["subzone:stonebull-lake"] = {n="Озеро Кам'яного Бика",s="Озеро Кам'яного Бика — тихе водоймище у формі підкови, що огортає Село Бладгуф у центральному Малгорі. Живлене чистими водами, що стікають із рівнин, воно дає прісну воду, вдосталь риби й мирні береги молодим тауренам, які дорослішають під проводом Кайрна Бладгуфа.",h="Озеро Кам'яного Бика — тихе водоймище у формі підкови, що огортає Село Бладгуф у центральному Малгорі.",kw={"озеро кам'яного бика","село бладгуф","малгор","риба","міст","тандер блаф"},ang={["race:Tauren"]="Для тауренів, що облаштовують домівки по всьому Малгору, Озеро Кам'яного Бика — лагідна пожива й нагадування про щедрість Земної Матері біля їхньої столиці."},sec={{t="Води рівнини",b="Огинаючи Село Бладгуф із трьох боків, Озеро Кам'яного Бика визначає географію центрального Малгору. Дерев'яний міст перетинає найвужче місце озера, несучи головну ґрунтову дорогу між поселенням і великим плато Тандер Блафа на півночі. Спокійні води повняться місцевою рибою, тож береги облюбували мисливці на спочинку, втомлені мандрівники й рибалки-учні, що опановують ремесло під безкраїм відкритим небом."}},fp="14,298,19.448.0,32.132.0,44.147.0,46.222.0"}
P.entries["subzone:stonefield-farm"] = {n="Ферма Стоунфілдів",s="Ферма Стоунфілдів — діюча садиба на півдні Лісу Елвінн. Тут живе родина Стоунфілдів, що давно загрузла в запеклій ворожнечі із сусідами Маклюрами.",h="Ферма Стоунфілдів — діюча садиба на півдні Лісу Елвінн.",kw={"ферма стоунфілдів","ферма","ворожнеча","маклюри","томмі джо стоунфілд","ґолдшир","ліс елвінн"},ang={["race:Human"]="Для людей, що починають шлях із Нортширу, чвари між Стоунфілдами й Маклюрами — легковажний погляд на сільське життя королівства поза загрозою розбійників і гнолів."},sec={{t="Гірка садиба",b="Ферма Стоунфілдів серед хвилястої зелені на південь від Ґолдшира вирощує збіжжя для королівства, водночас плекаючи люту, десятиліттями давню образу на сусідні Виноградники Маклюрів. Злопам'ятство між господарствами породжує дрібні сварки, взаємні звинувачення в крадіжках і постійну напругу. Та за ворожими перепалками юний Томмі Джо Стоунфілд таємно покохав Мейбелл Маклур, і це тихе кохання може або перекинути міст між родинами, або розпалити ще більший гнів."}},fp="15,190,18.517.0,58.248.0,29.124.0,38.239.0"}
P.entries["subzone:stormwind-city"] = {n="Стормвінд",s="Стормвінд — велична столиця Королівства Стормвінд і військове та політичне серце Альянсу. Відбудований із попелу після знищення в Першій війні, він стоїть як найбільший уцілілий бастіон людської могутності в Азероті після падіння північних королівств.",h="Стормвінд — велична столиця Королівства Стормвінд і військове та політичне серце Альянсу.",kw={"стормвінд","столиця","альянс","королівство стормвінд","собор світла","варіан рінн","болвар фордрагон"},ang={["faction:Alliance"]="Стормвінд — головний військовий, морський і духовний осередок Альянсу на півдні Східних Королівств, що однаково радо приймає дворфів, гномів і посланців нічних ельфів.",["race:Human"]="Для людей усього Азерота білі мури Стормвінда уособлюють витривалість, виживання й незгасну славу людства після цілковитої втрати північних королівств."},sec={{t="Відбудований маяк",b="Заснований понад тисячоліття тому нащадками араті, що рушили на південь, Стормвінд розквітнув як жвава прибережна столиця, оперезана кам'яними валами й живлена швидкими річковими млинами. Ця велич скінчилася в Першій війні, коли Орда орків узяла місто в облогу, пробила його оборону й спалила дощенту, змусивши сера Андуїна Лотара вести вцілілих біженців через Велике Море до Лордерону. Після перемоги Альянсу в Другій війні Гільдія каменярів узялася за грандіозне завдання — відбудувати столицю в сяйливу твердиню з білого каменю, мереживом каналів і стрімкими шпилями, що височіє на північ від Лісу Елвінн і сьогодні."},{t="Серце Альянсу",b="Коли Лордерон розтрощила Погибель, а Даларан тяжко зруйнувала Третя війна, Стормвінд став головним прихистком і твердинею людства. Його широкі проспекти й оборонні мури патрулюють дисципліновані міські вартові Стормвінда, а шпилі Собору Світла ведуть віру й відданість південних королівств. Та під його впорядкованими кварталами й церемоніальними брамами тліє тихе політичне сум'яття: Король Варіан Рінн загадково зник, і на троні лишився його юний син Андуїн під регентством Верховного Лорда Болвара Фордрагона та нашіптування королівської радниці Леді Катрани Престор."}},fp="14,298,16.651.0,21.636.0,46.327.0,35.292.0,61.301.0,38.284.0"}
P.entries["subzone:stormwind-gate"] = {n="Брама Стормвінда",s="Брама Стормвінда — монументальний укріплений вхід, що сполучає Ліс Елвінн зі Стормвіндом. Під невпинною охороною королівських вартових цей поріг — головна межа між спокійними лісами та величною Долиною Героїв.",h="Брама Стормвінда — монументальний укріплений вхід, що сполучає Ліс Елвінн зі Стормвіндом.",kw={"брама стормвінда","брама","вхід","долина героїв","вартові","стормвінд","ліс елвінн"},ang={["faction:Alliance"]="Брама уособлює безпеку й незламність Великого Альянсу: для солдатів у дорозі та молодих шукачів пригод це перший проблиск величі.",["race:Human"]="Для людей Стормвінда повернутися крізь ці кам'яні арки означає повернутися додому, у безпеку, після довгих мандрів Елвінном і далі."},sec={{t="Поріг королівства",b="Брама Стормвінда, що височіє над південною дорогою Лісу Елвінн, служить і оборонним оплотом, і церемоніальним порогом столиці. Міські вартові Стормвінда невпинно стежать за кам'яним порталом, охороняючи підступи з лісу, а регулярні патрулі крокують між зовнішньою аркою та Долиною Героїв. Попри тривалі заворушення по всьому Елвінну, величезна брама з заліза й каменю лишається широко відчиненою, щоб вітати мандрівників, купців і захисників, що повертаються, у серці Альянсу."}},fp="14,246,28.536.0,35.176.0,56.267.0,21.226.0,42.193.0"}
P.entries["subzone:the-den"] = {n="Лігво",s="Лігво — захищена печера в серці Долини Випробувань на південному заході Дуротару. Головна опорна база для молодих шукачів пригод з орків і тролів, вона дає бойову та магічну підготовку, перш ніж вони вирушать у широкий світ.",h="Лігво — захищена печера в серці Долини Випробувань на південному заході Дуротару.",kw={"лігво","печера","долина випробувань","новобранці","наставники","ґорнек","дуротар"},ang={["race:Orc"]="Кожен молодий орк починає свій шлях у Лігві, скидаючи заціпеніння таборів для інтернованих і кривавого мороку, щоб заслужити своє місце дисципліною і працею.",["race:Troll"]="Після спустошення Островів Темного Списа молоді тролі Темного Списа навчаються в Лігві пліч-о-пліч із союзниками-орками, доводячи свою вправність під прапором Орди."},sec={{t="Колиска Орди",b="Сховане в червоних стінах каньйону Долини Випробувань, Лігво служить суворим полігоном. У його висіченому в скелі сутінковому нутрі бійці, чаклуни й мисливці-новачки з'являються до ветеранів на кшталт Ґорнека та Зуріти Фарґейз. Саме тут пташенята отримують перші бойові настанови, припаси та початкові обряди посвяти, які гартують їх до суворої дійсності Дуротару й більших випробувань, що чекають на нову Орду."},{t="Пильна застава",b="Окрім того, що тут розмістилися наставники класів і припаси, Лігво працює як діючий польовий редут. Посилаючи новобранців винищувати місцеву звірину та войовничих шипогривів, наглядачі водночас тримають долину під суворим і пильним наглядом."}},fp="7,253,19.447.0,18.241.0,31.278.0,31.254.0,39.223.0"}
P.entries["subzone:thunder-bluff"] = {n="Тандер Блаф",s="Тандер Блаф — високо піднесена столиця тауренів, що здіймається на сотні футів над пагорбистими рівнинами Малгору. Заснований Кайрном Бладгуфом після Третьої війни, він служить об'єднаним прихистком і культурним серцем народу, який поколіннями кочував.",h="Тандер Блаф — високо піднесена столиця тауренів, що здіймається на сотні футів над пагорбистими рівнинами...",kw={"тандер блаф","столиця","таурени","кайрн бладгуф","малгор","плато","ґрімтотем","озерця видінь"},ang={["faction:Horde"]="Тандер Блаф дає Орді неодмінний бастіон у південному Калімдорі — надійний якір мудрості й ресурсів поруч з орківським Оргріммаром.",["race:Tauren"]="Для тауренів Тандер Блаф — перший справжній постійний дім після поколінь мандрів; тут їхні священні тотеми, духовні оселі й найвеличніші вожді."},sec={{t="Прихисток на плато",b="Незліченні покоління таурени жили кочовиками центрального Калімдору, яких раз у раз шарпали жорстокі загони кентаврів. Та доба втечі скінчилася під час Третьої війни, коли Кайрн Бладгуф уклав союз честі з Вождем Траллом і Новою Ордою. Разом вони відкинули кентаврську загрозу й зайняли родючі трави Малгору. Кайрн зібрав розпорошені племена й заснував Тандер Блаф на вершинах низки розлогих природних кам'яних плато. Нині місто з'єднане запаморочливими мотузяними мостами, а потрапити до нього можна хитромудрими дерев'яними підйомниками; воно дає і цілковитий захист, і жвавий осередок торгівлі та духовних зібрань."},{t="Єдність і туман, що згущується",b="Хоч Тандер Блаф і стоїть маяком злагоди, на його височинах живуть різні угруповання. Більшість племен шанує мудрість Кайрна Бладгуфа, та серед традиціоналістів, як-от Маґата Ґрімтотем та її рід на Узвишші Старійшин, тихо тліє незгода. Глибоко під поверхнею міста лежать підземні Озерця Видінь, де духоходці й шамани вдивляються у волю предків. Попри приховане суперництво племен, Тандер Блаф лишається справжньою духовною опорою Орди в Калімдорі: він приймає мисливців, що повертаються з Пусток, мандрівних ремісників і друїдів, які єднаються із Земною Матір'ю."}},fp="13,279,23.664.0,25.602.0,41.205.0,46.220.0,24.188.0,38.215.0"}
P.entries["subzone:thunder-falls"] = {n="Громові водоспади",s="Громові водоспади — відлюдна гірська ущелина, схована серед північно-західних височин Лісу Елвінн. Затиснута між прямовисними скелями й живлена ревучими каскадами, вона приховує тиху хатину над річкою, що потрапила до рук місцевих розбійників.",h="Громові водоспади — відлюдна гірська ущелина, схована серед північно-західних височин Лісу Елвінн.",kw={"громові водоспади","водоспад","ущелина","хатина","розбійники","дзеркальне озеро","ліс елвінн"},sec={{t="Прихована гірська западина",b="Сховані серед зубчастих хребтів над Дзеркальним Озером, Громові водоспади — незвичайна географічна розколина. Ущелину прорізає стрімкий гірський потік, що вливається через недоступний північний каскад, а потім обривається з обох боків видовищними водоспадами. З одного боку вода падає в Дзеркальне Озеро, а нижня течія тече на захід, до суворих кордонів Вестфолу. Попри ревучі води, на березі стоять невелика хатина, причал і кузня просто неба, та нині мирну галявину привласнили собі розбійники."}},fp="13,246,24.529.0,31.232.0,42.247.0,43.207.0"}
P.entries["subzone:thunderbrew-distillery"] = {n="Ґуральня Тандербрю",s="Ґуральня Тандербрю — гамірна корчма й головне місце зустрічей у Хараносі в Дун Мороґу. Славетна на всі усюди своїми міцними елями, вона водночас є діючою пивоварнею і необхідним місцем перепочинку для мандрівників, що долають засніжені гірські перевали. Усередині гостей чекають тепле вогнище, холодні кухлі та чимало наставників класів і місцевих ремісників.",h="Ґуральня Тандербрю — гамірна корчма й головне місце зустрічей у Хараносі в Дун Мороґу.",kw={"ґуральня тандербрю","корчма","харанос","ель","стаут","наставники","дун мороґ"},ang={["profession:Cooking"]="Кухня ґуральні пропонує кулінарне навчання й припаси, тож це важлива зупинка для кухарів, які хочуть навчитися готувати ситні гірські страви.",["race:Dwarf"]="Для дворфів, що залишають Долину Холодного Хребта, ґуральня — любе повернення додому: знайомий стаут, місце біля палаючого вогнища та надійні наставники в залізі й вірі."},sec={{t="Тепле вогнище Хараноса",b="Ґуральня Тандербрю в самому центрі Хараноса — серце громадського життя південного Дун Мороґу. Заснована кланом Тандербрю — його започаткував Аркілус Тандербрю, а підтримують його нащадки — пивоварня славиться на весь Хаз Модан міцними зігрівними елями, звареними, щоб проганяти пронизливий гірський холод. Вона працює як місцева корчма, якою в залі порядкує Шинкар Белм, пропонуючи втомленим горянам ревучий вогонь, ситну страву та ліжко, щоб перечекати хуртовину."},{t="Перехрестя знань і ремесла",b="Окрім того, що тут наливають славетні стаути, ґуральня є ще й важливим осередком для шукачів пригод, які лише набираються сили. Оскільки Харанос — перше велике поселення на шляху мандрівників після Долини Холодного Хребта, корчма Тандербрю приймає найрізноманітніших наставників. Під її міцними дерев'яними кроквами збираються вчителі військової справи, святих обрядів, таємних мистецтв і розбійницького ремесла поруч із наставниками кулінарії та першої допомоги, перетворюючи гамірну питну залу на незамінний пункт підготовки."}},fp="22,378,27.500.0,35.495.0,49.249.0,50.270.0,32.244.0,48.209.0"}
P.entries["subzone:thunderhorn-water-well"] = {n="Водяна Криниця Тандергорнів",s="Водяна Криниця Тандергорнів — життєво важливе джерело води на хвилястих рівнинах центрального Малгору, на шляху між Селом Бладгуф і Тандер Блафом. Як і всі криниці долини, вона живить племена та стада, що бродять пасовищами. Берегти цю воду чистою й захищеною конче потрібно, щоб підтримувати життя на батьківщині тауренів.",h="Водяна Криниця Тандергорнів — життєво важливе джерело води на хвилястих рівнинах центрального Малгору, на...",kw={"водяна криниця тандергорнів","криниця","вода","малгор","венчурна компанія","духи води"},ang={["class:Shaman"]="Шамани глибоко шанують чисті джерела Малгору й уважають захист духів води та підземних течій священним обов'язком.",["race:Tauren"]="Для тауренів такі криниці, як Криниця Тандергорнів, — життєво важливі артерії, дар Земної Матері, що потребує постійної охорони від чужинських отруювачів і жадібних зайд."},sec={{t="Життєдайне джерело",b="Водяна Криниця Тандергорнів серед розлогих пасовищ центрального Малгору сягає просто в чисті водоносні шари, що живлять долину. Для кочових тауренів та їхніх новозаснованих сіл такі спільні криниці означають життя, поживу й щедрість Земної Матері. Вода на випалених сонцем рівнинах дорогоцінна, тож хто володіє криницями — той володіє самою землею. Зайди на кшталт Венчурної Компанії не раз накидали оком на ці джерела, намагаючись прибрати їх до рук задля промислового визиску й зруйнувати крихку рівновагу, за яку борються племена."}},fp="22,373,20.585.0,44.142.0,47.252.0,28.210.1"}
P.entries["subzone:tiragarde-keep"] = {n="Фортеця Тіраґард",s="Фортеця Тіраґард — укріплена людська твердиня на Дріботливому Узбережжі Дуротару, на південь від Гострого Пагорба. Збудована під час вторгнення Великого Адмірала Деліна Праудмура, зруйнована цитадель досі утримується ворожою кул-тіраською морською піхотою під проводом Лейтенанта Бенедикта. Це зухвала, невиправна скалка в боці Орди просто на її рідній землі.",h="Фортеця Тіраґард — укріплена людська твердиня на Дріботливому Узбережжі Дуротару, на південь від Гострого...",kw={"фортеця тіраґард","кул тірас","люди","лейтенант бенедикт","праудмур","узбережжя","дуротар"},ang={["faction:Horde"]="Фортеця Тіраґард — відверта загарбницька база Альянсу просто на порозі Дуротару; штурмувати її вали й усунути Лейтенанта Бенедикта — обряд посвяти для молодих солдатів на службі Гострого Пагорба.",["race:Human"]="Гарнізон утілює незламну, мстиву спадщину Кул Тірасу й Адмірала Праудмура, ведучи вперту партизанську війну наперекір дипломатії Джайни Праудмур."},sec={{t="Бастіон Праудмура",b="Зведена під час походу Великого Адмірала Деліна Праудмура на знищення щойно заснованого королівства Тралла, Фортеця Тіраґард дала флоту Кул Тірасу укріплений плацдарм на червоних берегах Дуротару. Хоч Орда зрештою прорвала облогу й убила Праудмура на Острові Терамор, фортецю так і не покинули повністю. Війська постачання під проводом Лейтенанта Бенедикта знову зайняли розтрощені кам'яні стіни, виконуючи незмінний наказ покійного Адмірала вести з орками безкомпромісну війну й цілком відкидаючи мир, укладений Леді Джайною Праудмур."},{t="Скалка в боці Дуротару",b="Нині блискучі білі зубці фортеці різко контрастують із багряними скелями Дуротару. Добре вишколені моряки та морські піхотинці Кул Тірасу патрулюють вали й влаштовують набіги на шляхи постачання біля Гострого Пагорба. Для Орди Фортеця Тіраґард — і тривала криза безпеки, і живий полігон. Командири орків і тролів без упину доручають молодим воїнам штурмувати фортецю й рубати солдатів Бенедикта, прагнучи стримати гарнізон, перш ніж люди зможуть розгорнути глибший наступ углиб суходолу."}},fp="14,360,20.550.0,26.519.0,32.220.0,53.232.0,28.177.0,43.324.0"}
P.entries["subzone:tor-kren-farm"] = {n="Ферма Тор'крена",s="Ферма Тор'крена — тиха, злиденна свиноферма на північному заході Дуротару, між Громовим Хребтом і Річкою Південної Люті. Нею сама порядкує Міша Тор'крен — літня орчиха-вдова, чиє життя придавили горе та суворе порубіжжя.",h="Ферма Тор'крена — тиха, злиденна свиноферма на північному заході Дуротару, між Громовим Хребтом і Річкою...",kw={"ферма тор'крена","міша тор'крен","свиноферма","крон","кроколіски","річка південної люті","дуротар"},ang={["class:Hunter"]="Доля Крона — похмуре застереження молодим мисливцям про смертоносних хижаків, що чаяться на берегах Річки Південної Люті.",["faction:Horde"]="Тиха трагедія на Фермі Тор'крена розкриває щоденні жертви простих поселенців Орди, що прагнуть приборкати дике порубіжжя Дуротару."},sec={{t="Самотня садиба",b="Вижити на сухій, нещадній червоній землі Дуротару ніколи не було просто, але Фермі Тор'крена ведеться гірше за інших. Садиба на південний схід від Громового Хребта розводить свиней у суворому кліматі, де бракує і корму, і води. На відміну від гамірних торгових постів чи добре захищених казарм Орди, ферма стоїть самотня й тиха, даючи скупий урожай у тіні сусідніх круч."},{t="Материнська втрата",b="Найбільший тягар ферми — не бідний ґрунт, а трагедія. Колись Міша Тор'крен працювала в цих загонах разом із коханим сином Кроном. Те життя скінчилося, коли Крон спустився до Річки Південної Люті полювати на лютих кроколісків, що чаяться на берегах, і не повернувся. Лишившись сама, Міша доглядає свиней власноруч, міцно тримаючись за садибу й чіпляючись за пам'ять про полеглу дитину."}},fp="13,262,18.429.0,15.405.0,31.128.0,27.110.0,29.156.0,32.135.0"}
P.entries["subzone:tower-of-azora"] = {n="Вежа Азори",s="Вежа Азори — струнка чародійська вежа, що здіймається на сході Лісу Елвінн, на північ від Гарбузової Ділянки Брекуеллів. Під проводом Архімага Теокрітуса з людей цей анклав служить ученою заставою, втягнутою в мовчазну магічну ворожнечу з ворожою вежею в сусідніх Горах Редріджу.",h="Вежа Азори — струнка чародійська вежа, що здіймається на сході Лісу Елвінн, на північ від Гарбузової Ділянки...",kw={"вежа азори","вежа","теокрітус","архімаг","гноми","морґант","прозирання","ліс елвінн"},ang={["class:Mage"]="Для магів, що мандрують за межі Стормвінда, вежа пропонує відлюдний прихисток для студій, таємних наставників і місце в першому ряду перед небезпечним мистецтвом далекого прозирання.",["race:Gnome"]="Таємний шпиль у людських землях, який обслуговують гноми під проводом Архімага Теокрітуса, — гордий показ майстерності вашого народу в містичних мистецтвах."},sec={{t="Шпиль таємної пильності",b="Вежа Азори при східній дорозі до Гір Редріджу — таємне святилище, яке майже цілком обслуговують чаклуни-гноми. Під опікою Архімага Теокрітуса ці вчені вивчають дивні дивовижі й дають магічні настанови мандрівним чаклунам. Дика магічна аура довкола шпиля часом викривлює навколишню звірину, тож слугам-гномам доводиться давати раду зачарованому хатньому начинню та мутованим комахам, що повзуть повз двері."},{t="Ворожнеча з Ілґаларом",b="Під тихою вченою зовнішністю вежа веде тривалу війну прозирання й саботажу. На сході, на скелях Редріджу, стоїть лиховісна Вежа Ілґалара, якою править чаклун-відступник Морґант. Теокрітус і Морґант невпинно шпигують один за одним таємними засобами, залучаючи відважних шукачів пригод, щоб ті встановлювали реліквії прозирання на кшталт Ока Азори, пробивали захисні чари Ілґалара й стежили за темними задумами Морґанта."}},fp="14,299,27.497.0,21.444.1,29.185.0,34.181.0,34.218.0,42.200.0"}
P.entries["subzone:tundrid-hills"] = {n="Тундридські Пагорби",s="Тундридські Пагорби — суворий засніжений відтинок високогір'я в південно-центральному Дун Мороґу, просто на захід від Кар'єру Гол'Болар. Скелясті перевали, де водиться небезпечна гірська звірина, випадкові мандрівники перетинають нечасто.",h="Тундридські Пагорби — суворий засніжений відтинок високогір'я в південно-центральному Дун Мороґу, просто на...",kw={"тундридські пагорби","високогір'я","хижаки","мисливці","дун мороґ","навпростець"},ang={["class:Hunter"]="Обвіяні вітрами скелі — суворі мисливські угіддя, повні витривалих звірів, що пристосувалися до нещадного гірського холоду Дун Мороґу.",["race:Dwarf"]="Для горян Айронфорджа ці висоти — повсякчасне нагадування, що дика глушина й ворожі тролі Морозогриви тиснуть упритул до серця Дун Мороґу."},sec={{t="Підступна глушина",b="Простягшись між Долиною Холодного Хребта та низинами східного Дун Мороґу, Тундридські Пагорби пропонують суворий шлях навпростець тим, хто хоче оминути головні дороги через Харанос. Та за зручність доводиться дорого платити. Зубчастими засніженими схилами нишпорять люті хижаки, тож ці землі небезпечні для необачних мандрівників, які сходять з уторованої стежки, не оголивши зброї."}},fp="13,232,24.401.0,36.205.0,50.237.0,47.126.0"}
P.entries["subzone:undercity"] = {n="Андерсіті",s="Вирізане під розтрощеним палацом Столиці, Андерсіті служить розлогою підземною твердинею Відступників. Колись плетиво королівських склепів, підземель і каналізації, розширене Погибеллю, його захопила Сильвана Віндраннер і перекувала на добре укріплену столицю своєї вільної нежиті.",h="Вирізане під розтрощеним палацом Столиці, Андерсіті служить розлогою підземною твердинею Відступників.",kw={"андерсіті","столиця","сильвана","катакомби","підземне місто","лордерон","відступники"},ang={["faction:Horde"]="Підземне місто — головний військовий бастіон Орди у Східних Королівствах, хоч його тьмяні, просякнуті аптекарськими випарами ходи випробовують витримку гостей із Калімдору.",["race:Undead"]="Андерсіті — живе серце цивілізації Відступників: прихисток, збудований із руїн і склепів вашого колишнього життя, де ви захищені і від Погибелі, і від живих."},sec={{t="Від королівських склепів до бастіону Погибелі",b="До Третьої війни підземні ходи під Столицею — стольним містом Лордерону — знали як Андерсіті: величезну мережу каналізації, королівських катакомб і підземель. Саме тут Альянс колись ув'язнив полоненого вождя Орґріма Думгаммера, і тут найбідніші городяни перебивалися в темряві. Під час падіння Лордерону принц Артас Менетіл наказав своїй Погибелі розширювати ці глибини до підземного осідку влади. Коли Король-Ліч прикликав Артаса до Нортренду, лицар смерті лишив будівництво незавершеним."},{t="Столиця Відступників",b="Серед громадянської війни в Чумних Землях Сильвана Віндраннер згуртувала ту нежить, чий розум вирвався з лещат Короля-Ліча. Скинувши жахолордів і вигнавши суперників, новоназвані Відступники заявили права на підземний комплекс. Вони довершили покручений лабіринт катакомб, розпочатий Погибеллю, і укріпили його в неприступну твердиню під мовчазними руїнами колишнього королівства. Нині Темна Леді править своїм народом з його отруєних залів."}},fp="9,323,36.548.0,20.498.0,54.279.0,40.314.0,58.283.0,24.141.0"}
P.entries["subzone:valley-of-trials"] = {n="Долина Випробувань",s="Схована за суворими червоними скелями південного Дуротару, Долина Випробувань служить полігоном для нових новобранців Орди. Молоді орки та їхні союзники — тролі Темного Списа — приходять сюди довести свою силу й заслужити місце серед воїнів Калімдору. Ті, хто переживе сувору звірину й приховані загрози долини, виходять готовими боронити свою молоду державу.",h="Схована за суворими червоними скелями південного Дуротару, Долина Випробувань служить полігоном для нових...",kw={"долина випробувань","стартова локація","орки","тролі","лігво","скорпіди","саркот","дуротар"},ang={["race:Orc"]="Долина — обряд посвяти для кожного молодого орка, що шукає честі; вона відлунює воїнськими традиціями Дренору на новоствореній батьківщині.",["race:Troll"]="Втративши дім на Островах Відлуння через Залазана, тролі Темного Списа навчаються в цьому каньйоні пліч-о-пліч із союзниками-орками, щоб заслужити своє місце в Орді."},sec={{t="Горнило піску й каменю",b="Долина Випробувань створена, щоб відсіяти слабких, перш ніж ті ступлять у ширші простори Дуротару. Під наглядом вождів і наставників, що стоять у висіченому в скелі прихистку, відомому як Лігво, молодих бійців кидають у випалену сонцем балку полювати на скорпідів, винищувати войовничих вепрів і наводити лад серед ледачих робітників, що заготовляють скупий ліс. Випробування безкомпромісне: хто доведе свою вправність, здобуває право вирушити далі справжнім солдатом Орди, а хто зазнає невдачі — лишається біліти під пустельним сонцем."},{t="Тінь на півночі",b="Колись відлюдний тренувальний майданчик нещодавно набув значно зловіснішого відтінку. У природних печерах уздовж північних скель укорінилися культисти Палаючого Клинка, прикликаючи в долину дрібних демонічних фамільярів. Хоч наставники й використовують цих зайд як живу бойову практику для новобранців, присутність магії Скверни так близько до порога Оргріммара живить темні чутки, що Рада Тіней знову намагається запустити пазурі в орківський народ."}},faq={{q="Яке призначення Долини Випробувань?",a="Це традиційний полігон для новобранців Орди — насамперед молодих орків і тролів Темного Списа. У її захищених каньйонах нові шукачі пригод виконують суворі завдання, щоб показати бойову вправність, інстинкт виживання та вірність, перш ніж їм дозволять вирушити в решту Дуротару.",al={"чому тут орки","що це за місце","призначення долини випробувань"}},{q="Що таке Лігво?",a="Лігво — печера, висічена в скелях приблизно посередині долини. У ній розташувалися наставники класів, торговці та наглядачі на кшталт Ґорнека, які скеровують новобранців, споряджають їх і стежать за їхніми успіхами під час перших випробувань.",al={"лігво","печера в долині випробувань","хто в лігві"}},{q="Чому на тренувальному майданчику для новачків є демони?",a="Культисти Палаючого Клинка влаштували таємний ковен у північних печерах. Хоч наставники й використовують їхніх слабких фамільярів, щоб випробовувати новобранців, присутність культу натякає, що потаємні сили на кшталт Ради Тіней шукають опори просто на порозі Дуротару.",al={"чому демони в долині випробувань","палаючий клинок у дуротарі","демони в північній печері"}},{q="Хто такий Саркот?",a="Саркот — незвично великий отруйний скорпід, що живе на скелястих висотах долини. Через його лють і смертоносність наставники доручають перспективним новобранцям уполювати його, щоб перевірити їхню відвагу, і принести на доказ його понівечену клешню.",al={"лор саркота","велетенський скорпід","завдання саркот"}}},fp="16,385,28.558.0,23.490.1,44.300.0,16.231.0,53.276.0,15.251.0"}
P.entries["subzone:venomweb-vale"] = {n="Долина Отруйного Павутиння",s="Долина Отруйного Павутиння — тіниста долина у східних Галявинах Тірісфалю, одразу на південь від Багряного Монастиря. Колись пишний ліс, повний дичини, долина виродилася в уражене чумою гніздо, яке заполонили агресивні отруйні павуки. Невідомо більшості перехожих, вона зберігає й давню спадщину — як священне місце зібрань Ради Тірісфалю.",h="Долина Отруйного Павутиння — тіниста долина у східних Галявинах Тірісфалю, одразу на південь від Багряного...",kw={"долина отруйного павутиння","павуки","срі'скалк","рада тірісфалю","хранитель","еґвінн","лейтенант сандерс","тірісфаль"},ang={["class:Mage"]="Для адептів таємних мистецтв долина — священна земля: саме тут історично збиралася Рада Тірісфалю, де обирали й наділяли силою Хранителів давнини, зокрема Еґвінн.",["race:Undead"]="Мандрівникам з-поміж Відступників, що прямують до Багряного Монастиря, доводиться оминати і смертельну отруту виводку Срі'скалка, і пильні патрулі хрестоносців Лейтенанта Сандерса на півночі."},sec={{t="Уражений чумою притулок",b="Перш ніж чума поглинула Лордерон, ця долина була мирним куточком соковитої трави й зелених дерев, який любили місцеві мисливці, що вистежували оленів і кроликів. Сьогодні в краєвиді панують гниль і повзучий морок. Велетенські отруйні павуки кишать серед дерев і улоговин на чолі зі страхітливим павуком Срі'скалком. Північний край долини межує із землями Багряного Хрестового Походу, де темні гончаки нишпорять біля укріпленого Багряного Табору під командуванням Лейтенанта Сандерса."},{t="Спадщина Ради",b="Задовго до того, як павуки заполонили улоговини, долина була таємним місцем зібрань давньої Ради Тірісфалю. Саме тут найпершого Хранителя Тірісфалю наділили силою битися з демонічними вторгненнями. У відчайдушній і хибній спробі убезпечити своє святилище від зайд один із членів ради вивів і випустив смертоносних павуків, що й досі мучать цю улоговину. Дивна брила котячого золота — наслідок давньої невдалої трансмутації учня Фалріка — досі позначає відлюдне місце, де Хранителька Еґвінн колись збиралася з Радою."}},fp="13,355,17.469.0,21.590.0,47.285.0,60.264.0,36.143.0,58.241.0"}
P.entries["subzone:venture-co-mine"] = {n="Шахта Венчурної Компанії",s="Шахта Венчурної Компанії, схована у східних кручах Малгору, — самовільна промислова копальня, якою заправляють жадібні гоблінські пройдисвіти. Хоч таурени відмовили їм у праві на видобуток, Венчурна Компанія все одно вгризлася в пагорби, загрожуючи природній рівновазі рівнин.",h="Шахта Венчурної Компанії, схована у східних кручах Малгору, — самовільна промислова копальня, якою...",kw={"шахта венчурної компанії","венчурна компанія","гобліни","фіззпрокет","малгор","копальня","лісозаготівля"},ang={["profession:Engineering"]="За шахтними тунелями, на верхній лісовій вирубці, причаївся Твізвік Спрокетґрайнд — майстровий, готовий поділитися механічними секретами ремесла подалі від допитливих корпоративних очей.",["race:Tauren"]="Шахта — глибока образа Земній Матері: вона приносить кіптяву, гуркіт і безоглядні рубці в прабатьківські долини, які племена поклялися берегти."},sec={{t="Небажана промисловість",b="Коли Венчурна Компанія попросила права вигрібати з Малгору корисні копалини, таурени навідріз відмовили. Корпоративний картель знехтував ними й усе одно прорив тунелі глибоко в східну гірську стіну під орудою Наглядача Фіззпрокета. Розлогий комплекс має три входи: наземний тунель під охороною найманих горлорізів, стрімкий оглядовий виступ на скелі та верхній прохід до невеликої лісозаготівлі. Машини, дим і купи шлаку, що насуваються на край, — відверте осквернення священної землі."},{t="Дедалі більші апетити",b="Гірнича справа була для картелю лише першою ставкою. Внутрішні документи свідчать, що Магнат Раздунк і правління Венчурної Компанії заохочували Фіззпрокета розширитися до повномасштабних лісозаготівель і обіцяли передові гоблінські подрібнювачі, щоб зачистити хвилясті пагорби. Тауренські скороходи напали на корпоративний караван із припасами біля Озера Кам'яного Бика й спалили його, щоб загальмувати розширення, та картель негайно вислав збирачів відшукати вантаж. Аби зупинити руйнування, племена вдалися до прямої відплати наглядачам шахти."}},fp="16,280,17.506.0,19.546.1,34.290.0,37.192.0,48.266.0,44.184.0"}
P.entries["subzone:wellspring-lake"] = {n="Озеро Джерела",s="Озеро Джерела — тиха прісна водойма високо в гіллі Тельдрассила, на північний схід від Дарнасуса. Живлене природними джерелами з глибин Світового Дерева, воно дає початок звивистій Річці Джерела. Колись мирний притулок рибалок нічних ельфів, береги озера стали жертвою скверни, що збурює живність Тельдрассила.",h="Озеро Джерела — тиха прісна водойма високо в гіллі Тельдрассила, на північний схід від Дарнасуса.",kw={"озеро джерела","річка джерела","деревляники","риболовля","дарнасус","тельдрассил","скверна"},ang={["class:Druid"]="Друїди вивчають збурених деревляників і звірів біля Озера Джерела, щоб зрозуміти джерело неприродної хвороби, яка шириться водами й ґрунтом Тельдрассила.",["race:NightElf"]="Для калдореїв перетворення мирних гаїв на кшталт Озера Джерела на небезпечні лігва чудовиськ — болісне нагадування, що з їхнім молодим Світовим Деревом щось глибоко не так."},sec={{t="Споганений притулок",b="Озеро Джерела під кроною між Дарнасусом і Галявиною Оракула калдореї здавна плекали як тихий прихисток для риболовлі й роздумів. Його прозорі води беруть початок із підземних джерел, що біжать велетенським гіллям Світового Дерева, а далі стікають на північ Річкою Джерела. Та останнім часом підступна пошесть почала охоплювати довколишні хащі. Агресивні павуки, нічні шаблезуби, що нишпорять довкола, і збурені деревляники тепер бродять берегами, і колись ідилічний ставок став підступним місцем для необачних мандрівників."}},fp="15,384,16.584.0,33.127.0,45.193.0,49.252.0,38.161.0"}
P.entries["subzone:wellspring-river"] = {n="Річка Джерела",s="Річка Джерела витікає з природного джерела в Тельдрассилі й біжить на північ з Озера Джерела, аж поки не зривається з гілля велетенським водоспадом в океан далеко внизу. Колись мирне джерело прісної води для всієї живності Світового Дерева, її береги стали небезпечними через збурену місцеву живність.",h="Річка Джерела витікає з природного джерела в Тельдрассилі й біжить на північ з Озера Джерела, аж поки не...",kw={"річка джерела","озеро джерела","водоспад","деревляники","тельдрассил","світове дерево"},ang={["class:Druid"]="Зіпсутий, знавіснілий стан тутешніх деревляників річки — тривожна ознака хвороби, що повзе всією живою системою Тельдрассила.",["race:NightElf"]="Прісні потоки, що течуть із серця Тельдрассила, утілюють життєву силу нової домівки калдореїв, тож неспокій на їхніх берегах глибоко тривожить."},sec={{t="Води Світового Дерева",b="Живлена глибокими природними джерелами в гіллі Тельдрассила, Річка Джерела несе воду на північ з Озера Джерела через зелений ліс, а тоді велично падає з краю великого дерева в море внизу. Попри мирне довкілля, береги річки стають дедалі небезпечнішими. Деревляники, що живуть уздовж води, знавісніли й стали ворожими: вони люто нападають на мандрівників і друїдів, які намагаються підійти до річки."}},fp="16,318,24.486.0,37.221.0,57.249.0,44.173.0"}
P.entries["subzone:westbrook-garrison"] = {n="Гарнізон Вестбрук",s="Гарнізон Вестбрук — застава вартових Стормвінда на західному краю Лісу Елвінн, поблизу кордону з Вестфолом. Її тримає перевантажена, погано забезпечена жменька вартових під проводом Помічника Рейнера, і це перша лінія оборони королівства проти гнолів Річколапів, що насуваються, і розбійників-відступників.",h="Гарнізон Вестбрук — застава вартових Стормвінда на західному краю Лісу Елвінн, поблизу кордону з Вестфолом.",kw={"гарнізон вестбрук","застава","вартові стормвінда","помічник рейнер","гоґґер","гноли","ліс елвінн"},ang={["class:Warrior"]="Обложені вартові Вестбруку — образ перенапруженого королівства, що стримує хижаків глушини самою лише впертістю, і тут удосталь простої, брутальної роботи із зачистки бойових загонів гнолів.",["faction:Alliance"]="Для захисників Альянсу, що вирушають з Елвінну до Вестфолу, убезпечити околиці Вестбруку й забрати винагороду за Гоґґера вкрай важливо, щоб західні кордони серця королівства лишалися безпечними."},sec={{t="Обложений прикордонний пост",b="Гарнізон Вестбрук, що стоїть там, де Ліс Елвінн починає рідшати в бік Вестфолу, — важливий, але знесилений спостережний пункт. Оскільки більшу частину армії Стормвінда відрядили за кордон або скувала політична інертність у столиці, застава лишилася критично нечисленною. Помічник Рейнер і його жменька вартових мусять патрулювати західні дороги, водночас відбиваючись від знахабнілих злодіїв і лютих гнолів Річколапів, що заполонили південні ліси. Не маючи змоги добитися офіційного підкріплення від Маршала Дуґана в Ґолдширі, гарнізон майже цілком покладається на мандрівних шукачів пригод, щоб убезпечити шлях."},{t="Загроза Узлісся",b="Головна загроза Вестбруку — дедалі більша присутність гнолів, зосереджена на південь від Узлісся. Зграї знахабніли настільки, що нападають просто на обози з припасами й садиби, згуртовані під проводом грізного ватажка гнолів, відомого як Гоґґер. Переважений числом і грубою силою війська Гоґґера, гарнізон вивісив по всій своїй території високу винагороду, відчайдушно шукаючи здібних бійців, готових вирушити в пагорби й убити звіра, перш ніж той просунеться далі на схід."}},fp="18,300,25.608.0,27.516.0,42.261.0,34.192.0,36.176.0,52.187.0"}
P.entries["subzone:whispering-forest"] = {n="Шепітливий Ліс",s="Шепітливий Ліс — відлюдний гірський ліс, схований за стрімкими скелями на захід від Похоронного Подзвону. Майже відрізаний від решти Галявин Тірісфалю, він ховає моторошну живність, таємниче відьмине коло й глибоко вкорінену скверну, що спить далеко під землею.",h="Шепітливий Ліс — відлюдний гірський ліс, схований за стрімкими скелями на захід від Похоронного Подзвону.",kw={"шепітливий ліс","відьмине коло","гриби","лицар скорботи","високі ельфи","тіньова долина","фортеця бандаріон","тірісфаль"},ang={["class:Druid"]="Сяйливе відьмине коло вирізняється як один із небагатьох проблисків природної магії, що лишилися в ураженому чумою Лордероні.",["race:Undead"]="Схований одразу за Похоронним Подзвоном і піднаглядний Варті Тіра у Фортеці Бандаріон, відлюдний ліс ховає забуті небезпеки — мовчазну загрозу просто на порозі Андерсіті."},sec={{t="Прихована долина",b="Шепітливий Ліс, який ховають Камінь Північного Лику й Фортеця Бандаріон, здається зовсім чужим довколишньому ураженому чумою королівству. Хоч тут водяться хворі олені й мандрівні хижаки, тут також є тихе озеро й дивне коло велетенських грибів, що світяться моторошною енергією під завислою хмарою імли. Примарний Лицар Скорботи блукає відьминим колом, прив'язаний до нього клятвою, серед природної магії, яка немов кидає виклик зруйнованій Погибеллю землі."},{t="Тінь під лісом",b="Попри зовнішнє диво, ліс отруєний давнім жахом. Століття тому високі ельфи ненадовго спробували оселитися в Галявинах Тірісфалю, та їх прогнало приховане зло, що спить глибоко під землею й почало зводити їх з розуму. Довкола місцевого озера нишпорять мурлоки Темноплавців й трешадон-нежить Блайтскаллер, а зруйноване поселення Тіньова Долина уражене некромантичними рештками. Навіть божевільні блукальці по всьому Лордерону бурмочуть налякані застереження про всепоглинальну темряву, що спочиває під корінням Тірісфалю."}},fp="17,273,15.481.0,28.542.1,39.205.0,42.216.0,28.197.0,52.261.0,19.221.0"}
P.entries["subzone:whispering-shore"] = {n="Шепітливий Берег",s="Шепітливий Берег — похмура смуга узбережжя в західних Галявинах Тірісфалю; одразу на південь від нього лежить Хутір Соллідена. Колись тихий і щедрий притулок рибалок Лордерона, його холодні води відтоді захопило люте плем'я мурлоків.",h="Шепітливий Берег — похмура смуга узбережжя в західних Галявинах Тірісфалю; одразу на південь від нього лежить...",kw={"шепітливий берег","узбережжя","мурлоки","муад","рибалки","хутір соллідена","тірісфаль"},ang={["race:Undead"]="Для Відступників, що убезпечують західні Галявини Тірісфалю, навала мурлоків на Шепітливому Березі — некерована загроза просто вздовж межі їхніх володінь."},sec={{t="Зруйнована гавань",b="До того як Третя війна прокотилася північним Лордероном, Шепітливий Берег славився серед місцевих як улюблена рибальська гавань, відома спокійними водами й багатими уловами. Сьогодні крижані бризки Великого Моря б'ються об порожній берег, позбавлений свого мирного минулого. Води стали холодними й темними, без колишньої щедрості, і кожен нещасний мандрівник, що спуститься з пагорбів, ризикує потрапити в засідку ревнивих до своєї території прибережних мешканців."},{t="Загроза мурлоків",b="Пляж тепер міцно тримає ватага ворожих мурлоків, що безжально нападають на кожного, хто наближається до прибою. На чолі з лютим вождем на ім'я Муад ці водяні падложери агресивно стережуть мілини й припливні обмілини, становлячи постійну небезпеку для сусідніх доріг і для сусіднього Хутора Соллідена."}},fp="16,263,14.468.0,17.299.0,38.111.0,59.136.0,38.171.0,54.183.0"}
P.entries["subzone:wildmane-water-well"] = {n="Водяна Криниця Вайлдмейнів",s="Водяна Криниця Вайлдмейнів — найпівнічніша зі священних криниць, розкиданих по Малгору; вона лежить одразу на північ від плато Тандер Блафа. Життєво важлива для рівнин і їхніх стад, вона стала гарячою точкою, на яку націлилися гоблінські пройдисвіти, прагнучи перекрити тауренам джерело життя.",h="Водяна Криниця Вайлдмейнів — найпівнічніша зі священних криниць, розкиданих по Малгору; вона лежить одразу на...",kw={"водяна криниця вайлдмейнів","криниця","отрута","венчурна компанія","тандер блаф","малгор","очищення"},ang={["class:Druid"]="Спроби гоблінів отруїти прісну воду Малгору загрожують крихкій рівновазі рівнин і вимагають друїдської пильності, щоб очистити й зцілити землю.",["race:Tauren"]="Священні криниці Малгору — дар Земної Матері. Захистити Криницю Вайлдмейнів від осквернення й отрути — священний обов'язок кожного молодого сміливця."},sec={{t="Джерело життя в облозі",b="Поколіннями кочові таурени покладалися на священні криниці, викопані по золотавих рівнинах Малгору, щоб напувати свій народ і мандрівні стада кодо. Криниця Вайлдмейнів стереже північні простори одразу за тінню Тандер Блафа. Її надзвичайна важливість робить її принадною ціллю для ворогів племен. Гобліни Венчурної Компанії споганили її своїми отрутами, аби прибрати до рук водопостачання всього краю, і лише обряд очищення з тотемом, виготовленим тауренами, зможе знову зробити її води чистими."}},fp="19,292,23.543.0,41.184.0,40.191.0,46.157.0"}
P.entries["subzone:windfury-ridge"] = {n="Хребет Люті Вітру",s="Хребет Люті Вітру — суворе високогір'я, що обступає пасовища Малгору. Сумнозвісний лютими гарпіями, а також хижими вовками й пумами, він становить постійну небезпеку для подорожніх, зате дарує тауренським майстрам цінне пір'я.",h="Хребет Люті Вітру — суворе високогір'я, що обступає пасовища Малгору.",kw={"хребет люті вітру","гарпії","вітрофурії","пір'я","вовки","пуми","малгор"},ang={["class:Hunter"]="Круті схили й хитрі хижаки — чудовий ранній полігон для вистежування, приборкання звірів і бою на відстані.",["race:Tauren"]="Хребет — водночас постійна морока для молодих мисливців і джерело важливих обрядових прикрас, якими вшановують шлюби та сезонні зібрання."},sec={{t="Небезпечне сідало",b="Хребет Люті Вітру різко здіймається над тихими рівнинами Малгору й править за мисливські угіддя гарпій Вітрофурій. Ці люті крилаті створіння гніздяться високо в кручах і охоче кидаються згори на необачних мандрівників, що обходять пагорби. Скелясту місцевість також населяють степові вовки й дикі гірські пуми, тож хребет — один із найпідступніших кордонів тауренського серця краю. Попри небезпеку, хоробрі тауренські воїни часто полюють на гарпій: їхнє яскраве, переливчасте пір'я дуже цінують по всьому Тандер Блафу, прикрашаючи ним обрядові шати для пишних бенкетів і весільних святкувань."}},fp="14,245,16.644.0,36.267.0,53.250.0,32.131.0"}
P.entries["subzone:winterhoof-water-well"] = {n="Водяна Криниця Вінтергуфів",s="Водяна Криниця Вінтергуфів — життєво важливе джерело прісної води на краю Хвилястих Рівнин у південному Малгорі. Вкрай потрібна місцевій живності й кочовим тауренським племенам, криниця нещодавно опинилася під загрозою з боку хижої Венчурної Компанії, що прагне отруїти й прибрати до рук водопостачання краю.",h="Водяна Криниця Вінтергуфів — життєво важливе джерело прісної води на краю Хвилястих Рівнин у південному...",kw={"водяна криниця вінтергуфів","криниця","хвилясті рівнини","венчурна компанія","малл тандергорн","очищення","малгор"},ang={["class:Shaman"]="Очищення криниці вимагає гармонії стихій і стає наочним уроком того, як тотемами зцілювати поранених духів води.",["race:Tauren"]="Оборона й очищення прабатьківських криниць — одне з перших випробувань молодих сміливців, що бережуть землю від чужинського визиску."},sec={{t="Життєва артерія під загрозою",b="У посушливих просторах центрального Калімдору вода — це життя, і підземні криниці Малгору живлять і стада рівнин, і стійбища тауренів. Водяна Криниця Вінтергуфів, названа на честь одного з шанованих племен рівнин, сягає глибоких водоносних шарів під Хвилястими Рівнинами. На жаль, її стратегічна вага розпалила жадобу Венчурної Компанії. Замість ділити землю чи домовлятися безжальний гоблінський картель спробував отруїти воду, щоб здобути важіль тиску на довколишні землі."},{t="Очищення й оборона",b="Щоб протистояти промисловій диверсії Венчурної Компанії, тауренські старійшини й шамани підняли молодих сміливців по всьому Малгору. Малл Тандергорн виготовив священні тотеми, здатні нейтралізувати промислові отрути й відновити духовну та тілесну рівновагу криниці. Очищення криниці для тауренів — не просто боротьба за виживання, а духовний обов'язок: земля та її води мають лишатися неспаплюженими чужинською жадобою."}},fp="21,315,21.547.0,24.439.1,43.111.0,39.188.0,38.178.0,44.226.0"}
P.entries["topic:frostmane-tribe"] = {n="Плем'я Морозогривів",s="Плем'я Морозогривів — це люті крижані тролі, корінні мешканці студених вершин Дун Мороґу. Століття тому дворфи Айронфорджа загнали їх у печери та на віддалені хребти, і відтоді вони ведуть невпинну партизанську війну, щоб повернути дім предків.",h="Плем'я Морозогривів — це люті крижані тролі, корінні мешканці студених вершин Дун Мороґу.",kw={"морозогриви","крижані тролі","дун мороґ","тролі","твердиня морозогривів","мерехтливий хребет"},ang={["profession:Cooking"]="Скелясті вепри та звірі, яких тримають біля таборів Морозогривів, дають грубу дичину для похідних харчів серед пронизливих снігів Дун Мороґу.",["race:Dwarf"]="Для дворфів Морозогриви — постійне нагадування про кровну ворожнечу предків. Сама королева Еймір загинула в засідці тролів Морозогривів, тож оборона Дун Мороґу для горян — справа глибоко особиста.",["race:Troll"]="Хоч тролі Темного Списа й поділяють загальну спадщину тролів, відлюдні Морозогриви — дикі крижані тролі, яким байдуже до спорідненості: гостей з Орди вони мають за зайд на своїх священних вершинах."},sec={{t="Вигнанці високих скель",b="Задовго до того, як клан Бронзбірдів об'єднався під Айронфорджем, тролі Морозогриви панували над засніженими просторами Дун Мороґу. Піднесення і розширення дворфійського королівства розтрощило їхнє царство, і вцілілі крижані тролі відступили на замерзлі хребти й скелі. Ця принизлива поразка розпалила гірку ненависть, що передається з покоління в покоління й досі не згасла. Морозогриви бачать у кожному горянині, мандрівнику й хуторі ворога-загарбника, якого треба вигнати або вбити."},{t="Слушна нагода",b="Десятиліттями Сенат Айронфорджа мав Морозогривів лише за набридливу прикрість, що чаїться в пагорбах. Та раптова поява трогів з глибин під Дун Мороґом внесла безлад у дворфійську оборону. Відчувши слушну мить, поки горяни перевантажені, а дворфійські війська воюють у війнах Альянсу за кордоном, Морозогриви почали нові жорстокі набіги з твердинь на кшталт Твердині Морозогривів і Мерехтливого Хребта, щоб повернути давні землі."},{t="Нальотчики долин",b="Сенат Айронфорджа зрештою помітив зростання загрози й послав Ґреліна Вайтбірда з братом Сеніром дати їй раду. З печер Твердині Морозогривів і висот Мерехтливого Хребта тролі б'ють по дворфах, а в Долині Холодного Хребта воєначальники на кшталт Ґрік'ніра Холодного керують зухвалими нападами на горян."}},fp="15,246,24.488.0,20.499.0,22.347.1,29.182.0,48.202.0,30.171.0,32.230.0,53.217.0,41.148.0"}
P.entries["topic:grommash-hellscream"] = {n="Громмаш Хеллскрім",s="Громмаш Хеллскрім — легендарний ватажок клану Пісні Війни, близький побратим Вождя Тралла й перший орк, що випив кров Маннорота. Хоч його жага битви колись прикувала його народ до Палаючого Легіону, він спокутував провину орківської раси, вбивши повелителя демонів в Ашенвалі ціною власного життя.",h="Громмаш Хеллскрім — легендарний ватажок клану Пісні Війни, близький побратим Вождя Тралла й перший орк, що...",kw={"громмаш хеллскрім","гром","ґоргаул","маннорот","клан пісні війни","ашенваль","спокута"},ang={["class:Warrior"]="Воїни вивчають бойову майстерність Грома й володіння Ґоргаулом як вершину воїнської агресії, бачачи в ньому і страшну ціну неприборканої люті, і чисту силу незламного бойового духу.",["faction:Horde"]="Для Орди Гром утілює трагічну дугу її заснування: лютий воїн, чия безоглядна вдача завела їх у темряву, але чия незламна відвага купила їм виживання й свободу в Калімдорі.",["race:NightElf"]="Нічні ельфи згадують Грома з гіркотою, що не минає: для них він — ошалілий від демонів загарбник, який осквернив священні гаї Ашенвалю й убив напівбога Кенарія.",["race:Orc"]="Орки шанують Громмаша як свого остаточного рятівника. Його жертва в Ашенвалі розірвала демонічне Прокляття Крові, що тримало расу в рабстві поколіннями, і дозволила Новій Орді ходити з гордістю й вільною волею."},sec={{t="Перший ковток і залізна воля",b="Ще до того, як Темний Портал з'єднав світи, Гром Хеллскрім вів клан Пісні Війни з незламною люттю; його вирізняли чорна як смола татуйована щелепа й смертоносний змах дворучної сокири Ґоргаул. Коли Ґул'дан і Рада Тіней піднесли на Дренорі чашу демонічної сили, Гром першим із ватажків випив кров володаря ями Маннорота. Той фатальний ковток прирік орківську расу на демонічне рабство й палючу жагу крові. Та, на відміну від багатьох ватажків, що загинули чи цілком піддалися, Гром мав залізну волю, яка зберегла його лютий дух цілим: він пережив жахи старої Орди, плекаючи невимовний біль за тим, що його народ віддав."},{t="Братерство в нетрях",b="Залишений на Дренорі під час Другої війни, Гром пізніше пройшов крізь Темний Портал — лише для того, щоб застрягти, коли розлом було зруйновано. Майже п'ятнадцять років Гром і його вцілілі воїни Пісні Війни ховалися від Альянсу Лордерону, терплячи млявість і відчай, що охопили орків, коли демонічна кров вивітрилася. Надія спалахнула знову, коли молодий утікач на ім'я Тралл розшукав його в глушині. Побачивши силу й шляхетне серце Тралла, Гром навчив його гордої спадщини їхнього народу. Разом з Орґрімом Думхаммером вони згуртували розрізнені клани, розбили людські табори для інтернованих і запалили народження Нової Орди."},{t="Падіння й остання спокута",b="Прибувши до Калімдору під час Третьої війни, Гром знову дав волю невгамовній агресії в давніх лісах Ашенвалю. Оточений нічними ельфами й напівбогом Кенарієм, Гром піддався вдруге — випив із оскверненого джерела, насиченого кров'ю Маннорота, щоб урятувати свій клан. Знову поневолений повелителем демонів, Гром обернувся проти власного народу, доки Тралл і Джайна Праудмур не схопили його й не очистили його розбещений дух давніми шаманськими й таємними обрядами. Цілком повернувшись до тями й пригнічений безмірною провиною, Гром переслідував Маннорота до Каньйону Падіння Демона. У відчайдушному останньому ударі він увігнав Ґоргаул у груди повелителя демонів, навіки розірвавши демонічне прокляття, тоді як пекельний вогонь забрав його життя."}},fp="19,333,33.698.0,26.659.0,25.718.0,28.350.0,17.360.0,36.354.0,34.287.0,45.383.0,25.260.0"}
P.entries["zone:dunmorogh"] = {n="Дун Мороґ",s="Дун Мороґ — засніжене гірське високогір'я в серці Хаз Модану. Це прадавня стартова земля і спільна батьківщина дворфів Айронфорджа та гномів, що втратили Гномреґан. Хоч засніжений край захищають високі вершини й укріплені перевали, зсередини йому дедалі більше загрожують троги, тролі Морозогриви та опромінені прокажені гноми.",h="Дун Мороґ — засніжене гірське високогір'я в серці Хаз Модану.",kw={"дун мороґ","зона","дворфи","гноми","айронфордж","гномреґан","троги","морозогриви"},ang={["profession:Cooking"]="Місцеві мисливці та шинкарі в Хараносі й Селі Брюнолл щедро пускають у діло м'ясо вепрів, ведмежі ребра та дворфський стаут, щоб проганяти пронизливий гірський мороз.",["profession:Mining"]="Гірські скелі Дун Мороґу багаті на поверхневі поклади мідних жил, особливо навколо кар'єру Гол'Болар і вздовж засніжених скельних стін.",["race:Dwarf"]="Це батьківщина ваших предків. Від вогнищ Анвілмара до розжареного серця Великої Кузні в Айронфорджі — боронити ці вершини від тролів і трогів є вашим обов'язком перед Королем Маґні.",["race:Gnome"]="Ваш утрачений дім, Гномреґан, лежить опромінений у західній долині. Дун Мороґ — ваша база у вигнанні пліч-о-пліч із дворфськими родичами, поки ви даєте відсіч трогам і здичавілим прокаженим гномам."},sec={{t="Гірська твердиня",b="Дун Мороґ займає найвищі вершини Східних Королівств — альпійський простір, оточений зубчастими піками, що затуляють його від Палючої Ущелини на півдні та Багнокраю на півночі. Ці засніжені гори живлять річки, що течуть по всьому Хаз Модану, і дають майже невичерпні жили міді й заліза. Доступ сюди суворо обмежений гірськими тунелями, як-от Перевал Північної Брами та Прохід Південної Брами, за якими пильно стежать дворфські горяни. У серці краю лежить Айронфордж — прадавнє підземне диво й столиця королівства Короля Маґні Бронзбірда, сполучена просто зі Стормвіндом дивовижним Глибинним трамваєм."},{t="Розділений притулок",b="Століття тому дворфи відтіснили тутешніх крижаних тролів Морозогривів у скелі, вивільнивши місце для себе та своїх геніальних гномських союзників. Два народи процвітали в сусідніх гірських залах, аж доки під час Третьої війни не сталася нещодавня катастрофа в Гномреґані. Жахливе вторгнення трогів і згубний викид радіації зруйнували технологічне диво, обернувши його захисників на безтямних прокажених гномів і змусивши Великого Тінкера Ґелбіна Меккаторка з уцілілим народом піти у вигнання. Нині гноми живуть гостями всередині Айронфорджа, а прокажені гноми та вцілілі троги виливаються в Долину Холодного Вітерцю."},{t="Клопоти серед заметів",b="Життя серед заметів аж ніяк не спокійне. Плем'я Морозогривів знахабніло й розбиває добре озброєні табори від Мерехтливого Хребта до Долини Холодного Хребта. Тим часом первісні троги видряпалися з прадавніх підземних розколин у Кар'єр Гол'Болар, загрожуючи гірничим промислам краю. Між хижими вендіго, дикими вепрами, лазутчиками-дворфами Темного Заліза та отруйними опадами, що ширяться з руїн Гномреґану, дворфські горяни ледве дають раду, підтримуючи лад від Хараноса до прикордонних брам."}},faq={{q="Які раси починають у Дун Мороґу?",a="І дворфи, і гноми починають свій шлях тут, у Долині Холодного Хребта — захищеній улоговині на південному заході Дун Мороґу, — а потім виходять через Перевал Холодного Кряжа до Хараноса й решти зони.",al={"стартова раса дун мороґу","хто тут починає","стартова зона дворфів","стартова зона гномів"}},{q="Що сталося з Гномреґаном?",a="Під час Третьої війни підземна раса трогів заполонила Гномреґан. Намагаючись знищити загарбників, Великий Тінкер Ґелбін Меккаторк випустив у нижні рівні радіоактивний газ. План провалився з катастрофічними наслідками: загинули тисячі, багато гномів через опромінення перетворилися на божевільних прокажених гномів, а здорові вцілілі були змушені тікати до Айронфорджа.",al={"чому гномреґан зруйновано","що сталося з гномами","чому тут прокажені гноми"}},{q="Як вийти з Дун Мороґу пішки?",a="Дун Мороґ оточений високими гірськими хребтами. Щоб пішки потрапити на схід, до Лох Модану, ідіть дорогами до Перевалу Північної Брами або Проходу Південної Брами в північно-східних горах. Також можна дістатися просто до Стормвінда Глибинним трамваєм всередині Айронфорджа.",al={"вихід із дун мороґу","з дун мороґу до лох модану","покинути дун мороґ"}},{q="Де в Дун Мороґу розпорядник польотів?",a="Єдиний діючий розпорядник польотів Альянсу в зоні розташований усередині Великої Кузні Айронфорджа; він сполучає мандрівників із місцями по всьому Хаз Модану, Стормвіндом і північними заставами Альянсу.",al={"розпорядник польотів дун мороґ","маршрут польоту дун мороґ","куди літати з дун мороґу"}},{q="Хто такі тролі Морозогриви?",a="Морозогриви — плем'я крижаних тролів, яке правило Дун Мороґом задовго до того, як дворфи вийшли з Улдамана. Хоч багато поколінь тому їх розбили й загнали в скелі, вони лишаються запеклими ворогами Айронфорджа й раз у раз нападають на дворфські ферми та дороги зі своїх сховків на кшталт Твердині Морозогривів.",al={"чому в дун мороґу тролі","тролі дун мороґу","плем'я морозогривів"}},{q="Що таке Харанос?",a="Харанос — головне дворфське поселення в центральному Дун Мороґу. Тут розташовані Ґуральня Тандербрю, наставники та припаси, тож це центральний осередок для молодих шукачів пригод і горян, які дають раду місцевим тролям і дикій звірині.",al={"містечко в дун мороґу","осередок харанос","яке тут головне містечко"}}},fp="10,374,21.621.0,16.623.0,21.550.0,31.194.0,28.349.0,36.270.0,41.202.0,29.283.0,17.249.0"}
P.entries["zone:elwynn"] = {n="Ліс Елвінн",s="Ліс Елвінн — зелене серце королівства Стормвінд, що постачає столиці конче потрібні деревину, золото, рибу та збіжжя. Під покровом статечних листяних дерев він служить полігоном для новобранців з людей, що виходять з Абатства Нортшира. Та під ідилічним сільським склепінням ліс тяжко потерпає від погані, що насувається, зігнаної з місць звірини й повсюдного розбійництва.",h="Ліс Елвінн — зелене серце королівства Стормвінд, що постачає столиці конче потрібні деревину, золото, рибу та...",kw={"ліс елвінн","зона","люди","стормвінд","стартова локація","дефіас","кобольди","гноли"},ang={["class:Rogue"]="Всюдисуща тінь Братства Дефіас робить Елвінн захопливим перехрестям злодійства, контрабанди та підпільних сигналів бунтівників.",["faction:Alliance"]="Захист Елвінну життєво важливий для виживання головного людського королівства Альянсу: якщо шляхи постачання деревини, руди та збіжжя заваляться, Стормвінд не зможе себе прогодувати.",["profession:Mining"]="Ехо-Рідж, Фарґодіп і Яшмова копальня повні мідних жил, тож попри навалу кобольдів ліс — важливий перший полігон для шахтарів.",["race:Human"]="Це прадавнє серце королівства. Шукачі пригод з людей починають тут, навчаючись в Абатстві Нортшира, перш ніж вирушити боронити батьківщину від розбійників, звірів і політичного краху."},sec={{t="Житниця королівства",b="Елвінн, що тягнеться на південь від брами Стормвінда до річки Назферіті, — родючий край, щедро обдарований дощами й густими листяними лісами. Такі громади, як Ґолдшир і Лісозаготівельний Табір Східної Долини, дають столиці вкрай потрібні збіжжя, худобу, деревину та сиру мідь. Край також славиться витривалими евендейлськими кіньми, яких полюбляють мандрівники й лицарі по всьому королівству."},{t="Хиткий мир",b="Попри зовнішній спокій, ліс стоїть на межі безладу. Армія Стормвінда розтягнута далекими зобов'язаннями, і місцевим маршалам та помічникам доводиться покладатися на неперевірених новобранців. Кобольди заполонили важливі копальні Фарґодіп і Яшмову, гноли Річколапи нишпорять південно-західними кордонами, а дикі мурлоки захопили береги Озера Кам'яного Кургану й Кришталевого Озера. Через дедалі більше скверніння за річкою, у Сутінколіссі, вовки втекли на північ через кордон."},{t="Загроза червоних бандан",b="Значно організованіше за простих падложерів, Братство Дефіас глибоко проникло в ліс. Ці розбійники в масках походять із позбавленої прав Гільдії Каменярів Едвіна Венкліфа після гіркої суперечки про платню з Домом Вельмож; вони захопили володіння по всьому Елвінну, зокрема Виноградники Нортшира, Гарбузову Ділянку Брекуеллів, Пристань Джерода та Сад Дзеркального Озера. Ходять уперті чутки, що їхні злагоджені агенти нишком керують сусідніми гнолами й кобольдами, щоб іще дужче розхитати королівство. Вартових Рольфа й Малакая, посланих розслідувати появу мурлоків біля Озера Кам'яного Кургану, вбили й покинули на його берегах."}},faq={{q="Чому вартові Стормвінда майже не стежать за порядком у лісі?",a="Збройні сили Стормвінда вкрай перенапружені. Королівство розгорнуло великі військові сили на півдні, у Долині Стренглторну, наробивши глибоких боргів і висотавши місцеві людські ресурси. Тому застави на кшталт Гарнізону Вестбрук і Ґолдшира покладаються на жменьку вартових і новобранців-добровольців, щоб відбиватися від розбійників, гнолів і мурлоків.",al={"де вартові","чому немає армії стормвінда","чому елвінн беззахисний"}},{q="Чому в усіх копальнях кобольди?",a="Поки вартових бракувало, спритні кобольди заполонили Копальню Фарґодіп, Яшмову копальню та Шахту Ехо-Рідж у пошуках дорогоцінного золота й мінералів. Вони вигнали людей — шукачів і шахтарів — і люто боронять свої підземні володіння свічками, грубими кайлами та підібраним знаряддям.",al={"чому в копальнях кобольди","кобольди елвінну","фарґодіп заражений"}},{q="Хто ці розбійники в червоних масках?",a="Це члени Братства Дефіас на чолі з Едвіном Венкліфом. Багато з них спершу були ремісниками Гільдії Каменярів, яка відбудувала Стормвінд після Першої війни. Коли знать відмовилася виплатити обіцяну платню, спалахнули заворушення, що призвели до їхнього вигнання й скочування до організованого розбійництва.",al={"червоні маски","розбійники в червоних банданах","хто такі дефіас в елвінні"}},{q="Куди веде дорога на південь?",a="Перейшовши міст через річку Назферіті, ви потрапите до Сутінколісся, історично відомого як Світлолісся. Цей колись мирний край поринув у неприродну темряву й нині кишить нежиттю, жахливими павуками та ненажерливими звірами.",al={"що за річкою","куди веде міст до сутінколісся","міст через назферіті"}},{q="Що за ворожнеча між Маклюрами та Стоунфілдами?",a="Стоунфілди й Маклюри — сусідні фермерські родини на півдні Елвінну, що плекають гірку давню образу одна на одну. Попри нескінченні сварки й звинувачення, двоє їхніх молодших родичів — Мейбелл Маклур і Томмі Джо Стоунфілд — таємно покохали одне одного, ще дужче заплутавши суперництво.",al={"маклюри проти стоунфілдів","ворожнеча ферм елвінну","ворожнеча стоунфілдів і маклюрів"}},{q="Що таке Вежа Азори?",a="Вежа Азори — таємний шпиль при дорозі між Ґолдширом і Лісозаготівельним Табором Східної Долини. У ній живуть маги-відлюдники, зокрема Теокрітус, які спостерігають за лей-лініями краю й провадять магічні дослідження поза прямим наглядом Святилища Чародія в Стормвінді.",al={"вежа на дорозі до східної долини","чародійська вежа елвінн","хто живе у вежі азори"}}},fp="13,409,28.423.0,18.493.0,22.639.1,54.341.0,43.303.0,38.313.0,31.240.0,54.342.0,27.282.0"}
P.entries["zone:stormwind"] = {n="Стормвінд",s="Стормвінд — гамірна столиця королівства Стормвінд і найбільший оплот людей у світі після падіння Лордерона. Відбудовані з попелу Гільдією Каменярів після руйнування в Першій війні, його величні квартали з білого каменю нині вміщують серце Великого Альянсу. Та під розкішними каналами й соборами місто потерпає від раптового зникнення короля Варіана Рінна і дедалі гострішої політичної інтриги.",h="Стормвінд — гамірна столиця королівства Стормвінд і найбільший оплот людей у світі після падіння Лордерона.",kw={"стормвінд","столиця","варіан рінн","андуїн рінн","болвар","гільдія каменярів","дефіас"},sec={{t="Відродження з попелу",b="Заснований понад тисячу років тому нащадками араті, Стормвінд поколіннями був квітучим, самодостатнім королівством. Ця золота доба скінчилася, коли Орда орків ринула крізь Темний Портал, спустошила південний континент і зрівняла столицю з землею в Першій війні. Уцілілі на чолі з сером Андуїном Лотаром утекли на північ, за Велике Море, до Лордерона. Після поразки Орди в Другій війні король Теренас Менетіл II та Альянс профінансували повну відбудову. Гільдія Каменярів ретельно відродила столицю як Новий Стормвінд — сяйливу цитадель із полірованого білого каменю й кварталів, порізаних каналами."},{t="Розколотий двір",b="Попри зовнішню велич, столицю роздирають внутрішні негаразди. Суперечка між Домом Вельмож і Гільдією Каменярів через платню загнала королівство в борги й паралізувала його. Заворушення, що спалахнули, забрали життя королеви Тіффін Рінн, а вигнаних майстрів штовхнули на злочинний шлях — так постало Братство Дефіас. Тепер король Варіан Рінн загадково зник дорогою на дипломатичні перемовини. Щоб уникнути паніки, корону поклали на голову його малого сина, десятирічного принца Андуїна Рінна, а правити як регент і командувач війська став Верховний Лорд Болвар Фордрагон разом із королівською радницею Леді Катраною Престор."},{t="Серце Великого Альянсу",b="Відколи Лордерон захопила Погибель, Стормвінд успадкував роль найбільшого прихистку людства й осередку Альянсу. З дворфійським королівством Айронфордж його сполучає підземний Глибинний трамвай Великого Тінкера Меккаторка. Гостей, що перетинають Долину Героїв, зустрічають велетенські статуї Синів Лотара, які зникли за Темним Порталом. Від духовного маяка — Собору Світла — до чародійських студій у Святилищі Чародія Стормвінд лишається найважливішим осередком торгівлі, культури й оборони на південних морях."},{t="Тіні у фортеці",b="Розбрат, що терзає королівство, — не просто адміністративна випадковість. Леді Катрана Престор потай спрямовує рішення Дому Вельмож, розпалює ворожнечу з каменярами й навмисно ігнорує прохання про військову допомогу з віддалених поселень на кшталт Вестфола та Редріджа. Нашіптуючи отруйні поради Верховному Лорду Болвару й розпорошуючи увагу королівства, вона тримає легіони Стормвінда бездіяльними й розділеними, поки неспокій за мурами міста загрожує самому трону."}},fp="14,461,19.657.0,15.605.0,27.577.0,19.516.2,30.299.0,35.231.0,38.286.0,48.333.0,50.279.0,40.240.0,65.292.0"}
P.entries["zone:teldrassil"] = {n="Тельдрассил",s="Тельдрассил, що означає «Корона Землі», — велетенське нове Світове Дерево, вирощене біля північно-західного узбережжя Калімдору. Виплекане друїдами після Третьої війни, його могутнє гілля тримає на собі цілу сутінкову дику природу й столицю нічних ельфів — Дарнасус. Та під його тихою, залитою місячним світлом кроною почала ворушитися скверна.",h="Тельдрассил, що означає «Корона Землі», — велетенське нове Світове Дерево, вирощене біля північно-західного...",kw={"тельдрассил","світове дерево","нічні ельфи","дарнасус","фандрал стаґгелм","скверна","нордрассил","зона"},ang={["class:Druid"]="Поки Малфуріон ув'язнений у Смарагдовому Сні, Коло Кенарія тут очолює Архідруїд Фандрал Стаґгелм, хоч багато друїдів непокоїться, що Тельдрассил виростили поспіхом.",["faction:Alliance"]="Тельдрассил — найпівнічніший бастіон Альянсу в Калімдорі, що тримає морське сполучення й торгівлю між Дарнасусом і материковими королівствами.",["profession:Herbalism"]="Зовсім позбавлена мінералів і руди, зелена крона дерева надолужує це як рай для збирачів Мирноцвіту, Срібнолисту й Земнокореня.",["race:NightElf"]="Це могутнє дерево — новий початок вашого народу після спустошення Гори Гіджал, але відсутність благословення Аспектів робить його захист нагальним обов'язком."},sec={{t="Крона над морем",b="Тельдрассил — не просто дерево; це піднесена над водами Прихованого Моря жива система. Його велетенські гілки тримають хвилясті пагорби, річки, живлені вранішньою росою, імлисті озера й густі прадавні гаї. На західному краю лежить Дарнасус — велична столиця калдореїв. Біля підніжжя монументального стовбура — Селище Рут'теран, з'єднане з кроною містичною брамою; це головна гавань острова."},{t="Відмова Аспектів",b="Після жертви Нордрассила в Третій війні й таємничого зникнення Шан'до Малфуріона Стормрейджа в Смарагдовому Сні Архідруїд Фандрал Стаґгелм переконав Коло Древніх виростити заміну. Стаґгелм сподівався повернути калдореям утрачене безсмертя. Та Ноздорму й Аспекти драконів визнали цей задум гординею й відмовили в благословенні. Без їхнього життєво важливого захисту ріст Тельдрассила потерпає від неприродних вад."},{t="Недуга, що підкрадається",b="Попри зовнішню велич, молоде Світове Дерево приховує темну хворобу. Місцева живність стала лютою: мирні племена фурболгів упали в божевілля, покручені ґрелли плодяться в курганах, а мерзенні сатири чинять темні обряди в тінях на кшталт Скелі Скверни. Унизу, на берегах Темного Узбережжя, морські велети, трешери й черепахи викидаються на берег, тікаючи від отруєних вод довкола дерева. Натуралісти й вартові тепер гарячково працюють по всьому гіллю, щоб розпізнати тінь, яка повільно душить їхню нову домівку."}},faq={{q="Навіщо виростили Тельдрассил?",a="Коли Нордрассил було спустошено наприкінці Третьої війни, нічні ельфи втратили безсмертя. Архідруїд Фандрал Стаґгелм схилив Коло Древніх і друїдів Кола Кенарія посадити в морі нове Світове Дерево, щоб повернути втрачене їхнім народом.",al={"навіщо створили","хто створив тельдрассил","походження тельдрассила"}},{q="Чому Тельдрассил не повернув нічним ельфам безсмертя?",a="Нордрассил дарував безсмертя, бо його благословив Ноздорму, Позачасний. Коли виростили Тельдрассил, Ноздорму визнав бажання нічних ельфів зухвалим і відмовився дарувати новому дереву своє благословення.",al={"безсмертя","чому не безсмертні","благословення ноздорму"}},{q="Як вийти з Тельдрассила?",a="Мандрівникам треба пройти через Дарнасус до рожевого порталу в Храмових Садах, який переносить униз, до Селища Рут'теран біля підніжжя стовбура. З Рут'терана корабель пливе через море до Обердайна на материку, на Темному Узбережжі; є й маршрути гіпогрифів.",al={"як вибратися","покинути дерево","корабель з тельдрассила"}},{q="Чому в Тельдрассилі немає рудних жил?",a="Уся зона лежить на живих гілках і деревині велетенського Світового Дерева, а не на природній материковій породі. Оскільки тут немає кам'яних підземних шарів, не утворюються ні жили металу, ні поклади руди, зате трави ростуть у великому достатку.",al={"де мідь","немає руди","видобуток у тельдрассилі"}},{q="Чому фурболги й звірі божеволіють?",a="Лиховісна присутність почала просочуватися в неблагословенне коріння Тельдрассила. Хвороба зіпсувала місцеву воду й рослинність, штовхнувши мирних деревляників і плем'я фурболгів-Вузлошкірів у шалену агресію, а рештки сатирів свідомо плекають цю заразу.",al={"зіпсуті фурболги","божевільні вузлошкіри","що за скверна"}},{q="Що таке Тінедол?",a="Тінедол — захищена відлюдна долина на східному гіллі Тельдрассила довкола великого дерева Алдрассил. Це мирне святилище, де молоді нічні ельфи починають навчання, перш ніж вирушити в широкий світ.",al={"тінедол","стартова зона","зона алдрассила"}}},fp="10,340,21.456.0,26.478.0,17.517.1,25.261.0,52.223.0,28.276.0,44.256.0,52.264.0,19.232.0"}
P.entries["zone:tirisfal"] = {n="Галявини Тірісфалю",s="Галявини Тірісфалю — моторошний північний край Лордерона, нині серце володінь Леді Сильвани Віндраннер і Відступників. Під ураженим чумою небом і гнилим гіллям лежать занепалі маєтки, принишклі склепи й величезна підземна столиця — Андерсіті. Оточений безтямною Погибеллю й ревними багряними хрестоносцями, це небезпечний край, де вільна нежить виборює своє виживання.",h="Галявини Тірісфалю — моторошний північний край Лордерона, нині серце володінь Леді Сильвани Віндраннер і...",kw={"галявини тірісфалю","тірісфаль","відступники","лордерон","андерсіті","погибель","багряний хрестовий похід","сильвана","зона"},ang={["class:Priest"]="Тут лежать історичні святині на кшталт Спочинку Фаола — гробниці Архієпископа Алонсуса Фаола, засновника Срібної Длані, — спотворені смертю й спірні між фанатиками та жерцями Тіні.",["faction:Alliance"]="Для вцілілих народів Альянсу Тірісфаль — трагічний пам'ятник падінню Лордерона, повний осквернених гробниць колишніх братів і сестер у вірі.",["faction:Horde"]="Тірісфаль — життєво важливий бастіон Орди на півночі Східних Королівств, що закріплює дипломатичні зв'язки з Відступниками й відбиває людських екстремістів і Погибель.",["race:Undead"]="Це ваша прабатьківська домівка двічі: королівство, яке ви збудували за життя, і хистке святилище, яке мусите боронити в нежитті під рукою Леді Сильвани."},sec={{t="Земля в сутінках",b="Колись родюча колиска людства, Галявини Тірісфалю всохли під прокляттям чуми, яку наслав Король-Ліч. Сонце рідко пробивається крізь каламутний морок, кидаючи вічну хворобливу блідість на вмирущі ліси, занедбані гарбузові грядки й холодні прибережні пагорби. Рештки старих хуторів, як-от Млини Аґаманда й Хутір Балнірів, досі стоять, та їхніх колишніх господарів здебільшого змели в братські могили або підняли неспокійними мерцями. Попри спустошення, край просякнутий темною стійкістю, опертою на такі містечка, як Брілл, і замкнене святилище Похоронного Подзвону, де щойно пробуджені Відступники вчаться витримувати своє друге життя."},{t="Війна на два фронти",b="Хоч Леді Сильвана заявляє про владу над краєм із підземних Руїн Лордерона, Відступники лишаються в облозі з усіх боків. Залишкові раби Погибелі досі заповнюють улоговини, поля й напівзруйновані склепи, цілком покірні крижаному трону Нортренду. На сході фанатичний Багряний Хрестовий Похід зробив північний Тірісфаль своїм головним бастіоном, діючи з Багряного Монастиря. Ревно віддані винищенню кожної істоти нежиті — і живої, і неживої, — їхні застави й патрулі ведуть безперервну партизанську війну проти розвідників Відступників й мирних подорожніх."},{t="Відлуння сивої давнини",b="Задовго до того, як людські королівства коронували перших монархів, Галявини несли давню спадщину. Прадавньою мовою врайкулів «Тірісфаль» означає «Падіння Тіра» — на честь героїчного титана-хранителя Тіра, що бився на смерть із велетенськими космічними жахіттями. У наступні епохи вигнанці-високі ельфи ненадовго спробували оселитися в цих лісах, та тіньові енергії глибоко під землею почали зводити їх з розуму, спонукавши рушити далі на північ. Пізнішими століттями таємна спілка смертних, відома як Рада Тірісфалю, обрала ці тінисті гаї, щоб наділяти силою самотніх Хранителів, які боронили Азерот від демонічного вторгнення."}},faq={{q="Чому небо зелене, а земля гниє?",a="Під час Третьої війни принц Артас і Погибель випустили Чуму Нежиті на Королівство Лордерон. Магічна пошесть отруїла не лише населення, а й ґрунт, дерева та саму воду, лишивши галявини у вічному стані моторошного, хворобливого тління.",al={"чому тірісфаль уражений чумою","що сталося з тірісфалем","чому тірісфаль умирає"}},{q="Яка тут різниця між Відступниками й Погибеллю?",a="Відступники — нежить, що вирвалася з-під телепатичного панування Короля-Ліча після битви біля Гори Гіджал і з власної волі пішла за Леді Сильваною Віндраннер. Погибель, що блукає хуторами й руїнами, лишається безтямними рабами, прив'язаними до наказів Короля-Ліча.",al={"відступники проти погибелі","чому зомбі нападають на нежить","чи вся нежить зла"}},{q="Хто ці вояки в червоних обладунках, що нападають на подорожніх?",a="Вони належать до Багряного Хрестового Походу — безкомпромісного ордену, що відколовся від колишніх паладинів Срібної Длані й уцілілих. Переконані, що вся нежить — невиправна гидота, яку треба очистити мечем і вогнем, вони з фанатичною ненавистю страчують і безтямних рабів, і вільних Відступників.",al={"багряний хрестовий похід","червоні люди","люди з монастиря"}},{q="Звідки походить назва Тірісфаль?",a="Край названо на честь титана-хранителя Тіра. За легендою, Тір упав у битві з потойбічними жахіттями в цій галявині. Прадавньою мовою врайкулів «Падіння Тіра» перетворилося на назву «Тірісфаль», а срібна рука хранителя стала символом, глибоко вплетеним у ранню міфологію людей.",al={"значення тірісфаль","падіння тіра","походження назви тірісфаль"}},{q="Де щойно пробуджені Відступники починають свою путь?",a="Щойно пробуджені Відступники виходять зі склепів Тіньової Могили в Похоронному Подзвоні — замкненому містечку в південно-західному Тірісфалі. Там управителі й екзекутори оцінюють, чи мають воскреслі мерці здоровий глузд і вірність, потрібні для служби Темній Леді.",al={"стартова зона нежиті","де похоронний подзвін","стартова зона відступників"}},{q="Як мандрівники залишають Тірісфаль, щоб дістатися інших континентів?",a="Велика гоблінська вежа цепелінів стоїть на схилі пагорба на південь від Брілла, одразу за Руїнами Лордерона. Ці повітряні кораблі регулярно й напряму перевозять через моря до Оргріммара в Калімдорі та Базового Базового Табору Ґром'ґол у Долині Стренглторну.",al={"цепеліни тірісфалю","як дістатися до оргріммара","як дістатися до стренглторну"}}},fp="15,403,18.637.0,19.603.0,26.621.0,42.269.0,65.287.0,53.289.0,39.297.0,53.269.0,53.247.0"}
